(globalThis.TURBOPACK||(globalThis.TURBOPACK=[])).push(["object"==typeof document?document.currentScript:void 0,50891,(e,a,n)=>{a.exports=JSON.parse('{"nameplate.???":"???","nameplate.Dark Figure":"Silhouette sombre","nameplate.Eerie Voice":"Voix inquiétante","nameplate.Elder Grah":"Elder Grah","nameplate.Eriole":"Eriole","nameplate.Grahdens":"Grahdens","nameplate.Kar & Seria":"Kar & Seria","nameplate.Karl":"Karl","nameplate.Lin":"Lin","nameplate.Lugina":"Lugina","nameplate.Man\'s Voice":"Voix d\'homme","nameplate.Mare":"Mare","nameplate.Mysterious Man":"Homme mystérieux","nameplate.Mysterious Woman":"Femme mystérieuse","nameplate.Paris":"Paris","nameplate.Seria":"Seria","nameplate.Seria & Karl":"Seria & Karl","nameplate.Seria & Lugina":"Seria & Lugina","nameplate.Seria・Lugina":"Seria・Lugina","nameplate.Tilith":"Tilith","nameplate.Tilith & Seria":"Tilith & Seria","nameplate.Woman\'s Voice":"Voix de femme","nameplate.Zebra":"Zebra","nameplate.静かな男の声":"Voix d\'un homme calme","story.map1-dungeon0-1end.001":"Tu peux maintenant obtenir des matériaux à la <color=00FF00>Ferme</color> du Village of the Venturer !","story.map1-dungeon0-2end.001":"Tu peux maintenant obtenir des matériaux à la <color=00FF00>Montagne</color> du Village of the Venturer !","story.map1-dungeon0-3end.001":"Tu as maintenant accès à la <color=00FF00>Maison des sphères</color> du Village of the Venturer !","story.map1-dungeon0-3end.002":"À la Maison des sphères, tu peux utiliser des matériaux pour forger des <color=00FFFF>sphères</color> à équiper sur tes unités.","story.map1-dungeon0-3end.003":"Forge de puissantes sphères pour renforcer tes unités !","story.map1-dungeon1.001":"<size=13>Il fait trop chaud ! <wait=40>Je veux rentrer ! <wait=40>C\'est insupportable...","story.map1-dungeon1.002":"<size=20>Oh ! <wait=20><rep_handlename> !","story.map1-dungeon1.003":"Hé, tu es en retard ! <wait=40>Qu\'est-ce que tu fabriquais ?!","story.map1-dungeon1.004":"Comment as-tu pu me faire attendre dans cette grotte étouffante ?!","story.map1-dungeon1.005":"Je commence à m\'inquiéter pour notre voyage...","story.map1-dungeon1.006":"Bon, <wait=40>j\'ai promis de t\'expliquer plus en détail ce qui se passe...","story.map1-dungeon1.007":"C\'est sérieux, alors écoute bien, d\'accord ?","story.map1-dungeon1.008":"Grand Gaia traverse une crise terrible...","story.map1-dungeon1.009":"Parmi les dieux puissants qui veillent sur nous, certains ont été corrompus par le mal.","story.map1-dungeon1.010":"Défiant le Saint Empereur Karna Masta, <wait=19>ils sèment désormais le chaos.","story.map1-dungeon1.011":"Parmi ces forces maléfiques, <wait=40>les rares qui possèdent les pouvoirs les plus redoutables sont appelés...","story.map1-dungeon1.012":".<wait=10>.<wait=10>.<wait=10>les Quatre Dieux déchus.","story.map1-dungeon1.013":"Autrefois, c\'étaient des dieux de haut rang...","story.map1-dungeon1.014":"...<wait=20>Mais maintenant, ils veulent s\'emparer de Grand Gaia.","story.map1-dungeon1.015":"Les Quatre Dieux déchus n\'ont pas seulement soumis les monstres et les esprits,","story.map1-dungeon1.016":"...ils se servent aussi de leurs pouvoirs pour invoquer et manipuler les héros légendaires de Grand Gaia.","story.map1-dungeon1.017":"Si on ne les arrête pas, <wait=40>Grand Gaia sera détruit...","story.map1-dungeon1.018":"Même le Saint Empereur Karna Masta et les autres dieux...","story.map1-dungeon1.019":"...<wait=20>ne pourront pas les retenir éternellement.","story.map1-dungeon1.020":"Voilà pourquoi Lord Lucius a ouvert la Porte menant à ce monde.","story.map1-dungeon1.021":"Il cherche à emprunter ton pouvoir.","story.map1-dungeon1.022":"C\'est pour ça que seuls les élus peuvent voir la Porte.","story.map1-dungeon1.023":"Lord Lucius place de grands espoirs en toi.","story.map1-dungeon1.024":"Alors j\'espère bien que tu ne nous décevras pas, <wait=20><rep_handlename> !","story.map1-dungeon1.025":"Cela dit, <wait=40>ta première cible sera l\'un des Quatre Dieux déchus...","story.map1-dungeon1.026":"La Déesse de la Création, <wait=20>Maxwell !","story.map1-dungeon1.027":"Maxwell <wait=20>s\'est emparée de St. Lamia. Autrefois terre sacrée, c\'est désormais sa forteresse.","story.map1-dungeon1.028":"D\'ici, à Mistral, <wait=40>il te faudra aller au-delà de Morgan pour l\'atteindre.","story.map1-dungeon1.029":"La route est longue, <wait=40>mais je suis sûre que ça ira !","story.map1-dungeon1.030":"Avançons pas à pas jusqu\'à ce que tu maîtrises ton rôle d\'Invocateur !","story.map1-dungeon1.031":"D\'abord, pour rejoindre Morgan, il faut nous diriger vers la Tour de Mistral.","story.map1-dungeon1.032":"Pour ça, <wait=20>on doit traverser la Grotte des flammes.","story.map1-dungeon1.033":"On raconte <wait=20>que cette grotte grouille de bêtes féroces.","story.map1-dungeon1.034":"Mais quand même, <wait=20>tu devrais t\'en sortir !","story.map1-dungeon1.035":"<size=20>Argh ! <wait=40>Je ne supporte plus cette chaleur !","story.map1-dungeon1.036":"Je rentre prendre une douche. Fais attention et continue sans moi !","story.map1-dungeon2.001":"...Brr <wait=60><size=24>...Brr !","story.map1-dungeon2.002":"<size=36>Atchoum !!","story.map1-dungeon2.003":"...Oh là là,<wait=30> on gèle !","story.map1-dungeon2.004":"Hé ! <wait=40>Comment oses-tu faire attendre une fille dans un endroit aussi froid ?!","story.map1-dungeon2.005":"Brr... <wait=30>il fait trop froid !!","story.map1-dungeon2.006":"Bon, <wait=20>pour atteindre la Tour de Mistral, <wait=40>tu devras traverser la Plaine enneigée d\'Egor puis la forêt...","story.map1-dungeon2.007":"Ensuite le marais, <wait=30>et enfin les ruines...","story.map1-dungeon2.008":"Rien que d\'y penser, c\'est loin, <wait=40>et c\'est sans compter le climat extrême !","story.map1-dungeon2.009":"Enfin bref, <wait=20>la tour est encore loin.","story.map1-dungeon2.010":"Mais sois prudent. <wait=20>Plus tu t\'en approches, plus les ennemis sont forts.","story.map1-dungeon2.011":"Si tu tombes sur un ennemi que tu n\'arrives pas à vaincre, <wait=20>retourne peut-être au donjon précédent pour t\'entraîner un peu.","story.map1-dungeon2.012":"Ah oui, <wait=20>il est temps aussi de composer ton escouade en tenant compte des éléments.","story.map1-dungeon2.013":"Dans la grotte, la plupart des ennemis étaient de Feu, alors une escouade d\'unités d\'Eau t\'aurait donné un énorme avantage !","story.map1-dungeon2.014":"Cette fois, on est dans une plaine enneigée. <wait=40>Je pense qu\'on va croiser beaucoup d\'ennemis d\'Eau.","story.map1-dungeon2.015":"Alors... <wait=20>petite interro ! <wait=40>Quel élément est fort contre l\'Eau ?","story.map1-dungeon2.016":"Oui, <wait=40>c\'est ça !","story.map1-dungeon2.017":"On dirait que tu as révisé. <wait=40>Eh oui, la Foudre bat l\'Eau.","story.map1-dungeon2.018":"En revanche, les unités de Feu seront désavantagées face aux ennemis de la plaine enneigée, alors attention.","story.map1-dungeon2.019":"...Brr <wait=60><size=24>...Brr !","story.map1-dungeon2.020":"<size=36>Atchoum !!","story.map1-dungeon2.021":"Pfff, <wait=20>je n\'en peux plus. <wait=40>Je rentre !","story.map1-dungeon2.022":"...Ah, <wait=20>j\'allais oublier.","story.map1-dungeon2.023":"Il paraît qu\'un chevalier invoqué par Maxwell sème le chaos quelque part au bout de cette plaine enneigée.","story.map1-dungeon2.024":"Il a l\'air plutôt fort. Fais attention !","story.map1-dungeon3.001":"Oh, <wait=20><rep_handlename> ! <wait=40>Bravo, tu as traversé la plaine enneigée.","story.map1-dungeon3.002":"Hmm, <wait=40>je dois dire que tu as l\'air plus digne qu\'à notre première rencontre.","story.map1-dungeon3.003":"Bon, <wait=20>il est temps de traverser la Forêt des bêtes !","story.map1-dungeon3.004":"Comme son nom l\'indique, cette forêt grouille de bêtes sauvages...","story.map1-dungeon3.005":"Mais ton véritable ennemi, <wait=20>c\'est celui qui les chasse.","story.map1-dungeon3.006":"Oh, <wait=40>et tu as équipé une sphère ?","story.map1-dungeon3.007":"Tu peux améliorer les capacités de tes unités en les équipant de sphères.","story.map1-dungeon3.008":"Un Invocateur doit savoir ça s\'il compte survivre longtemps.","story.map1-dungeon3.009":"Les sphères se forgent à la Maison des sphères, dans ton monde.","story.map1-dungeon3.010":"Équipe tes unités de sphères pour bâtir une escouade plus forte !","story.map1-dungeon3.011":"Pour fabriquer des sphères, il faut d\'abord récolter certains matériaux.","story.map1-dungeon3.012":"Bref, <wait=20>bonne chance et bats-toi bien !<br>","story.map1-dungeon4.001":"<size=18>Argh, <wait=20>c\'est horrible !! C\'est quoi cette humidité de fou ?!","story.map1-dungeon4.002":"Mes cheveux et mes vêtements sont tout collants, beurk !!","story.map1-dungeon4.003":"Ah... <wait=20><rep_handlename>.","story.map1-dungeon4.004":"Tu as traversé la forêt. Au moins, je ne t\'ai pas appris tout ça pour rien.","story.map1-dungeon4.005":"Oh, <wait=20>c\'est vrai. <wait=40>Tu utilises bien les étincelles ?","story.map1-dungeon4.006":"Quand tes unités attaquent en même temps et déclenchent une étincelle, les dégâts infligés augmentent nettement.","story.map1-dungeon4.007":"C\'est une technique très importante, surtout utile contre les ennemis coriaces.","story.map1-dungeon4.008":"Entraîne-toi jusqu\'à maîtriser le timing et enchaîne les étincelles !","story.map1-dungeon4.009":"<wait=20>Bon, dépêchons-nous de traverser le Marais de Magutagal ! C\'est trop dégoûtant ici...","story.map1-dungeon4.010":"Argh, <wait=20>les insectes me piquent. Mes jambes toutes douces vont être couvertes de piqûres si je reste plus longtemps.","story.map1-dungeon4.011":"Ça suffit ! <wait=40>Je t\'attendrai aux ruines !","story.map1-dungeon5.001":"Oh, <wait=20><rep_handlename> ! <wait=40>Tu as enfin atteint les ruines !","story.map1-dungeon5.002":"Pour être honnête, <wait=20>à notre rencontre, tu semblais peu fiable, <wait=20>perdu, <wait=20>et totalement inconscient de ce qui se passait autour de toi...","story.map1-dungeon5.003":"Je me demandais vraiment... <wait=40>cette personne est-elle vraiment un Invocateur ?","story.map1-dungeon5.004":"Mais on dirait que Lord Lucius avait raison. <wait=20>Tu as du potentiel !","story.map1-dungeon5.005":"Au fait, <wait=20>je suppose que tu connais déjà les Compétences de Leader, non ?","story.map1-dungeon5.006":"Pour prendre l\'avantage sur l\'adversaire ou compenser les faiblesses de ton escouade...","story.map1-dungeon5.007":"il est important de changer de leader pour essayer différentes Compétences de Leader.","story.map1-dungeon5.008":"Et aussi, <wait=40>quand un autre Invocateur vient t\'aider...","story.map1-dungeon5.009":"...sa Compétence de Leader s\'active aussi.","story.map1-dungeon5.010":"C\'est important, alors retiens-le !","story.map1-dungeon5.011":"Allez, <wait=20>on est à deux pas de la Tour de Mistral !","story.map1-dungeon5.012":"Ces Vestiges de Mirza <wait=40>sont les restes d\'une construction bâtie il y a des milliers d\'années...","story.map1-dungeon5.013":"Mais dernièrement, je n\'ai entendu parler d\'aucune créature rôdant par ici.","story.map1-dungeon5.014":"Peut-être, <wait=20>juste peut-être, <wait=20>que tu pourras passer sans encombre !","story.map1-dungeon5.015":"Enfin... <wait=20>on ne le saura qu\'en essayant.","story.map1-dungeon5.016":"Mais vu tout ce que tu as accompli, <wait=20>je doute que quoi que ce soit puisse t\'arrêter !","story.map1-dungeon5.017":"Aie confiance ! Bonne chance !","story.map1-dungeon6.001":"Oh, <wait=20><rep_handlename>.<br><wait=40>Tu es sorti des ruines vivant...","story.map1-dungeon6.002":"Brr... <wait=20>Cet endroit est froid et lugubre. <wait=40>Regarde ce bâtiment louche là-bas.","story.map1-dungeon6.003":"Il paraît qu\'on l\'appelle le Nid du monstre...","story.map1-dungeon6.004":"Cet endroit me donne la chair de poule !","story.map1-dungeon6.005":"Et récemment, on a signalé un mystérieux épéiste qui rôde dans les parages.","story.map1-dungeon6.006":"<size=20>J-<wait=10>Je <size=19>ne <size=18>d-<size=17>dis <size=16>pas <size=15>que <size=14>j\'ai <size=13>p-<size=12>peur, <size=11>OK<size=9> ?!","story.map1-dungeon6.007":"B-Bref, <wait=20>il paraît qu\'il porte une tenue bizarre et manie une épée étrange. <wait=20>Mais il ne faut pas prendre sa force à la légère.","story.map1-dungeon6.008":"Garde bien la tête froide...","story.map1-dungeon6.009":"<size=20>Iiih !!<br><wait=20><size=18>Qu-<size=20>Quelque <size=16>chose <size=19>s\'est <size=17>posé <size=18>s-<size=15>sur <size=17>mon <size=19>bras...","story.map1-dungeon6.010":"Oh, <wait=20>une feuille ?<br><wait=60>Qu\'est-ce... <wait=20>qu\'est-ce que c\'est que cette tête ?","story.map1-dungeon6.011":"B-Bref, <wait=20>sois prudent !","story.map1-dungeon6.012":"Une fois passé ici, <wait=20>on sera au pied de la Tour de Mistral !","story.map1-dungeon6.013":"Bonne chance, <wait=20><rep_handlename> !","story.map1-dungeon7.001":"Nous voilà enfin à la Tour de Mistral.","story.map1-dungeon7.002":"Même si la tour se trouve encore à Mistral, Maxwell en a déjà pris le contrôle.","story.map1-dungeon7.003":"Pour être honnête, <wait=20>les ennemis qu\'on a croisés jusqu\'ici ne sont rien comparés aux sbires de Maxwell.","story.map1-dungeon7.004":"Il faut être parfaitement prêts pour gagner ce combat et libérer la tour de l\'emprise de Maxwell.","story.map1-dungeon7.005":"Au dernier étage <wait=20>attend un monstre qui aurait été créé par Maxwell elle-même.","story.map1-dungeon7.006":"Mais on ne peut pas se permettre que tu te fasses écraser ici.","story.map1-dungeon7.007":"On est encore loin de St. Lamia, où Maxwell nous attend.","story.map1-dungeon7.008":"Je suis sûre que ça ira. <wait=40>Tu as même gagné mon respect. <wait=20>Aie un peu confiance en toi !","story.map1-dungeon7.009":"Allez, <wait=40><rep_handlename> !","story.map1-dungeon7.010":"Libère ton pouvoir <wait=20>et délivre Mistral des griffes du mal !","story.map1-dungeon_ex_clear.001":"<size=18>*Bzz* </size><wait=20><size=20>*Bz</size><wait=10><size=19>zzzz* </size><wait=40><size=18>*Bzzzzzz*</size>","story.map1-dungeon_ex_clear.002":"<size=21>Te voilà !</size>","story.map1-dungeon_ex_clear.003":"<rep_handlename> ! <wait=40>Tu as réussi !","story.map1-dungeon_ex_clear.004":"Nous avons constaté l\'extinction d\'une puissance colossale.","story.map1-dungeon_ex_clear.005":"On dirait que tu as vaincu Skramya.","story.map1-dungeon_ex_clear.006":"Je savais que si quelqu\'un pouvait le faire, c\'était toi !","story.map1-dungeon_ex_clear.007":"Oh, <wait=20>tu n\'es pas blessé, au moins ?","story.map1-dungeon_ex_clear.008":"Je prendrai soin de toi à notre retour !","story.map1-dungeon_ex_clear.009":"Hihi, je plaisante.","story.map1-dungeon_ex_clear.010":"Euh, <wait=20>grâce à toi, nous avons obtenu toutes sortes de nouvelles informations.","story.map1-dungeon_ex_clear.011":"Il semble qu\'il y a longtemps, une petite nation de la région de Mystral ait tenté d\'utiliser le pouvoir de Skramya.","story.map1-dungeon_ex_clear.012":"Leur plan s\'est retourné contre eux, et Skramya, furieux, l\'a anéantie.","story.map1-dungeon_ex_clear.013":"La colère de Skramya ne s\'est pas apaisée et il s\'est dirigé vers d\'autres nations.","story.map1-dungeon_ex_clear.014":"Mais un héros est apparu et a brillamment scellé Skramya. ","story.map1-dungeon_ex_clear.015":"Ensuite, Skramya a continué de dormir dans les Monts d\'Egor sans jamais être dérangé. ","story.map1-dungeon_ex_clear.016":"J\'aimerais vraiment savoir qui était ce héros, mais nous n\'avons pas plus d\'informations.","story.map1-dungeon_ex_clear.017":"J\'espère qu\'un jour nous en apprendrons davantage sur cette personne.","story.map1-dungeon_ex_clear.018":"Bon, <wait=40>je te préviendrai si nous obtenons de nouvelles informations !","story.map1-dungeon_ex_clear.019":"Bonne chance pour la suite de ton enquête sur Grand Gaia !","story.map1-dungeon_ex_open.001":"<size=18>*Bzz* </size><wait=20><size=20>*Bz</size><wait=10><size=19>zzzz* </size><wait=40><size=18>*Bzzzzzz*</size>","story.map1-dungeon_ex_open.002":"B-<wait=20>Bonjour...","story.map1-dungeon_ex_open.003":"Quelqu\'un m\'entend ?","story.map1-dungeon_ex_open.004":"Vous m\'entendez, <wait=40>monsieur ?","story.map1-dungeon_ex_open.005":"Ah ! <wait=40>J\'ai réussi à vous joindre !","story.map1-dungeon_ex_open.006":"<rep_handlename> !","story.map1-dungeon_ex_open.007":"Tu as déjà atteint les Monts d\'Egor !","story.map1-dungeon_ex_open.008":"Je savais que tu y arriverais !","story.map1-dungeon_ex_open.009":"Oh, <wait=20>permets-moi de me présenter à nouveau.","story.map1-dungeon_ex_open.010":"Je suis Lin Merylham, du Soutien logistique...","story.map1-dungeon_ex_open.011":"...du Bureau d\'enquête de l\'Office d\'exploration de Grand Gaia, à ton service.","story.map1-dungeon_ex_open.012":"Aujourd\'hui...","story.map1-dungeon_ex_open.013":"...<rep_handlename>, en tant que membre de l\'Armée des Invocateurs du Hall des Invocateurs d\'Akras...","story.map1-dungeon_ex_open.014":"...nous te demandons d\'enquêter sur les Monts d\'Egor !","story.map1-dungeon_ex_open.015":"Ils se trouvent dans la région de Mystral, et l\'enquête avait pris du retard car ils étaient sous le contrôle de Maxwell...","story.map1-dungeon_ex_open.016":"...mais depuis sa défaite, nous pouvons enfin les explorer plus en profondeur !","story.map1-dungeon_ex_open.017":"Il y a vraiment des Invocateurs impressionnants, n\'est-ce pas ?","story.map1-dungeon_ex_open.018":"Fais de ton mieux, toi aussi !","story.map1-dungeon_ex_open.019":"Oh, <wait=20>revenons à ce que je disais.","story.map1-dungeon_ex_open.020":"À propos des Monts d\'Egor...","story.map1-dungeon_ex_open.021":"D\'après notre enquête, un démon extrêmement puissant y sommeille. ","story.map1-dungeon_ex_open.022":"Nous n\'en sommes pas encore tout à fait sûrs, mais...","story.map1-dungeon_ex_open.023":"...il y a de fortes chances que ce soit le démon de glace qui existerait dans la région de Mystral.","story.map1-dungeon_ex_open.024":"Hein ?","story.map1-dungeon_ex_open.025":"Tu ne connais pas Skramya, le démon de glace ?","story.map1-dungeon_ex_open.026":"Ça me surprend beaucoup...","story.map1-dungeon_ex_open.027":"Compris ! <wait=40>Alors laisse-moi t\'expliquer !","story.map1-dungeon_ex_open.028":"Il y a longtemps, dans la région de Mystral...","story.map1-dungeon_ex_open.029":"...il y aurait eu plusieurs petites nations en plus de l\'ancien royaume de St. Lamia.","story.map1-dungeon_ex_open.030":"On dit qu\'elles ont toutes été détruites par les dieux après leur invasion.","story.map1-dungeon_ex_open.031":"Pourtant, l\'une d\'elles n\'aurait pas été détruite par un dieu, mais par Skramya.","story.map1-dungeon_ex_open.032":"Aussi petit soit-il, qu\'un royaume puisse être anéanti par un seul démon...","story.map1-dungeon_ex_open.033":"......","story.map1-dungeon_ex_open.034":".........","story.map1-dungeon_ex_open.035":"Euh, <wait=20>c\'est tout ce que je sais.","story.map1-dungeon_ex_open.036":"C\'est tout ce que tu as besoin de savoir !","story.map1-dungeon_ex_open.037":"Il a le pouvoir de détruire des royaumes !","story.map1-dungeon_ex_open.038":"Il est extrêmement dangereux !","story.map1-dungeon_ex_open.039":"En tant qu\'Invocateur, tu ne peux pas le laisser faire !","story.map1-dungeon_ex_open.040":"Ouah, tu n\'as même pas l\'air inquiet de sa dangerosité.","story.map1-dungeon_ex_open.041":"Mais ce démon est vraiment brutal, <wait=20>alors ne force pas trop !","story.map1-dungeon_ex_open.042":"Bon, j\'attends ton rapport avec impatience !","story.map1-ending.001":"<size=24><rep_handlename> !!<br>Tu as réussi !!</size>","story.map1-ending.002":"Ton combat contre le Juggernaut était <wait=40>génial !","story.map1-ending.003":"Tu peux fièrement te dire Invocateur chevronné maintenant.","story.map1-ending.004":"Peut-être... <wait=40>es-tu l\'ennemi juré de Maxwell...","story.map1-ending.005":"Non, <wait=40>il n\'y a pas de peut-être !","story.map1-ending.006":"Tu dois être l\'Invocateur destiné à sauver Grand Gaia !","story.map1-ending.007":"...<wait=20>Hé ! <wait=40>Tu pourrais être un peu plus reconnaissant envers quelqu\'un qui te félicite, non ?!","story.map1-ending.008":"Tu ne peux pas montrer un peu d\'enthousiasme ? <wait=40>C\'est gênant d\'être la seule à s\'emballer.","story.map1-ending.009":"Oh ! <wait=40>Lord Lucius nous appelle !","story.map1-ending.010":"<speed=12>Enfin, nous pouvons partir pour Morgan<wait=10>.<wait=20>.<wait=30>.","story.map1-ending.011":"<anchor=center><br><br><br><br><br><br><br><br><br><br><speed=8><size=15>Je suis Lucius...<br><wait=40>Dieu de cette Porte...","story.map1-ending.012":"<anchor=center><br><br><br><br><br><speed=8><size=15><rep_handlename>... <wait=40>Sauveur de St. Lamia...","story.map1-ending.013":"<anchor=center><br><br><br><br><br><br><br><br><br><br><speed=8><size=15>Fais usage de mon pouvoir <wait=40>et aventure-toi en de nouvelles terres...","story.map1-ending.014":"<anchor=center><br><br><br><br><br><br><br><speed=8><size=15>Va de l\'avant <wait=20>et sers-toi de ton pouvoir pour ramener la paix en ce monde...","story.map1-ending.015":"<anchor=center><color=000000><speed=5><size=12>...Réveille-toi !","story.map1-ending.016":"<anchor=center><color=000000><speed=7><size=18>...Tu m\'entends ?","story.map1-ending.017":"<anchor=center><color=000000><speed=15><size=40><rep_handlename>, réveille-toi !!","story.map1-ending.018":"Pfff, <wait=40>tu dors vraiment beaucoup trop !!","story.map1-ending.019":"Quoi ? <wait=40>Où on est ? C\'est Morgan... <wait=20>Morgan !","story.map1-ending.020":"C\'est génial ! <wait=20>Les portes de Morgan sont enfin ouvertes.","story.map1-ending.021":"Enfin, hein... <wait=20>Morgan...","story.map1-ending.022":"Cet endroit était autrefois célèbre pour ses paysages pittoresques...","story.map1-ending.023":"Mais bien des années ont passé, <wait=20> et il est tombé entre les mains de Maxwell.","story.map1-ending.024":"Les monstres d\'ici sont bien plus forts que ceux de Mistral...","story.map1-ending.025":"On ne sait pas ce qui nous attend, <wait=40>alors tu ferais mieux de retourner à ton village pour te préparer.","story.map1-ending.026":"Je t\'attendrai ici.","story.map1-ending.027":"À ton retour, on se dirigera vers la Tour de Morgan, <wait=19>et là-bas on libérera cette terre !","story.map1-ending.028":"Bon, <wait=20>à plus tard !","story.map10-dungeon1.001":"<size=20>Tu es en retard ! <wait=40>T\'étais où, <rep_handlename> !</size>","story.map10-dungeon1.002":"Je me démène pour sauver ton ami, et tu oses me faire attendre !","story.map10-dungeon1.003":"Espèce d\'idiot <size=20>empoté </size>!","story.map10-dungeon1.004":"Je sais que c\'est une demande des Invocateurs Anciens, mais pourquoi est-ce à moi de lui courir après ?","story.map10-dungeon1.005":"Hé, c\'est quoi cette tête ?","story.map10-dungeon1.006":"Tu ne crois quand même pas que je vais abandonner cette mission ?","story.map10-dungeon1.007":"<size=20>Ne te moque pas de moi !</size>","story.map10-dungeon1.008":"Quand j\'aurai parfaitement rempli ma mission, c\'est ce faux jeton de Karl qui aura l\'air d\'un idiot.","story.map10-dungeon1.009":"Je n\'aurai pas beaucoup d\'autres occasions comme celle-ci.","story.map10-dungeon1.010":"Alors tu as intérêt à te reprendre et à m\'aider !","story.map10-dungeon1.011":"Si tu le fais, on pourra peut-être boucler notre enquête rapidement.","story.map10-dungeon1.012":"Je ne sais pas si c\'était la capitale de l\'empire d\'Agni ou non, ces vieilles ruines poussiéreuses se ressemblent toutes.","story.map10-dungeon1.013":"<size=20>Hé !</size>","story.map10-dungeon1.014":"Arrête de traîner et mets-toi à chercher ce fainéant de Karl !","story.map10-dungeon1.015":"Hmm ?","story.map10-dungeon1.016":"Par où commencer ?","story.map10-dungeon1.017":"Quel idiot tu fais !","story.map10-dungeon1.018":"Je me demande si cette tête sur tes épaules n\'est là que pour la décoration.","story.map10-dungeon1.019":"Mais cette disciple, Mare, est toujours à tes trousses, non ?","story.map10-dungeon1.020":"Si tu sèmes la pagaille ici, elle viendra à coup sûr en se servant de Karl comme monnaie d\'échange.","story.map10-dungeon1.021":"Ce sera notre chance de sauver cet abruti de Karl.","story.map10-dungeon1.022":"Si tu as compris, continue de faire semblant d\'enquêter comme l\'idiot que tu es et fais le plus de raffut possible !","story.map10-dungeon2.001":"<size=20>Bon sang ! </size><wait=40><size=22>Que c\'est agaçant !","story.map10-dungeon2.002":"Qu\'est-ce qu\'elle croit faire, cette femme au teint pâle, à se cacher de nous !","story.map10-dungeon2.003":"Hé ! <wait=40><rep_handlename> !","story.map10-dungeon2.004":"Tu pourrais faire un peu plus de bruit, tu ne crois pas ?","story.map10-dungeon2.005":"Va courir à découvert comme d\'habitude, qu\'on te repère plus facilement !","story.map10-dungeon2.006":"Tu es pathétique, tu ne sais même pas servir d\'appât !","story.map10-dungeon2.007":"Nngh ! <wait=40>Je suis patient, mais tu me pousses à bout.","story.map10-dungeon2.008":"Je ne peux plus attendre cette disciple.","story.map10-dungeon2.009":"Je vais chercher Karl tout seul !","story.map10-dungeon2.010":"Toi aussi, cherche-le de ton côté !","story.map10-dungeon2.011":"Je ne suis pas assez gentil pour protéger quelqu\'un qui ne me sert à rien.","story.map10-dungeon2.012":"Alors ne me suis pas, compris ?","story.map10-dungeon2.013":"<size=20>Hé ! <rep_handlename> !</size>","story.map10-dungeon2.014":"J\'ai failli oublier de te le dire.","story.map10-dungeon2.015":"Ne te laisse surtout pas attraper par cette disciple.","story.map10-dungeon2.016":"Je suis sûr que si tu te faisais prendre, c\'est encore moi qu\'on chargerait de te sauver.","story.map10-dungeon2.017":"Je ne supporterai pas une corvée de plus.","story.map10-dungeon2.018":"En fait, si tu te faisais capturer, mieux vaudrait qu\'elle te réduise en miettes.","story.map10-dungeon2.019":"<size=20>Tu m\'as bien compris, hein !?</size>","story.map10-dungeon3.001":"On dirait que je suis enfin débarrassée de ces nuisibles.","story.map10-dungeon3.002":"Hmm. <wait=40>Pourquoi cet air surpris ?","story.map10-dungeon3.003":"On dirait que tu es enfin seul.","story.map10-dungeon3.004":"Même un humain stupide aurait deviné que j\'apparaîtrais devant toi, ma proie.","story.map10-dungeon3.005":"Ou peut-être es-tu si bête que tu ne l\'as même pas remarqué ?","story.map10-dungeon3.006":"......","story.map10-dungeon3.007":"Tu cherches cette chétive excuse verte de créature vivante ?","story.map10-dungeon3.008":"Il s\'est sûrement laissé berner par les fausses informations que j\'ai laissées sur l\'endroit où se trouve Karl.","story.map10-dungeon3.009":"Il doit être en train de courir frénétiquement dans tout Agni en ce moment même.","story.map10-dungeon3.010":"Malgré sa grande gueule, il n\'est qu\'un humain.","story.map10-dungeon3.011":"Tes petits amis m\'ont causé bien des soucis, car j\'ignorais leur existence.","story.map10-dungeon3.012":"Mais il semble qu\'il ne reste plus personne pour t\'aider.","story.map10-dungeon3.013":"J\'aimerais tenter une fois de plus de prendre ta vie.","story.map10-dungeon3.014":"......","story.map10-dungeon3.015":"Cependant, tu es l\'Invocateur qui a déjà vaincu de nombreux dieux.","story.map10-dungeon3.016":"Je devrais te laisser t\'épuiser encore un peu.","story.map10-dungeon3.017":"Si tu veux sauver Karl, suis-moi.","story.map10-dungeon3.018":"Sinon, c\'en est fini de lui.","story.map10-dungeon3.019":"Même en sachant que le chemin est truffé de pièges, viendras-tu quand même à ma poursuite ?","story.map10-dungeon3.020":"Hmph. <wait=40>Vous, les humains, êtes vraiment des êtres stupides.","story.map10-dungeon3.021":"Fraie-toi un chemin à grand-peine, que je puisse m\'occuper de toi plus facilement ensuite.","story.map10-dungeon3.022":"J\'ai hâte de te voir affaibli.","story.map10-dungeon4.001":"Alors tu as franchi le Granasta Plateau.","story.map10-dungeon4.002":"Il fallait s\'y attendre de la part de celui qui a vaincu Maxwell et Cardes.","story.map10-dungeon4.003":"......","story.map10-dungeon4.004":"En te regardant, je me souviens de la guerre où les humains furent anéantis.","story.map10-dungeon4.005":"Ces humains assez stupides pour croire qu\'ils pouvaient s\'opposer aux dieux.","story.map10-dungeon4.006":"D\'ailleurs, à cette époque, il y avait un autre humain aussi tenace que toi.","story.map10-dungeon4.007":"Il semble que les autres humains le considéraient comme un héros.","story.map10-dungeon4.008":"Pourtant, il était tout aussi impuissant et désespérément effrayé que toi en ce moment.","story.map10-dungeon4.009":"Aussi puissant qu\'il fût pour un humain...","story.map10-dungeon4.010":"...cela ne changeait rien au fait qu\'il n\'était qu\'un humain ignorant.","story.map10-dungeon4.011":"Toi aussi, tu finiras par afficher la même expression.","story.map10-dungeon4.012":"J\'ai hâte de m\'en délecter.","story.map10-dungeon4.013":"......","story.map10-dungeon4.014":"Hmph. <wait=40>Ce regard ne m\'intéresse pas.","story.map10-dungeon4.015":"Je suppose qu\'il faut te faire souffrir encore un peu.","story.map10-dungeon4.016":"Qu\'en dis-tu ?","story.map10-dungeon4.017":"Voyons jusqu\'où tu peux aller seul.","story.map10-dungeon5.001":"<rep_handlename>. Tu choisis donc toujours de résister.","story.map10-dungeon5.002":"Je déteste ces yeux, <wait=40>et leur absence de désespoir.","story.map10-dungeon5.003":"Comment peux-tu encore garder espoir dans une telle situation ?","story.map10-dungeon5.004":"Aucun des alliés qui te soutenaient n\'est encore là.","story.map10-dungeon5.005":"Pas même ton ami d\'enfance.","story.map10-dungeon5.006":"Ni la jeune Invocatrice qui ne cessait de t\'insulter.","story.map10-dungeon5.007":"Ni le vieil homme et ses attentes ridicules envers toi.","story.map10-dungeon5.008":"Ni cette créature incroyablement vulgaire.","story.map10-dungeon5.009":"Pas même le dieu de bas rang qui se servait de toi depuis le début.","story.map10-dungeon5.010":"......","story.map10-dungeon5.011":"Ou veux-tu me dire que, depuis le tout début, tu ne t\'es jamais reposé sur personne ?","story.map10-dungeon5.012":"Et malgré cela, tu t\'acharnes à vouloir sauver tes amis ?","story.map10-dungeon5.013":"Quelle idée incompréhensible.","story.map10-dungeon5.014":"......","story.map10-dungeon5.015":"Je vois, je m\'en souviens maintenant.","story.map10-dungeon5.016":"D\'ailleurs, <wait=20>une fois, alors que cet homme était dans une situation désespérée...","story.map10-dungeon5.017":"...il a éveillé un nouveau pouvoir en lui.","story.map10-dungeon5.018":"De grandes ailes de flammes ont surgi dans son dos.","story.map10-dungeon5.019":"Je souhaite depuis longtemps oublier l\'humiliation de ce pouvoir qu\'il maniait.","story.map10-dungeon5.020":"Si tu portes le même pouvoir en toi, alors je n\'ai plus de temps à perdre.","story.map10-dungeon5.021":"Hmph...","story.map10-dungeon5.022":"Mais je ne peux pas te laisser rester planté là à me faire perdre mon temps.","story.map10-dungeon5.023":"La bataille entre Lord Zefalhua et Afla Dilith est imminente.","story.map10-dungeon5.024":"Je dois en finir avec toi avant que tu ne contraries mes prédictions.","story.map10-dungeon5.025":"Es-tu prêt ?","story.map10-dungeon5.026":"Je vais te montrer un monde de désespoir comme tu n\'en as jamais vu.","story.map10-dungeon5.027":"Je ne vais pas me retenir, alors contemple mon véritable pouvoir !","story.map10-dungeon5.028":"Encaisse-le de toutes tes forces !","story.map10-dungeon6.001":"Ça suffit, <wait=40><rep_handlename>.","story.map10-dungeon6.002":"Tu t\'es bien battu contre les dieux jusqu\'à présent.","story.map10-dungeon6.003":"Cependant, vu les blessures qui couvrent ton corps, je vois que tu ne peux plus te battre.","story.map10-dungeon6.004":"Je ne laisserai pas Lucius et ses prédictions aller plus loin !","story.map10-dungeon6.005":"Meurs !","story.map10-dungeon6.006":"<size=18>*Kliiiing*","story.map10-dungeon6.007":"Nngh !","story.map10-dungeon6.008":"Comment as-tu pu te laisser mettre dans un tel pétrin par une femme pareille ?","story.map10-dungeon6.009":"Franchement, <wait=20>tu es vraiment un idiot.","story.map10-dungeon6.010":"Hé, ressaisis-toi !","story.map10-dungeon6.011":"Ne te fais pas battre avant qu\'on ait pu sauver Karl !","story.map10-dungeon6.012":"Idiote ! <wait=20>Tu comptes encore bouger malgré tes blessures ?","story.map10-dungeon6.013":"Ne te moque pas de moi.","story.map10-dungeon6.014":"Tu croyais vraiment qu\'une telle attaque suffirait à m\'abattre ?","story.map10-dungeon6.015":"Pour une disciple, tu es vraiment stupide.","story.map10-dungeon6.016":"Comme c\'est humain de ta part.","story.map10-dungeon6.017":"<size=18>*Klaaaang*","story.map10-dungeon6.018":"Nngh !","story.map10-dungeon6.019":"Qu\'est-ce que tu fais plantée là ?","story.map10-dungeon6.020":"Ton combat contre <rep_handlename> t\'a peut-être paralysée ?","story.map10-dungeon6.021":"C\'est ça, <wait=20>pour Karl, <wait=20>Lugina est déjà en route pour le délivrer de l\'Ocean Shrine.","story.map10-dungeon6.022":"Et toi qui pensais l\'avoir si habilement dupé. <wait=20>Quel dommage.","story.map10-dungeon6.023":"C\'est impossible.","story.map10-dungeon6.024":"Nngh, <rep_handlename>. <wait=20>On dirait que tu as échappé de justesse à la mort cette fois.","story.map10-dungeon6.025":"Même si tout ce qui t\'est revenu, c\'est un Invocateur criblé de blessures.","story.map10-dungeon6.026":"Je vous détruirai tous les deux une fois que j\'en aurai fini avec cette créature vulgaire.","story.map10-dungeon6.027":"......","story.map10-dungeon6.028":"......<wait=40>Je ne la sens plus.","story.map10-dungeon6.029":"Nngh.","story.map10-dungeon6.030":"*Pff* <wait=20>*pff* <wait=20>*Pff* ","story.map10-dungeon6.031":"Ç-<wait=20>Ça va.","story.map10-dungeon6.032":"Une partie de la douleur est juste revenue après son départ.","story.map10-dungeon6.033":"Quand même, je suis contente qu\'on ait réussi à la duper.","story.map10-dungeon6.034":"Écoute...<wait=40>On ne peut pas rester là, il faut aller à l\'Ocean Shrine.","story.map10-dungeon6.035":"Je suis sûre que c\'est là que Karl est retenu.","story.map10-dungeon6.036":"C\'est quoi cette tête ?","story.map10-dungeon6.037":"Je n\'ai pas le temps de rester là à discuter avec toi.","story.map10-dungeon6.038":"Promis, on parlera plus tard, alors pour l\'instant, allons chercher Karl.","story.map10-dungeon7.001":"*Pff* *pff* *pff*","story.map10-dungeon7.002":"On est enfin arrivés à l\'Ocean Shrine.","story.map10-dungeon7.003":"On dirait que tu es à bout de forces.","story.map10-dungeon7.004":"Encore elle.","story.map10-dungeon7.005":"Je reconnais qu\'il faut du courage pour te présenter devant moi aussi meurtri et brisé que tu l\'es.","story.map10-dungeon7.006":"Hmph. <wait=40>Quelle prétention.","story.map10-dungeon7.007":"Alors que je t\'ai piégée pour que tu me dises où tu retenais Karl.","story.map10-dungeon7.008":"...Bande d\'idiots.","story.map10-dungeon7.009":"Je vois que tu t\'es péniblement frayé un chemin jusqu\'à moi à travers Lognea Cove.","story.map10-dungeon7.010":"Tu crois pouvoir m\'échapper avec de telles blessures ?","story.map10-dungeon7.011":"Nngh...","story.map10-dungeon7.012":"Mes serviteurs !","story.map10-dungeon7.013":"Rassemblez-vous et débarrassez le monde de ces insectes !","story.map10-dungeon7.014":"Qu-Qu\'est-ce que c\'est ? <wait=20>D\'où sortent-ils tous !?","story.map10-dungeon7.015":"Ce n\'est pas gênant, pour un dieu comme toi, d\'en appeler autant juste pour combattre des humains ?","story.map10-dungeon7.016":"Cesse tes divagations stupides.","story.map10-dungeon7.017":"C\'est ici que je me débarrasserai enfin de toi.","story.map10-dungeon7.018":"C\'est tout.","story.map10-dungeon7.019":"<rep_handlename> !","story.map10-dungeon7.020":"Regrette ton défi insensé envers les dieux, et meurs !","story.map10-dungeon7.021":"Nngh... <wait=40>C\'est mauvais, <wait=40>ils sont bien trop nombreux.","story.map10-dungeon7.022":"Ça ne te ressemble pas d\'être aussi craintif dans une situation pareille.","story.map10-dungeon7.023":"Cette voix !","story.map10-dungeon7.024":"C-Comment as-tu...","story.map10-dungeon7.025":"Salut. <wait=40>Désolé de t\'avoir fait attendre.","story.map10-dungeon7.026":"Karl !","story.map10-dungeon7.027":"Comment as-tu...","story.map10-dungeon7.028":"Tu étais encore enfermé dans cette pièce la dernière fois que j\'ai vérifié...","story.map10-dungeon7.029":"C\'est quand tu es venue vérifier que j\'ai compris où je me trouvais.","story.map10-dungeon7.030":"Ô dieu à l\'intelligence si limitée.","story.map10-dungeon7.031":"Comment oses-tu...","story.map10-dungeon7.032":"Lugina ! <wait=20>Pourquoi tu as mis autant de temps !","story.map10-dungeon7.033":"Silence !","story.map10-dungeon7.034":"Ça m\'a pris un temps fou de le délivrer, tellement il est paresseux !","story.map10-dungeon7.035":"Je t\'ai déjà dit que j\'étais désolé.","story.map10-dungeon7.036":"Ah oui, et Seria...","story.map10-dungeon7.037":"Comment t\'es-tu retrouvée dans cet état ?","story.map10-dungeon7.038":"Ce n\'est pas ma faute, quelqu\'un me ralentissait !","story.map10-dungeon7.039":"C\'est bon, oublions ça !","story.map10-dungeon7.040":"On a quelque chose à régler ici.","story.map10-dungeon7.041":"N\'est-ce pas, Mare ?","story.map10-dungeon7.042":"Ton plan est déjà tombé à l\'eau.","story.map10-dungeon7.043":"Que comptes-tu faire maintenant ?","story.map10-dungeon7.044":"Humain, oses-tu te croire au-dessus des dieux ?","story.map10-dungeon7.045":"Je te félicite d\'avoir dépassé mes attentes.","story.map10-dungeon7.046":"Mais malgré mon respect pour toi, je vais abandonner mes plans et simplement te faire détruire.","story.map10-dungeon7.047":"Moi, Mare, disciple de Lord Zevalhua, je vous l\'ordonne !","story.map10-dungeon7.048":"Mes serviteurs !","story.map10-dungeon7.049":"Rassemblez-vous autour de moi et détruisez mes ennemis !","story.map10-dungeon7.050":"Tuez tous les humains devant moi !","story.map10-dungeon7.051":"On dirait qu\'un bon nombre d\'entre eux sont déjà rassemblés ici.","story.map10-dungeon7.052":"Ils sont bien plus nombreux qu\'avant.","story.map10-dungeon7.053":"Humains. <wait=40>Vous vous êtes bien battus.","story.map10-dungeon7.054":"Je me souviendrai de vous...","story.map10-dungeon7.055":"...et de la fin tragique qui vous attend.","story.map10-dungeon7.056":"Où crois-tu aller comme ça !","story.map10-dungeon7.057":"Écartez-vous tous de mon chemin !","story.map10-dungeon7.058":"Il y en a tellement.","story.map10-dungeon7.059":"Karl, <wait=40>tu es blessé...","story.map10-dungeon7.060":"Haha, <wait=20>cette disciple m\'a juste un peu malmené, c\'est tout...","story.map10-dungeon7.061":"Ne prends pas ça à la légère !","story.map10-dungeon7.062":"Mais Seria, toi aussi tu es blessée...","story.map10-dungeon7.063":"C-C\'est juste...","story.map10-dungeon7.064":"Regardez-moi toutes ces créatures pitoyables !","story.map10-dungeon7.065":"Hé ! <wait=40><rep_handlename> !","story.map10-dungeon7.066":"J\'en ai marre de courir partout.","story.map10-dungeon7.067":"Toi, poursuis cette femme pâle et abats-la !","story.map10-dungeon7.068":"Je m\'occupe de ces deux-là pendant ton absence !","story.map10-dungeon7.069":"On n\'a pas besoin que tu t\'occupes de nous !","story.map10-dungeon7.070":"Désolé de t\'avoir inquiété, <rep_handlename>.","story.map10-dungeon7.071":"Laisse-nous gérer ici et pars à la poursuite de cette disciple.","story.map10-dungeon7.072":"Je me rattraperai, c\'est promis.","story.map10-dungeon7.073":"On compte sur toi, <wait=20><rep_handlename>.","story.map10-dungeon_ex_clear.001":"<size=18>*Bzz* </size><wait=20><size=20>*Bz</size><wait=10><size=19>zzzz* </size><wait=40><size=18>*Bzzzzzz*</size>","story.map10-dungeon_ex_clear.002":"<size=18>Tu m\'en...</size> <wait=20><size=20> *Bzz...zzz*</size>","story.map10-dungeon_ex_clear.003":"<size=20>*Bzz*</size> <size=18>...M\'sieur...?</size> <wait=20>*Bzz*</size>","story.map10-dungeon_ex_clear.004":"<size=18>*Bzz*</size><wait=20><size=20> Ah, voilà !</size>","story.map10-dungeon_ex_clear.005":"C\'est tellement dur de capter du signal au fond de ces donjons.","story.map10-dungeon_ex_clear.006":"Bref, <wait=20>laisse-moi te dire ce que j\'ai découvert.","story.map10-dungeon_ex_clear.007":"D\'après des textes anciens...","story.map10-dungeon_ex_clear.008":"...cet endroit est scellé depuis la fin de l\'Empire d\'Agni.","story.map10-dungeon_ex_clear.009":"Mais 100 ans auparavant, un empereur y avait été emprisonné en secret.","story.map10-dungeon_ex_clear.010":"Beaucoup de temps a passé sans que personne ne sache qu\'il était là-dessous. ","story.map10-dungeon_ex_clear.011":"Cet empereur était craint de son entourage et considéré comme un tyran.","story.map10-dungeon_ex_clear.012":"En réalité, <wait=20>ce n\'étaient pas seulement ses sujets qui le craignaient, mais aussi leurs enfants.","story.map10-dungeon_ex_clear.013":"Un jour, un enfant qui avait souffert de sa main tomba malade et mourut.","story.map10-dungeon_ex_clear.014":"C\'est pour cette raison qu\'il fut emprisonné en secret.","story.map10-dungeon_ex_clear.015":"Au fil du temps, dans ce cachot plongé dans le noir, la colère de l\'empereur grandit avec sa solitude.","story.map10-dungeon_ex_clear.016":"Il renaquit sous la forme d\'un spectre extrêmement puissant et se vengea de l\'empire pendant 100 ans.","story.map10-dungeon_ex_clear.017":"Résultat, <wait=20>le fantôme de l\'empereur fut scellé avec le donjon.","story.map10-dungeon_ex_clear.018":"Il est toujours quelque part là-dessous, <wait=20>et sa colère grandit de seconde en seconde.","story.map10-dungeon_ex_clear.019":"Rien que d\'y penser, ça fait peur.","story.map10-dungeon_ex_clear.020":"Monsieur, <wait=20>pas besoin de te surmener pour trouver ce fantôme !","story.map10-dungeon_ex_clear.021":"Il te suffit d\'évaluer précisément à quel point cet endroit est dangereux.","story.map10-dungeon_ex_clear.022":"Qu-<wait=20>Quoi ?<wait=40> Qu\'est-ce que tu viens de dire ?","story.map10-dungeon_ex_clear.023":"Pas possible !","story.map10-dungeon_ex_clear.024":"Tu as vaincu le fantôme de l\'empereur pendant que je faisais mes recherches !?","story.map10-dungeon_ex_clear.025":"Waouh, monsieur...<wait=20>tu es incroyable.","story.map10-dungeon_ex_clear.026":"Mais attends ! <wait=40>Attends une seconde !","story.map10-dungeon_ex_clear.027":"J\'aurais vraiment voulu que tu attendes que j\'aie fini mes recherches...","story.map10-dungeon_ex_clear.028":"Hmm...<wait=20> Enfin bref !","story.map10-dungeon_ex_clear.029":"La prochaine fois, je ferai de mon mieux pour te transmettre les informations le plus vite possible !","story.map10-dungeon_ex_clear.030":"Je vais te prouver que tu n\'es pas le seul à avoir progressé !","story.map10-dungeon_ex_clear.031":"Je te recontacte bientôt, alors attends-moi !","story.map10-dungeon_ex_open.001":"<size=18>*Bzz* </size><wait=20><size=20>*Bz</size><wait=10><size=19>zzzz* </size><wait=40><size=18>*Bzzzzzz*</size>","story.map10-dungeon_ex_open.002":"<size=18>Mon...</size> <wait=20><size=20>*Bzz...zzz*</size>","story.map10-dungeon_ex_open.003":"<size=20>*Bzz*</size> <size=18>...m\'entends...?</size> <wait=20>*Bzz*</size>","story.map10-dungeon_ex_open.004":"<size=18>*Bzz*</size><wait=20><size=20>Monsieur !</size>","story.map10-dungeon_ex_open.005":"Enfin, on est connectés !","story.map10-dungeon_ex_open.006":"On dirait que tu es dans un endroit où ça capte plutôt mal.","story.map10-dungeon_ex_open.007":"Bref, <wait=20>je reprends depuis le début.","story.map10-dungeon_ex_open.008":"Je suis Lin Merylham, du Soutien logistique...","story.map10-dungeon_ex_open.009":"...du Bureau d\'enquête de l\'Office d\'exploration de Grand Gaia, à ton service.","story.map10-dungeon_ex_open.010":"Nous avons constaté l\'autre jour la disparition d\'une grande puissance dans la région d\'Agni. ","story.map10-dungeon_ex_open.011":"Il semble que cela ait provoqué l\'ouverture d\'une structure souterraine autrefois scellée. ","story.map10-dungeon_ex_open.012":"D\'après nos archives, <wait=20>quelque chose de très sinistre y était enfermé.","story.map10-dungeon_ex_open.013":"Ta mission, cette fois, est d\'aller y mettre un terme...","story.map10-dungeon_ex_open.014":"...avant que ça ne puisse sortir et causer des dégâts !","story.map10-dungeon_ex_open.015":"Il semble que cette structure ait été un cachot, il y a très, très longtemps.","story.map10-dungeon_ex_open.016":"Hein ? <wait=40>Tu y es déjà ?","story.map10-dungeon_ex_open.017":"Ça ne m\'étonne pas !","story.map10-dungeon_ex_open.018":"Bon, <wait=20>je vais faire mon possible pour en savoir plus sur ce donjon.","story.map10-dungeon_ex_open.019":"J\'aurai de nouvelles informations pour toi avant la fin de ton enquête.","story.map10-dungeon_ex_open.020":"Tiens bon encore un petit peu !","story.map10-ending.001":"B-<wait=20>Bande d\'idiots...","story.map10-ending.002":"Comment un dieu tel que moi a-t-il pu être vaincu par des humains...","story.map10-ending.003":"S-Soit !","story.map10-ending.004":"<size=20>Je vais tous vous ensevelir avec ce sanctuaire !</size>","story.map10-ending.005":"<size=14>*Grondement* *grondement*</size>","story.map10-ending.006":"<size=21>Je ne te laisserai pas faire !</size>","story.map10-ending.007":"Nngh, <wait=40>toi aussi, tu as survécu !","story.map10-ending.008":"Tilith, disciple de Lucius !","story.map10-ending.009":"Je suis là, <rep_handlename> !","story.map10-ending.010":"Bon, sortons tous d\'ici !","story.map10-ending.011":"Attends, <rep_handlename> !","story.map10-ending.012":"Ne crois pas avoir déjà gagné !","story.map10-ending.013":"Peu importe combien vous êtes à vous unir.","story.map10-ending.014":"Face à Lord Zevalhua, vous n\'êtes rien !","story.map10-ending.015":"Et surtout, la pièce maîtresse parmi vous est...","story.map10-ending.016":"<size=15>*Grondement* *grondement*</size>","story.map10-ending.017":"Mare ! <wait=40>Rends-toi à l\'évidence, tu as perdu !","story.map10-ending.018":"<rep_handlename> ! <wait=40>Tout le monde t\'attend !","story.map10-ending.019":"On y va !","story.map10-ending.020":"<size=16>*Grondement* *grondement*</size>","story.map10-ending.021":"Nngh...","story.map10-ending.022":"<size=19>Lord Zevalhua...</size>","story.map10-ending.023":"<size=18>*Grondement* *grondement*</size>","story.map10-ending.024":"<rep_handlename> !","story.map10-ending.025":"Tu as réussi !","story.map10-ending.026":"Je savais que tu pouvais vaincre Mare, mon <rep_handlename> !","story.map10-ending.027":"A-Aïe...","story.map10-ending.028":"Toujours aussi brutale en vol, à ce que je vois, <wait=40> Déesse.","story.map10-ending.029":"Tu ne pourrais pas faire un tout petit peu plus attention ?","story.map10-ending.030":"Hé, <wait=20>vous deux, arrêtez de vous plaindre !","story.map10-ending.031":"Quand même, je suis contente que vous alliez bien tous les deux, Karl et Seria.","story.map10-ending.032":"J\'étais vraiment inquiète en te portant, Seria, blessée comme tu l\'es !","story.map10-ending.033":"Merci pour ça...","story.map10-ending.034":"Oui, <wait=20>je te suis reconnaissant à toi aussi, Déesse.","story.map10-ending.035":"Et bien sûr à toi aussi, <rep_handlename> !","story.map10-ending.036":"Mais ne prends pas la grosse tête, ça nous ferait passer pour des nuls.","story.map10-ending.037":"Désolé d\'avoir mis autant de temps à me remettre.","story.map10-ending.038":"En tout cas, tu as été génial comme toujours, <rep_handlename> !","story.map10-ending.039":"Tu as vaincu Mare !","story.map10-ending.040":"Oui, <wait=20>c\'est vrai.","story.map10-ending.041":"<rep_handlename>, <wait=40>je suis vraiment fier de pouvoir t\'appeler mon ami proche.","story.map10-ending.042":"C\'est vrai, Karl.","story.map10-ending.043":"Euh...","story.map10-ending.044":"Je ne veux pas jouer les rabat-joie, mais on n\'oublie pas quelqu\'un ?","story.map10-ending.045":"C\'est vrai ! <wait=40>Lugina !","story.map10-ending.046":"Où peut-il bien être ?","story.map10-ending.047":"C\'est qui, Lugina ?","story.map10-ending.048":"Je vois, tu n\'as pas encore rencontré Lugina en personne, n\'est-ce pas, Déesse ?","story.map10-ending.049":"Pas possible, <wait=40>tu veux dire que tu n\'as ramené que nous ?","story.map10-ending.050":"Euh, <wait=40>déjà, je ne savais même pas qu\'il y avait quelqu\'un d\'autre.","story.map10-ending.051":"Tu parles peut-être de la personne qui était à moitié enterrée dans le sol ?","story.map10-ending.052":"<size=21>Lugina !</size>","story.map10-ending.053":"<size=22>Bande d\'abrutis ! <wait=40>Je vais tous vous assommer !</size>","story.map10-ending.054":"Hé, au moins tu es arrivé ici en un seul morceau.","story.map10-ending.055":"Héhé... <wait=20>Tu étais dans un sacré état tout à l\'heure, Lugina.","story.map10-ending.056":"<size=20>Sale gamine ! <wait=40>C\'est toi qui vas prendre le plus cher !","story.map10-ending.057":"Seria, j\'ai dit arrête !","story.map10-ending.058":"Lugina, <wait=40>tu nous as vraiment sauvés cette fois.","story.map10-ending.059":"Merci.","story.map10-ending.060":"Heh, <wait=20>je ne vous ai aidés que parce que le Hall des Invocateurs me l\'a demandé.","story.map10-ending.061":"Honnêtement, peu importait de qui il s\'agissait.","story.map10-ending.062":"Quand même, comment as-tu su où j\'étais retenu ?","story.map10-ending.063":"C\'était facile.","story.map10-ending.064":"Je savais que cette femme essaierait d\'isoler cette tête de mule.","story.map10-ending.065":"Alors je savais que si je créais une telle situation, elle accourrait à coup sûr.","story.map10-ending.066":"Cependant, elle était très prudente.","story.map10-ending.067":"Karl, <wait=20>j\'avais prévu qu\'elle se servirait de toi comme appât en se rapprochant peu à peu.","story.map10-ending.068":"Le reste était réglé avant même que je quitte Elgaia.","story.map10-ending.069":"Je n\'avais plus qu\'à dire à cette idiote de sauver cet abruti.","story.map10-ending.070":"<size=20>Qui tu traites d\'idiote !</size>","story.map10-ending.071":"Eh bien, <wait=40>ton idée a fini par me sauver.","story.map10-ending.072":"Dès mon arrivée, j\'ai mentionné à cette disciple le nom de l\'endroit voisin dont tu m\'avais parlé.","story.map10-ending.073":"À peine l\'avais-je dit que, comme tu l\'avais prévu, elle est partie.","story.map10-ending.074":"Heh, <wait=40>c\'était facile à deviner, sachant quand tu arriverais.","story.map10-ending.075":"Il n\'y avait vraiment pas beaucoup d\'endroits où cacher quelqu\'un.","story.map10-ending.076":"Cette disciple stupide <wait=20>a fait exactement ce que je pensais.","story.map10-ending.077":"Elle est partie à l\'Ocean Shrine vérifier son prisonnier.","story.map10-ending.078":"Et ce faisant, elle m\'a mené droit à lui.","story.map10-ending.079":"Waouh, c\'est incroyable, Lugina.","story.map10-ending.080":"<size=19>Difficile de croire que quelqu\'un comme toi ait pu réussir un coup pareil.</size>","story.map10-ending.081":"<size=21>Comment oses-tu !<\\\\size>","story.map10-ending.082":"Alors c\'est toi, Lugina !","story.map10-ending.083":"Enchantée !","story.map10-ending.084":"Je suis Tilith, la déesse qui veille sur <rep_handlename>.","story.map10-ending.085":"Je suis une disciple de Lucius.","story.map10-ending.086":"Une déesse disciple de Lucius ?","story.map10-ending.087":"Hé, <rep_handlename> !","story.map10-ending.088":"Elle est folle ou quoi, cette fille ?","story.map10-ending.089":"T\'es méchant !","story.map10-ending.090":"Dire que c\'est moi qui t\'ai ramené de l\'Ocean Shrine !","story.map10-ending.091":"C\'était toi ?","story.map10-ending.092":"Bon, si c\'est le cas...","story.map10-ending.093":"Oui, c\'est une vraie déesse.","story.map10-ending.094":"<size=18>Pas possible...</size>","story.map10-ending.095":"Ce vieux fou de Grahdens.","story.map10-ending.096":"De quoi il parlait, au juste...","story.map10-ending.097":"Oh, et Lugina...","story.map10-ending.098":"C\'est Grahdens qui t\'a demandé de nous sauver, n\'est-ce pas ?","story.map10-ending.099":"Qu\'est-ce qu\'il mijote encore, le vieux ?","story.map10-ending.100":"Quoi !? <wait=20>Comment je le saurais ?","story.map10-ending.101":"Il doit sûrement se balader quelque part.","story.map10-ending.102":"Si tu parles de l\'Ancien Grahdens, il a été capturé par Zevalhua.","story.map10-ending.103":"C\'est toi...","story.map10-ending.104":"Ça fait longtemps, <rep_handlename>.","story.map10-ending.105":"Mais il semble que je n\'aie encore rencontré aucun de tes amis.","story.map10-ending.106":"J\'avais hâte de tous vous rencontrer.","story.map10-ending.107":"Qu\'est-ce qu\'un minable garde impérial comme toi fait ici ?","story.map10-ending.108":"Avant ça, comment ça, le vieux a été capturé ?","story.map10-ending.109":"Hé hé hé, <wait=20>ne sois pas si impatient.","story.map10-ending.110":"Moi aussi, j\'ai des questions à poser.","story.map10-ending.111":"Comme par exemple pourquoi tu es encore en vie après avoir été capturé par cette disciple.","story.map10-ending.112":"Mais nous pourrons parler des détails à Milvana.","story.map10-ending.113":"Cela vous convient-il, à vous deux...","story.map10-ending.114":"<rep_handlename> et Tilith, disciple de Lord Lucius ?","story.map10-ending.115":"Oui, ça me convient.","story.map10-ending.116":"Lord Lucius nous ouvrira sûrement bientôt un chemin vers Milvana.","story.map10-ending.117":"Ça commence déjà à devenir pénible.","story.map10-ending.118":"Karl, <wait=40>ça va ?","story.map10-ending.119":"Grahdens...","story.map10-open.001":"<anchor=center><br><br><br><br><br><br><br><br><br><br><speed=8><size=15>Je suis Lucius...<br><wait=40>Dieu de cette Porte...","story.map10-open.002":"<anchor=center><br><br><br><br><br><br><br><br><br><br><speed=8><size=15>Toi, <rep_handlename>,<wait=39> qui as libéré Ryvern...","story.map10-open.003":"<anchor=center><br><br><br><br><br><br><br><br><br><br><speed=8><size=15>Use de mon pouvoir <wait=40>et aventure-toi sur de nouvelles terres...","story.map10-open.004":"<anchor=center><br><br><br><br><br><br><br><br><br><br><speed=8><size=15>Afin d\'apporter un nouvel espoir à ce monde sans ordre...","story.map10-open.005":"<anchor=center><br><br><br><br><br><br><br><br><br><br><speed=8><size=15>Tu dois avoir foi en ton pouvoir, <wait=20>et continuer d\'avancer...","story.map10-open.006":"<size=21><rep_handlename> ! <wait=40>Pourquoi tu as mis autant de temps !</size>","story.map10-open.007":"Faire attendre celui qui t\'a sauvé la vie, comme toujours, je n\'en reviens pas.","story.map10-open.008":"Peu importe.","story.map10-open.009":"Je vais être gentil et t\'expliquer les choses, à toi et à ta cervelle d\'abruti.","story.map10-open.010":"Pourquoi c\'est toi qui m\'as trouvé là-bas, bien sûr !","story.map10-open.011":"J\'ai eu une vision.","story.map10-open.012":"Grâce à mon esprit de génie, j\'ai pu prévoir le pétrin dans lequel tu finirais par te fourrer.","story.map10-open.013":"......","story.map10-open.014":"Tu ne me crois pas, <wait=20>hein ?","story.map10-open.015":"Hmph, <wait=20>peu importe.","story.map10-open.016":"C\'était le vieux Grahdens.","story.map10-open.017":"Il m\'a demandé de vous suivre tous.","story.map10-open.018":"C\'était une demande directe des Invocateurs Anciens, adressée à moi.","story.map10-open.019":"Ça prouve que le Hall des Invocateurs a foi en ma force !","story.map10-open.020":"<size=21>Ha ha ha ha !</size>","story.map10-open.021":"Bref, <wait=20>ce qu\'ils voulaient vraiment, c\'est que je sauve cet incapable de Karl.","story.map10-open.022":"......","story.map10-open.023":"Tu vas m\'aider avec ça.","story.map10-open.024":"Tu n\'oserais pas refuser les souhaits de celui à qui tu dois la vie, hein ?","story.map10-open.025":"Bon, je me mets en route vers l\'Empire d\'Agni.","story.map10-open.026":"Si mes informations sont exactes, c\'est là que Karl est retenu.","story.map10-open.027":"Ça ne va pas être facile, mais tout commence à l\'empire.","story.map10-open.028":"Ce n\'est pas le moment d\'hésiter ! Tu m\'entends ?","story.map10-open.029":"Ah oui !","story.map10-open.030":"Cette disciple, Mare, a toujours un œil sur toi, non ?","story.map10-open.031":"Tu ferais bien de prier pour qu\'elle ne te rattrape pas !","story.map10-open.032":"<size=22>Ha ha ha ha !</size>","story.map11-dungeon1.001":"<rep_handlename>...<wait=40>tu es en retard !! ","story.map11-dungeon1.002":"Arrête de lambiner !","story.map11-dungeon1.003":"Franchement...","story.map11-dungeon1.004":"Pourquoi tu nous as fait attendre aussi longtemps dans un endroit aussi chaud ?","story.map11-dungeon1.005":"Tiens, tiens ! <wait=20>On dirait que vous vous entendez plutôt bien, tous les deux.","story.map11-dungeon1.006":"<speed=15><size=21>Te moque pas de moi ! Arrête de te moquer de moi !</size></speed>","story.map11-dungeon1.007":"Waouh...<wait=20>vous dites même exactement la même chose !","story.map11-dungeon1.008":"<speed=15><size=21>Qu\'est-ce que t\'as dit ?! T\'as dit quoi ?!</size></speed>","story.map11-dungeon1.009":"Déesse, <wait=40>c\'est bien la Paris de la Garde impériale ?","story.map11-dungeon1.010":"Je t\'en supplie, ne me mets pas encore plus de fardeaux sur les épaules...","story.map11-dungeon1.011":"Les parents qui m\'ont élevé ont déjà bien assez d\'ennuis comme ça...","story.map11-dungeon1.012":"Héhé... <wait=20>Désolée.","story.map11-dungeon1.013":"Et<wait=20><rep_handlename> est venu aussi.","story.map11-dungeon1.014":"Peux-tu me raconter la suite le plus vite possible ?","story.map11-dungeon1.015":"C\'est vrai que l\'Ancien Grahdens a été capturé par Zevalhua ?","story.map11-dungeon1.016":"Oui, c\'est vrai.","story.map11-dungeon1.017":"Je ne peux pas vraiment entrer dans les détails,","story.map11-dungeon1.018":"mais je tiens l\'information d\'un membre fiable de la Garde impériale, alors elle est très crédible.","story.map11-dungeon1.019":"Je vois...","story.map11-dungeon1.020":"Tss.<wait=40> Pourquoi ce vieil Invocateur a-t-il fallu qu\'il se fasse capturer ? ","story.map11-dungeon1.021":"Quelle plaie.","story.map11-dungeon1.022":"Lugy ! <wait=40> Ne dis pas des choses pareilles !","story.map11-dungeon1.023":"Tu sais bien qu\'Elder Grah se démène pour nous tous !","story.map11-dungeon1.024":"Lugy ?!","story.map11-dungeon1.025":"Lugy... <wait=80> Héhé...","story.map11-dungeon1.026":"Quel surnom répugnant...","story.map11-dungeon1.027":"Tu as assurément une qualité que les humains ne peuvent comprendre, Déesse.","story.map11-dungeon1.028":"Madame de la Garde impériale, tu te trompes.","story.map11-dungeon1.029":"Elle est juste un peu folle, c\'est tout.","story.map11-dungeon1.030":"Vous êtes trop méchants, tous les deux !!!","story.map11-dungeon1.031":"Seria, <wait=40>ça suffit, d\'accord ?","story.map11-dungeon1.032":"Si tu continues comme ça, on n\'avancera jamais.","story.map11-dungeon1.033":"Et toi...<wait=20> On peut juste t\'appeler Paris ?","story.map11-dungeon1.034":"Héhé.<wait=20> Rien que m\'appeler par mon nom est un honneur, ô célèbre Invocateur Karl.","story.map11-dungeon1.035":"Ne te moque pas de moi.","story.map11-dungeon1.036":"Bref, on est sûrs que l\'Ancien est quelque part ici, à Mirvana ?","story.map11-dungeon1.037":"Oui. <wait=40>J\'en ai bien peur.","story.map11-dungeon1.038":"Je pense que si Elder Grah a été capturé par Zevalhua, il est sûrement quelque part à Mirvana, lui aussi.","story.map11-dungeon1.039":"Parce que grâce à tous les efforts de <rep_handlename>, ","story.map11-dungeon1.040":"c\'est le seul endroit encore sous le contrôle de Zevalhua.","story.map11-dungeon1.041":"Et si c\'est le cas, <wait=40> ce serait plus rapide de nous séparer pour chercher les endroits suspects.","story.map11-dungeon1.042":"Je suppose qu\'on n\'a pas le choix, il faut diviser nos forces, hein ?","story.map11-dungeon1.043":"Alors vous n\'avez qu\'à rester hors de mon chemin !","story.map11-dungeon1.044":"Oui, oui. On a compris.","story.map11-dungeon1.045":"Fais de ton mieux, Lugy !","story.map11-dungeon1.046":"Sale gamine ! <wait=40>Je vais te réduire en bouillie !","story.map11-dungeon1.047":"On dirait qu\'avoir quelque chose à faire va rendre les choses amusantes à nouveau !","story.map11-dungeon1.048":"Quelle corvée...","story.map11-dungeon1.049":"<rep_handlename>, <wait=40><br>on compte sur toi pour celle-là.","story.map11-dungeon1.050":"Aide l\'Ancien avec le même pouvoir que tu as utilisé pour m\'aider !","story.map11-dungeon2.001":"Hmm...","story.map11-dungeon2.002":"On dirait qu\'il n\'y a aucun endroit suspect par ici...","story.map11-dungeon2.003":"Hein... ?","story.map11-dungeon2.004":"Ah, Karl !","story.map11-dungeon2.005":"Bonjour, Déesse.","story.map11-dungeon2.006":"Tu as trouvé des indices de ton côté ?","story.map11-dungeon2.007":"Malheureusement, non.","story.map11-dungeon2.008":"Sérieusement, <wait=20>où peut bien être l\'Ancien... ?","story.map11-dungeon2.009":"C\'est parce qu\'il fait ce genre de folies à son âge qu\'il a fini par se faire capturer.","story.map11-dungeon2.011":"Mais non. Je vois bien que tu t\'inquiètes pour lui, Karl.","story.map11-dungeon2.012":"Haha. Je ne fais pas le poids face à une déesse.","story.map11-dungeon2.013":"Tu n\'as pas à t\'inquiéter pour lui !","story.map11-dungeon2.014":"Je suis sûre qu\'Elder Grah va très bien !","story.map11-dungeon2.015":"Toi aussi, tu allais bien quand tu t\'es fait capturer, non ?","story.map11-dungeon2.016":"Alors c\'est évident qu\'un type encore plus fort comme Elder Grah va bien aussi.","story.map11-dungeon2.017":"Il y a des choses avec lesquelles je ne suis pas d\'accord dans ce que tu dis...","story.map11-dungeon2.018":"Mais j\'imagine que même si je m\'inquiète pour lui, il ne va pas passer l\'arme à gauche de sitôt.","story.map11-dungeon2.019":"Merci, Déesse !","story.map11-dungeon2.020":"Mais c\'est un peu étrange.","story.map11-dungeon2.021":"Toi...","story.map11-dungeon2.022":"Paris-nounours.","story.map11-dungeon2.023":"N-Nounours ?!","story.map11-dungeon2.024":"C\'est vraiment difficile à dire à une déesse, mais...","story.map11-dungeon2.025":"...pourrais-tu arrêter de m\'appeler « nounours » ?","story.map11-dungeon2.026":"Appelle-moi simplement « Paris ». Ça ne me dérange pas.","story.map11-dungeon2.027":"D\'accord, très bien.","story.map11-dungeon2.028":"Alors, Paris, que fais-tu ici exactement ?","story.map11-dungeon2.029":"Eh bien, <wait=20>moi aussi, je cherche l\'Ancien Grahdens.","story.map11-dungeon2.030":"Il n\'y a donc rien d\'étonnant à ce que je sois tombée sur vous.","story.map11-dungeon2.031":"D\'accord, peu importe.","story.map11-dungeon2.032":"Alors, qu\'est-ce que tu trouves si étrange dans tout ça ?","story.map11-dungeon2.033":"Oh, <wait=20>quelqu\'un comme Karl de Nyonne ne voit pas de quoi je parle ?","story.map11-dungeon2.034":"Je n\'ai pas de temps pour tes petits jeux stupides. Dis-nous, maintenant.","story.map11-dungeon2.035":"Héhé, <wait=20>on dirait que tu es différent de Lugina, finalement.","story.map11-dungeon2.036":"Bon, très bien.","story.map11-dungeon2.037":"Je suis sûre que toi aussi, tu trouves ça étrange, non ?","story.map11-dungeon2.038":"Pourquoi les dieux l\'auraient-ils capturé en le laissant en vie ?","story.map11-dungeon2.039":"...","story.map11-dungeon2.040":"Si l\'Ancien Grahdens a combattu à tes côtés contre Zevalhua et s\'est fait capturer","story.map11-dungeon2.041":"alors pourquoi n\'ont-ils pas de raison suffisante de le tuer ?","story.map11-dungeon2.042":"...","story.map11-dungeon2.043":"Et si tout ça nous menait droit dans un piège ?","story.map11-dungeon2.044":"...","story.map11-dungeon2.045":"On ne peut pas y penser plus tard ?! Il faut sauver Elder Grah !","story.map11-dungeon2.046":"Tu as raison.","story.map11-dungeon2.047":"Karl, <wait=20><rep_handlename>, ","story.map11-dungeon2.048":"la Déesse a raison. Je vais moi aussi continuer à chercher l\'Ancien.","story.map11-dungeon2.049":"Faisons de notre mieux ensemble.","story.map11-dungeon2.050":"Oui, tu m\'as eu. Merci pour ton aide.","story.map11-dungeon2.051":"Héhé, <wait=20>de toute façon, Grahdens pourra peut-être résoudre cette petite énigme pour nous.","story.map11-dungeon2.052":"Oui, peut-être bien...","story.map11-dungeon2.053":"Héhé...","story.map11-dungeon3.001":"Oh, <wait=20><rep_handlename>.","story.map11-dungeon3.002":"Tu es seul en ce moment ?","story.map11-dungeon3.003":"Héhé, <wait=20>je plains tous les Invocateurs protégés par cette Déesse.","story.map11-dungeon3.004":"Je n\'ai pas pu entendre ta réponse la dernière fois à cause de Lugina, mais","story.map11-dungeon3.005":"ce n\'est pas pour autant que j\'ai renoncé à toi.","story.map11-dungeon3.006":"Je suis heureuse de pouvoir à nouveau me battre à tes côtés comme ça.","story.map11-dungeon3.007":"C\'est pourquoi--","story.map11-dungeon3.008":"<size=23>Pas question !!!</size>","story.map11-dungeon3.009":"<size=21>Paris ! <wait=20><br>Arrête ça !</size>","story.map11-dungeon3.010":"<size=21><rep_handlename> est mon Invocateur !</size>","story.map11-dungeon3.011":"Ah, alors <rep_handlename> est ton Invocateur ?","story.map11-dungeon3.012":"Eh bien, <wait=20>et qu\'est-ce que ça veut dire, exactement ?","story.map11-dungeon3.013":"<size=20>Ça veut dire exactement ce que ça veut dire !</size>","story.map11-dungeon3.014":"<size=20><rep_handlename> est mon Invocateur ! <wait=20> Point final !</size>","story.map11-dungeon3.015":"J-<wait=20>Je vois...","story.map11-dungeon3.016":"<rep_handlename>...<wait=40><br>tu <wait=20>en endures beaucoup en ce moment, n\'est-ce pas ?","story.map11-dungeon3.017":"Bref, <wait=20>quoi qu\'il en soit, nous aurons notre petite discussion plus tard.","story.map11-dungeon3.018":"Pour l\'instant, je vais chercher l\'Ancien Grahdens.","story.map11-dungeon3.019":"De nouvelles informations devraient arriver aussi, alors garde l\'œil ouvert.","story.map11-dungeon3.020":"Ah ! <wait=40>Paris, c\'est pas juste !","story.map11-dungeon3.021":"Je ne vais pas perdre contre toi, tu sais !","story.map11-dungeon3.022":"<rep_handlename> !","story.map11-dungeon3.023":"Je vais lui montrer que c\'est cette jolie déesse invincible qui va te trouver, Elder Grah !","story.map11-dungeon3.024":"Alors ne t\'inquiète pas, et attends-moi !","story.map11-dungeon3.025":"<rep_handlename>, <wait=40><br>je te plains vraiment....","story.map11-dungeon4.001":"Tss, c\'est toi.","story.map11-dungeon4.002":"Si tu traînes encore ici, c\'est que tu es toujours le même idiot.","story.map11-dungeon4.003":"Quoi ? <wait=40>Tu as dit qu\'on était tous les deux encore au même endroit ?","story.map11-dungeon4.004":"Tss, <wait=20>c\'est pour ça que je déteste les abrutis.","story.map11-dungeon4.005":"Moi, j\'ai une vraie raison d\'être ici.","story.map11-dungeon4.006":"Mais surtout, <rep_handlename>.","story.map11-dungeon4.007":"Méfie-toi vraiment de cette Garde impériale, Paris.","story.map11-dungeon4.008":"Cette bonne femme, <wait=20>elle mijote quelque chose, c\'est sûr.","story.map11-dungeon4.009":"Raconter que les nobles du Randall Empire travaillent avec le Hall des Invocateurs d\'Akras et tout ça...","story.map11-dungeon4.010":"c\'est impossible que ce soit vrai.","story.map11-dungeon4.011":"Et je suis sûr qu\'elle a aussi une raison de s\'intéresser autant à toi...","story.map11-dungeon4.012":"<size=23>Hé, les abrutis !</size>","story.map11-dungeon4.013":"<size=23>Pourquoi vous restez plantés là ?!</size>","story.map11-dungeon4.014":"Tss, et voilà qu\'une bonne femme encore plus pénible débarque.","story.map11-dungeon4.015":"<size=20>Qui tu traites de bonne femme pénible ?!</size>","story.map11-dungeon4.016":"<size=16>Ce n\'est pas le moment de jacasser ! L\'Ancien Grahdens a besoin de nous !</size>","story.map11-dungeon4.017":"Vous êtes tellement copains-copains que ça me donne la chair de poule...","story.map11-dungeon4.018":"<size=21>Qui tu traites de copains-copains ?! <wait=40><br>Abruti !</size>","story.map11-dungeon4.019":"<size=22>Qui tu traites d\'abruti ?!</size>","story.map11-dungeon4.020":"<size=21>Ne joue pas les grands seigneurs alors que t\'avais la tête plantée dans le sol !</size>","story.map11-dungeon4.021":"Grr, <wait=20>c\'était la faute de cette Déesse bizarre...","story.map11-dungeon4.022":"Lugy, tu devrais faire un peu plus d\'efforts !","story.map11-dungeon4.023":"<size=23>Je vais lui mettre une raclée, à cette sale gamine !</size>","story.map11-dungeon4.024":"<size=21>Hé, <rep_handlename> !</size>","story.map11-dungeon4.025":"<size=21>Où tu files comme ça ?!</size>","story.map11-dungeon4.026":"<size=18>Attends, <rep_handlename> ! Où tu vas ?!</size>","story.map11-dungeon4.027":"<size=16>Ne me laisse pas avec ces deux zigotos !</size>","story.map11-dungeon4.028":"<size=14>Je ne sais pas ce qu\'ils vont me faire !</size>","story.map11-dungeon4.029":"<size=12>Comme si j\'avais envie de te faire quoi que ce soit !</size>","story.map11-dungeon4.030":"<size=10>Et ça veut dire quoi, ça ?!</size>","story.map11-dungeon4.031":"<size=9>Tu piges pas ?!</size><wait=20><br><size=9>Quelle idiote !</size>","story.map11-dungeon4.032":"<size=8>La ferme !</size><wait=20><br><size=8>Espèce de nul !</size>","story.map11-dungeon5.001":"<rep_handlename> !!<wait=40> Écoute, écoute !!","story.map11-dungeon5.002":"Je sais <wait=20>où est Elder Grah !","story.map11-dungeon5.003":"Alors, euh... <wait=20>On dirait qu\'il est dans un endroit appelé la « Tour des dieux ».","story.map11-dungeon5.004":"Zevalhua a fait de la Tour des dieux sa base.","story.map11-dungeon5.005":"Donc, en bref, <wait=20>si on va à cette tour","story.map11-dungeon5.006":"on pourra vaincre Zevalhua, <wait=20>et sauver Elder Grah au passage.","story.map11-dungeon5.007":"Alors dis à Karl et aux autres de viser la Tour des dieux !","story.map11-dungeon5.008":"On n\'en attendait pas moins de la servante de Lord Lucius, Dame Tilith.","story.map11-dungeon5.009":"Ah, <wait=20>Paris !","story.map11-dungeon5.010":"Héhéhé, <wait=20>je suis plutôt douée, hein ?","story.map11-dungeon5.011":"Mais oui.<wait=20><br>Digne d\'une déesse.","story.map11-dungeon5.012":"Mais <wait=20>comment as-tu découvert où se trouve l\'Ancien Grahdens ?","story.map11-dungeon5.013":"Eh bien...","story.map11-dungeon5.014":"Il y a un autre serviteur de Lord Lucius, comme moi, qui surveillait Zevalhua.","story.map11-dungeon5.015":"Ce serviteur est allé à la Tour des dieux, et a rapporté avoir vu un vieil homme enfermé dans une pièce là-bas.","story.map11-dungeon5.016":"Je vois. <wait=20><br>Maintenant je comprends...","story.map11-dungeon5.017":"Lord Lucius <wait=20>rassemble plein de serviteurs divins incroyables !","story.map11-dungeon5.018":"Et bien sûr, j\'en fais partie moi aussi.","story.map11-dungeon5.019":"Oui, je sais bien que tu possèdes des pouvoirs incroyables, Déesse.","story.map11-dungeon5.020":"Mais <wait=20>c\'est curieux.","story.map11-dungeon5.021":"Hein ? <wait=20>Quoi donc ?","story.map11-dungeon5.022":"S\'il a autant d\'excellents êtres divins de son côté,","story.map11-dungeon5.023":"pourquoi ne s\'en prend-il pas lui-même aux Dieux déchus ?","story.map11-dungeon5.024":"Euh, <wait=20>eh bien...","story.map11-dungeon5.025":"Et puis, <wait=20>le messager du dieu principal,","story.map11-dungeon5.026":"le Saint Empereur Karna Masta, éveille lui aussi ma curiosité.","story.map11-dungeon5.027":"Alors que Grand Gaia est en danger, il ne montre aucune intention d\'agir.","story.map11-dungeon5.028":"Si Lord Lucius et Karna Masta travaillent ensemble, alors ils n\'ont nul besoin de nous, les humains.","story.map11-dungeon5.029":"J\'ai l\'impression qu\'ils pourraient facilement vaincre seuls les deux Dieux déchus restants.","story.map11-dungeon5.030":"Eh bien... <wait=40><br>Euh, <wait=20>hum...","story.map11-dungeon5.031":"Se pourrait-il que Lord Lucius et les autres ne puissent pas agir librement par eux-mêmes ?","story.map11-dungeon5.032":"Par exemple, <wait=20>peut-être qu\'après avoir été vaincu par les Quatre Dieux déchus, il a été scellé par un quelconque pouvoir, ou--","story.map11-dungeon5.033":"Ce... <wait=20>Ce n\'est pas du tout ça !","story.map11-dungeon5.034":"Lord Lucius se porte à merveille !","story.map11-dungeon5.035":"Je ne peux pas tout te dire, mais il ne peut pas vraiment agir pour l\'instant...","story.map11-dungeon5.036":"Et...<wait=20>Et Karna Masta a le même problème !","story.map11-dungeon5.037":"Mais ce n\'est pas comme s\'ils étaient scellés quelque part !","story.map11-dungeon5.038":"Toutes mes excuses.","story.map11-dungeon5.039":"Je t\'en prie, pardonne à cette humaine stupide et méfiante.","story.map11-dungeon5.040":"Une idiote comme moi ne peut espérer comprendre les grands desseins des dieux.","story.map11-dungeon5.041":"Je suis juste quelqu\'un de perpétuellement inquiet.","story.map11-dungeon5.042":"Non, <wait=20>ce n\'est rien.","story.map11-dungeon5.043":"Je ne m\'attendais pas à ce que tu me demandes une chose pareille, tu m\'as prise au dépourvu.","story.map11-dungeon5.044":"Tes paroles à elles seules m\'ont beaucoup aidée.","story.map11-dungeon5.045":"Bien, <wait=20>nous devrions partir sauver l\'Ancien Grahdens.","story.map11-dungeon5.046":"Karl et les autres semblent être partis juste devant, vers la cité en ruine de Mirvana.","story.map11-dungeon5.047":"D-<wait=20>D\'accord. <wait=40><br>C\'est vrai !","story.map11-dungeon5.048":"Il faut dire à Karl et aux autres où se trouve Elder Grah le plus vite possible !","story.map11-dungeon5.049":"Allez, <rep_handlename> ! <wait=40> En route !","story.map11-dungeon6.001":"Ah, <wait=20>Karl !","story.map11-dungeon6.002":"Salut, <wait=20>Déesse et <rep_handlename>.","story.map11-dungeon6.003":"On vous attendait.","story.map11-dungeon6.004":"On dirait que vous avez découvert où se trouve l\'Ancien Grahdens, hein ?","story.map11-dungeon6.005":"Merci beaucoup.","story.map11-dungeon6.006":"Hé, <wait=20>comment tu le sais ?","story.map11-dungeon6.007":"Paris est passée tout à l\'heure <wait=20>et nous l\'a dit.","story.map11-dungeon6.008":"Quoiiii ?!<wait=40> Paris, espèce d\'andouille !!","story.map11-dungeon6.009":"C\'est moi qui voulais leur faire la surprise !!","story.map11-dungeon6.010":"Mais au fait, <wait=20>où est Paris maintenant ?","story.map11-dungeon6.011":"Eh bien, <wait=20>elle a dit qu\'une chose l\'intriguait, alors elle est partie avant nous vers la Tour des dieux.","story.map11-dungeon6.012":"Je vois...","story.map11-dungeon6.013":"Qu\'est-ce qui peut bien <wait=20> l\'intriguer à ce point... ?","story.map11-dungeon6.014":"Déesse, <wait=40>qu\'est-ce qui ne va pas ?","story.map11-dungeon6.015":"Tu n\'as pas l\'air bien.<wait=20> Il s\'est passé quelque chose ?","story.map11-dungeon6.016":"N-<wait=20>Non, ce n\'est rien !","story.map11-dungeon6.017":"Je suis toujours pleine d\'énergie !","story.map11-dungeon6.018":"Pas vrai, <wait=20><rep_handlename> ?","story.map11-dungeon6.019":"D\'accord.","story.map11-dungeon6.020":"Bon, <wait=20>une fois qu\'on aura sauvé l\'Ancien Grahdens, je compte bien lui faire tout nous raconter.","story.map11-dungeon6.021":"Ce vieux... <wait=20>J\'ai l\'impression qu\'il nous cache encore plein de choses.","story.map11-dungeon6.022":"Libérer la Déesse de ses soucis pourrait nous être utile à long terme.","story.map11-dungeon6.023":"Karl est vraiment un chic type.","story.map11-dungeon6.024":"Mais bon, c\'est bien les amis de <rep_handlename>, ça !","story.map11-dungeon6.025":"Haha. <wait=20>Quand tu le dis juste devant moi, ça me fait un peu rougir.","story.map11-dungeon6.026":"Au fait, <wait=20>pour changer de sujet...","story.map11-dungeon6.027":"Et comment va cette chose ?","story.map11-dungeon6.028":"Cette chose... ?","story.map11-dungeon6.029":"Eh bien, <wait=20>comme d\'habitude. <wait=40><br>Alors ne t\'en fais pas...","story.map11-dungeon6.030":"Je vois ! <wait=20><br>Donc, comme d\'habitude, hein ?","story.map11-dungeon6.031":"Bon alors, <wait=20>je ne m\'en ferai pas.","story.map11-dungeon6.032":"Je te l\'ai déjà dit ! <wait=20>C\'est moi qui arriverai la première à la Tour des dieux !","story.map11-dungeon6.033":"Qu\'est-ce que t\'en sais !","story.map11-dungeon6.034":"Tu devrais juste rester à l\'entrée pour faire le guet !","story.map11-dungeon6.035":"<size=18>Pourquoi c\'est moi qui dois monter la garde ?!</size>","story.map11-dungeon6.036":"Parce que c\'est le boulot parfait pour une idiote comme toi.","story.map11-dungeon6.037":"<size=18>Je suis pas idiote !</size>","story.map11-dungeon6.038":"Faire le guet, c\'est quand même un boulot important !","story.map11-dungeon6.039":"Si tu comprends pas ça, tu vas rater plein de missions à l\'avenir !","story.map11-dungeon6.040":"<size=18>Qu\'est-ce que tu m\'as dit ?!</size>","story.map11-dungeon6.041":"Si faire le guet est un boulot si important, pourquoi tu le fais pas toi-même ?!","story.map11-dungeon6.042":"Ça n\'a rien à voir !","story.map11-dungeon6.043":"Oh là là. <wait=20>Ces deux-là me mettent vraiment les nerfs à vif...","story.map11-dungeon7.001":"Enfin, <wait=40><br><rep_handlename> !","story.map11-dungeon7.002":"Elder Grah est ici,","story.map11-dungeon7.003":"et l\'un des Quatre Dieux déchus aussi, « l\'Empereur divin Zevalhua ».","story.map11-dungeon7.004":"Je sens un immense pouvoir là-bas...","story.map11-dungeon7.005":"Pas très surprenant venant de l\'un des Dieux déchus.","story.map11-dungeon7.006":"Tss, <wait=20>je me fiche de sa taille, s\'il m\'agace, je le réduis en pièces.","story.map11-dungeon7.007":"Mais au fait, <wait=20>où est la dame de la Garde impériale ?","story.map11-dungeon7.008":"On dirait qu\'elle n\'est pas là.","story.map11-dungeon7.009":"Ha, <wait=20>on ne peut décidément pas compter sur les soldats de l\'Armée impériale de Randall.","story.map11-dungeon7.010":"Mais <wait=20>elle a aussi sa propre mission à accomplir.","story.map11-dungeon7.011":"On dirait qu\'elle est occupée à droite à gauche.","story.map11-dungeon7.012":"Elle s\'intéresse même à la raison de la capture de l\'Ancien...","story.map11-dungeon7.013":"Karl !","story.map11-dungeon7.014":"On n\'a pas le temps de penser à tout ça maintenant !","story.map11-dungeon7.015":"Il faut vite sauver Elder Grah avant qu\'il ne soit trop tard !","story.map11-dungeon7.016":"Tu as raison. <wait=40><br>C\'est comme le dit la Déesse.","story.map11-dungeon7.017":"Ça ne sert à rien d\'y penser maintenant !","story.map11-dungeon7.018":"Bon, <wait=20>séparons-nous pour chercher l\'Ancien !","story.map11-dungeon7.019":"À vrai dire, j\'aimerais qu\'on se regroupe tous avant d\'affronter Zevalhua, mais","story.map11-dungeon7.020":"selon la situation, ce ne sera peut-être pas possible. On devra peut-être l\'affronter seuls, s\'il le faut.","story.map11-dungeon7.021":"Pas de problème.","story.map11-dungeon7.022":"Même si ce n\'est pas le vrai, ou si c\'est un piège, je me battrai quand même !","story.map11-dungeon7.023":"Ha ! <wait=20>Je n\'ai jamais attendu grand-chose de vos pouvoirs, à vous autres.","story.map11-dungeon7.024":"<rep_handlename>, <wait=20>on compte encore sur ton pouvoir.","story.map11-dungeon7.025":"Bon, <wait=20>ne vous faites pas tuer là-bas !","story.map11-dungeon7.026":"C\'est...","story.map11-dungeon7.027":"Je suppose que je n\'ai pas le choix, je dois changer mes plans initiaux...","story.map11-ending.001":"On a réussi, <wait=40><br><rep_handlename> !","story.map11-ending.002":"Dire que tu as même vaincu Zevalhua ! Tu es incroyable, <rep_handlename> !","story.map11-ending.003":"Et Karl et l\'Ancien sont...","story.map11-ending.005":"*Haan* *haan* *haan* <wait=40><br><rep_handlename>...","story.map11-ending.006":"*Pff*<wait=40><br>*Haan*","story.map11-ending.007":"Waouh, tu as réussi !","story.map11-ending.008":"J\'ai senti un immense pouvoir devenir encore plus fort, alors je me suis précipité ici,","story.map11-ending.009":"mais on dirait que je n\'avais pas besoin de courir, finalement...","story.map11-ending.010":"Bon sang, <wait=20>on dirait que je ne suis pas arrivé à temps.","story.map11-ending.011":"<rep_handlename> !","story.map11-ending.012":"Espèce d\'enfoiré, <wait=20>tu t\'es amusé tout seul, hein ?!","story.map11-ending.013":"C\'est pour ça que je ne t\'aime pas !","story.map11-ending.014":"Oh, <wait=20>on dirait que tout le monde s\'en est sorti indemne !","story.map11-ending.015":"<rep_handlename> !","story.map11-ending.016":"Je savais que tu vaincrais Zevalhua ! Après tout, tu es mon ami.","story.map11-ending.017":"Je suis content de voir que tout le monde est sain et sauf.","story.map11-ending.018":"Alors, <wait=20>vous avez trouvé Elder Grah ?","story.map11-ending.019":"Il n\'est pas ici ?","story.map11-ending.020":"Il n\'était dans aucune des autres pièces,","story.map11-ending.021":"alors j\'étais sûr qu\'il serait ici, puisque c\'était la seule pièce qui restait. C\'est pour ça que je suis accouru.","story.map11-ending.022":"Pff, <wait=20>encore plus de saletés pénibles à gérer.","story.map11-ending.023":"J\'espère que l\'Ancien Grahdens <wait=20>est en sécurité quelque part...","story.map11-ending.024":"Oh, <wait=20>pardon, Karl. <wait=20> Je ne voulais pas le dire comme ça...","story.map11-ending.025":"Non, ça va.","story.map11-ending.026":"Il n\'y a aucune trace indiquant <wait=20>qu\'il soit venu ici, donc","story.map11-ending.027":"il s\'est sûrement échappé tout seul.","story.map11-ending.028":"Ho ho ho. <wait=40><br>C\'est exactement ça.","story.map11-ending.029":"Cette voix !","story.map11-ending.030":"Elder Grah !","story.map11-ending.031":"Ho ho ho.","story.map11-ending.032":"On dirait que je vous ai causé bien des ennuis.","story.map11-ending.033":"Ancien Grahdens...","story.map11-ending.034":"Ne fais pas cette tête d\'enfant.","story.map11-ending.035":"Je vous ai peut-être inquiétés, <wait=20><br>mais je ne suis pas encore devenu un faiblard.","story.map11-ending.036":"Q-Qui s\'inquiétait pour toi ?!","story.map11-ending.037":"Et surtout, <wait=20>qu\'est-ce que tu fabriquais pendant tout ce temps, et où ?!","story.map11-ending.038":"Explique à tout le monde pourquoi on a dû courir partout pour te chercher !","story.map11-ending.039":"Hmph, <wait=20>j\'ai fait une bêtise, c\'est vrai.","story.map11-ending.040":"Quelque chose dans cette tour me tracassait, <wait=20>juste un peu.","story.map11-ending.041":"J\'ai fait semblant d\'être capturé par cette Mare-je-ne-sais-quoi des Dieux déchus, pour qu\'elle m\'amène ici.","story.map11-ending.042":"Peut-être <wait=20>espérait-elle que ma capture lui donnerait un avantage sur vous tous au combat.","story.map11-ending.043":"Mais avant que Mare ne puisse s\'en servir, vous l\'avez vaincue.","story.map11-ending.044":"Comme elle avait acquis des connaissances sur Zevalhua et Afla Dilith en combattant à leurs côtés,","story.map11-ending.045":"je ne voulais pas l\'affronter moi-même.","story.map11-ending.046":"Mais comme prévu, <wait=20>me faire capturer vous a amenés à ma rescousse.","story.map11-ending.047":"Et grâce à cela, j\'ai eu tout le temps de mener mes recherches tranquillement.","story.map11-ending.048":"Dans ce cas, <wait=20>tu aurais pu nous le dire.","story.map11-ending.049":"Vieux schnock pénible.","story.map11-ending.050":"Ho ho ho. <wait=40>Désolé, Lugina.","story.map11-ending.051":"Je te suis redevable pour ce que tu as fait.","story.map11-ending.052":"Je te récompenserai généreusement.","story.map11-ending.053":"Et comment.","story.map11-ending.054":"Et pas seulement ça, <wait=20>tu dois aussi raconter aux gens importants <wait=20>tout ce que j\'ai fait.","story.map11-ending.055":"Franchement, <wait=20>ce type n\'a aucune classe.","story.map11-ending.056":"Tu peux parler !","story.map11-ending.057":"Alors, <wait=20>l\'Ancien.<wait=40> Tu sais ce que je veux te demander, pas vrai ?","story.map11-ending.058":"Hmph. <wait=40>Au sujet de ta naissance, n\'est-ce pas ?","story.map11-ending.059":"C\'est écrit dans mon testament. Tu ne peux pas attendre jusque-là pour le lire ?","story.map11-ending.060":"Hors de question.","story.map11-ending.061":"Ho ho ho. <wait=40>Je plaisantais. <wait=20>Pas la peine de te fâcher.","story.map11-ending.062":"Mais <wait=20>ce n\'est pas vraiment un si grand secret.","story.map11-ending.063":"Karl.","story.map11-ending.064":"Je t\'ai trouvé bébé et je t\'ai élevé. Ça, tu le sais, n\'est-ce pas ?","story.map11-ending.065":"Oui, <wait=20>et je t\'en suis reconnaissant.","story.map11-ending.066":"Mais <wait=20>l\'endroit où tu m\'as trouvé a-t-il quelque chose de spécial ?","story.map11-ending.067":"Hmph. <wait=20><br>Eh bien, oui.","story.map11-ending.068":"Tu l\'as peut-être vaguement senti toi-même, <wait=20><br>mais je t\'ai trouvé à Grand Gaia.","story.map11-ending.069":"Attends, <wait=20>quoi ?!","story.map11-ending.070":"Tss, <wait=20>alors c\'est comme ça.","story.map11-ending.071":"...","story.map11-ending.072":"Mais <wait=20>je croyais qu\'il n\'y avait aucun survivant humain à Grand Gaia... ?","story.map11-ending.073":"Moi-même, je ne le comprends pas.","story.map11-ending.074":"J\'étais simplement venu ici avec d\'autres Invocateurs, et en explorant les environs,","story.map11-ending.075":"nous avons trouvé un bébé dans les ruines de Mistral.","story.map11-ending.076":"Alors, <wait=40>nous l\'avons ramené avec nous à Elgaia.","story.map11-ending.077":"C\'est tout.","story.map11-ending.078":"Je n\'avais aucune idée de la véritable nature de ce bébé.","story.map11-ending.079":"Karl.","story.map11-ending.080":"Je ne sais pas si tu es un orphelin survivant de Grand Gaia, ","story.map11-ending.081":"ou un enfant des dieux.","story.map11-ending.082":"Cependant--","story.map11-ending.083":"L\'Ancien. <wait=40><br>Tu n\'as rien besoin de me dire de plus.","story.map11-ending.084":"Parce que je te suis vraiment reconnaissant, à toi et à tous les autres Invocateurs.","story.map11-ending.085":"...","story.map11-ending.086":"Karl...","story.map11-ending.087":"Waouh, alors Karl cachait un secret pareil, hein ?","story.map11-ending.088":"Hmm... <wait=40>Un bébé abandonné à Grand Gaia.","story.map11-ending.089":"Je n\'ai jamais entendu parler d\'une chose pareille.","story.map11-ending.090":"Je me demande si Lord Lucius en sait quelque chose.","story.map11-ending.091":"Je crois <wait=20>que je vais aller lui demander !","story.map11-ending.092":"<rep_handlename> !","story.map11-ending.093":"Bon, il ne nous reste plus qu\'un seul Dieu déchu à éliminer : le Dieu bête Afla Dilith !","story.map11-ending.094":"Je suis sûre qu\'on peut le vaincre si on travaille tous ensemble !","story.map11-ending.095":"Et bien sûr, <wait=20>on comptera aussi sur tes pouvoirs d\'Invocateur, <rep_handlename>.","story.map11-ending.096":"Bon, <wait=20>je vais aller me renseigner sur Karl et je reviens vers vous la prochaine fois !","story.map11-ending.097":"Oh, <wait=20>attends ! <wait=20><br>Déesse !","story.map11-ending.098":"Je voulais lui dire que ça ne m\'importait pas vraiment...","story.map11-ending.099":"Elle n\'écoute jamais, hein ?","story.map11-ending.100":"Ho ho ho. <wait=40><br>C\'est parce que Tilith est une gentille fille.","story.map11-ending.101":"Alors, <wait=20>qu\'est-ce qu\'on fait de cette présence malveillante apparue après le départ de la Déesse ?","story.map11-ending.102":"Je suis vraiment sans pitié avec les présences malveillantes.","story.map11-ending.103":"Vous êtes...","story.map11-ending.104":"Je suis Eriole.","story.map11-ending.105":"Je viens de l\'Empire de Randall,","story.map11-ending.106":"où je suis commandant de la Garde impériale, qui protège la famille impériale.","story.map11-ending.107":"Heh, <wait=20>j\'ai entendu des rumeurs sur ce nom.","story.map11-ending.108":"Des rumeurs qui disent que c\'est un sale type, devenu le plus jeune à porter le titre de commandant.","story.map11-ending.109":"Quelle insolence !","story.map11-ending.110":"Oh, <wait=20>revoilà la dame qui avait trop peur d\'affronter les Quatre Dieux déchus !","story.map11-ending.111":"Cet homme est un--","story.map11-ending.112":"Paris, recule un peu.","story.map11-ending.113":"Quoi ? <wait=20>M-<wait=20>Mais--","story.map11-ending.114":"Paris.","story.map11-ending.115":"C-<wait=20>Compris...","story.map11-ending.116":"Alors, <wait=20>que nous veut exactement le commandant de la Garde impériale ?","story.map11-ending.117":"J\'aimerais aussi que vous nous expliquiez qui est cette personne effrayante derrière vous.","story.map11-ending.118":"...","story.map11-ending.119":"Cette personne est mon associé. <wait=40><br>Ne vous en souciez pas.","story.map11-ending.120":"Vous avez tous dû entendre beaucoup de choses de ma subordonnée, Paris.","story.map11-ending.121":"Je voulais vous parler à tous au moins une fois,","story.map11-ending.122":"mais en tant qu\'envoyé de l\'Empereur de Randall,","story.map11-ending.123":"je suis venu cette fois pour parler spécifiquement à l\'Invocateur Grahdens.","story.map11-ending.124":"Ho ho ho.","story.map11-ending.125":"Si vous vouliez seulement me parler, <wait=20>vous n\'aviez pas besoin de venir jusqu\'ici, vous savez.","story.map11-ending.126":"Ha ha ha.","story.map11-ending.127":"Nous avons nos raisons.","story.map11-ending.128":"Nous vous expliquerons en détail plus tard.","story.map11-ending.129":"Vous comptez emmener l\'Ancien avec vous ?","story.map11-ending.130":"Vous croyez vraiment qu\'il va vous suivre sans broncher ?","story.map11-ending.131":"Ne vous méprenez pas, je vous prie.","story.map11-ending.132":"Nous ne sommes pas venus pour nous battre.","story.map11-ending.133":"Je le sais.","story.map11-ending.134":"Puisque s\'il m\'arrivait quelque chose, ce serait très gênant pour vous.","story.map11-ending.135":"...","story.map11-ending.136":"Excusez-moi, <wait=20>tout le monde. <wait=40><br>Je vais m\'entretenir un moment avec ces gens.","story.map11-ending.137":"Je voulais vous remercier tous comme il se doit, mais on dirait que ça devra attendre la prochaine fois.","story.map11-ending.138":"Karl.","story.map11-ending.139":"J\'ai été heureux de voir cette fois<wait=20> à quel point tu as grandi.","story.map11-ending.140":"Ancien Grahdens...","story.map11-ending.141":"Et toi, <rep_handlename>.","story.map11-ending.142":"Tu as bien fait de vaincre Zevalhua.","story.map11-ending.143":"Cependant, <wait=20>la prochaine fois, tu affronteras Afla Dilith.","story.map11-ending.144":"Et contrairement aux autres Dieux déchus, je suis sûr qu\'il sera prêt à te combattre.","story.map11-ending.145":"Ce sera sans aucun doute un combat difficile, mais tu dois te dépasser, toi et tes amis.","story.map11-ending.146":"Aussi, <wait=20>je te confie Karl.","story.map11-ending.147":"Tu le sais peut-être déjà, mais","story.map11-ending.148":"il lui manque encore quelques pièces ici et là, alors il m\'inquiète.","story.map11-ending.149":"Je n\'ai besoin de personne pour s\'occuper de moi...","story.map11-ending.150":"Ho ho ho.","story.map11-ending.151":"Bien, envoyé de l\'Empire de Randall, <wait=40><br>on y va ?","story.map11-ending.152":"Je vous remercie<wait=20> de votre considération et de votre compréhension.","story.map11-ending.153":"Paris, <wait=40>allons-y.","story.map11-ending.154":"À vos ordres !","story.map11-ending.155":"Il est parti comme ça, hein ?","story.map11-ending.156":"Comme c\'est l\'Ancien Grahdens, je suis sûre qu\'il ira bien. Mais quand même...","story.map11-ending.157":"Hmph. <wait=20>Ces types de l\'Empire de Randall ne peuvent pas toucher un cheveu du vieil Invocateur.","story.map11-ending.158":"Tu as raison.","story.map11-ending.159":"On parle de l\'Ancien Grahdens, après tout. <wait=40><br>Il ira très bien.","story.map11-ending.160":"Et surtout, <wait=20>on devrait se concentrer sur ce qu\'on peut faire de notre côté pour aider.","story.map11-ending.161":"<rep_handlename>,","story.map11-ending.162":"tu vas affronter Afla Dilith, <wait=20> le dernier des Quatre Dieux déchus, <wait=20>pas vrai ?","story.map11-ending.163":"À vrai dire, Seria et moi voudrions te prêter main-forte, mais on ne peut pas non plus ignorer le démon Graham.","story.map11-ending.164":"C\'est vrai ! <wait=40><br>Je l\'avais complètement oublié !","story.map11-ending.165":"Si on ne le bat pas...","story.map11-ending.166":"<rep_handlename> !","story.map11-ending.167":"On va devoir se séparer, <wait=20><br>mais ça ira pour toi, hein ?","story.map11-ending.168":"On va battre Graham et revenir aussitôt, alors prends soin de toi !","story.map11-ending.169":"Tiens, tiens... <wait=20>On dirait que la grande démone Seria a aussi un bon côté, finalement.","story.map11-ending.170":"Imbé-- <wait=20>Créti-- <wait=20>C\'est ce qu\'on est censé dire dans ces moments-là !","story.map11-ending.171":"Hé, <rep_handlename> !","story.map11-ending.172":"Ne va pas t\'attribuer tout le mérite <wait=20>d\'avoir vaincu Zevalhua à toi tout seul.","story.map11-ending.173":"N\'oublie pas non plus tout ce que <wait=40><br>j\'ai fait.","story.map11-ending.174":"La prochaine fois, je déciderai de te sauver ou non selon la reconnaissance que tu me montreras.","story.map11-ending.175":"Haha, <wait=20>c\'est bien Lugina, ça.","story.map11-ending.176":"<rep_handlename>, <wait=40><br>on doit y aller maintenant.","story.map11-ending.177":"Si tu revois la Déesse, dis-lui que je lui suis très reconnaissant pour son aide.","story.map11-ending.178":"Et <wait=20>si tu apprends quelque chose sur moi et que tu veux m\'en parler, c\'est à toi de voir.","story.map11-ending.179":"Parce que si c\'est toi qui me le dis, <wait=20>je suis sûr que je pourrai affronter n\'importe quelle vérité.","story.map11-ending.180":"Bon, <wait=20>j\'ai hâte de te revoir la prochaine fois.","story.map11-open.001":"<anchor=center><br><br><br><br><br><br><br><br><br><br><speed=8><size=15>Je suis Lucius...<wait=40><br>Dieu de cette Porte...","story.map11-open.002":"<anchor=center><br><br><br><br><br><br><br><br><br><br><speed=8><size=15>Libérateur d\'Agni...<wait=40><br><rep_handlename>...","story.map11-open.003":"<anchor=center><br><br><br><br><br><br><br><br><br><br><speed=8><size=15>Use de mon pouvoir...<wait=40><br>et pars pour de nouvelles terres...","story.map11-open.004":"<anchor=center><br><br><br><br><br><br><br><br><br><br><speed=8><size=15>afin de porter notre parole<wait=40><br>à ce monde plongé dans le chaos...","story.map11-open.005":"<anchor=center><br><br><br><br><br><br><br><br><br><br><speed=8><size=15>Aie foi en toi<wait=20><br>et continue d\'avancer...","story.map11-open.006":"<rep_handlename> ! <wait=40><br>C\'est l\'heure !","story.map11-open.007":"Voici Mirvana, la région dont Zevalhua a fait sa base pendant la guerre contre les dieux.","story.map11-open.008":"On dirait que c\'est pour ça <wait=20>que la région d\'Agni est devenue le plus grand champ de bataille de la guerre.","story.map11-open.009":"Le paysage est si lugubre par ici...","story.map11-open.010":"Oh ! <wait=20>Pardon, pardon !","story.map11-open.011":"Ce n\'est pas le moment de faire du sentiment !","story.map11-open.013":"Bon, <wait=20>allons vaincre Zevalhua et sauver Elder Grah !","story.map11-open.014":"Je sais qu\'on peut compter sur toi, <rep_handlename>. J\'ai foi en toi !","story.map2-dungeon1.001":"<size=22>Oh ?! <rep_handlename> !!","story.map2-dungeon1.002":"Ça alors, <wait=20>jamais je n\'aurais cru te croiser dans un endroit pareil !","story.map2-dungeon1.003":"Je vois, <wait=40>toi aussi tu vas à la Tour de Morgan, hein ?","story.map2-dungeon1.004":"Tu dois être avec l\'Armée des Invocateurs, toi aussi, à la poursuite des Quatre Dieux déchus...","story.map2-dungeon1.005":"Non ? <wait=40>C\'est Tilith qui t\'a dit de venir ?","story.map2-dungeon1.006":"Ah, <wait=20>ce doit être la fille dont tu me parlais l\'autre fois.","story.map2-dungeon1.007":"On dirait qu\'elle prend bien soin de toi.  <wait=20>Je devrais la saluer poliment quand on se verra. <wait=19>Tu nous présenteras, hein ?","story.map2-dungeon1.008":"Hein ? <wait=20>Elle n\'est pas là ? <wait=40>Tu la cherches aussi ?","story.map2-dungeon1.009":"Hmm... <wait=40>Bon, <wait=40>inutile d\'insister, je suppose.","story.map2-dungeon1.010":"Nous, les Pourfendeurs de démons, traquons le démon Graham.","story.map2-dungeon1.011":"On l\'a acculé plusieurs fois, <wait=20>mais il arrive toujours à s\'échapper...","story.map2-dungeon1.012":"Il a filé vers le désert, alors on s\'apprête à y entrer pour le retrouver.","story.map2-dungeon1.013":"Bon, <wait=20>on y va ?","story.map2-dungeon1.014":"Au fait, <wait=40>il fait une chaleur écrasante dans ce désert, alors sois très prudent.","story.map2-dungeon1.015":"Et ouvre l\'œil : on a récemment aperçu un abruti qui agite une épée enflammée dans tous les sens !","story.map2-dungeon1.016":"Fais attention, <wait=20>et à très bientôt !","story.map2-dungeon2.001":"Oh, <rep_handlename> !!","story.map2-dungeon2.002":"Tu le sens ? <wait=40>Elle n\'est pas géniale, cette brise marine ?","story.map2-dungeon2.003":"Hein ? <wait=40>Pourquoi on est là ?","story.map2-dungeon2.004":"Parce qu\'il faisait trop chaud là-bas...","story.map2-dungeon2.005":"<size=22>Ah ! <wait=40>Je retire ce que j\'ai dit !!","story.map2-dungeon2.006":"On n\'est pas venus ici juste à cause de la chaleur...","story.map2-dungeon2.007":"J\'ai vraiment à faire ici ! <wait=40>Et arrête avec ce regard sceptique !","story.map2-dungeon2.008":"Bon, faut que j\'y aille ! <wait=40>Je te rattrape dès que j\'ai fini.","story.map2-dungeon2.009":"Pars devant, <rep_handlename> !<br><wait=40>Et ne traîne pas, d\'accord ?","story.map2-dungeon2.010":"Au fait, <wait=40>il paraît qu\'une épéiste ennemie rôde sur cette plage, et qu\'elle sait manipuler l\'air glacé !","story.map2-dungeon2.011":"On dit aussi qu\'elle est belle, mais je sais que je suis bien plus mignonne qu\'elle !","story.map2-dungeon2.012":"Arrange-toi pour la vaincre, <wait=20>et vite, hein !","story.map2-dungeon2.013":"Bref, <wait=20>je t\'attends ici ! <wait=40>Bonne chance !","story.map2-dungeon3.001":"C\'est toi, <rep_handlename> ?!<br><wait=40>Tu as vu Graham ?!","story.map2-dungeon3.002":"Oh, <wait=20>non... <wait=40>Bon sang... <wait=40>Argh...","story.map2-dungeon3.003":"Ah, <wait=20>ne t\'en fais pas. <wait=40>C\'est juste une égratignure, rien de grave...","story.map2-dungeon3.004":"Mais le pire, <wait=20>c\'est que la plupart de mes camarades ont été anéantis...","story.map2-dungeon3.005":"Graham... <wait=30>Il est dans la Forêt nocturne maintenant.","story.map2-dungeon3.006":"Apparemment, cette forêt est le territoire d\'un des chevaliers de Graham.","story.map2-dungeon3.007":"Ce chevalier connaît les ombres de la forêt comme sa poche et profite de la mauvaise visibilité.","story.map2-dungeon3.008":"Il abat les Invocateurs un par un.","story.map2-dungeon3.009":"Si on arrive à vaincre ce chevalier, on pourrait sûrement chasser Graham de la forêt.","story.map2-dungeon3.010":"Tout ce que je sais, c\'est que ce chevalier manie la lance.","story.map2-dungeon3.011":"Pour l\'instant, nous, les Pourfendeurs de démons, ne pouvons guère faire plus qu\'encercler Graham...","story.map2-dungeon3.012":"Et pas question que je reste les bras croisés pendant que mes camarades tombent un par un.","story.map2-dungeon3.013":"Quoi qu\'il arrive, je le sortirai de cette forêt, quitte à le faire moi-même !","story.map2-dungeon3.014":"Bon, il est temps d\'y aller.<br><wait=40>Je compte sur toi pour tout donner aussi !","story.map2-dungeon4.001":"Hé, <wait=20><rep_handlename> !<br><wait=40>Content de te voir entier !","story.map2-dungeon4.002":"Bon, <wait=20>je n\'ai jamais cru que tu perdrais contre un type pareil !","story.map2-dungeon4.003":"Tu vas à la Tour de Morgan, c\'est ça ?","story.map2-dungeon4.004":"Dans ce cas, tu vas devoir traverser la Désolation d\'Asekutt.","story.map2-dungeon4.005":"Les bêtes qui rôdent dans la Désolation d\'Asekutt sont plutôt coriaces.","story.map2-dungeon4.006":"Ce serait risqué si tes unités avaient une mauvaise affinité élémentaire face à ces bêtes, alors fais gaffe.","story.map2-dungeon4.007":"Hmm ? <wait=40>Tu t\'inquiètes de la situation de notre côté ?","story.map2-dungeon4.008":"Eh bien, j\'ai réussi tant bien que mal à chasser Graham de la forêt.","story.map2-dungeon4.009":"Mais contrairement à la Forêt nocturne, Asekutt est un terrain à découvert.","story.map2-dungeon4.010":"Il ne pourra pas fuir et se cacher comme dans la Forêt nocturne.","story.map2-dungeon4.011":"Même si notre équipe de Pourfendeurs de démons a perdu la moitié de ses forces...","story.map2-dungeon4.012":"J\'ai l\'intention de régler ça une bonne fois pour toutes à Asekutt.","story.map2-dungeon4.013":"C\'est pour mes coéquipiers, <wait=40>pour leur sacrifice.","story.map2-dungeon4.014":"Alors malheureusement, <wait=40>je ne peux pas t\'accompagner.","story.map2-dungeon4.015":"Mais sois tranquille, je suis certain que tu vaincras Maxwell.","story.map2-dungeon4.016":"À plus !","story.map2-dungeon5.001":"Salut, <rep_handlename>.<br><wait=40>Graham s\'est encore échappé...","story.map2-dungeon5.002":"Bon sang, <wait=40>on y était presque !","story.map2-dungeon5.003":"Et j\'ai perdu encore plus de camarades... <wait=40>Je jure que je l\'écraserai quand je lui mettrai la main dessus.","story.map2-dungeon5.004":"...<wait=20>Mais maintenant, nous, les Pourfendeurs de démons, sommes trop peu nombreux.","story.map2-dungeon5.005":"Alors on retourne au Hall des Invocateurs chercher des renforts.","story.map2-dungeon5.006":"Je devais la retrouver ici aussi, mais...","story.map2-dungeon5.007":"Oh, <wait=20>la voilà !","story.map2-dungeon5.008":"Tiens, Seria, <wait=40>toujours aussi pimpante, hein ?","story.map2-dungeon5.009":"Karl ! <wait=40>Ce n\'est pas le moment de bavarder !","story.map2-dungeon5.010":"Qu\'est-ce que <rep_handlename> fait ici ?!","story.map2-dungeon5.011":"Tu ne fais pas partie des Pourfendeurs de démons, si ?!","story.map2-dungeon5.012":"Oh, <wait=40><rep_handlename> et moi, on s\'est juste croisés ici par hasard.","story.map2-dungeon5.013":"Ta prochaine étape, <wait=20>c\'est le Sanctuaire de Lystia, je parie ?","story.map2-dungeon5.014":"Si tu n\'es pas membre des Pourfendeurs de démons, tu n\'as rien à faire ici.","story.map2-dungeon5.015":"Hé, <wait=20>Seria. <wait=40>Pas besoin d\'être aussi dure !","story.map2-dungeon5.016":"<size=12>...<wait=40>Pourquoi c\'est moi qui me fais crier dessus ??","story.map2-dungeon5.017":"Plus important, j\'ai des nouvelles pour toi, Karl.","story.map2-dungeon5.018":"D\'après les renseignements du Hall des Invocateurs, <wait=20>Graham serait l\'un des favoris d\'Abaddon.","story.map2-dungeon5.019":"Il a la faveur d\'Abaddon ? <wait=40>Qu\'est-ce que ça veut dire ?","story.map2-dungeon5.020":"Il semble être extrêmement apprécié, même parmi les autres dieux...","story.map2-dungeon5.021":"Alors si Graham est en danger, tu peux être sûr que d\'autres ennuis vont suivre.","story.map2-dungeon5.022":"Peut-être même qu\'Abaddon en personne apparaîtra...","story.map2-dungeon5.023":"Si c\'est vrai, il faut abattre Graham pour attirer Abaddon hors de sa tanière.","story.map2-dungeon5.024":"C\'est pourquoi le Hall des Invocateurs nous a ordonné d\'avancer sur la Tour de Morgan. ","story.map2-dungeon5.025":"Je vois.","story.map2-dungeon5.026":"Voilà sans doute pourquoi notre demande de renforts a été acceptée si vite.","story.map2-dungeon5.027":"Bref, tu ne crois pas qu\'il est temps d\'arrêter le bavardage !?","story.map2-dungeon5.028":"Tu devrais être en route pour la Tour de Morgan, non ?","story.map2-dungeon5.029":"On a encore beaucoup de choses à planifier...","story.map2-dungeon5.030":"...alors pourquoi tu ne filerais pas tout seul en vitesse !","story.map2-dungeon5.031":"Hein ? <wait=20>H-<wait=20>Hé, Seria ! <wait=40><rep_handlename> !!","story.map2-dungeon6.001":"<rep_handlename> ! <wait=40>Tu vas bien ?!","story.map2-dungeon6.002":"Tu es parti en courant après que Seria t\'a crié dessus. <wait=20>J\'ai cru que tu t\'étais fâché.","story.map2-dungeon6.003":"Enfin, <wait=20>je suis content de voir que tu vas bien.","story.map2-dungeon6.004":"On vient tout juste de traverser le Sanctuaire de Lystia, nous aussi.","story.map2-dungeon6.005":"Dis donc, <wait=40>pourquoi tu surgis toujours partout où on va ?!","story.map2-dungeon6.006":"Tu ne serais pas en train de nous suivre, par hasard ?!","story.map2-dungeon6.007":"Tu veux bien arrêter ces agressions gratuites ?!","story.map2-dungeon6.008":"Pourquoi faut-il toujours que tu cherches la bagarre ?","story.map2-dungeon6.009":"J-<wait=20>Je ne cherche pas la bagarre !","story.map2-dungeon6.010":"Il n\'est même pas si puissant que ça...","story.map2-dungeon6.011":"Ça m\'énerve de te voir encenser quelqu\'un comme lui. Franchement, regarde-le !","story.map2-dungeon6.012":"*Soupir* <wait=40>Si ce n\'est pas chercher la bagarre, <wait=20>je ne sais pas ce que c\'est...","story.map2-dungeon6.013":"Je ne sais pas si tu l\'as remarqué, <wait=20>mais <rep_handlename> est arrivé jusqu\'ici tout seul.","story.map2-dungeon6.014":"<rep_handlename> nous a aidés en battant le sbire de Graham dans la Forêt nocturne.","story.map2-dungeon6.015":"<rep_handlename> n\'est pas un faiblard, ça, c\'est sûr.","story.map2-dungeon6.016":"Hmph. <wait=40>De toute façon, ça m\'est bien égal.","story.map2-dungeon6.017":"Vas-y, savoure tous ces éloges immérités, je m\'en fiche !","story.map2-dungeon6.018":"...<wait=40>Je ne comprendrai jamais les femmes.","story.map2-dungeon6.019":"Bon, <wait=20>bref...","story.map2-dungeon6.020":"On va traverser cette cathédrale détruite pour rejoindre la Tour de Morgan...","story.map2-dungeon6.021":"<rep_handlename>, tu veux venir avec nous ?","story.map2-dungeon6.022":"<size=24>Je m\'y oppose !","story.map2-dungeon6.023":"Hé, <wait=20>je savais que tu dirais ça.","story.map2-dungeon6.024":"Bon, <wait=20>on ne peut pas partir au combat ensemble en se chamaillant comme ça. Inutile de forcer les choses.","story.map2-dungeon6.025":"Chacun sa route.","story.map2-dungeon6.026":"On se retrouve à la Tour de Morgan !","story.map2-dungeon7.001":"<rep_handlename> !! <wait=40>T\'es rapide, <wait=20>je ne pensais pas que tu serais déjà là.","story.map2-dungeon7.002":"Hé, <wait=40>c\'est bien le minimum...","story.map2-dungeon7.003":"Toujours à chercher la bagarre, comme d\'habitude...","story.map2-dungeon7.004":"Bon, <wait=20>bref... <wait=40>Voici la base d\'Abaddon, <wait=20>la Tour de Morgan.","story.map2-dungeon7.005":"Abaddon et Graham sont sûrement ici.","story.map2-dungeon7.006":"C\'est à peu près le seul endroit où Graham a pu se réfugier.","story.map2-dungeon7.007":"On s\'occupe de Graham. <wait=40><br>Et toi, <rep_handlename>, tu te charges d\'Abaddon.","story.map2-dungeon7.008":"On est venus de si loin, <wait=40>alors écrasons-les !","story.map2-dungeon7.009":"Mais on pourrait bien vaincre Abaddon avant même que tu en aies l\'occasion !","story.map2-dungeon7.010":"Et qu\'est-ce que tu dirais si <rep_handlename> battait Graham avant nous ?","story.map2-dungeon7.011":"Bon, <wait=40>c\'est normal de vouloir affronter soi-même les ennemis de ses amis...","story.map2-dungeon7.012":"Mais je pense que le mieux, c\'est de travailler ensemble chacun sur son front et de tout donner !","story.map2-dungeon7.013":"Hé... <wait=20>hé ! <wait=40>On dirait des secousses, vous les entendez ?","story.map2-dungeon7.014":"Là-bas !!","story.map2-dungeon7.015":"Qu-<wait=20>Qu\'est-ce que c\'est !? <wait=40>Des hordes de... <wait=20>monstres ?!","story.map2-dungeon7.016":"...Maxwell. <wait=40>Alors elle compte nous arrêter ici...","story.map2-dungeon7.017":"Pas de retour possible... <wait=40>On n\'a pas d\'autre choix que de se battre... <wait=40>Ici et maintenant...","story.map2-dungeon7.018":"...<wait=40>Attendez, <wait=40>il y a peut-être un autre moyen.","story.map2-dungeon7.019":"Il suffit de grimper au sommet de la Tour de Morgan <wait=40>et d\'y vaincre Abaddon.","story.map2-dungeon7.020":"C\'est impossible !","story.map2-dungeon7.021":"On ne peut pas affronter tous ces monstres et Abaddon en même temps...","story.map2-dungeon7.022":"N\'y pense même pas. <wait=40>On n\'arriverait sans doute même pas assez près pour apercevoir Abaddon.","story.map2-dungeon7.023":"Tu as raison. <wait=40>Mais <wait=20>ces monstres n\'iront pas plus loin.","story.map2-dungeon7.024":"Je vais les arrêter ici même !","story.map2-dungeon7.025":"Karl !? <wait=40>Qu\'est-ce que tu racontes !?","story.map2-dungeon7.026":"Tu comptes vraiment les retenir ici pendant qu\'on va affronter Abaddon ?!","story.map2-dungeon7.027":"Exactement. <wait=40>C\'est notre seule option...","story.map2-dungeon7.028":"Mais regarde-les tous. <wait=40>Personne ne peut tous les affronter seul !","story.map2-dungeon7.029":"Oui... <wait=40>J\'en suis conscient.","story.map2-dungeon7.030":"Mais si tout doit se terminer ici, je mise sur ce qui offre la meilleure chance de vaincre Abaddon.","story.map2-dungeon7.031":"Karl...","story.map2-dungeon7.032":"<rep_handlename>, <wait=40>pars devant avec Seria.","story.map2-dungeon7.033":"J\'arrêterai ces monstres. <wait=40>Toi, tu dois aller éliminer Abaddon.","story.map2-dungeon7.034":"...<wait=40>Je n\'y vais pas.","story.map2-dungeon7.035":"Seria !!","story.map2-dungeon7.036":"Cette horde, <wait=20>c\'est trop pour toi tout seul, Karl.","story.map2-dungeon7.037":"Si je t\'aide à les retenir <wait=20>juste un peu plus longtemps...","story.map2-dungeon7.038":"C\'est peut-être tout le temps qu\'il nous faudra <wait=20>pour vaincre Abaddon.","story.map2-dungeon7.039":"Seria, <wait=40>toi...","story.map2-dungeon7.040":"<rep_handlename> !","story.map2-dungeon7.041":"Toi, <wait=40>les Invocateurs d\'antan ont reconnu ta force d\'Invocateur, n\'est-ce pas ?","story.map2-dungeon7.042":"Alors prouve-le-moi.","story.map2-dungeon7.043":"Je te réduis en bouillie si tu ne bats pas Abaddon !!","story.map2-dungeon7.044":"...<wait=40>Bon, <wait=20>allons-y !!","story.map2-dungeon7.045":"Tss... <wait=20>Cette fille...","story.map2-dungeon7.046":"<rep_handlename>, <wait=40>on va tout donner pour les retenir.","story.map2-dungeon7.047":"Tu dois vaincre Abaddon.","story.map2-dungeon7.048":"On compte sur toi, <wait=40><rep_handlename>.","story.map2-dungeon7.049":"Maintenant, <wait=40>au combat !!","story.map2-ending.001":"<size=20><rep_handlename> ! Tu vas bien ?!</size>","story.map2-ending.002":"Oh, <wait=20>tu as... <wait=40>vaincu Abaddon ?","story.map2-ending.003":"Waouh... <wait=40>Tu es vraiment très puissant.","story.map2-ending.004":"Je n\'arrive pas à croire que tu aies pu vaincre Abaddon à toi tout seul...","story.map2-ending.005":"Oh, moi ? <wait=20>Je vais bien.","story.map2-ending.006":"Après qu\'on s\'est séparés, <wait=20>j\'ai tout donné pour garder l\'entrée de la tour.","story.map2-ending.007":"Seria et moi, on s\'est poussés à nos limites, on a bien failli y rester...","story.map2-ending.008":"Mais heureusement, les renforts du Hall des Invocateurs sont arrivés juste à temps.","story.map2-ending.009":"Ils ont tout donné pour nous aider...","story.map2-ending.010":"Hmm ? <wait=20>Seria ? <wait=40>Elle est là-bas... <wait=40>Hein ? <wait=20>Seria ?","story.map2-ending.011":"Où est-elle passée ? <wait=40>...<wait=40>Hmm, <wait=20>tant pis.","story.map2-ending.012":"Au fait, <wait=20>elle s\'inquiétait pas mal pour toi.","story.map2-ending.013":"Elle était épuisée et en lambeaux, mais elle a tenu à t\'aider et a filé droit en haut de la tour...","story.map2-ending.014":"Héhé, <wait=20>qui sait ce qu\'elle ferait si elle apprenait que je t\'ai raconté tout ça...","story.map2-ending.015":"Alors ne lui dis pas que je te l\'ai dit, d\'accord ?","story.map2-ending.016":"Mais sérieusement, <wait=40>tu es vraiment devenu fort.","story.map2-ending.017":"On s\'est précipités pour t\'aider, <wait=40>mais apparemment tu n\'avais pas besoin de renforts.","story.map2-ending.018":"Pour moi, tu es déjà un Invocateur de premier ordre.","story.map2-ending.019":"Ah, <wait=20>au fait...","story.map2-ending.020":"Finalement, on n\'a pas réussi à abattre Graham.","story.map2-ending.021":"Mais on a capturé quelques monstres et on leur a fait cracher la cachette de Graham.","story.map2-ending.022":"Seulement, il a filé quelque part où on ne peut pas le suivre... <wait=20>Sale démon, celui-là... ","story.map2-ending.023":"Ça ne va pas être facile de le retrouver.","story.map2-ending.024":"Je vais devoir faire mon rapport à ce Hall des Invocateurs d\'Akras...","story.map2-ending.025":"Toi... <wait=40>Enfin, <wait=40>je suppose que tu as tes propres affaires à régler.","story.map2-ending.026":"...<wait=20>Je ferais mieux de me mettre en route.","story.map2-ending.027":"Nos objectifs sont peut-être différents, <wait=40>mais je serai toujours de ton côté.","story.map2-ending.028":"Surtout, reste en vie ! <wait=40>À plus !","story.map2-ending.029":"Hé ! <wait=40><rep_handlename> !!","story.map2-ending.030":"Je t\'ai enfin rattrapé !","story.map2-ending.031":"Tu es tout simplement incroyable !!","story.map2-ending.032":"Pendant que j\'étais à la Plage de la brise, à voir qui de la Reine des glaces Selena ou moi était la plus mignonne...","story.map2-ending.033":"...tu as vaincu Abaddon, on dirait ! Incroyable !","story.map2-ending.034":"...Hein ?!","story.map2-ending.035":"N-<wait=20>Ne te méprends pas ! <wait=40>Ce n\'était pas du tout un concours de beauté ou un truc du genre...","story.map2-ending.036":"Je veux dire, Selena ne s\'est même pas montrée !","story.map2-ending.037":"En plus, <rep_handlename>, tu n\'étais pas là, donc personne ne pouvait juger le concours de toute façon, hein ?!","story.map2-ending.038":"...<wait=40>C\'est quoi, cette tête !","story.map2-ending.039":"J\'avais vraiment une affaire importante à la Plage de la brise !","story.map2-ending.040":"Ah ! <wait=20>Tu entends ça ?<br><wait=40>On dirait que Lord Lucius t\'appelle ?","story.map2-ending.041":"<speed=12>Bon <wait=10>voyage<wait=20>, à <wait=30>bientôt...","story.map2-ending.042":"<anchor=center><br><br><br><br><br><br><br><br><br><br><speed=8><size=15>Je suis Lucius...<br><wait=40>Dieu de la Porte...","story.map2-ending.043":"<anchor=center><br><br><br><br><br><speed=8><size=15><rep_handlename>... <wait=40>Sauveur de Morgan...","story.map2-ending.044":"<anchor=center><br><br><br><br><br><br><br><br><br><br><speed=8><size=15>Fais usage de mon pouvoir <wait=40>et aventure-toi en de nouvelles terres...","story.map2-ending.045":"<anchor=center><br><br><br><br><br><br><br><speed=8><size=15>Va de l\'avant <wait=20>et sers-toi de ton pouvoir pour ramener la paix en ce monde...","story.map2-ending.046":"Oh, <wait=20>tu es réveillé.","story.map2-ending.047":"Bonjour, <wait=20> <rep_handlename>.","story.map2-ending.048":"Regarde... <wait=40>On est enfin arrivés à St. Lamia.","story.map2-ending.049":"Voici... <wait=40>le domaine de Maxwell.","story.map2-ending.050":"...<wait=40><rep_handlename>, tu le sens aussi ?","story.map2-ending.051":"Je sens les ondes d\'une puissance formidable...","story.map2-ending.052":"Les monstres sont aussi plus forts qu\'avant. <wait=40>On doit rester concentrés...","story.map2-ending.053":"Maxwell se trouve au Palais de St. Lamia.","story.map2-ending.054":"De rudes combats nous attendent, <wait=40>donnons tout ensemble !","story.map2-ending.055":"Quoi ? <wait=40>Tu me demandes où j\'étais pendant que tu te battais à Morgan ?","story.map2-ending.056":"Ne sois pas si mesquin...","story.map2-ending.057":"Je promets de faire de mon mieux à St. Lamia, <wait=40>d\'accord ?","story.map2-ending.058":"Bon, <wait=20>en route !!","story.map3-dungeon1.001":"<size=13>Ça brûle ici ! <wait=40>Je veux rentrer... <wait=40>Ma pauvre peau n\'en peut plus...","story.map3-dungeon1.002":"<size=20>Hé ! <wait=20><rep_handlename> !","story.map3-dungeon1.003":"Toi ! <wait=20>Encore en retard !!","story.map3-dungeon1.004":"Ne me dis pas que tu te prélassais dans un coin plus frais !?","story.map3-dungeon1.005":"Ce n\'est pas le moment de traîner ! <wait=40>Qu\'as-tu à dire pour ta défense ?","story.map3-dungeon1.006":"Hein ? <wait=20>Et moi alors ?","story.map3-dungeon1.007":"<size=15>Je <size=14>ne <size=13>me <size=12>suis <size=11>pas <size=10>du <size=9>tout <size=8>prélassée<size=7>...<size=6>","story.map3-dungeon1.008":"Bref, <wait=40>à partir d\'aujourd\'hui, on grimpe le Volcan Eldent.","story.map3-dungeon1.009":"Le Volcan Eldent est un volcan actif, alors c\'est vraiment dangereux.","story.map3-dungeon1.010":"Attention aux coulées de lave !","story.map3-dungeon1.011":"Bon, <wait=20>bon voyage !","story.map3-dungeon1.012":"Quoi ? <wait=40>Tu veux des conseils plus concrets ?","story.map3-dungeon1.013":"Il fait trop chaud... Je suis déjà à bout !","story.map3-dungeon1.014":"<size=20>Ah ! <wait=40>Je n\'en peux plus !","story.map3-dungeon1.015":"Je rentre prendre un bain,<wait=20> ne te fais pas tuer avant mon retour !","story.map3-dungeon2.001":"<size=12>Brr...","story.map3-dungeon2.002":"Oh, <wait=20><rep_handlename> ! <wait=40>Enfin, <wait=20>tu en as mis du temps !","story.map3-dungeon2.003":"Hein ? <wait=40>Qu\'est-ce que j\'ai ?","story.map3-dungeon2.004":"Je n\'ai rien du tout. <wait=40>Je suis la Tilith pleine d\'énergie, comme toujours !","story.map3-dungeon2.005":"Oui, <wait=20>je dois bien avouer qu\'il commence à faire un peu froid par ici.","story.map3-dungeon2.006":"Mais c\'est seulement parce que tu m\'as fait attendre si longtemps, <rep_handlename> !","story.map3-dungeon2.007":"Cela dit, <wait=20>je devrais t\'en dire un peu plus sur le Mt sacré Craylia.","story.map3-dungeon2.008":"Cette montagne sacrée, le Mt Craylia, est la plus haute de St. Lamia.","story.map3-dungeon2.009":"Son sommet abriterait une source de puissance spirituelle, qui semble être à l\'origine de cette tempête de neige perpétuelle.","story.map3-dungeon2.010":"En plus, <wait=40>on dit que le Roi des mers Leviathan y réside aussi.","story.map3-dungeon2.011":"Je me demande pourquoi il a quitté la mer pour vivre tout là-haut sur une montagne...","story.map3-dungeon2.012":"Hmm<wait=20>...","story.map3-dungeon2.013":"<size=12><wait=20>Euh... <wait=20>Brr...","story.map3-dungeon2.014":"Quoi ? <wait=40>Non vraiment, <wait=20>je vais très bien !","story.map3-dungeon2.015":"Mais on dirait que je suis restée si longtemps dans ce froid glacial que j\'ai attrapé un rhume...","story.map3-dungeon2.016":"Je vais partir devant. <wait=40>Bon courage pour l\'ascension de cette montagne enneigée !","story.map3-dungeon3.001":"*Soupir* <wait=20>Hmph... <wait=40>Encore un petit effort...","story.map3-dungeon3.002":"Oh, <wait=20><rep_handlename> ! <wait=40>Je t\'attendais.","story.map3-dungeon3.003":"Pour atteindre Maxwell, on doit passer par ici, <wait=40>la Forêt de sang.","story.map3-dungeon3.004":"Forêt de sang, quel nom sinistre...","story.map3-dungeon3.005":"La rumeur dit que ceux qui tentent de traverser cette forêt finissent par être retrouvés couverts de sang...","story.map3-dungeon3.006":"<size=20><size=18>C\'est <size=20>tellement, <size=16>tellement, <size=19><size=17>tellement, <size=18>absolument, <size=15>totalement <size=17>flippant<size=19> !","story.map3-dungeon3.007":"Quoi ? <wait=40>Tu trouves que je me comporte bizarrement ?","story.map3-dungeon3.008":"Je ne me comporte pas bizarrement ! <wait=40>Je suis aussi gracieuse que d\'habitude, tu ne trouves pas ?","story.map3-dungeon3.009":"Tu t\'inquiètes... <wait=20>pour moi ?","story.map3-dungeon3.010":"Je vois, <wait=20>mais si tu as le temps de dire des bêtises pareilles, dépêche-toi plutôt d\'affronter cette forêt !","story.map3-dungeon3.011":"Bonne chance !!","story.map3-dungeon3.012":"<size=12><wait=20>Ugh<wait=20>...","story.map3-dungeon4.001":"*Kof* <wait=20>*Kof*... <wait=40>Ahh, <wait=20>ugh...","story.map3-dungeon4.002":"Oh, <wait=40><rep_handlename>... <wait=40>Tu es là...","story.map3-dungeon4.003":"Je... <wait=40>ne peux <wait=40>plus te le cacher...","story.map3-dungeon4.004":"Mon état, <wait=20>ce n\'est pas une maladie. <wait=40>Je ne suis pas malade.","story.map3-dungeon4.005":"Maxwell... <wait=40>Elle m\'a jeté une malédiction.","story.map3-dungeon4.006":"Depuis... <wait=20>le moment où on a mis le pied à St. Lamia.","story.map3-dungeon4.007":"Maintenant qu\'on approche du Palais de St. Lamia, <wait=40>ça empire...","story.map3-dungeon4.008":"Maxwell me trouvait sûrement <wait=40>gênante...","story.map3-dungeon4.009":"Hmm ? <wait=40>Si tu n\'es pas touché, c\'est parce que...","story.map3-dungeon4.010":"Je... <wait=40>t\'en protège.","story.map3-dungeon4.011":"...<wait=40>Ça va. <wait=40>Ça ne me dérange pas.","story.map3-dungeon4.012":"Merci de t\'inquiéter... <wait=40>mais ça ira.","story.map3-dungeon4.013":"Je suis une déesse, <wait=40>ton guide...","story.map3-dungeon4.014":"Je te protégerai <wait=40>coûte que coûte...","story.map3-dungeon4.015":"Bientôt... <wait=40>on aura Maxwell.","story.map3-dungeon4.016":"<wait=20>Allons-y, <rep_handlename> !!","story.map3-dungeon4.017":"<size=12><wait=20>Ugh<wait=20>...","story.map3-dungeon5.001":"<speed=12>...Ugh. <wait=40>*Kof* <wait=20>*Souffle*... <wait=40>*Souffle*...","story.map3-dungeon5.002":"<speed=12><rep_handlename>... <wait=40>Je suis désolée... <wait=40>Je...","story.map3-dungeon5.003":"<speed=12>Je ne peux... <wait=40>pas aller plus loin<wait=40>...","story.map3-dungeon5.004":"<speed=12><rep_handlename>, <wait=40>je...","story.map3-dungeon5.005":"<speed=12>Je ne fais pas ça parce que Lord Lucius me l\'a demandé...","story.map3-dungeon5.006":"<speed=12>Je le fais parce que c\'est toi, <rep_handlename>... <wait=40>J-<wait=20>Je voulais juste te protéger.","story.map3-dungeon5.007":"<speed=12>J\'ai demandé à Lord Lucius de me laisser... <wait=40>*Kof* <wait=20>*Kof*","story.map3-dungeon5.008":"<speed=12>Il y a tant d\'autres endroits <wait=40>que je voulais visiter avec toi...","story.map3-dungeon5.009":"<speed=12>Je voulais <wait=40>voyager encore...","story.map3-dungeon5.010":"<speed=12>Mais... <wait=40>on dirait que le temps me manque...","story.map3-dungeon5.011":"<speed=12>Même si je tombe... <wait=40>ma magie continuera de te protéger.","story.map3-dungeon5.012":"<speed=12>Promets-moi<wait=20>.<wait=20>.<wait=40>.","story.map3-dungeon5.013":"<speed=10>...que <wait=40>tu vaincras <wait=40>sans faute <wait=12>Max<wait=10>we<wait=7>ll<wait=5>...","story.map3-dungeon5.014":"<speed=10>Ugh...","story.map3-dungeon5.015":"<size=24>(S\'évanouit)","story.map3-dungeon5.016":"...<wait=40>...<wait=40>...","story.map3-dungeon5.017":"Hé ! <wait=40>C\'est vraiment toi, <rep_handlename> !?","story.map3-dungeon5.018":"Tu dois être sacrément coriace, <wait=40>pour être arrivé jusqu\'ici tout seul...","story.map3-dungeon5.019":"Alors, comment ça s\'est passé avec Abaddon ??<wait=40>","story.map3-dungeon5.020":"<size=18>Hé, <wait=20>qu\'est-ce qui est arrivé à cette fille ?! <wait=40>Elle est toute bleue !!","story.map3-dungeon5.021":"<rep_handlename>... <wait=40>Ne me dis pas<wait=20>...","story.map3-dungeon5.022":"Ne me dis pas que tu ne sais toujours pas synthétiser d\'antidotes ?!","story.map3-dungeon5.023":"Je sais, je sais. <wait=40>Je plaisantais.","story.map3-dungeon5.024":"...Une malédiction ? <wait=40>Comment ça ?","story.map3-dungeon5.025":"Allons, qu\'est-ce que tu racontes !?","story.map3-dungeon5.026":"...<wait=60>...<wait=60>...<wait=60> !","story.map3-dungeon5.027":"Attends... <wait=40>tu es en train de dire que <wait=20>cette fille est une déesse ?","story.map3-dungeon5.028":"Tu ne te... <wait=40>moques pas <wait=20>de moi, <wait=40>hein ?","story.map3-dungeon5.029":"Et ?","story.map3-dungeon5.030":"...<wait=60>...<wait=60>...","story.map3-dungeon5.031":"Alors... <wait=40>c\'était Maxwell, hein...","story.map3-dungeon5.032":"J\'aimerais pouvoir aider, <wait=40>mais ça me dépasse...","story.map3-dungeon5.033":"Ce n\'est pas le genre de chose qu\'on soigne en synthétisant des potions...","story.map3-dungeon5.034":"Mais attends, <wait=40>cette malédiction a été jetée par Maxwell, non ?","story.map3-dungeon5.035":"Alors vaincre Maxwell devrait lever sa malédiction, tu ne crois pas ?","story.map3-dungeon5.036":"Et si vaincre Maxwell ne suffit pas, tu pourras toujours la frapper jusqu\'à ce qu\'elle crache le morceau !","story.map3-dungeon5.037":"C\'est le seul autre moyen auquel je pense pour l\'instant.","story.map3-dungeon5.038":"...<wait=20>Bien sûr. <wait=40>Je vais m\'occuper d\'elle.","story.map3-dungeon5.039":"Mon équipe a monté un camp pas loin, je vais l\'y emmener.","story.map3-dungeon5.040":"Tu devrais te dépêcher.","story.map3-dungeon5.041":"<size=22>Arrête de rester planté là à rêvasser !!","story.map3-dungeon5.042":"Elle souffre à cause de toi !","story.map3-dungeon5.043":"Ce n\'est pas le moment de traîner, tu devrais foncer vers le Palais de St. Lamia !","story.map3-dungeon5.044":"<size=14>...<wait=20>Quel idiot.","story.map3-dungeon7.001":"<size=20><rep_handlename> ! <wait=40>Content de te voir en vie !!","story.map3-dungeon7.002":"Pourquoi je suis là ? <wait=40>Mais pour t\'aider, voyons !","story.map3-dungeon7.003":"<size=20>Bon sang !","story.map3-dungeon7.004":"<size=24>*Tchac*","story.map3-dungeon7.005":"<size=24>*Tchac*","story.map3-dungeon7.006":"...Nom d\'un chien, <wait=40>c\'est toute une horde qu\'on a sur les bras, hein ?","story.map3-dungeon7.007":"Seria m\'a tout raconté.","story.map3-dungeon7.008":"Laisse-moi m\'occuper de tout ici.","story.map3-dungeon7.009":"Le temps presse, pas vrai ? <wait=40>Fonce !","story.map3-dungeon7.010":"<size=20>Argh !","story.map3-dungeon7.011":"<size=24>*Tchac*","story.map3-dungeon7.012":"<size=20>Va-t\'en d\'ici !!","story.map3-dungeon7.013":"<rep_handlename>... <wait=40>on compte sur toi...","story.map3-ending.001":"<size=20><rep_handlename> !!","story.map3-ending.002":"*Souffle*... <wait=40>hmph...","story.map3-ending.003":"Ma parole, <wait=40>l\'Invocateur a réussi...","story.map3-ending.004":"Maxwell, l\'un des Quatre Dieux déchus, a été vaincue !!","story.map3-ending.005":"Ouf... <wait=40>Mais il était moins une...","story.map3-ending.006":"<size=20><rep_handlename>, bien joué !!","story.map3-ending.007":"On dirait que vaincre Maxwell a bien levé la malédiction.","story.map3-ending.008":"Et comment, <wait=40>content de voir cette charmante jeune déesse s\'en remettre...","story.map3-ending.009":"Au fait, <wait=20>comment tu es arrivée ici avant moi ?!","story.map3-ending.010":"...<wait=20>Elle doit vraiment être une déesse. <wait=40>Ses pouvoirs ont dû revenir quand la malédiction a été levée.","story.map3-ending.011":"Je n\'arrive pas à croire que <rep_handlename> avait l\'aide d\'une déesse depuis le début<wait=40>...","story.map3-ending.012":"Et toi, Seria, tu m\'étonnes aussi. Tu t\'es vraiment donnée à fond pour ces deux-là, hein ?","story.map3-ending.013":"Je, <wait=30>je n\'ai pas agi pour défendre <rep_handlename>.","story.map3-ending.014":"J\'ai fait ce que j\'ai fait pour la déesse, et pour le monde.","story.map3-ending.015":"C\'est bon, c\'est bon... <wait=40>Arrête un peu.","story.map3-ending.016":"<size=18>Tu as vaincu Maxwell ! C\'est bien mon <rep_handlename> !!","story.map3-ending.017":"...<wait=40>Bon, <wait=20>d\'accord.","story.map3-ending.018":"Bref, <wait=40>pour un débutant, progresser aussi vite...","story.map3-ending.019":"Eh bien, <wait=40>c\'est vraiment quelque chose.","story.map3-ending.020":"<rep_handlename> ! <wait=40>Je reconnais que tu es un véritable...","story.map3-ending.021":"<rep_handlename> a réussi !! <wait=40><rep_handlename> a gagné !!","story.map3-ending.022":"Abaddon, et même Maxwell, ils ont tous été vaincus !!","story.map3-ending.023":"J\'étais un peu inquiète lors de notre première rencontre...","story.map3-ending.024":"...mais maintenant, <wait=20>pas de doute, tu es l\'Invocateur le plus fort qui soit !!","story.map3-ending.025":"<size=18>E-<wait=20>Excuse-moi ! <wait=40>Tu es franchement agaçante, tu ne pourrais pas te calmer un peu !","story.map3-ending.026":"Tu ne peux pas m\'en vouloir. <wait=40>Mon Invocateur a vaincu l\'un des Quatre Dieux déchus !","story.map3-ending.027":"Je n\'ai jamais été aussi heureuse !","story.map3-ending.028":"Oh, la ferme ! <wait=40>Arrête de couper la parole aux gens !!","story.map3-ending.029":"Et c\'est quoi, ces mièvreries <wait=40>« mon <rep_handlename> » !?","story.map3-ending.030":"Vous n\'êtes pas en couple, quand même ?!","story.map3-ending.031":"Mon <rep_handlename> est mon <rep_handlename> !","story.map3-ending.032":"J\'ai risqué ma vie pour garder <rep_handlename> en vie.","story.map3-ending.033":"Et en plus, <wait=20><rep_handlename> s\'est donné tant de mal pour me sauver...","story.map3-ending.034":"<rep_handlename> et moi, nous sommes liés par le destin !","story.map3-ending.035":"Alors, qu\'est-ce qu\'il y a ? <wait=40>T\'es jalouse ou quoi ?","story.map3-ending.036":"<size=20>J-Ja-Jalouse d\'une gamine pareille !?","story.map3-ending.037":"<size=18>Et c\'est quoi, cette histoire de destin ? <wait=40><size=24>T\'es bête ou quoi !?","story.map3-ending.038":"...Hé, <wait=20>calmez-vous toutes les deux...","story.map3-ending.039":"Il faut être idiote pour subir une malédiction à la place de quelqu\'un comme <rep_handlename>. <wait=20>Quelle bêtise !","story.map3-ending.040":"<rep_handlename> s\'en serait très bien sorti même si tu l\'avais laissé tranquille !!","story.map3-ending.041":"En plus, <wait=20>tu n\'es pas censée être une déesse ?!","story.map3-ending.042":"Tu n\'aurais pas pu briser la malédiction toi-même ?!","story.map3-ending.043":"Qu\'est-ce que ça veut dire !? <wait=40>Tu insinues que je n\'ai pas fait de mon mieux !?","story.map3-ending.044":"Tu étais au bord de la mort au Sanctuaire isolé !","story.map3-ending.045":"Si je n\'avais pas été là, ces monstres t\'auraient dévorée !!","story.map3-ending.046":"N\'importe quoi ! <wait=40><rep_handlename> m\'aurait protégée même sans toi !","story.map3-ending.047":"Tu parles beaucoup, mais tu n\'as rien fait non plus !","story.map3-ending.048":"A-<wait=10>Attends un peu !! <wait=40>Qui t\'a soignée, d\'après toi !","story.map3-ending.049":"J\'étais inconsciente, je ne me souviens de rien...","story.map3-ending.050":"Espèce de petite... !!","story.map3-ending.051":"Hé, vous deux... <wait=40>Arrêtez un peu.","story.map3-ending.052":"<size=24>Tais-toi !!","story.map3-ending.053":"Whoa...","story.map3-ending.054":"D\'abord, pourquoi Seria joue-t-elle toujours les cheffes avec <rep_handlename> !?","story.map3-ending.055":"Elle n\'a même pas pu vaincre Graham, sans parler d\'Abaddon !","story.map3-ending.056":"<size=12>Aïe... <wait=40>Moi aussi j\'étais dans ce combat, hein...","story.map3-ending.057":"Arrête de te moquer de mon <rep_handlename> !!","story.map3-ending.058":"J-<wait=20>Je dis ce que je veux ! <wait=40>Tu cherches la bagarre !?","story.map3-ending.059":"C\'est toi qui as commencé !","story.map3-ending.060":"Et sache que je suis plutôt puissante quand je ne suis pas maudite !","story.map3-ending.061":"<size=24>Oh, pour l\'amour du ciel ! <wait=40>Ça suffit !!","story.map3-ending.062":"<rep_handlename> a vaincu Maxwell !","story.map3-ending.063":"Ce n\'est pas le moment de se disputer.","story.map3-ending.064":"...Hmph.","story.map3-ending.065":"Hmph.","story.map3-ending.066":"Vous deux, <wait=20>vous vous comportez encore pire que Maxwell...","story.map3-ending.067":"Mais bref, <wait=20>je dois vraiment te tirer mon chapeau, <wait=20><rep_handlename>.","story.map3-ending.068":"Je suis fier d\'être ton ami.","story.map3-ending.069":"...<wait=40>Ça m\'agace de le dire, <wait=40>mais je ne peux pas nier que tu as bel et bien vaincu Maxwell.","story.map3-ending.070":"<wait=40>Beau travail.","story.map3-ending.071":"Ouf.","story.map3-ending.072":"Bon, <wait=20>Seria et moi devons y aller.","story.map3-ending.073":"...Hein ? <wait=40>Pas besoin de me remercier.","story.map3-ending.074":"Promets-moi juste de nous donner un coup de main la prochaine fois qu\'on sera dans le pétrin !","story.map3-ending.075":"À la prochaine, l\'ami.","story.map3-ending.076":"Hmph, <wait=20>au revoir.","story.map3-ending.077":"...Bon, <wait=40>laisse-moi te le redire.","story.map3-ending.078":"Félicitations ! <wait=40><rep_handlename>.","story.map3-ending.079":"J\'étais sûre que tu vaincrais Maxwell.","story.map3-ending.080":"Mais au lieu de t\'aider... <wait=40>c\'est toi qui m\'as aidée.","story.map3-ending.081":"Je suis vraiment heureuse. <wait=40>Merci.","story.map3-ending.082":"Héhé. <wait=40>Oh là là, c\'est gênant.","story.map3-ending.083":"Ah, <wait=20>c\'est vrai. On s\'était promis de visiter plein d\'endroits ensemble, non ?","story.map3-ending.084":"Je croyais que j\'allais mourir, <wait=40>c\'est pour ça que je t\'ai fait faire cette promesse.","story.map3-ending.085":"Mais maintenant que tu as vaincu Maxwell, on risque d\'être encore plus occupés.","story.map3-ending.086":"Maxwell a beau avoir été vaincue, <wait=40>les Dieux déchus sont quatre en tout.","story.map3-ending.087":"Il en reste encore trois.","story.map3-ending.088":"Tant que tu n\'auras pas vaincu tous les Dieux déchus, <wait=40>la paix ne reviendra pas sur Grand Gaia.","story.map3-ending.089":"Cela dit, <wait=40>il va falloir reporter l\'aventure qu\'on s\'était promise.","story.map3-ending.090":"Je suis vraiment désolée, <wait=40>mais les déesses sont très occupées, tu sais.","story.map3-ending.091":"Bon, <wait=40>il est temps que j\'aille faire mon rapport à Lord Lucius.","story.map3-ending.092":"Continue de t\'entraîner, <wait=20>tu dois devenir encore plus fort si tu comptes vaincre les autres Dieux déchus.","story.map3-ending.093":"Oh, <wait=40>et encore une chose...","story.map3-ending.094":"Si tu revois ces deux-là, dis-leur merci de ma part.","story.map3-ending.095":"Dis-leur que je leur suis vraiment reconnaissante pour tout ce qu\'ils ont fait pour nous.","story.map3-ending.096":"Bon, <wait=20>je vais y aller !","story.map3-ending.097":"On se reverra bientôt, <wait=20>j\'en suis sûre !","story.map3-ending.098":"À plus !!!","story.map4-dungeon1.001":"Pff... Pas l\'ombre d\'un<br>monstre depuis que je suis arrivé !","story.map4-dungeon1.002":"J\'y crois pas... <wait=40> Pourquoi moi, le puissant Lugina, je me coltine des tâches aussi minables...","story.map4-dungeon1.003":"Hm ?<wait=40><br>Hé, toi, là-bas ! <wait=20>Identifie-toi !","story.map4-dungeon1.004":"Aha ! <wait=20>Un membre de l\'armée d\'Akras, hein ?<br>C\'est quoi ton nom ?","story.map4-dungeon1.005":"<rep_handlename> ?<wait=40><br>Pff... <wait=40>Drôle de nom, si tu veux mon avis.","story.map4-dungeon1.006":"Quoi ?<wait=40><br>Tu veux connaître mon nom ?","story.map4-dungeon1.007":"J\'ai aucune raison de me présenter<br>à un membre de l\'armée régulière, mais...","story.map4-dungeon1.008":"<wait=20>...Bon, si tu tiens vraiment à le savoir, ça ne peut pas faire de mal.","story.map4-dungeon1.009":"Je suis le puissant Invocateur Lugina,<wait=40><br>illustre chef de la 23e division des Pourfendeurs de démons,<wait=40>","story.map4-dungeon1.010":"aussi connue sous le nom de Sky Garden !<br>Grave-toi bien ça dans le crâne !","story.map4-dungeon1.011":"Alors,<wait=40> tu cherches quelque chose par ici, ou quoi ?","story.map4-dungeon1.012":"Hein ?<wait=40> Ta mission, c\'est de vaincre les Quatre Dieux déchus ?","story.map4-dungeon1.013":"Pff... Héhé... <size=24>Bwahaha !","story.map4-dungeon1.014":"Alors les vieux croulants d\'Akras<br>ont vraiment commencé à perdre la boule !","story.map4-dungeon1.015":"Tu crois sérieusement que l\'armée régulière<br>a une chance de vaincre les Quatre Dieux déchus ?","story.map4-dungeon1.016":"Il est temps que ces vieux fossiles prennent leur retraite<br>et laissent la chasse aux démons aux pros comme moi.","story.map4-dungeon1.017":"Hmm ? <wait=40>Tu reçois tes ordres d\'une déesse, tu dis ?<br>Pas du Hall des Invocateurs ?","story.map4-dungeon1.018":"...C\'est une blague ?<wait=40><br>Ou t\'es vraiment aussi bête que ça ?","story.map4-dungeon1.019":"Tu sais au moins ce que je fais<br>aussi loin de chez moi ?","story.map4-dungeon1.020":"Incroyable... <wait=40>Tu vois, c\'est pour ça que je dis toujours","story.map4-dungeon1.021":"qu\'on ne peut pas faire confiance à l\'armée régulière.","story.map4-dungeon1.022":"Tu sais au moins que ce territoire<br>où on se tient vient d\'être découvert par le Hall des Invocateurs d\'Akras ?","story.map4-dungeon1.023":"Il n\'a pas encore été exploré correctement,<br>alors tu ferais bien de regarder où tu mets les pieds.","story.map4-dungeon1.024":"Tu vois le genre : des monstres et tout le tralala.","story.map4-dungeon1.025":"Bref, c\'est aux Invocateurs puissants<br>et redoutables comme votre serviteur","story.map4-dungeon1.026":"de s\'assurer que les zones potentiellement<br>dangereuses comme celle-ci soient assez sûres","story.map4-dungeon1.027":"pour que des Invocateurs débutants<br>comme toi puissent y mettre les pieds.","story.map4-dungeon1.028":"Si t\'as un peu de jugeote,<br>va voir un endroit plus sûr en attendant que j\'aie fini ici !","story.map4-dungeon1.029":"Il y a plein de zones à Grand Gaia<br>qui n\'ont pas encore été explorées correctement.","story.map4-dungeon1.030":"Quoi ? J\'ai bégayé ou quoi ?<wait=40><br>Bon sang, t\'es aussi bête que t\'en as l\'air.","story.map4-dungeon1.031":"Tiens, je vais être plus clair...<br><wait=40>Dégage de mon chemin et laisse-moi bosser en paix !<wait=40>","story.map4-dungeon1.032":"Arrête de perdre ton temps avec ces petits sbires et va chercher ailleurs !","story.map4-dungeon1.033":"Tss... Avec des abrutis pareils dans l\'armée régulière, pas étonnant que le Hall des Invocateurs ait des soucis...","story.map4-dungeon2.001":"Encore toi ?!<wait=40><br>Je t\'ai dit de dégager !","story.map4-dungeon2.002":"T\'as du culot de<br>m\'ignorer comme ça !","story.map4-dungeon2.003":"Ou alors t\'as besoin qu\'on te tienne<br>la main pour rentrer chez toi ?","story.map4-dungeon2.004":"Bon sang... <wait=40>Même ceux de l\'Armée impériale ne sont pas aussi incompétents.","story.map4-dungeon2.005":"Hein ?<wait=40><br>C\'est quoi cet air ahuri ?","story.map4-dungeon2.006":"Attends une seconde... <wait=40>Ne me dis pas que tu n\'as <br>jamais entendu parler de l\'Armée impériale de Randall ?","story.map4-dungeon2.007":"Ouah. Juste... ouah...","story.map4-dungeon2.008":"Sérieux, tu me ferais presque<br>pitié.","story.map4-dungeon2.009":"Dans ce cas, pas le choix.","story.map4-dungeon2.010":"Moi, Lugina, au cœur pur et vertueux, je vais t\'apprendre tout ce que tu dois savoir !","story.map4-dungeon2.011":"Sèche tes larmes de gratitude<br>et retiens bien ce que je vais te dire !","story.map4-dungeon2.012":"On commence en douceur. <wait=40>Tu sais déjà que notre terre d\'Elgaia a été séparée de Grand Gaia.","story.map4-dungeon2.013":"Tu sais, la Terre des dieux,<br>non ?","story.map4-dungeon2.014":"Bien,<wait=40> au moins tu sais quelque chose !","story.map4-dungeon2.015":"Je vois pas de quoi t\'es si fier !<wait=40> C\'est ce qu\'il y a de plus banal comme savoir.","story.map4-dungeon2.016":"Bon sang...","story.map4-dungeon2.017":"OK, continuons. <wait=40>Elgaia se compose de deux grands pays.","story.map4-dungeon2.018":"L\'un d\'eux, l\'Empire de Randall, abrite le Hall des Invocateurs d\'Akras.","story.map4-dungeon2.019":"Le Hall des Invocateurs d\'Akras gère les affaires économiques","story.map4-dungeon2.020":"et militaires du pays, alors tout ce cirque impérial, c\'est surtout de la façade.","story.map4-dungeon2.021":"L\'élite de Randall descend<br>de ceux qui ont rebâti le pays après sa","story.map4-dungeon2.022":"séparation de Grand Gaia, ce qui explique en partie leurs grands airs.","story.map4-dungeon2.023":"Aujourd\'hui, c\'est juste une bande de vieux fossiles qui profitent de leur vie dorée.","story.map4-dungeon2.024":"Inutile de dire que leur armée est surtout décorative, une démonstration d\'autorité, si tu veux.","story.map4-dungeon2.025":"Même si, j\'imagine, un ou deux soldats doués sont passés par ses rangs de temps en temps.","story.map4-dungeon2.026":"Bref, <wait=40>l\'autre pays, c\'est la Fédération d\'Elgaia,","story.map4-dungeon2.027":"mais leur histoire est assez similaire.","story.map4-dungeon2.028":"Aucun des deux pays n\'a l\'étoffe pour tenir tête au Hall des Invocateurs d\'Akras,","story.map4-dungeon2.029":"alors le Hall règne en pratique sur<br>tout Elgaia.","story.map4-dungeon2.030":"Et comme je suis l\'Invocateur le plus puissant<br>du Hall des Invocateurs d\'Akras,","story.map4-dungeon2.031":"ça fait de moi le plus puissant de tout Elgaia !","story.map4-dungeon2.032":"Alors ?<wait=40><br>Tu veux sûrement un autographe, hein ?","story.map4-dungeon2.033":"<size=14>(Grondement, grondement)","story.map4-dungeon2.034":"Ou-<wait=20>Ouah !","story.map4-dungeon2.035":"C-<wait=20>C\'était un séisme ?!","story.map4-dungeon2.036":"Pourtant, ça ne ressemblait pas<br>à un séisme ordinaire...","story.map4-dungeon2.037":"Tu vois ce que je veux dire, maintenant ?!","story.map4-dungeon2.038":"Cordelica ne sera pas sûr tant qu\'on n\'aura pas compris ce qui se passe.","story.map4-dungeon2.039":"Alors écoute mes sages paroles, et file d\'ici tant que tu le peux encore !","story.map4-dungeon2.040":"Tu le regretteras si nos chemins se croisent encore !","story.map4-dungeon3.001":"<size=20>Encore toi ?!<wait=40> <rep_handlename> !","story.map4-dungeon3.002":"Qu\'est-ce que tu fais encore là !?","story.map4-dungeon3.003":"Bon, ça suffit !","story.map4-dungeon3.004":"Si tu ne veux pas écouter mes conseils,<wait=40> je vais devoir te remettre les idées en place à coups de poing !","story.map4-dungeon3.005":"Maintenant, bouge pas !","story.map4-dungeon3.006":"<size=14>(Grondement, grondement)","story.map4-dungeon3.007":"E-Encore !<wait=40><br>C\'est quoi, tous ces séismes ces derniers temps ?","story.map4-dungeon3.008":"Hé !<wait=40> <rep_handlename> !","story.map4-dungeon3.009":"Tu vois de quoi je parle,<br>maintenant ?","story.map4-dungeon3.010":"C\'est pas un endroit pour qu\'un Invocateur débutant comme toi traîne dans le coin.","story.map4-dungeon3.011":"Alors rentre chez toi et vérifie<br>que ce n\'est pas l\'Armée impériale qui manigance quelque chose !","story.map4-dungeon3.012":"...<wait=20>C\'est quoi ce regard ?","story.map4-dungeon3.013":"Pourquoi j\'ai l\'impression que tu ne mesures toujours pas à quel point je suis génial...","story.map4-dungeon3.014":"Bon, écoute bien.<wait=40><br>Je te l\'ai dit tout à l\'heure,","story.map4-dungeon3.015":"mais ici, à Elgaia, il y a plusieurs factions distinctes,<br>chacune avec sa propre armée.","story.map4-dungeon3.016":"La plus forte de ces armées appartient au Hall des Invocateurs d\'Akras.","story.map4-dungeon3.017":"C\'est logique, non ?<br>Après tout, ils regroupent presque tous les","story.map4-dungeon3.018":"Invocateurs d\'Elgaia...","story.map4-dungeon3.019":"Bref, l\'armée d\'Akras se compose<br>de trois types de forces.","story.map4-dungeon3.020":"D\'abord, <wait=40>il y a l\'Armée des Invocateurs, alias l\'Armée régulière, où chaque Invocateur débutant","story.map4-dungeon3.021":"fait ses débuts. C\'est ton régiment, au passage.","story.map4-dungeon3.022":"Votre mission officielle est de vaincre les Quatre Dieux déchus, mais... bon, comment dire ?","story.map4-dungeon3.023":"À vrai dire, personne ne s\'attend vraiment<br>à ce que l\'Armée régulière accomplisse quoi que ce soit.","story.map4-dungeon3.024":"Alors de qui on attend des résultats, tu demandes ?<br>Eh bien, de ma bande, les Pourfendeurs de démons !","story.map4-dungeon3.025":"On est une escouade d\'élite d\'Invocateurs<br>triés sur le volet dans les rangs de l\'Armée régulière.","story.map4-dungeon3.026":"Les plus forts, comme moi par exemple, reçoivent ensuite le commandement d\'escouades plus petites.","story.map4-dungeon3.027":"Et bien sûr, la plus forte de toutes, c\'est celle que je dirige :","story.map4-dungeon3.028":"la 23e division des Pourfendeurs de démons, Sky Garden !","story.map4-dungeon3.029":"Et toi qui pensais que je ne pouvais<br>pas faire mieux, hein ?","story.map4-dungeon3.030":"Hmm ? <wait=40>Et les armées de Randall<br>et de la Fédération d\'Elgaia, tu dis ?","story.map4-dungeon3.031":"Ha ! À elles deux, elles ont à peine une poignée d\'Invocateurs. Elles sont encore plus inutiles que notre Armée régulière.","story.map4-dungeon3.032":"Maintenant arrête de me harceler de questions, et file chez toi, là où est ta place !","story.map4-dungeon3.033":"Les monstres du coin ne sont pas<br>des mauviettes comme ceux que tu as l\'habitude d\'affronter !","story.map4-dungeon3.034":"Tu m\'entends ? Du vent !","story.map4-dungeon3.035":"*Soupir* <wait=40>Qu\'est-ce que j\'ai fait<br>pour être envoyé aussi loin ?","story.map4-dungeon3.036":"Alors ils ont envoyé le Pourfendeur de démons Lugina, du Sky Garden...","story.map4-dungeon3.037":"Heh. Ils voulaient sans doute juste<br>qu\'il arrête de les embêter un moment...","story.map4-dungeon3.038":"Quoi qu\'il en soit, il semble assez facile à utiliser pour mes desseins.","story.map4-dungeon3.039":"Il ne reste plus qu\'à élaborer un plan...","story.map4-dungeon4.001":"<size=20>Encore toi ?! <rep_handlename> !","story.map4-dungeon4.002":"Ça suffit ! Fini d\'être gentil !","story.map4-dungeon4.003":"J\'espère que tu aimes l\'endroit où tu te tiens, parce que c\'est là que je vais t\'enterrer quand j\'en aurai fini !","story.map4-dungeon4.004":"<size=18>(Grondement, grondement)","story.map4-dungeon4.005":"Encore un... ?<br>Ces séismes ne sont vraiment pas normaux.","story.map4-dungeon4.006":"Ces vieux idiots du Hall des Invocateurs...<br>Que le diable les emporte tous !","story.map4-dungeon4.007":"Écoute, <rep_handlename> !","story.map4-dungeon4.008":"Cet endroit est trop dangereux pour<br>qu\'on traîne ici.","story.map4-dungeon4.009":"Je rédige mes conclusions et je rentre<br>à Elgaia sur-le-champ. <wait=40>Tu seras mon témoin, hein ?","story.map4-dungeon4.010":"Pense à tout ce que je t\'ai appris !<br>Tu ne laisserais pas tomber un vieux pote, quand même ?","story.map4-dungeon4.011":"Des propos plutôt lâches pour un gradé autoproclamé des Pourfendeurs de démons, tu ne trouves pas ?","story.map4-dungeon4.012":"...?!<br><wait=40>Qui es-tu ?","story.map4-dungeon4.013":"C-Ces armoiries...","story.map4-dungeon4.014":"C\'est pas possible !<br>Un membre de la Garde impériale ?!","story.map4-dungeon4.015":"C\'est exact.<br>Tu as peut-être l\'étoffe d\'un professeur, après tout.","story.map4-dungeon4.016":"Je m\'appelle Paris. J\'appartiens à l\'une<br>des forces « inutiles » que tu décrivais tout à l\'heure.","story.map4-dungeon4.017":"Tu nous espionnais depuis le début ?<br>On ne t\'a jamais appris les bonnes manières ?","story.map4-dungeon4.018":"Je pourrais te retourner la question.","story.map4-dungeon4.019":"Ou bien considères-tu qu\'ignorer les ordres<br>de ton pays, sans parler de rabaisser","story.map4-dungeon4.020":"l\'Armée impériale qui œuvre<br>pour la prospérité de notre royaume, soit le comportement d\'une personne honorable ?","story.map4-dungeon4.021":"Pff...<br><wait=40>Oh, je suis vraiment désolé ! Pardonnez-moi, je vous en prie !","story.map4-dungeon4.022":"Comme je m\'y attendais, vous, les membres<br>du Hall des Invocateurs, êtes tous aussi grossiers les uns que les autres...","story.map4-dungeon4.023":"Raconte ça à quelqu\'un que ça intéresse,<br>ma petite dame !","story.map4-dungeon4.024":"D\'ailleurs, vous, les abrutis de la Garde impériale,<br>vous protégez la famille impériale, non ?","story.map4-dungeon4.025":"Qu\'est-ce que tu fabriques aussi loin ?","story.map4-dungeon4.026":"J\'ai pas toute la journée,<br>alors crache le morceau, et vite !","story.map4-dungeon4.027":"Heh...<br>Tu as du caractère, pour un acolyte.","story.map4-dungeon4.028":"Qui tu traites d\'acolyte ?!","story.map4-dungeon4.029":"Tu crois que moi et cet idiot-là, on fait équipe ? Ha !","story.map4-dungeon4.030":"Peu importe, ma petite dame.<br>J\'ai mieux à faire de","story.map4-dungeon4.031":"mon temps que de chercher des noises à la<br>Garde impériale au fin fond de nulle part.","story.map4-dungeon4.032":"Ah, la fameuse diplomatie des Pourfendeurs de démons.<br>Au moins, chacun sait à quoi s\'en tenir.","story.map4-dungeon4.033":"Eh bien, à vrai dire, j\'ai fait tout ce chemin pour te demander une faveur.","story.map4-dungeon4.034":"Nous voulons ton aide<br>pour enquêter sur Cordelica.","story.map4-dungeon4.035":"Ha !<wait=40><br>T\'as vraiment dit ce que je crois ?","story.map4-dungeon4.036":"Je cherche pas les ennuis, <wait=40>mais je vais pas non plus obéir à tes ordres !","story.map4-dungeon4.037":"Cet endroit n\'est pas sûr pour nous,<br>au cas où tu ne l\'aurais pas remarqué.","story.map4-dungeon4.038":"Je vois que tu as conscience du danger<br>que représente cette région.","story.map4-dungeon4.039":"Bien sûr, je n\'en attendais pas<br>moins d\'un chef autoproclamé des Pourfendeurs de démons.","story.map4-dungeon4.040":"Qu\'est-ce que tu insinues, hein ?","story.map4-dungeon4.041":"Insinuer ?<wait=40> Non, je ne fais qu\'énoncer des faits.","story.map4-dungeon4.042":"Quelqu\'un qui a peur de<br>quelques malheureux séismes ne pourrait","story.map4-dungeon4.043":"sûrement pas diriger une escouade aussi talentueuse que tu le prétends.","story.map4-dungeon4.044":"Espèce de...!<wait=40><br>Surveille ton langage !","story.map4-dungeon4.045":"Tu me traites de lâche ?!","story.map4-dungeon4.046":"Me fais pas rire !<wait=40><br>Je vais te montrer ce que c\'est, avoir peur !","story.map4-dungeon4.047":"Hé !<wait=40> <rep_handlename> !","story.map4-dungeon4.048":"Il est temps que tu fasses ta part du boulot !","story.map4-dungeon4.049":"Jusqu\'ici, t\'as ignoré tout ce<br>que je t\'ai dit.","story.map4-dungeon4.050":"Tu te prends sûrement pour un as, hein ?","story.map4-dungeon4.051":"Eh bien, si t\'es si doué, prouve-le en te débarrassant du minus planqué dans cette forteresse là-bas !","story.map4-dungeon4.052":"Les monstres qu\'on va croiser vont<br>devenir plus coriaces à partir de maintenant,","story.map4-dungeon4.053":"mais même toi, tu ne devrais avoir<br>aucun mal avec ceux-là.","story.map4-dungeon4.054":"Héhé... <wait=40>Voilà qui devrait être intéressant.","story.map4-dungeon4.055":"...Alors ?! Reste pas planté là à bayer aux corneilles !<wait=40><br>Va leur botter les fesses !","story.map4-dungeon4.056":"Tu as entendu le monsieur,<br><rep_handlename>... Héhé.","story.map4-dungeon5.001":"Hmph ! <wait=40>T\'as vraiment pris<br>ton temps pour arriver.","story.map4-dungeon5.002":"Et on se demande pourquoi je n\'ai pas plus<br>de respect pour vous autres de l\'Armée régulière.","story.map4-dungeon5.003":"Enfin, au moins t\'as devancé cette donneuse de leçons de la Garde impériale, c\'est déjà ça.","story.map4-dungeon5.004":"Et de qui pourrait-il bien s\'agir ?","story.map4-dungeon5.005":"Qu- ? <wait=20>Toi ?!<wait=40><br>Depuis combien de temps t\'es là !","story.map4-dungeon5.006":"Depuis juste avant que tu arrives<br>et que tu te ridiculises.","story.map4-dungeon5.007":"Espèce de... ! <wait=40>Tu m\'as<br>observé tout ce temps !","story.map4-dungeon5.008":"Oh, détends-toi, tu veux ?","story.map4-dungeon5.009":"J\'ai des choses plus importantes à faire<br>que d\'analyser chacun de tes faits et gestes.","story.map4-dungeon5.010":"Argh, laissez-moi la massacrer !","story.map4-dungeon5.011":"C\'est pour ça que je déteste vous autres de la Garde<br>impériale, vous êtes toujours si fichtrement suffisants !","story.map4-dungeon5.012":"Tu pourras te plaindre plus tard.<wait=40><br>D\'abord, dis-moi ce que tu fais ici.","story.map4-dungeon5.013":"Hein ?<wait=40> <br>C\'est une blague ?","story.map4-dungeon5.014":"Je suis là pour explorer les ruines, évidemment.","story.map4-dungeon5.015":"Regarde-les ! Elles doivent<br>être là depuis avant le Grand Effondrement.","story.map4-dungeon5.016":"T\'as déjà vu un endroit qui<br>réclame autant qu\'on l\'explore ?","story.map4-dungeon5.017":"Bref, je suis venu les examiner,<br>et celui-là n\'arrête pas de me suivre.","story.map4-dungeon5.018":"Je vois...<wait=40><br>Donc tu sais lire l\'écriture ancienne, j\'imagine ?","story.map4-dungeon5.019":"J\'avais l\'impression que c\'était moi<br>qui étais censée mener l\'enquête...","story.map4-dungeon5.020":"Quoi ? Tu crois que je suis pas à la hauteur, c\'est ça !?","story.map4-dungeon5.021":"T\'es la seule capable<br>de réfléchir, c\'est ça ?","story.map4-dungeon5.022":"Non, <wait=40>en fait, je suis plutôt impressionnée.","story.map4-dungeon5.023":"Tu n\'es peut-être pas aussi bête que<br>ton allure bourrue le laisse penser.","story.map4-dungeon5.024":"...<wait=40>Je te préviens,<br>ma petite dame.","story.map4-dungeon5.025":"Crois pas que je vais rester sans réagir si tu continues à me chercher.","story.map4-dungeon5.026":"Et crois-moi, quand je me fâche,<br>je suis capable de réduire les choses en poussière !","story.map4-dungeon5.027":"Garde impériale ou pas.","story.map4-dungeon5.028":"Mon Dieu, comme c\'est effrayant.<br>Je ferais mieux de rester dans tes bonnes grâces, alors.","story.map4-dungeon5.029":"Grrr...<wait=40><br>Je le savais ! Tu te moques de moi !","story.map4-dungeon5.030":"Héhé...<wait=40><br>Tu me crois vraiment aussi cruelle ?","story.map4-dungeon5.031":"D\'ailleurs, tu ferais sans doute bien de ne pas contrarier Lugina non plus, compris ?","story.map4-dungeon5.032":"Non pas que j\'imagine<br>un ami de Karl se laisser","story.map4-dungeon5.033":"effrayer par un membre du Sky Garden...","story.map4-dungeon5.034":"Hein ?<wait=40><br>Ce Karl dont tu parles... <wait=40>Ce ne serait pas Karl de Nyonne, par hasard ?","story.map4-dungeon5.035":"<size=20>Bwahaha !","story.map4-dungeon5.036":"Oh, ça fait une éternité que je n\'avais pas ri comme ça.<wait=40><br>L\'idée même que cet abruti puisse être ami avec Karl !","story.map4-dungeon5.037":"Là, j\'aurai vraiment tout entendu...","story.map4-dungeon5.038":"Hé, où tu crois aller comme ça !","story.map4-dungeon5.039":"Enquêter.<wait=40><br>On couvrira plus de terrain en se séparant, tu ne crois pas ?","story.map4-dungeon5.040":"Lugina,<wait=40><br>tu vérifies par là.","story.map4-dungeon5.041":"A-Attends !<wait=40><br>Comment je suis censé savoir où...","story.map4-dungeon5.042":"...Hmph.","story.map4-dungeon5.043":"Quitte à me mentir en face,<br>elle pourrait au moins essayer d\'être un peu crédible.","story.map4-dungeon5.044":"Heh, comme si cet ignare à la noix<br>pouvait vraiment connaître Karl...","story.map4-dungeon5.045":"Grr... <wait=40>Rien que de penser à<br>ce joli cœur à la tête de fillette, mon sang ne fait qu\'un tour !","story.map4-dungeon5.046":"Hé, toi ! <wait=40>Reste pas planté là les bras ballants ! Va t\'occuper de ces monstres !","story.map4-dungeon6.001":"<size=20>Argh, <wait=40>ça suffit !","story.map4-dungeon6.002":"J\'en ai marre !<br>Qu\'est-ce que j\'ai fait pour mériter ça, hein ?!","story.map4-dungeon6.003":"Pourquoi c\'est toujours moi qui dois<br>affronter des bêtes aussi monstrueuses !","story.map4-dungeon6.004":"C\'est pas juste !<wait=40><br>J\'ai rien fait pour mériter ça !","story.map4-dungeon6.005":"Aaah !!<wait=40><br>...Oh, c\'est juste toi, <rep_handlename>.","story.map4-dungeon6.006":"Tss... J\'ai eu que des ennuis<br>depuis que je suis tombé sur toi.","story.map4-dungeon6.007":"Toujours en train de te plaindre, à ce que je vois ?<br>Vraiment, Lugina, ce n\'est pas digne d\'un homme de ton rang.","story.map4-dungeon6.008":"Toi, la ferme !<wait=40><br>C\'est quoi l\'idée, de toujours me surprendre comme ça !","story.map4-dungeon6.009":"T\'es une des raisons pour lesquelles je me suis<br>retrouvé embarqué dans ce bazar !","story.map4-dungeon6.010":"Notre situation actuelle est loin d\'être idéale,<br>je te l\'accorde.","story.map4-dungeon6.011":"Mais insulter les gens et te plaindre ne changera rien à la situation.","story.map4-dungeon6.012":"Tu crois que je le sais<br>pas déjà ?!","story.map4-dungeon6.013":"J\'ai une nouvelle pour toi : je ratisse pas ces tunnels crasseux pour le plaisir, d\'accord !","story.map4-dungeon6.014":"Héhé...<wait=40><br>Non, je vois bien.","story.map4-dungeon6.015":"Cela dit, tu as l\'air de savoir<br>ce qu\'il faut faire.","story.map4-dungeon6.016":"Exact. <wait=40>Et c\'est bien de ça que je me plains.","story.map4-dungeon6.017":"Bon ! Traversons ce tunnel une bonne<br>fois pour toutes et filons aux Ruines du géant.","story.map4-dungeon6.018":"Eh bien, quelqu\'un a l\'air pressé...<wait=40> Tu ferais bien de te dépêcher, toi aussi.","story.map4-dungeon6.019":"Si on ne se presse pas, les grands dieux vont<br>s\'éveiller et ravager tout ce continent.","story.map4-dungeon6.020":"On n\'a pas le temps d\'expliquer les choses à cet abruti !","story.map4-dungeon6.021":"Je passe devant.","story.map4-dungeon6.022":"Toi, tu achèves les traînards qui<br>arrivent à me passer sous le nez !","story.map4-dungeon6.023":"Heh...<wait=40><br>Parole de vrai guerrier, Lugina.","story.map4-dungeon6.024":"Mais tu te trompes sur un point.","story.map4-dungeon6.025":"<rep_handlename> a le droit de connaître<br>le danger de notre situation.","story.map4-dungeon6.026":"Tu as vu <rep_handlename> se battre,<br>n\'est-ce pas ?","story.map4-dungeon6.027":"Nous devrions tirer parti de toute<br>la puissance militaire à notre portée.","story.map4-dungeon6.028":"Hmph ! <wait=40>Fais comme tu veux.<br>Mais je te laisse toutes les explications !","story.map4-dungeon6.029":"J\'en ai ras le bol de<br>jouer la nounou pour ce gamin trop grand.","story.map4-dungeon6.030":"On dirait qu\'il a décidé de partir<br>seul, finalement.","story.map4-dungeon6.031":"Tss... Il ne se fera jamais d\'amis<br>avec un caractère aussi aigri.","story.map4-dungeon6.032":"Eh bien,<wait=40><br>nous voilà enfin seuls, tous les deux !","story.map4-dungeon6.033":"Alors c\'est toi dont parlent les Anciens, l\'ami de Karl,","story.map4-dungeon6.034":"le chef de la toute-puissante 24e division des Pourfendeurs de démons, Rebluens.","story.map4-dungeon6.035":"J\'ai entendu beaucoup de choses sur toi,<br><rep_handlename>.","story.map4-dungeon6.036":"Inutile de prendre cet air<br>alarmé.","story.map4-dungeon6.037":"Détends-toi.<wait=40><br>Je suis de ton côté, tu sais.","story.map4-dungeon6.038":"À en juger par ton expression, j\'ai encore du chemin à faire pour gagner ta confiance.","story.map4-dungeon6.039":"Où en étais-je ?<wait=40><br>Ah oui, les géants.","story.map4-dungeon6.040":"Ce n\'est pas si compliqué, en fait.","story.map4-dungeon6.041":"Il y a longtemps, une race de géants vivait<br>ici, à Cordelica.","story.map4-dungeon6.042":"Mais leur race entière a été<br>anéantie par des forces qui nous dépassent.","story.map4-dungeon6.043":"Tous, sauf un :<br>celui qu\'on appelle aujourd\'hui le Dieu géant.","story.map4-dungeon6.044":"Cédant à la rage et au désespoir<br>pour ses camarades tombés, ","story.map4-dungeon6.045":"le géant s\'est scellé lui-même dans cette terre.","story.map4-dungeon6.046":"Voilà la légende telle qu\'elle est gravée sur<br>la Tour de Lumière. <wait=40>Qui l\'a écrite, nous l\'ignorons.","story.map4-dungeon6.047":"Lugina a dû tomber sur<br>la même inscription.","story.map4-dungeon6.048":"Après l\'avoir lue, <wait=40>il a dû<br>arriver à la même conclusion que moi...","story.map4-dungeon6.049":"À savoir que le Dieu géant va bientôt<br>sortir de son sommeil, bouillonnant de rage.","story.map4-dungeon6.050":"Heh...<wait=40> <br>On dirait que j\'ai enfin toute ton attention.","story.map4-dungeon6.051":"Détends-toi.<wait=40><br>À en juger par l\'ampleur des secousses,","story.map4-dungeon6.052":"le Dieu géant ne s\'est pas encore complètement éveillé.","story.map4-dungeon6.053":"D\'après l\'inscription des ruines,<br>quand le géant s\'éveillera enfin,","story.map4-dungeon6.054":"toute cette île sera engloutie<br>en un instant.","story.map4-dungeon6.055":"Viens.<wait=40><br>Nous devons partir sur-le-champ.","story.map4-dungeon6.056":"Les ruines où repose le Dieu géant devraient se trouver juste au bout de ce tunnel.","story.map4-dungeon7.001":"...Oui. <wait=40>Grantos est encore engourdi,<br>mais il est désormais éveillé.","story.map4-dungeon7.002":"Non, monsieur, <wait=40>cela ne posera<br>pas de problème.","story.map4-dungeon7.003":"Bien sûr, monsieur.<wait=40><br>Je vous tiendrai informé de tout nouveau développement.","story.map4-dungeon7.004":"Hé, <wait=40>toi, la femme !","story.map4-dungeon7.005":"T\'as bientôt fini de papoter<br>là-bas ?","story.map4-dungeon7.006":"Tu me dénonces à un de tes<br>potes impériaux, ou quoi ?","story.map4-dungeon7.007":"Heh. Rien ne t\'échappe, hein ?","story.map4-dungeon7.008":"L\'Empire s\'intéresse de près<br>aux jeunes Invocateurs talentueux.","story.map4-dungeon7.009":"Bah !<wait=40><br>Eh bien, c\'est pas réciproque !","story.map4-dungeon7.010":"...!","story.map4-dungeon7.011":"Hé, <rep_handlename> !<br>Tu pourrais te grouiller un peu ?","story.map4-dungeon7.012":"Au cas où t\'aurais pas remarqué, on est<br>un peu en pleine urgence, là !","story.map4-dungeon7.013":"Si tu es si pressé,<br>pourquoi ne pas être parti sans nous ?","story.map4-dungeon7.014":"Vous n\'êtes peut-être pas à la hauteur du grand Lugina, mais même vous, les amateurs, avez votre utilité !","story.map4-dungeon7.015":"Heh...","story.map4-dungeon7.016":"Bon, écoutez bien.<wait=40><br>Je vais aller terrasser Grantos,","story.map4-dungeon7.017":"le Dieu géant qui dort depuis<br>des centaines d\'années.","story.map4-dungeon7.018":"Puissant comme je suis,<br>c\'est moi qui ferai le gros du travail.","story.map4-dungeon7.019":"Cela dit, je veux pas être embêté<br>par des petits sbires pendant ce temps.","story.map4-dungeon7.020":"C\'est là que vous intervenez.<wait=40> Vous allez attirer leur attention pendant que je m\'occupe du gros !","story.map4-dungeon7.021":"Tu vas affronter un monstre aussi<br>énorme tout seul ? Comme c\'est galant de ta part...","story.map4-dungeon7.022":"Sarcastique, avec ça ?","story.map4-dungeon7.023":"Comme si vous aviez ce qu\'il faut pour<br>affronter un géant pareil !","story.map4-dungeon7.024":"Je préfère encore l\'affronter moi-même que de devoir vous tirer d\'affaire quand tout partira en vrille.","story.map4-dungeon7.025":"Vous allez voir, <wait=40>je vais vous montrer ce qu\'est la vraie puissance.","story.map4-dungeon7.026":"C\'est bien clair ? <wait=40>Vous distrayez les sbires pendant que je sauve le monde !","story.map4-dungeon7.027":"Et rappelez-vous, si vous foirez,<br>je vous étripe avec vos propres épées !","story.map4-dungeon7.028":"Il est assurément assez autoritaire pour<br>diriger un régiment de Pourfendeurs de démons...","story.map4-dungeon7.029":"Son ton laisse beaucoup à désirer,","story.map4-dungeon7.030":"mais il semble au moins capable<br>et suffisamment bien informé.","story.map4-dungeon7.031":"Sans compter qu\'il a rassemblé plus<br>de données que je ne le pensais.","story.map4-dungeon7.032":"Pourtant, d\'après mes découvertes,","story.map4-dungeon7.033":"il n\'a aucune chance de venir à bout<br>de Grantos tout seul.","story.map4-dungeon7.034":"Je suppose que je vais devoir lui prêter main-forte.","story.map4-dungeon7.035":"Bien sûr,<wait=40><br>il aura aussi besoin de ton aide.","story.map4-dungeon7.036":"Il est temps de voir de quoi tu es<br>vraiment capable.","story.map4-dungeon_ex_clear.001":"<size=18>*Bzz* </size><wait=20><size=20>*Bz</size><wait=10><size=19>zzzz* </size><wait=40><size=18>*Bzzzzzz*</size>","story.map4-dungeon_ex_clear.002":"Tu as réussi, <rep_handlename> !","story.map4-dungeon_ex_clear.003":"Merci infiniment !","story.map4-dungeon_ex_clear.004":"Je savais que tu en étais capable !","story.map4-dungeon_ex_clear.005":"Tu es formidable !","story.map4-dungeon_ex_clear.006":"Hihi, <wait=20>désolée, je me suis un peu emballée.","story.map4-dungeon_ex_clear.007":"Bref, nous avons découvert ce qu\'était ce monstre.","story.map4-dungeon_ex_clear.008":"Il semble qu\'à l\'origine, les géants l\'utilisaient pour se débarrasser des ordures.","story.map4-dungeon_ex_clear.009":"Mais il est vite devenu si énorme que même eux ne pouvaient plus le contrôler. ","story.map4-dungeon_ex_clear.010":"Il a fini par être enfermé à cet endroit par un certain héros.","story.map4-dungeon_ex_clear.011":"Ce héros devait être incroyablement fort pour soumettre un monstre que même les géants ne pouvaient maîtriser.","story.map4-dungeon_ex_clear.012":"Oh, <wait=20>mais toi aussi, tu as une force incroyable !","story.map4-dungeon_ex_clear.013":"Je veux dire, tu as terrassé cet énorme monstre à toi tout seul !","story.map4-dungeon_ex_clear.014":"Et il était si visqueux et dégoûtant...","story.map4-dungeon_ex_clear.015":"Je t\'admire vraiment, <rep_handlename> !","story.map4-dungeon_ex_clear.016":"Euh, qu\'est-ce que c\'est ?","story.map4-dungeon_ex_clear.017":"Il y a quelque chose sur ton épaule. <wait=20>Ce ne serait pas...","story.map4-dungeon_ex_clear.018":"<size=21>Kyaaaaahh !</size>","story.map4-dungeon_ex_clear.019":"<size=21>Beurk, c\'est tout visqueux !!</size>","story.map4-dungeon_ex_open.001":"<size=18>*Bzz* </size><wait=20><size=20>*Bz</size><wait=10><size=19>zzzz* </size><wait=40><size=18>*Bzzzzzz*</size>","story.map4-dungeon_ex_open.002":"Monsieur, <wait=20>on a un problème ! <wait=40>Un gros problème !","story.map4-dungeon_ex_open.003":"Désolée ! Je ne voulais pas semer la panique...","story.map4-dungeon_ex_open.004":"Lin Merylham, du Soutien logistique...","story.map4-dungeon_ex_open.005":"...du Bureau d\'enquête de l\'Office d\'exploration de Grand Gaia, à ton service.","story.map4-dungeon_ex_open.006":"C-<wait=20>Comment pouvez-vous rester si calme dans un moment pareil !?","story.map4-dungeon_ex_open.007":"<rep_handlename>, en tant que membre de l\'Armée des Invocateurs du Hall des Invocateurs d\'Akras...","story.map4-dungeon_ex_open.008":"...nous te demandons d\'enquêter sur la Caverne d\'Ignia !","story.map4-dungeon_ex_open.009":"Il semble qu\'un monstre dormait derrière les Chutes d\'Ignia.","story.map4-dungeon_ex_open.010":"Mais le séisme de l\'autre jour à Cordelica semble l\'avoir réveillé.","story.map4-dungeon_ex_open.011":"Et à propos du monstre lui-même...","story.map4-dungeon_ex_open.012":"Il est tout mouillé et gluant, et il dévore tout !","story.map4-dungeon_ex_open.013":"Rien que d\'imaginer un monstre aussi énorme et dégoûtant, j\'en ai des frissons.","story.map4-dungeon_ex_open.014":"<size=21>Kyaaaaaahh ! Beurk !!</size>","story.map4-ending.001":"Heh, <wait=40>c\'est bien ce que je soupçonnais.","story.map4-ending.002":"Pas étonnant que Karl te tienne en si haute estime.","story.map4-ending.003":"(Pff... <wait=40>pff...)","story.map4-ending.004":"Eh bien, <wait=40>regardez qui arrive enfin !","story.map4-ending.005":"...<wait=40>Pff, et c\'est reparti.","story.map4-ending.006":"Je suppose que tu connais la nouvelle ?","story.map4-ending.007":"<rep_handlename> vient de vaincre<br>Grantos.","story.map4-ending.008":"On n\'a pas eu besoin de tes services, finalement.<br>Et après toutes tes fanfaronnades, en plus...","story.map4-ending.009":"E-Espèce de...<wait=40><br>Si c\'est des fanfaronnades que tu veux, je t\'affronte ici même !","story.map4-ending.010":"Tu peux laisser tomber ta fausse bravoure.<wait=40><br>Tu as eu ta chance, et tu l\'as gâchée.","story.map4-ending.011":"L-La ferme !<wait=40><br>Les informations que j\'ai trouvées étaient parfaitement justes !","story.map4-ending.012":"Ce fichu géant a dû changer de position ou je sais pas quoi...","story.map4-ending.013":"Je te l\'accorde, tu es arrivé aux mêmes conclusions que moi,","story.map4-ending.014":"et tu as réussi à éliminer quelques monstres coriaces en chemin.","story.map4-ending.015":"Néanmoins, tu n\'as pas réussi à accomplir ta mission.","story.map4-ending.016":"À quoi bon être doué si tu échoues au moment où ça compte vraiment ?","story.map4-ending.017":"Grr...<wait=40> Je vais te montrer !<br>Qu\'est-ce que t\'en sais, d\'abord ?!","story.map4-ending.018":"Ça suffit ! J\'en ai fini !","story.map4-ending.019":"J\'ai jamais demandé à jouer les nounous pour vous, et regardez où ça m\'a mené !","story.map4-ending.020":"Je rentre à Elgaia !","story.map4-ending.021":"En plus, je dois remettre mon rapport<br>à ces vieux fossiles du Hall des Invocateurs.","story.map4-ending.022":"......","story.map4-ending.023":"Hé !<wait=40> <rep_handlename> !","story.map4-ending.024":"Va pas te croire le roi du monde juste parce que t\'as eu de la chance contre Grantos !","story.map4-ending.025":"J\'aurais pu le battre les yeux<br>fermés et une main dans le dos !","story.map4-ending.026":"En fait, tu devrais me remercier !","story.map4-ending.027":"Ouais, c\'est ça ! <wait=40>Remercier l\'Invocateur le plus puissant de tout le Hall des Invocateurs d\'Akras d\'avoir veillé sur toi !","story.map4-ending.028":"Hum.<wait=40> Ce n\'est pas plutôt Karl, de l\'escouade Rebluens, le plus puissant du Hall des Invocateurs ?","story.map4-ending.029":"Tu cherches à te prendre<br>un œil au beurre noir ?","story.map4-ending.030":"Arrête de prononcer ce nom !","story.map4-ending.031":"J\'ai plus de talent dans mon petit doigt que ce frimeur dans tout son corps !","story.map4-ending.032":"Ce rabat-joie était juste au bon endroit au bon moment, c\'est tout !","story.map4-ending.033":"À Randall, on dit qu\'il a vaincu à lui seul Sagamur, le Dragon infernal.","story.map4-ending.034":"Après quoi, il aurait été personnellement recruté pour la Garde impériale.","story.map4-ending.035":"Ha ! Lui ?!<wait=40><br>Il a peut-être porté le coup de grâce,","story.map4-ending.036":"mais c\'est un autre régiment qui<br>l\'a vraiment mis à genoux !","story.map4-ending.037":"Et oui,<wait=40> au cas où tu te poserais la question,<wait=40>","story.map4-ending.038":"cet autre régiment, c\'était le Sky Garden, figure-toi !","story.map4-ending.039":"Ah oui, <wait=40>ça me revient.","story.map4-ending.040":"Il paraît que le chef du Sky Garden s\'est évanoui en entendant des hurlements dans l\'obscurité...","story.map4-ending.041":"Quoi ?!","story.map4-ending.042":"C-Ce n\'est pas ce qui s\'est passé !","story.map4-ending.043":"J\'ai risqué ma vie pour protéger ces faiblards de ce qui rôdait là-derrière !","story.map4-ending.044":"C\'est grâce à moi qu\'ils ont<br>seulement pu se battre !","story.map4-ending.045":"Sans moi, ils n\'auraient pas eu la moindre chance de gagner !","story.map4-ending.046":"Héhé. <wait=40>Dans ce cas, je<br>dois m\'excuser d\'avoir douté du grand chef du Sky Garden.","story.map4-ending.047":"Je suis bien d\'accord !","story.map4-ending.048":"Tss... <wait=40>Tu vois, c\'est pour ça que je<br>ne supporte pas cet imposteur de Karl.","story.map4-ending.049":"Où est son sens du respect ?<br>Je suis son supérieur, nom d\'un chien !","story.map4-ending.050":"Que ce soit toi<br>ou cette idiote d\'impériale,","story.map4-ending.051":"quiconque se range du côté de Karl n\'est rien d\'autre qu\'une épine dans mon pied !","story.map4-ending.052":"Écoute-moi bien, <rep_handlename>, parce que je ne le dirai qu\'une fois !","story.map4-ending.053":"La prochaine fois que tu te mets en travers de mon chemin,","story.map4-ending.054":"je te flanquerai une telle raclée que tu t\'arracheras des épines du derrière pendant une semaine !","story.map4-ending.055":"Si ça ne te tente pas, je te conseille de commencer à me montrer du respect !","story.map4-ending.056":"Je suis le grand et puissant Lugina, et ne l\'oublie pas !","story.map4-ending.057":"Heh...<wait=40> <br>Bon, ça aurait pu mieux se passer.","story.map4-ending.058":"D\'ailleurs,<wait=40><br>il est temps que je me mette en route, moi aussi.","story.map4-ending.059":"Si tu tiens toujours à traquer les Quatre Dieux déchus,<wait=40> nos chemins se recroiseront peut-être un jour.","story.map4-ending.060":"J\'ai hâte de me battre à tes<br>côtés à l\'avenir.","story.map4-ending.061":"Bonne chance à toi,<br>valeureux guerrier.","story.map4-ending.062":"––Je vois.<wait=40><br>Ce n\'était donc pas à Cordelica, finalement...","story.map4-ending.063":"––Je m\'en doutais,<wait=40><br>mais je ne peux m\'empêcher d\'être un peu déçu.","story.map4-ending.064":"––Hmm ?<wait=40><br>Tu n\'as pas à t\'excuser.","story.map4-ending.065":"––Si quelqu\'un doit<br>s\'excuser, c\'est moi, pour t\'avoir lancée sur une fausse piste.","story.map4-ending.066":"––Oui, bien sûr.<wait=40><br>Continue ton bon travail.","story.map4-ending.067":"––N\'oublie pas, je compte sur toi.","story.map4-ending.068":"Héhé...","story.map4-ending.069":"Alors, <wait=40>le jeune Invocateur<br>a réussi à vaincre Grantos...","story.map4-ending.070":"Exactement comme je l\'avais prévu.","story.map4-ending.071":"Le monde semble bel et bien aller<br>dans la bonne direction.","story.map4-ending.072":"Il ne reste plus qu\'à Paris de se dépêcher<br>de trouver ce qui sommeille vraiment à Grand Gaia.","story.map4-ending.073":"......","story.map4-ending.074":"Tu m\'écoutes, j\'imagine ?","story.map4-ending.075":"Le compte à rebours a commencé.<wait=40><br>Impossible de faire marche arrière.","story.map4-ending.076":"Ton maître ferait bien de se préparer<br>à ce qui l\'attend.","story.map4-ending.077":"......","story.map4-ending.078":"...<wait=40>Héhé.","story.map4-ending.079":"<size=20>Mwahaha !","story.map4-open.001":"(Toc, <wait=20>toc.)","story.map4-open.002":"Excusez-moi, monsieur.","story.map4-open.003":"Selon nos sources gouvernementales,","story.map4-open.004":"le Hall des Invocateurs d\'Akras a pris<br>le contrôle de la région sud de Mistral.","story.map4-open.005":"...<wait=40>Oui, <wait=40>c\'est ce que j\'ai entendu.","story.map4-open.006":"Ils deviennent une force plutôt<br>redoutable à Grand Gaia aussi.","story.map4-open.007":"Il semblerait...","story.map4-open.008":"Paris,<wait=40><br>je veux que tu te rendes à Cordelica.","story.map4-open.009":"Tiens-moi informé de tout<br>nouveau développement sur la frontière.","story.map4-open.010":"...<wait=40>Bien sûr, monsieur.<wait=40><br>...<wait=40>Et pour mes fonctions habituelles ?","story.map4-open.011":"J\'expliquerai la situation à l\'Empereur.","story.map4-open.012":"Merci, monsieur.<wait=40><br>Dans ce cas, je prends congé.","story.map4-open.013":"......","story.map4-open.014":"...Oh,<wait=40><br>je ne t\'avais pas vu.","story.map4-open.015":"Tu n\'as jamais été du genre à frapper, hein ?","story.map4-open.016":"......","story.map4-open.017":"Le Hall des Invocateurs d\'Akras <wait=40>et le gouvernement de la Fédération d\'Elgaia...<wait=60><br>La faction d\'Abel passe à l\'action...","story.map4-open.018":"......","story.map4-open.019":"...<wait=40>Héhé.","story.map4-open.020":"<size=20>Mwahaha !","story.map4-open.021":"On dirait que les choses<br>vont devenir intéressantes...","story.map5-dungeon1.001":"...<wait=40>Cet endroit est franchement déprimant.","story.map5-dungeon1.002":"On dirait que les combats sont arrivés jusqu\'ici aussi.","story.map5-dungeon1.003":"Quelle tragédie...","story.map5-dungeon1.004":"Nous devons tout faire pour que cela ne se reproduise plus.","story.map5-dungeon1.005":"Oh, <wait=40><rep_handlename>,<wait=40> quel air assuré tu as sur le visage !","story.map5-dungeon1.006":"C\'est ça, <wait=40>allons régler son compte à ce vilain Cardes !","story.map5-dungeon1.007":"Hein ? <wait=40>Qui est Cardes, tu demandes ?","story.map5-dungeon1.008":"Oh, pardon !<wait=40> <br>Je ne t\'ai pas parlé de lui, c\'est ça !?","story.map5-dungeon1.009":"Hum hum, <wait=40>bon, <wait=40>c\'est l\'heure des histoires de Tilith !","story.map5-dungeon1.010":"Ici, l\'archipel de Palmyna, est gouverné par « Cardes le Malveillant », l\'un des Quatre Dieux déchus.","story.map5-dungeon1.011":"Notre objectif actuel, <rep_handlename>, c\'est de le vaincre !","story.map5-dungeon1.012":"Et tu devras rester sur tes gardes, car il est bien plus fort que Maxwell !","story.map5-dungeon1.013":"Mais pas la peine de s\'inquiéter !","story.map5-dungeon1.014":"En fait, <wait=20>la plus grande partie du pouvoir de Cardes est scellée en ce moment.","story.map5-dungeon1.015":"On raconte qu\'il a été scellé pendant la grande guerre, au cœur de Palmyna, dans un lieu appelé le « monde spirituel »...","story.map5-dungeon1.016":"Il devait y avoir des humains drôlement impressionnants ici, à part toi, <rep_handlename>.","story.map5-dungeon1.017":"Attends,<wait=40> une seconde...","story.map5-dungeon1.018":"Ça veut dire que Cardes a régné sur cette terre même après le scellement de ses pouvoirs, non ?","story.map5-dungeon1.019":"Il est peut-être encore plus puissant que je l\'imaginais...","story.map5-dungeon1.020":"...<wait=20>...","story.map5-dungeon1.021":"Bref, <wait=40>on doit le vaincre de toute façon !","story.map5-dungeon1.022":"Mais ce ne sera pas un problème pour toi, <rep_handlename> !","story.map5-dungeon1.023":"Je dois y aller. <wait=20>J\'ai encore des recherches à faire sur Cardes !","story.map5-dungeon1.024":"Bonne chance !!","story.map5-dungeon2.001":"<size=14><rep_handlename> !","story.map5-dungeon2.002":"<size=14>O-<wait=20>Où es-tu ?","story.map5-dungeon2.003":"<size=20>Aaaah !!","story.map5-dungeon2.004":"...N-<wait=40>Ne m\'approche pas en douce comme ça !","story.map5-dungeon2.005":"Hein ?<wait=40><br>De quoi j\'ai peur ?","story.map5-dungeon2.006":"D-<wait=40>De rien !","story.map5-dungeon2.007":"J-<wait=41>Je n\'ai peur de rien du tout !","story.map5-dungeon2.008":"Les vaisseaux fantômes et tout ça, ça n\'a absolument rien d\'effrayant !","story.map5-dungeon2.009":"D\'ailleurs, <wait=40>je pourrais même vivre ici, tu sais !","story.map5-dungeon2.010":"Ah !<wait=40> Je vois !","story.map5-dungeon2.011":"Tu dis ça parce que c\'est toi qui as peur, <wait=40>pas vrai, <rep_handlename> !?","story.map5-dungeon2.012":"Héhé, <wait=40><rep_handlename> n\'est qu\'une poule mouillée !","story.map5-dungeon2.013":"Tu aurais dû me le dire, <wait=40>j\'aurais pu te protéger.","story.map5-dungeon2.014":"Après tout, <wait=20>une déesse, ce n\'est pas seulement joli, c\'est aussi coriace !","story.map5-dungeon2.015":"Oui, <wait=20>exactement !","story.map5-dungeon2.016":"Il paraît qu\'un monstre qui dévore les âmes humaines rôde par ici, alors ouvre l\'œil !","story.map5-dungeon2.017":"<size=18>*Splash*","story.map5-dungeon2.018":"<size=20>Hein ?<wait=40> Q-Qu\'est-ce que c\'était !","story.map5-dungeon2.019":"T-Tu as entendu, <wait=20>ce bruit bizarre à l\'instant !?","story.map5-dungeon2.020":"Hein ?<wait=40> C\'étaient juste tes pas ?","story.map5-dungeon2.021":"...<wait=40>...<wait=40>...","story.map5-dungeon2.022":"<size=20><rep_handlename>, espèce d\'idiot !","story.map5-dungeon2.023":"Je t\'apportais des informations importantes, <wait=40>mais maintenant je n\'ai plus envie de te les dire !","story.map5-dungeon2.024":"Je rentre chez moi !","story.map5-dungeon2.025":"Héhé, <wait=40>tu m\'as vraiment crue ?","story.map5-dungeon2.026":"Je t\'ai fait peur ?","story.map5-dungeon2.027":"Une déesse ne se fâcherait jamais pour si peu.","story.map5-dungeon2.028":"Bref, <wait=40>d\'après mes recherches, Palmyna, l\'endroit où Cardes est scellé...","story.map5-dungeon2.029":"...se trouve au-delà d\'Encervis, <wait=40>juste après Amdahl.","story.map5-dungeon2.030":"On doit d\'abord franchir le Château d\'Amdahl, <wait=40>et ensuite on pourra traverser Encervis !","story.map5-dungeon2.031":"Alors dépêchons-nous de traverser cette zone, <wait=40>elle me donne vraiment la chair de poule...","story.map5-dungeon2.032":"<size=18>*Splash* *Splash*","story.map5-dungeon2.033":"Hein ?","story.map5-dungeon2.034":"*Floc* *Floc*","story.map5-dungeon2.035":"<size=20>Aaaah !!","story.map5-dungeon3.001":"<speed=10>Que vois-je là...<wait=40><br>Celui-ci est assurément différent des autres Invocateurs.","story.map5-dungeon3.002":"C\'est décidé, <wait=20>je vais en finir avec toi ici.","story.map5-dungeon3.003":"Tu n\'as pas à t\'inquiéter.<wait=50><br>Tout sera bientôt terminé.","story.map5-dungeon3.004":"Cette présence...<wait=20>...","story.map5-dungeon3.005":"Oh, je vois...","story.map5-dungeon3.006":"Te voilà !","story.map5-dungeon3.007":"Hé, <wait=40>quelque chose ne va pas ?<wait=40> Tu as l\'air tout inquiet.","story.map5-dungeon3.008":"Tu devrais être plus joyeux avec un temps pareil ! Allez, souris-moi !","story.map5-dungeon3.009":"En plus, tu m\'as avec toi, <wait=40>alors reprends-toi !","story.map5-dungeon3.010":"Et puis, <wait=40>regarde comme cet endroit est paisible.","story.map5-dungeon3.011":"J\'aimerais vraiment passer du temps à me détendre dans des endroits comme ça avec toi, <rep_handlename>.","story.map5-dungeon3.012":"Héhé, <wait=40>je plaisante !","story.map5-dungeon3.013":"Tu as une mission importante, <rep_handlename> : vaincre les Quatre Dieux déchus.","story.map5-dungeon3.014":"Tu n\'as pas le temps de paresser !","story.map5-dungeon3.015":"Hein ? <wait=40>Et moi ?","story.map5-dungeon3.016":"Bien sûr que je n\'ai pas le temps non plus...<wait=40> Autrement dit...","story.map5-dungeon3.017":"Tu trouves peut-être,<wait=40> que je suis juste en train de m\'amuser ici !?","story.map5-dungeon3.018":"Quel culot !!","story.map5-dungeon3.019":"Je fais tout ce que je peux pour t\'aider, <rep_handlename> !","story.map5-dungeon3.020":"Hein ? <wait=40>Par exemple ?","story.map5-dungeon3.021":"C-<wait=40>C\'est qu\'il y a tellement de choses que je ne peux pas mettre en mots...<wait=40> *M<size=15>a<size=14>r<size=13>m<size=12>o<size=11>n* <size=12>*M<size=11>a<size=10>r<size=9>m<size=8>o<size=7>n<size=6>*","story.map5-dungeon3.022":"Bref, <wait=40>assez parlé de moi !","story.map5-dungeon3.023":"Ce qui compte maintenant, c\'est la route devant nous !","story.map5-dungeon3.024":"Bon, <wait=40>mettons-nous en route vers le Château d\'Amdahl !","story.map5-dungeon4.001":"Beurk, <wait=20>c\'est affreux ! <wait=40>Cet endroit est tellement dégoûtant !","story.map5-dungeon4.002":"Même Graham ne mettrait pas les pieds dans un endroit pareil !","story.map5-dungeon4.003":"Je te l\'ai déjà expliqué, non ?","story.map5-dungeon4.004":"Il est très probable que Graham soit à Edila, la ville fantôme juste après ces mines.","story.map5-dungeon4.005":"Arrête un peu de te plaindre ! <wait=40> On doit continuer d\'avancer !","story.map5-dungeon4.006":"En tout cas, <wait=40>on dirait que le Hall des Invocateurs ne nous refile que des tuyaux percés !","story.map5-dungeon4.007":"Franchement, Seria, <wait=40>tu es la femme la plus dure que je connaisse...","story.map5-dungeon4.008":"Hm ?<wait=40> Oh !<wait=40> <rep_handlename> !","story.map5-dungeon4.009":"Hmph...","story.map5-dungeon4.010":"Alors tu es venu dans l\'archipel de Palmyna, toi aussi !","story.map5-dungeon4.011":"Je me disais que si quelqu\'un pouvait y arriver, ce serait toi, <rep_handlename>.","story.map5-dungeon4.012":"Je suppose que tu es après Cardes ?","story.map5-dungeon4.013":"Haha, <wait=40>j\'ai l\'impression qu\'il ne fera pas le poids, vu comment tu as réglé son compte à Maxwell.","story.map5-dungeon4.014":"Hmph ! <wait=40>Ne prends pas la grosse tête, <wait=40>il pourrait t\'arriver malheur.","story.map5-dungeon4.015":"Qu\'est-ce que tu racontes encore ? <wait=50> Tu ne pourrais pas traiter <rep_handlename> avec un peu plus de respect ?<wait=40>","story.map5-dungeon4.016":"*Bonk*","story.map5-dungeon4.017":"<size=18>C-<wait=20>C\'était rien ! <wait=40>Promis, j\'arrête !","story.map5-dungeon4.018":"Bref, <wait=40>il y a dans l\'archipel de Palmyna un subordonné de Cardes que redoutent même les forces les plus puissantes...","story.map5-dungeon4.019":"Hésite ne serait-ce qu\'un instant et c\'en est fini de toi !","story.map5-dungeon4.020":"Oh, Seria...","story.map5-dungeon4.021":"Cela dit, <wait=40>il y a du vrai dans ce qu\'elle dit.","story.map5-dungeon4.022":"En réalité, <wait=40>à part Graham, que nous poursuivons en ce moment...","story.map5-dungeon4.023":"...La rumeur parle d\'une bête aussi puissante, voire plus, dans les parages, du nom de Zebra.","story.map5-dungeon4.024":"On n\'est jamais trop prudent, <wait=40>alors avançons tous avec précaution.","story.map5-dungeon4.025":"Au fait, <wait=40>qu\'est-il arrivé à cette déesse ?","story.map5-dungeon4.026":"Vous étiez toujours collés l\'un à l\'autre...","story.map5-dungeon4.027":"Oh, je vois !<wait=40> Elle en a enfin eu marre de ton ennui mortel !?","story.map5-dungeon4.028":"Seria, <wait=40>ça suffit.","story.map5-dungeon4.029":"...<wait=40>C\'était juste une petite blague, de toute façon.","story.map5-dungeon4.030":"Nous allons à Edila, droit devant, à la poursuite de Graham.","story.map5-dungeon4.031":"J\'aimerais qu\'on se batte tous ensemble, <wait=40>mais avec une compagne aussi pénible que toi...","story.map5-dungeon4.032":"Je n\'étais pas pénible...","story.map5-dungeon4.033":"Haha... <wait=40>Alors, tu comptes continuer seul ?","story.map5-dungeon4.034":"Des ennemis redoutables t\'attendent plus loin,<wait=40> mais je crois que nous survivrons pour nous revoir !","story.map5-dungeon4.035":"Karl ! <wait=40>On n\'a pas le temps de traîner, avançons !","story.map5-dungeon4.036":"Fais de ton mieux pour ne pas devenir la proie de ces démons !","story.map5-dungeon4.037":"H-<wait=40>Hé, <wait=40>attends-moi !","story.map5-dungeon4.038":"Ma parole... <wait=40>Bon, <wait=20>à la prochaine, <rep_handlename> !","story.map5-dungeon5.001":"Ah, <wait=40>quel délice !","story.map5-dungeon5.002":"Oh, <wait=40><rep_handlename> !","story.map5-dungeon5.003":"Tu es arrivé en un seul morceau. <wait=40>Je savais que tu y arriverais !","story.map5-dungeon5.004":"Même si je croyais en toi, je suis quand même soulagée de te voir.","story.map5-dungeon5.005":"Hein ? <wait=40>Ce que je faisais ?","story.map5-dungeon5.006":"Héhé, <wait=40>je profitais du sanctuaire, bien sûr !","story.map5-dungeon5.007":"Baigné de lumière jusque dans ses moindres recoins, <wait=20>rien ne vaut un bon sanctuaire.","story.map5-dungeon5.008":"L\'atmosphère solennelle et toute cette belle lumière, une déesse comme moi ne peut pas y résister.","story.map5-dungeon5.009":"Et il n\'y a pas de bruits bizarres comme ceux du vaisseau fantôme !","story.map5-dungeon5.010":"<size=18>*Frrr* *Frrr*","story.map5-dungeon5.011":"Qu\'est-ce que c\'est !?<wait=40> Qui est là !?","story.map5-dungeon5.012":"Ho ho ho. <wait=40><br>Je vous ai fait peur ?","story.map5-dungeon5.013":"Pardonnez-moi, <wait=20>jeune demoiselle.","story.map5-dungeon5.014":"Je ne voulais pas vous effrayer, <wait=40>c\'est simplement que vous avez une voix si agréable.","story.map5-dungeon5.015":"Ah, <wait=40>eu-<wait=40>euh...","story.map5-dungeon5.016":"Qui êtes-vous, grand-père ?","story.map5-dungeon5.017":"Ho ho ho. <wait=40><br>Je vous prie de m\'excuser.","story.map5-dungeon5.018":"Je m\'appelle Grah. <wait=40><br>Appelez-moi Elder Grah, je vous prie.","story.map5-dungeon5.019":"Elder Grah, hein...","story.map5-dungeon5.020":"Ho ho ho. <wait=40><br>C\'est un beau nom, n\'est-ce pas ?","story.map5-dungeon5.021":"Je vous ai donné mon nom, <wait=40>ne me direz-vous pas le vôtre ?","story.map5-dungeon5.022":"Euh, <wait=40>je m\'appelle Tilith ! <wait=40>Je suis une fille normale, comme on en trouve partout.","story.map5-dungeon5.023":"Et cette charmante personne juste ici, c\'est <rep_handlename> !","story.map5-dungeon5.024":"<rep_handlename> est un Invocateur incroyablement fort !","story.map5-dungeon5.025":"Quel courage.","story.map5-dungeon5.026":"Alors, Elder Grah, <wait=40>qu\'est-ce qui vous amène dans un endroit pareil ?","story.map5-dungeon5.027":"Eh bien, <wait=40>j\'allais simplement faire une promenade par là-bas.","story.map5-dungeon5.028":"Une promenade, vous dites...","story.map5-dungeon5.029":"Je croyais que cette zone était pleine de monstres...","story.map5-dungeon5.030":"Hmm, <wait=20>eh bien, il semble qu\'ils ne m\'aient prêté aucune attention.","story.map5-dungeon5.031":"Hmm...<wait=40> Vous m\'avez quand même l\'air un peu louche...","story.map5-dungeon5.032":"Regardez-moi ces armes puissantes que vous portez...","story.map5-dungeon5.033":"Hé hé hé...","story.map5-dungeon5.034":"On dirait que je suis démasqué !","story.map5-dungeon5.035":"Je suis en vérité <wait=20>Grah, le dieu qui règne sur cette terre !","story.map5-dungeon5.036":"Et maintenant, je vais vous faire disparaître d\'ici, tous les deux, sur-le-champ !","story.map5-dungeon5.037":"Quoi !?","story.map5-dungeon5.038":"Je vous fais marcher.","story.map5-dungeon5.039":"Ho ho ho. <wait=40><br>Je vous ai fait peur ?","story.map5-dungeon5.040":"Vous êtes si mignonne quand vous êtes surprise, jeune demoiselle.","story.map5-dungeon5.041":"Pfffft !","story.map5-dungeon5.042":"Pardonnez-moi, je vous prie.","story.map5-dungeon5.043":"Il y a longtemps, je suis parti pour une sorte d\'aventure.","story.map5-dungeon5.044":"Je me servais de cette lance à l\'époque, <wait=40>même si elle ne me sert plus guère que de décoration aujourd\'hui.","story.map5-dungeon5.045":"Je suis ici pour enquêter sur la légende des Quatre Héros d\'antan, <wait=40>mais il est peu probable que je trouve quoi que ce soit d\'important ici.","story.map5-dungeon5.046":"Bien, <wait=40>je crois qu\'il est temps que je prenne congé.","story.map5-dungeon5.047":"J\'ai eu l\'occasion de rencontrer un Invocateur si intéressant, <wait=40>ce fut une bonne journée.","story.map5-dungeon5.048":"Eh bien, <wait=40>j\'ai hâte de notre prochaine rencontre.","story.map5-dungeon5.049":"Ce vieil homme, <wait=40>il était un peu bizarre, non ?","story.map5-dungeon5.050":"N\'importe qui ne peut pas se promener par ici comme ça.","story.map5-dungeon5.051":"Il cache sûrement quelque chose<wait=20>.<wait=20>.<wait=20>.","story.map5-dungeon5.052":"Bref, <wait=40>ça ne sert à rien de s\'en inquiéter maintenant.","story.map5-dungeon5.053":"Ça ne change rien à notre objectif !","story.map5-dungeon5.054":"Bon, <wait=40>traversons vite cet endroit, puis direction le Château d\'Amdahl !","story.map5-dungeon6.001":"Seria !<wait=40> Comment ça se passe de ton côté !?","story.map5-dungeon6.002":"Rien !<wait=40> Aucune trace de lui nulle part...","story.map5-dungeon6.003":"Bon sang ! <wait=40>Il nous a encore échappé !","story.map5-dungeon6.004":"À ce rythme, <wait=40>nous ne pourrons jamais les venger...","story.map5-dungeon6.005":"Karl...","story.map5-dungeon6.006":"<size=18>Hein !?<wait=40> <size=16>D\'où tu sors, toi ?","story.map5-dungeon6.007":"Mais c\'est <rep_handlename>...","story.map5-dungeon6.008":"Héhé, <wait=40>on dirait que tu tombes mal.","story.map5-dungeon6.009":"Une fois de plus, <wait=20>Graham nous a glissé entre les doigts.","story.map5-dungeon6.010":"Comparés à toi qui as combattu si vaillamment les Quatre Dieux déchus, <wait=20>nous devons faire pitié...","story.map5-dungeon6.011":"Qu\'est-ce que tu racontes !","story.map5-dungeon6.012":"<rep_handlename> a juste de la chance !<wait=40> Karl, tu as battu des ennemis des centaines de fois plus forts que les siens !","story.map5-dungeon6.013":"Haha, <wait=40>merci bien, Seria.","story.map5-dungeon6.014":"C\'est vraiment spécial de recevoir un compliment de ta part.","story.map5-dungeon6.015":"Je n\'ai plus aucune raison d\'avoir le moral à zéro, hein !","story.map5-dungeon6.016":"Comment ça, « spécial » ?","story.map5-dungeon6.017":"Haha, <wait=40>j\'essaie juste de te remercier, c\'est tout.","story.map5-dungeon6.018":"Ah, et <rep_handlename>...","story.map5-dungeon6.019":"Si Graham nous a encore échappé, ce n\'est pas seulement parce qu\'il était fort...","story.map5-dungeon6.020":"Quand nous l\'avons rattrapé cette fois, <wait=40>il y avait un autre monstre incroyablement fort avec lui.","story.map5-dungeon6.021":"Désolé d\'être aussi vague.","story.map5-dungeon6.022":"À vrai dire, <wait=40>nous n\'avons pas vraiment vu l\'autre monstre.","story.map5-dungeon6.023":"Dès que nous avons senti sa puissance incroyable, <wait=40>nous avons littéralement été balayés.","story.map5-dungeon6.024":"Quand nous avons repris nos esprits, <wait=40>Graham avait disparu quelque part.","story.map5-dungeon6.025":"On l\'aurait eu si on ne s\'était pas fait attaquer comme ça...","story.map5-dungeon6.026":"Tu as sans doute raison...","story.map5-dungeon6.027":"Cependant, <wait=40>tout ce dont nous sommes sûrs, c\'est qu\'aucune personne normale ne pourrait posséder une telle puissance...","story.map5-dungeon6.028":"Ça, c\'est sûr...","story.map5-dungeon6.029":"Bref, <wait=40>nous avons eu la chance de ne pas subir trop de pertes.","story.map5-dungeon6.030":"Nous allons continuer à chercher Graham.","story.map5-dungeon6.031":"Tu te diriges vers le Château d\'Amdahl, plus loin, c\'est bien ça ?","story.map5-dungeon6.032":"Je sens aussi une forte présence dangereuse venir de là-bas.","story.map5-dungeon6.033":"Sois très prudent.","story.map5-dungeon6.034":"Si tu croises ce monstre, tu es cuit !","story.map5-dungeon6.035":"Haha, <wait=40>toujours aussi dure avec <rep_handlename>, à ce que je vois.","story.map5-dungeon6.036":"J-<wait=40>Je ne suis pas dure qu\'avec <rep_handlename>...","story.map5-dungeon6.037":"Te voilà !","story.map5-dungeon6.038":"Où étais-tu ! <wait=40>Je t\'ai cherché partout !","story.map5-dungeon6.039":"Hein ?<wait=40> Qu\'est-ce que c\'est ?<wait=40><br>Je vous ai déjà vus, non ?","story.map5-dungeon6.040":"...<wait=20>...","story.map5-dungeon6.041":"Bonjour, déesse.<wait=40> Ça fait longtemps.","story.map5-dungeon6.042":"Ça fait drôlement longtemps !<wait=40> Toujours en pleine forme, Karl !","story.map5-dungeon6.043":"Et toi, <wait=40>tu as encore embêté mon petit <rep_handlename> comme d\'habitude ?","story.map5-dungeon6.044":"<size=18>Comment ça, « embêté » !","story.map5-dungeon6.045":"Et comme je l\'ai déjà dit, <wait=40><rep_handlename> ne t\'appartient pas !","story.map5-dungeon6.046":"Pourquoi tu t\'énerves ?<wait=40> Ce serait <wait=20>de la jalousie ?","story.map5-dungeon6.047":"...<wait=20>...","story.map5-dungeon6.048":"<size=18>*Clang*","story.map5-dungeon6.049":"<size=18>A-Attendez une seconde !","story.map5-dungeon6.050":"Calme-toi, Seria !","story.map5-dungeon6.051":"A-<wait=20>Allons, <wait=40>on doit reprendre la piste de Graham !","story.map5-dungeon6.052":"H-<wait=40>Hein, c\'est vrai !?","story.map5-dungeon6.053":"<speed=14>Bon, <wait=20><rep_handlename> !","story.map5-dungeon6.054":"<speed=14>Promettons-nous tous les deux de tout donner sur la route qui nous attend !","story.map5-dungeon6.055":"<speed=14>Allez, on y va ! Toi aussi, Seria !","story.map5-dungeon6.056":"Karl ! <wait=20> Attends !<wait=40> J\'ai compris, <wait=40>pas besoin de tirer si fort !","story.map5-dungeon6.057":"Déesse ! <wait=40>Tiens-toi bien !","story.map5-dungeon6.058":"Pfft !!","story.map5-dungeon6.059":"Ouf, <wait=40>elle est enfin partie.","story.map5-dungeon6.060":"Quand même, <wait=40>j\'espère qu\'ils réussiront à vaincre Graham !","story.map5-dungeon6.061":"On y est presque. <wait=40>Une fois passé cet endroit, nous serons aux portes du Château d\'Amdahl !","story.map5-dungeon6.062":"Je compte sur toi !","story.map5-dungeon7.001":"On y est enfin.","story.map5-dungeon7.002":"Une fois le Château d\'Amdahl franchi, la voie est libre jusqu\'à Encervis.","story.map5-dungeon7.003":"Et nous serons alors un pas plus près de Cardes et de la terre où il est scellé.","story.map5-dungeon7.004":"Héhé, <wait=40>ne fais pas cette tête crispée.","story.map5-dungeon7.005":"Je sais que tu peux y arriver, <rep_handlename> !","story.map5-dungeon7.006":"Dépêchons-nous de traverser ce château !","story.map5-dungeon7.007":"Vous croyez vraiment que ce sera aussi facile ?","story.map5-dungeon7.008":"Quoi !!","story.map5-dungeon7.009":"Je vous ai encore fait peur ?","story.map5-dungeon7.010":"Comment osez-vous ! <wait=40>Ne m\'approchez pas en douce comme ça !!","story.map5-dungeon7.011":"Ho ho ho.","story.map5-dungeon7.012":"Vous êtes toujours aussi mignonne, jeune demoiselle.","story.map5-dungeon7.013":"Hmph, <wait=40>vieux méchant...","story.map5-dungeon7.014":"Ho ho ho.","story.map5-dungeon7.015":"Bref, <wait=40><rep_handlename>...","story.map5-dungeon7.016":"Tu l\'as remarquée toi aussi, n\'est-ce pas ? <wait=40>La présence maléfique plus loin...","story.map5-dungeon7.017":"Oui, <wait=40>je le lis sur ton visage.","story.map5-dungeon7.018":"Bien, <wait=40>permets-moi de te dire à quoi t\'attendre.","story.map5-dungeon7.019":"Juste devant, l\'ancien maître de ce château t\'attend.","story.map5-dungeon7.020":"Le dernier empereur de l\'Empire d\'Amdahl, détruit par Palmyna.","story.map5-dungeon7.021":"Devenu un fantôme, il nourrit une profonde rancune envers les humains.","story.map5-dungeon7.022":"Un fantôme qui en veut aux humains...","story.map5-dungeon7.023":"Ho ho ho.","story.map5-dungeon7.024":"À quoi vous attendiez-vous ?","story.map5-dungeon7.025":"Tout ce qui existe ici, à Grand Gaia, n\'a pas forcément quelque chose à voir avec les dieux.","story.map5-dungeon7.026":"C\'est évident quand on regarde l\'histoire des humains...","story.map5-dungeon7.027":"Les humains se sont entretués bien plus que les dieux ne les ont détruits.","story.map5-dungeon7.028":"......","story.map5-dungeon7.029":"Ho ho ho.","story.map5-dungeon7.030":"Bref, <wait=40>je suis un peu trop vieux pour ça, <wait=40>je crois que je ferais mieux de partir.","story.map5-dungeon7.031":"Mais avant de partir, <wait=40>sache que même si elle est une déesse, elle a ses faiblesses.","story.map5-dungeon7.032":"Fais de ton mieux pour la protéger.","story.map5-dungeon7.033":"Hein ?<wait=40> Attendez une seconde !","story.map5-dungeon7.034":"Ho ho ho.","story.map5-dungeon7.035":"Il est parti...","story.map5-dungeon7.036":"Quand est-ce que j\'ai dit à Elder Grah que j\'étais une déesse ?","story.map5-dungeon7.037":"Il en sait tellement, <wait=40>qui peut-il bien être ?","story.map5-dungeon7.038":"Ah, <wait=40>tant pis !","story.map5-dungeon7.039":"Ça ne sert à rien de s\'en inquiéter maintenant ! <wait=40>","story.map5-dungeon7.040":"On doit passer par ici avant de pouvoir affronter Cardes !","story.map5-dungeon7.041":"Bon, <rep_handlename>, je ne sais pas quoi penser de cette histoire de fantôme...","story.map5-dungeon7.042":"...mais quoi qu\'il en soit, mettons-le K.-O., quel qu\'il soit ! <wait=40>Ça surprendra sûrement Elder Grah !","story.map5-ending.001":"Tu as réussi, <rep_handlename> !","story.map5-ending.002":"Il n\'était pas bien coriace, celui-là !","story.map5-ending.003":"Même les fantômes d\'anciens empereurs ne font pas le poids face à toi, <rep_handlename> !","story.map5-ending.004":"<size=18>Ouah !","story.map5-ending.005":"Quoi !!","story.map5-ending.006":"Hé, <wait=40>pourquoi vous essayez toujours de me faire peur...","story.map5-ending.007":"Désolé, <wait=40>c\'est juste que je ressens la même chose que vous, Tilith...","story.map5-ending.008":"J\'ai été tout aussi surpris par la façon dont <rep_handlename> a réglé son compte à ce spectre.","story.map5-ending.009":"Hmph.","story.map5-ending.010":"Ho ho ho.","story.map5-ending.011":"Cependant, <wait=40>que <rep_handlename> ait vaincu le fantôme d\'un empereur de la sorte...","story.map5-ending.012":"Héhé, <wait=40>oui ?","story.map5-ending.013":"Ça veut dire que <rep_handlename> est vraiment un Invocateur extraordinaire, non ?","story.map5-ending.014":"Hmm, <wait=40>ce fut assurément un magnifique croisement de lames.","story.map5-ending.015":"Je dois dire, <wait=40>bien joué.","story.map5-ending.016":"<size=18><rep_handlename> !<wait=40> Tu es encore en vie !!","story.map5-ending.017":"Pff... <wait=40>pff...","story.map5-ending.018":"A-<wait=40>Attendez une seconde...","story.map5-ending.019":"Q-<wait=40>Qu\'est-il arrivé à ce fantôme ?","story.map5-ending.020":"<rep_handlename> l\'a éliminé !","story.map5-ending.021":"...<wait=40>...","story.map5-ending.022":"<size=14>Hmph...<wait=40><br>Karrrrrrl !!","story.map5-ending.023":"Alors tu t\'inquiétais pour <rep_handlename> finalement, pas vrai, Seria !?","story.map5-ending.024":"On dirait que tu as un côté attentionné.","story.map5-ending.025":"J-<wait=40>Ce n\'est pas ça !<wait=40> J\'avais juste entendu dire que Graham était apparu quelque part par ici...","story.map5-ending.026":"Allons, <wait=20>pas besoin de te cacher derrière un mensonge aussi grossier.","story.map5-ending.027":"Grr...","story.map5-ending.028":"Ho ho ho.","story.map5-ending.029":"<size=20>!?","story.map5-ending.030":"Je crois que nous n\'avons pas été présentés.","story.map5-ending.031":"Mademoiselle Seria, <wait=40>appelez-moi Elder Grah, je vous prie.","story.map5-ending.032":"Hein !?<wait=40> E-<wait=40>Elder Grah ?","story.map5-ending.033":"C\'est exact.","story.map5-ending.034":"Hein, <wait=40>mais... <wait=40>J-<wait=40>Je veux dire...","story.map5-ending.035":"C\'est Elder Grah.","story.map5-ending.036":"Tâchez de vous en souvenir, <wait=40>Mademoiselle Seria.","story.map5-ending.037":"Elder Grah, <wait=40>vous êtes vraiment un drôle de vieil homme, vous !","story.map5-ending.038":"Toujours à surgir à l\'improviste dans des endroits bizarres, <wait=40>et vous savez les choses les plus obscures.","story.map5-ending.039":"Et vous essayez toujours de me faire peur !","story.map5-ending.040":"Q-<wait=40>Q-<wait=40>Qu\'est-ce que tu racontes !?<wait=40> Cet homme est...","story.map5-ending.041":"...Elder Grah, un simple vieil homme farceur.","story.map5-ending.042":"N\'est-ce pas, <wait=40>Mademoiselle Seria ?","story.map5-ending.043":"Hein ?<wait=40> O-<wait=40>Oh, <wait=20>oui...","story.map5-ending.044":"Ho ho ho.","story.map5-ending.045":"Hmph, <wait=40>il y a quelque chose de bizarre chez toi, Seria !","story.map5-ending.046":"P-<wait=40>Peu importe ! <wait=40>J\'ai juste quelques trucs en tête !","story.map5-ending.047":"Quels trucs ?","story.map5-ending.048":"T-<wait=40>Tu n\'as pas besoin de le savoir !","story.map5-ending.049":"Hmph, <wait=40>qu\'est-ce qui t\'arrive !","story.map5-ending.050":"Tu es peut-être fâchée que Karl t\'ait poussée à nous courir après ?","story.map5-ending.051":"H-<wait=40>Hein ? <wait=20>Comment tu sais ça !?","story.map5-ending.052":"Une déesse sait tout !","story.map5-ending.053":"Et tu es quel genre de déesse, au juste !?<wait=40> Tu ne sais rien faire toute seule !","story.map5-ending.054":"Que tu es méchante !","story.map5-ending.055":"Hé, <rep_handlename>, <wait=40>aide-moi un peu et dis quelque chose !","story.map5-ending.056":"Pourquoi ?<wait=40> Tu sais déjà ce que <rep_handlename> dirait, non ?","story.map5-ending.057":"Ho ho ho.","story.map5-ending.058":"La jeunesse déborde tant de vie.","story.map5-ending.059":"Quoi qu\'il en soit, <rep_handlename>...","story.map5-ending.060":"En vainquant ce spectre, <wait=40>tu as brisé la barrière qui recouvrait cette région.","story.map5-ending.061":"Bientôt, la route vers Encervis s\'ouvrira.","story.map5-ending.062":"Zebra devrait t\'y attendre...","story.map5-ending.063":"...le démon qui règne actuellement sur l\'archipel de Palmyna à la place de Cardes.","story.map5-ending.064":"Entraîne-toi dur, et ne laisse pas l\'orgueil te barrer la route.","story.map5-ending.065":"Ah !<wait=40> J\'allais le dire !","story.map5-ending.066":"Tout ce que tu dis est idiot, <wait=40>tu devrais laisser ça à Grahde...","story.map5-ending.067":"Elder Grah ! Laisse ça à Elder Grah !","story.map5-ending.068":"Idiot, tu dis !?","story.map5-ending.069":"Qu\'est-ce qu\'il y a de mal à te dire ce que tu es vraiment ?","story.map5-ending.070":"Ça suffit !<wait=40> Je vais te montrer le vrai pouvoir d\'une déesse !","story.map5-ending.071":"Vas-y !<wait=50> Je vais te montrer à quel point je suis plus forte que toi !","story.map5-ending.072":"<size=20>Tu as intérêt à être prête !!","story.map5-ending.073":"Ho ho ho.","story.map5-ending.074":"Vous êtes un sacré duo de jeunes filles au sang chaud, n\'est-ce pas.","story.map5-ending.075":"Bref, <wait=40><rep_handlename>...","story.map5-ending.076":"Nous devrions rentrer à Elgaia.","story.map5-ending.077":"<rep_handlename> ! <wait=40>Attends une seconde !","story.map5-ending.078":"J\'ai un message de Karl !","story.map5-ending.079":"Il dit : « Je crois en ta force. »","story.map5-ending.080":"C\'est vraiment le moment pour ça !?","story.map5-ending.081":"<rep_handlename> !","story.map5-ending.082":"On ira à Encervis quand j\'aurai donné à Seria une petite leçon de respect !","story.map5-ending.083":"Si tu crois pouvoir me battre, <wait=40>alors essaie un peu !","story.map5-ending.084":"Ça suffit !!<wait=40> Il est temps de te montrer mon immense pouvoir magique !","story.map5-ending.085":"Hmph, <wait=40>on dirait que tu es sérieuse. <wait=40>OK, <wait=40>allons-y !","story.map5-ending.086":"<size=20>Prends ça !!","story.map5-ending.087":"Bon, <wait=40>je suppose qu\'on y va...","story.map5-open.001":"<anchor=center><br><br><br><br><br><br><br><br><br><br><speed=8><size=15>Toi, <rep_handlename>,<wait=40> qui as vaincu Maxwell, Déesse de la Création…","story.map5-open.002":"<anchor=center><br><br><br><br><br><br><br><br><br><br><speed=8><size=15>La crise provoquée par les Quatre Dieux déchus,<wait=40> elle persiste encore…","story.map5-open.003":"<anchor=center><br><br><br><br><br><br><br><br><br><br><speed=8><size=15>Afin d\'apporter un nouvel espoir à ce monde imprégné de tristesse…","story.map5-open.004":"<anchor=center><br><br><br><br><br><br><br><br><br><br><speed=8><size=15>Tu dois avoir foi en ton pouvoir, <wait=20>et continuer d\'avancer…","story.map5-open.005":"<size=22>Tu es en retard !","story.map5-open.006":"Qu\'est-ce qui t\'a pris autant de temps !?","story.map5-open.007":"Ça fait si longtemps, si longtemps que je t\'attends, <rep_handlename> !","story.map5-open.008":"Tu ne trouves pas que tu t\'es un peu trop relâché depuis ta victoire sur Maxwell ?","story.map5-open.009":"<size=20>Héhé, <wait=20>je t\'ai eu !!","story.map5-open.010":"Je parlais avec Lucius, <wait=40>je viens d\'arriver moi aussi.","story.map5-open.011":"Bref, <wait=40>prochaine étape : l\'archipel de Palmyna !","story.map5-open.012":"Après avoir vu à quel point tu es puissant à St. Lamia...","story.map5-open.013":"...j\'attends beaucoup de toi cette fois !","story.map5-open.014":"Donnons tout ce qu\'on a !","story.map5-open.015":"*Toc* <wait=20>*Toc*","story.map5-open.016":"Pardonnez-moi de vous déranger.","story.map5-open.017":"J\'ai de nouvelles informations du service de renseignement.","story.map5-open.018":"Il semble que la barrière protégeant l\'archipel de Palmyna ait été percée.","story.map5-open.019":"...<wait=40>Oui, <wait=40>j\'ai reçu le rapport il n\'y a pas longtemps.","story.map5-open.020":"On dirait qu\'ils deviennent de plus en plus ambitieux.","story.map5-open.021":"Je vais enquêter immédiatement.","story.map5-open.022":"Non, <wait=40>poursuivez vos tâches actuelles.","story.map5-open.023":"Je ne peux pas laisser mon précieux subordonné se retrouver mêlée à ce que ces gens-là préparent.","story.map5-open.024":"M-<wait=20>Merci...<br>Bien, <wait=20>je vais retourner à mon travail.","story.map5-open.025":"Les Quatre Dieux déchus...","story.map5-open.026":"On dit qu\'ils détiennent le pouvoir de détruire tout Grand Gaia.","story.map5-open.027":"J\'aimerais bien voir à quel point ils sont vraiment forts...","story.map6-dungeon1.001":"Chaud, chaud, chaud !!","story.map6-dungeon1.002":"Pourquoi il fait une chaleur pareille ici !","story.map6-dungeon1.003":"Une petite brise fraîche de temps en temps, ce serait pas de refus !","story.map6-dungeon1.004":"Regarde un peu comme je transpire !","story.map6-dungeon1.005":"Je te l\'ai déjà dit, <wait=40>mais je déteste les endroits chauds !","story.map6-dungeon1.006":"Souviens-t\'en la prochaine fois que tu choisis où on se retrouve, <rep_handlename> !","story.map6-dungeon1.007":"Hmm, <wait=40>mais de toute façon, Lord Lucius compte vraiment sur toi, <rep_handlename>...","story.map6-dungeon1.008":"Je vais sûrement devoir faire beaucoup plus d\'efforts qu\'avant, moi aussi...","story.map6-dungeon1.009":"Qu-<wait=20>Qu\'est-ce que c\'est que cette tête !?","story.map6-dungeon1.010":"Co-<wait=40>Comment ça, je ne fais jamais d\'efforts !?","story.map6-dungeon1.011":"Grr, <wait=40>t\'es vraiment méchant.","story.map6-dungeon1.012":"Si on ne t\'attaque pas plus souvent, c\'est uniquement parce que je suis à tes côtés !","story.map6-dungeon1.013":"Personne n\'oserait m\'approcher, <wait=40>ils ont tous bien trop peur de mon incroyable puissance !","story.map6-dungeon1.014":"Même en ce moment, il y a sûrement des méchants qui t\'ont dans le collimateur, <rep_handlename>.","story.map6-dungeon1.015":"Héhé, <wait=40>je plaisante !","story.map6-dungeon1.016":"Si quelqu\'un comme ça rôdait vraiment, je ne risquerais pas de le rater !","story.map6-dungeon1.017":"Tu trouveras un lac en sortant de cet endroit atrocement chaud...","story.map6-dungeon1.018":"Juste après se dresse un magnifique château, <wait=40>ce sera notre prochain point de rendez-vous !","story.map6-dungeon1.019":"Essaie de rester en vie d\'ici là.","story.map6-dungeon1.020":"Et si tu as des ennuis, tu peux toujours prier ta magnifique déesse !","story.map6-dungeon2.001":"<size=18>*Clang*","story.map6-dungeon2.002":"<speed=10>Hé hé hé...<wait=40> Je n\'aurais jamais cru devoir user de mes pouvoirs ainsi.","story.map6-dungeon2.003":"Tu es vraiment quelqu\'un de dangereux, on dirait.","story.map6-dungeon2.004":"Quoi qu\'il en soit, j\'éliminerai sur-le-champ quiconque se dresse sur le chemin de mes plans.","story.map6-dungeon2.005":"Je vais t\'effacer de ce monde avant même que tu t\'en rendes compte.","story.map6-dungeon2.006":"Vous croyez vraiment que ce sera aussi facile ?","story.map6-dungeon2.007":"!?","story.map6-dungeon2.008":"Tout dieu que vous êtes, <wait=40>vous comptez encore fanfaronner ainsi devant un simple Invocateur ?","story.map6-dungeon2.009":"Ahh...<wait=40> Je vois que tu sais qui je suis.","story.map6-dungeon2.010":"Il semble que je sois tombé sur un autre élément imprévu.","story.map6-dungeon2.011":"Mais peu importe. <wait=40>Quoi qu\'il arrive à présent, le résultat sera le même.","story.map6-dungeon2.012":"Ce que j\'ai mis en marche finira par anéantir toute l\'humanité.","story.map6-dungeon2.013":"Quoi !? <wait=40>Vous voulez dire que vous avez déjà lancé le fort céleste ?","story.map6-dungeon2.014":"...<wait=40>Qui es-tu, au juste ?","story.map6-dungeon2.015":"Je devrais peut-être m\'occuper de toi ici et maintenant...","story.map6-dungeon2.016":"Ho ho ho.<wait=40> Faut-il que je le répète ?","story.map6-dungeon2.017":"Vous croyez vraiment que ce sera aussi facile ?","story.map6-dungeon2.018":"Cette puissance...<wait=40>...","story.map6-dungeon2.019":"Je vois. <wait=40>Tu dois donc être... ","story.map6-dungeon2.020":"Invocateur, <wait=40>tu as éveillé mon intérêt.","story.map6-dungeon2.021":"Il semble aussi que tu aies plus d\'un dieu de ton côté. ","story.map6-dungeon2.022":"Je vais garder un œil sur tes faits et gestes encore un moment...","story.map6-dungeon2.023":"Ho ho ho.<wait=40> On dirait que nous nous sommes tirés d\'affaire.","story.map6-dungeon2.024":"Cependant, <wait=40>la situation reste grave. ","story.map6-dungeon2.025":"C\'était Zebra, <wait=20>serviteur de Cardes le Malveillant, <wait=40>l\'un des Quatre Dieux déchus.","story.map6-dungeon2.026":"Il semble qu\'il ait réussi, je ne sais comment, à ressusciter le légendaire fort céleste de l\'Empire d\'Amdahl.","story.map6-dungeon2.027":"Ce monde n\'a nul besoin d\'une telle chose.","story.map6-dungeon2.028":"La faire renaître ne mènerait qu\'à davantage de combats.","story.map6-dungeon2.029":"Tu comptes te rendre à Palmyna, n\'est-ce pas ?","story.map6-dungeon2.030":"Tant que tu poursuis Zebra, <wait=40>pourquoi ne pas abattre le fort céleste au passage ?","story.map6-dungeon2.031":"Ho ho ho.","story.map6-dungeon2.032":"Qu\'y a-t-il ?<wait=40> Tu n\'as aucune raison de t\'inquiéter.","story.map6-dungeon2.033":"La jeune demoiselle est avec toi, n\'est-ce pas ?","story.map6-dungeon2.034":"Tant que tu as la protection de la déesse, <wait=40>tout ira bien.","story.map6-dungeon2.035":"Je te demande seulement de bien l\'écouter !","story.map6-dungeon2.036":"Hmph<wait=40>...","story.map6-dungeon2.037":"En vérité,<wait=40> on ne sait plus très bien qui sauve qui, entre vous deux.","story.map6-dungeon2.038":"Ho ho ho.","story.map6-dungeon2.039":"Je dois m\'en aller.<wait=40> Transmets mes amitiés à la jeune demoiselle.","story.map6-dungeon3.001":"Hé, <wait=40><rep_handlename> !","story.map6-dungeon3.002":"Je t\'attendais.","story.map6-dungeon3.003":"Hein ? <wait=40>Qu\'est-ce qui s\'est passé ?<wait=40> Pourquoi tu fais cette tête sinistre ?","story.map6-dungeon3.004":"Qu\'est-ce que tu dis !?<wait=40> Zebra a ressuscité le fort céleste !?","story.map6-dungeon3.005":"Comment a-t-il pu...","story.map6-dungeon3.006":"Mais attends, <wait=40>c\'est quoi un fort céleste ? C\'est important ?","story.map6-dungeon3.007":"Qu-<wait=20>Qu\'est-ce que c\'est que ce regard !? <wait=40>Il y a des choses que même les déesses ignorent !","story.map6-dungeon3.008":"Ho ho ho.","story.map6-dungeon3.009":"En effet, de telles armes humaines sont bien insignifiantes aux yeux d\'une déesse.","story.map6-dungeon3.010":"Oh, <wait=40>Elder Grah.","story.map6-dungeon3.011":"Hein ? <wait=40>Vous n\'essayez pas de me faire peur, cette fois ?","story.map6-dungeon3.012":"Oh, <wait=40>pardonnez-moi.","story.map6-dungeon3.013":"Il semble que j\'aie déçu les attentes de la jeune demoiselle.","story.map6-dungeon3.014":"Eh bien, <wait=40>permettez-moi de tout reprendre depuis le début.","story.map6-dungeon3.015":"Ce n\'est pas la peine !","story.map6-dungeon3.016":"Ho ho ho.","story.map6-dungeon3.017":"À ce propos, <wait=40>j\'ai quelque chose à vous raconter, accepteriez-vous de m\'écouter ?","story.map6-dungeon3.018":"C\'est l\'histoire du légendaire « fort céleste » de l\'Empire d\'Amdahl.","story.map6-dungeon3.019":"C\'est de ça que parlait <rep_handlename>, <wait=40>le truc que Zebra a ressuscité, c\'est ça ?","story.map6-dungeon3.020":"Oui, <wait=40>c\'est exact.","story.map6-dungeon3.021":"Par le passé, les humains ont eux aussi tenté de le ressusciter.","story.map6-dungeon3.022":"Nul ne sait qui l\'a construit, ni quand, ni même comment...","story.map6-dungeon3.023":"Il semble que seules des instructions d\'utilisation et une description de ses capacités aient subsisté dans l\'Empire d\'Amdahl.","story.map6-dungeon3.024":"Longtemps, la famille impériale l\'a considéré comme interdit... ","story.map6-dungeon3.025":"...jusqu\'à ce qu\'un empereur décide de passer outre.","story.map6-dungeon3.026":"Gardé scellé par l\'Empire d\'Amdahl génération après génération...","story.map6-dungeon3.027":"...il fut libéré par le dernier empereur d\'Amdahl, Myzelion IV...","story.map6-dungeon3.028":"...qui se servit de la puissance du fort céleste pour attaquer les nations voisines et tenter de les soumettre. ","story.map6-dungeon3.029":"C\'est alors <wait=20>que le roi de Palmyna eut vent des plans de l\'empereur.","story.map6-dungeon3.030":"Il implora Myzelion IV, mais celui-ci s\'obstina et refusa de céder. ","story.map6-dungeon3.031":"Finalement, <wait=20>le roi de Palmyna usa de sa puissance pour soumettre Amdahl...","story.map6-dungeon3.032":"...et l\'écrasa avant qu\'il ait pu ressusciter le fort céleste. ","story.map6-dungeon3.033":"Euh, <wait=40>donc en gros...","story.map6-dungeon3.034":"Le fort céleste est si dangereux qu\'il vaut mieux détruire une nation entière que de le laisser renaître ?","story.map6-dungeon3.035":"Oui, <wait=40>c\'est tout à fait ça.","story.map6-dungeon3.036":"C\'est pas vrai !?<wait=40> Et c\'est ça que Zebra a ramené à la vie !?","story.map6-dungeon3.037":"Exactement.","story.map6-dungeon3.038":"Alors on est dans un sacré pétrin !!","story.map6-dungeon3.039":"Enfin, <wait=40>ça n\'a rien à voir avec notre objectif !","story.map6-dungeon3.040":"<rep_handlename> !<wait=40> Continuons à poursuivre Cardes !","story.map6-dungeon3.041":"Et vous, Elder Grah, <wait=40>allez donc détruire le fort céleste !","story.map6-dungeon3.042":"Hein !?<wait=40> Jeune demoiselle, ce serait sûrement impossible.","story.map6-dungeon3.043":"N\'est-ce pas plutôt à vous de relever ce défi ?","story.map6-dungeon3.044":"Ehhh, <wait=40>mais je vais me faire gronder si on s\'écarte de notre chemin...","story.map6-dungeon3.045":"Ne vous inquiétez pas !","story.map6-dungeon3.046":"Le fort céleste est sur la route de Palmyna, <wait=40>il suffit d\'aller tout droit !","story.map6-dungeon3.047":"Accepteriez-vous de vous en charger pour moi ?<wait=40> Voyez-y le vœu d\'un vieil homme au crépuscule de sa vie.","story.map6-dungeon3.048":"Hé, <wait=40><rep_handlename> !","story.map6-dungeon3.049":"Me rendriez-vous ce service ?","story.map6-dungeon3.050":"Bon, <wait=40>je n\'ai pas vraiment le choix, on dirait.","story.map6-dungeon3.051":"Si vous en faites toute une histoire, on peut toujours essayer...","story.map6-dungeon3.052":"...mais vous allez quand même nous aider, hein, Elder Grah ?","story.map6-dungeon3.053":"Ho ho ho,<wait=40> vous êtes sûre de vouloir que je vous accompagne ?","story.map6-dungeon3.054":"Héhé, <wait=40>bien sûr !","story.map6-dungeon3.055":"Et puis, la seule qui a le droit de demander quoi que ce soit à <rep_handlename>, c\'est moi !","story.map6-dungeon3.056":"Ahh, <wait=40>je vois.","story.map6-dungeon3.057":"Ho ho ho. <wait=40>Je vous prie d\'excuser mon impolitesse.","story.map6-dungeon3.058":"Je ferai de mon mieux, tout vieux que je suis.","story.map6-dungeon3.059":"Adieu, <rep_handlename> !<wait=40> Je compte te retrouver au fort céleste !","story.map6-dungeon3.060":"Hmm, <wait=40>je crois qu\'Elder Grah est bien plus fort qu\'il n\'en a l\'air. <wait=20>T\'en penses quoi ?","story.map6-dungeon3.061":"Bah, <wait=40>ça ne nous regarde pas, de toute façon !","story.map6-dungeon3.062":"Bon, allez !<wait=40> En route pour le fort céleste !","story.map6-dungeon4.001":"......<wait=40>Tu as toujours une façon bien détournée de procéder.","story.map6-dungeon4.002":"Ceci est le territoire de Cardes.<wait=40> J\'y agirai comme bon me semble.","story.map6-dungeon4.003":"Heh, <wait=40>cela me convient. <wait=40>J\'aimerais voir de quoi tu es réellement capable, Zebra.","story.map6-dungeon4.004":"Quelle malchance pour cet Invocateur et sa suite...","story.map6-dungeon4.005":"Ils ignorent que le dieu qu\'ils traquent a jadis enseveli des dizaines de milliers d\'humains.","story.map6-dungeon4.006":"...<wait=40>...<wait=40>Cette présence.","story.map6-dungeon4.007":"Il semble qu\'ils soient arrivés.","story.map6-dungeon4.008":"Hmph...","story.map6-dungeon4.009":"On dirait que tu n\'as pas de chance, toi non plus.","story.map6-dungeon4.010":"Je défendrai ton honneur,<wait=40> et je veillerai à ce qu\'ils quittent ces lieux.","story.map6-dungeon4.011":"Allez, <rep_handlename> !<wait=40> Dépêche-toi !","story.map6-dungeon4.012":"Hein ? <wait=40>Où est-ce que c\'est passé ?","story.map6-dungeon4.013":"Pas de doute, cette présence sinistre venait bien d\'ici...","story.map6-dungeon4.014":"<rep_handlename> !<wait=40> C\'est parce que tu as traîné des pieds tout le long du chemin.","story.map6-dungeon4.015":"Enfin, tu ne trouves pas que c\'est bizarre, ici ?<wait=40> Je ne sens plus personne du tout...","story.map6-dungeon4.016":"Je suis sûre d\'avoir senti la présence d\'un dieu tout à l\'heure...","story.map6-dungeon4.017":"C\'était peut-être juste mon imagination ?","story.map6-dungeon4.018":"Hmm, <wait=40>bon, de toute façon on devrait se diriger vers le fort céleste !","story.map6-dungeon4.019":"Direction le Ravin de Gadillian !","story.map6-dungeon5.001":"<size=18>Hé !<wait=40> <rep_handlename> !","story.map6-dungeon5.002":"Pff, pff, pff.<wait=40> Je t\'ai enfin trouvé...","story.map6-dungeon5.003":"Seria !<wait=40> Par ici !","story.map6-dungeon5.004":"Pff, pff, pff, pff.<wait=40> Qui aurait cru que tu serais allé aussi loin...","story.map6-dungeon5.005":"Imbécile !<wait=40> La prochaine fois, mets-toi dans un endroit plus facile à trouver !","story.map6-dungeon5.006":"Ça, c\'est sûrement impossible...","story.map6-dungeon5.007":"Ouf. <wait=40>Mais franchement, on t\'a cherché partout.","story.map6-dungeon5.008":"On pensait que tu serais encore quelque part du côté du Château d\'Avenia...","story.map6-dungeon5.009":"...mais on dirait que tu es déjà arrivé à Encervis, toi aussi.","story.map6-dungeon5.010":"Tu es vraiment une plaie.","story.map6-dungeon5.011":"Pourquoi les Pourfendeurs de démons doivent-ils chercher un idiot comme toi ?","story.map6-dungeon5.012":"Nous, au Hall des Invocateurs, devrions nous concentrer sur les affaires du Hall des Invocateurs.","story.map6-dungeon5.013":"Nous demander soudain d\'épauler <rep_handlename>, à quoi peuvent-ils bien penser ?","story.map6-dungeon5.014":"Ça suffit.","story.map6-dungeon5.015":"On n\'y peut rien, c\'est la situation dans laquelle on se trouve.","story.map6-dungeon5.016":"Arrêter le fort céleste passe avant Graham. <wait=20>Même toi, tu le sais, n\'est-ce pas, Seria ?","story.map6-dungeon5.017":"Je sais, je sais !","story.map6-dungeon5.018":"Ça m\'énerve juste que <rep_handlename> fasse partie de ce plan !","story.map6-dungeon5.019":"Haha, <wait=40>ça te ressemble bien, Seria.","story.map6-dungeon5.020":"Mais je le répète, <wait=40>nous sommes venus arrêter Zebra. ","story.map6-dungeon5.021":"On ne peut pas le laisser utiliser le fort céleste pour attaquer Elgaia.","story.map6-dungeon5.022":"Je sais que le combat a été rude jusqu\'ici, <wait=40>mais à partir de maintenant, il va falloir redoubler d\'efforts !","story.map6-dungeon5.023":"...Qu\'est-ce que c\'est ?","story.map6-dungeon5.024":"Hein ? <wait=40>Tu dis que tu n\'es pas au courant ? <wait=50>Tu es sérieux ??","story.map6-dungeon5.025":"*Soupir* <wait=40>Quelle honte...","story.map6-dungeon5.026":"J\'ai vraiment l\'air d\'une idiote, à m\'enflammer toute seule !","story.map6-dungeon5.027":"On dirait que quelqu\'un au Hall des Invocateurs a sacrément cafouillé !","story.map6-dungeon5.028":"Quelle tristesse. <wait=40>Nous sommes censés être en état d\'alerte maximale.","story.map6-dungeon5.029":"Je pensais que tu avais reçu les mêmes informations que nous...","story.map6-dungeon5.030":"Il a peut-être simplement reçu de mauvaises informations ?","story.map6-dungeon5.031":"Ça ne ressemble pas du tout au Hall des Invocateurs.","story.map6-dungeon5.032":"Tu as sûrement raison...","story.map6-dungeon5.033":"Bref, <wait=40>on dirait que je vais devoir t\'expliquer moi-même.","story.map6-dungeon5.034":"Tu poursuis Zebra, celui qui a ressuscité le fort céleste, <wait=40>c\'est bien ça ?","story.map6-dungeon5.035":"Bon, <wait=40>au moins, tu as compris ça.","story.map6-dungeon5.036":"Quant au fort céleste, <wait=40>c\'est une chose véritablement maléfique. ","story.map6-dungeon5.037":"S\'il devenait pleinement opérationnel...","story.map6-dungeon5.038":"...<wait=40>Zebra pourrait s\'en servir pour franchir la Porte de Lucius et attaquer Elgaia.","story.map6-dungeon5.039":"C\'est pourquoi même les hauts responsables du Hall des Invocateurs ont reconnu que nous sommes en situation d\'urgence...","story.map6-dungeon5.040":"Et ils ont demandé l\'aide de tous les Invocateurs se trouvant près du fort céleste...","story.map6-dungeon5.041":"Toi compris, <rep_handlename>.","story.map6-dungeon5.042":"Même si nous, les Pourfendeurs de démons, pourrions très bien nous occuper de tout ça seuls...","story.map6-dungeon5.043":"...depuis que tu as vaincu Maxwell, Karl insiste pour que je reconnaisse tes capacités, moi aussi...","story.map6-dungeon5.044":"On va t\'aider cette fois, <wait=40>alors tu as intérêt à être reconnaissant !","story.map6-dungeon5.045":"Ha ha ha.","story.map6-dungeon5.046":"Cela dit, <wait=40>il te suffit de continuer à poursuivre le fort céleste comme tu l\'as fait jusqu\'ici. ","story.map6-dungeon5.047":"Nous t\'aiderons à avancer en écartant tous les obstacles qui pourraient se présenter. ","story.map6-dungeon5.048":"Franchement, <wait=40>c\'est nous qui héritons de la sale besogne.","story.map6-dungeon5.049":"Tu as intérêt à nous renvoyer l\'ascenseur après !","story.map6-dungeon5.050":"D\'après les informations du Hall des Invocateurs d\'Akras...","story.map6-dungeon5.051":"...il semble qu\'on puisse atteindre le fort céleste une fois passée la Terre des morts, juste devant. ","story.map6-dungeon5.052":"Nous allons te dégager la voie.","story.map6-dungeon5.053":"Toi, continue d\'avancer sans quitter le fort céleste des yeux !","story.map6-dungeon5.054":"Allons-y, Seria !","story.map6-dungeon5.055":"Hé, <wait=40>Karl, <wait=20>attends-moi !","story.map6-dungeon5.056":"<rep_handlename> !","story.map6-dungeon5.057":"Et veille à ce que cette déesse donne un coup de main, elle aussi ! <wait=40>Compris ?","story.map6-dungeon5.058":"Franchement, <wait=40>pourquoi je m\'inquiète pour un morveux comme toi...","story.map6-dungeon6.001":"Ah ! <wait=40>Te voilà !","story.map6-dungeon6.002":"<rep_handlename> !<wait=40> Par ici !","story.map6-dungeon6.003":"Cet endroit me donne la chair de poule...","story.map6-dungeon6.004":"Pourquoi les endroits que dirigent les Quatre Dieux déchus sont-ils si effrayants...","story.map6-dungeon6.005":"Tu dois ramener la lumière dans ces contrées, <rep_handlename> !","story.map6-dungeon6.006":"Oh, <wait=40>j\'ai des informations très spéciales pour toi aujourd\'hui !","story.map6-dungeon6.007":"Laisse-moi t\'expliquer comment on va atteindre le fort céleste. ","story.map6-dungeon6.008":"Écoute bien ta jolie petite déesse t\'expliquer tout ça !","story.map6-dungeon6.009":"Tout d\'abord, <wait=40>le nom officiel du fort céleste, c\'est Solaris. ","story.map6-dungeon6.010":"Je n\'ai pas réussi à savoir depuis combien de temps il est dans les parages...","story.map6-dungeon6.011":"...mais on dirait qu\'il flotte dans le ciel, juste après la Terre des morts.","story.map6-dungeon6.012":"Haha, <wait=40>je savais que tu serais surpris. ","story.map6-dungeon6.013":"Tu te demandes sûrement « Comment on va monter dans le ciel ? », pas vrai ?","story.map6-dungeon6.014":"Laisse faire la déesse !","story.map6-dungeon6.015":"Une fois que tu auras passé cet endroit et que tu seras en route vers le fort céleste...","story.map6-dungeon6.016":"Je t\'enverrai là-haut grâce à mes pouvoirs spéciaux !","story.map6-dungeon6.017":"Héhé, <wait=40>qu\'est-ce que tu ferais sans moi ?","story.map6-dungeon6.018":"Tu peux me remercier autant que tu veux !","story.map6-dungeon6.019":"Mais ne baisse pas ta garde !","story.map6-dungeon6.020":"On dirait qu\'il y a plus loin une fille super effrayante qui adore les bons massacres...","story.map6-dungeon6.021":"Je pars devant au fort céleste, <rep_handlename>, <wait=40>alors ne traîne pas !","story.map6-dungeon6.022":"E-<wait=40>Et ne va pas croire que je pars devant parce que j\'ai peur, compris !?","story.map6-dungeon7.001":"On y est !","story.map6-dungeon7.002":"On dirait que je t\'ai envoyé pile au milieu du fort céleste !","story.map6-dungeon7.003":"Je suis plutôt incroyable, hein ?","story.map6-dungeon7.004":"Aïe... <wait=40>Où est-ce qu\'on est, au juste ?","story.map6-dungeon7.005":"J\'ai <wait=40>le tournis...","story.map6-dungeon7.006":"On était en train de repousser des démons sur la Terre des morts, non ?","story.map6-dungeon7.007":"Ah ! <wait=40>Karl !","story.map6-dungeon7.008":"Et ta petite copine Seria !","story.map6-dungeon7.009":"Comment ça, « petite copine » !?","story.map6-dungeon7.010":"Mais c\'est <rep_handlename> !","story.map6-dungeon7.011":"Mais si tu es ici, <wait=40>ça veut dire que...","story.map6-dungeon7.012":"On est à l\'intérieur du fort céleste !","story.map6-dungeon7.013":"...<wait=40>On dirait bien.","story.map6-dungeon7.014":"<size=18>Mais t\'es complètement idiote !?","story.map6-dungeon7.015":"C\'est entièrement ta faute si on est là-haut, non !?","story.map6-dungeon7.016":"Tu ne vois pas que tout le monde se bat encore en bas ?","story.map6-dungeon7.017":"Tu devrais prendre le temps de comprendre la situation avant d\'agir, la déesse !","story.map6-dungeon7.018":"Qu-<wait=40>Qu\'est-ce que tu racontes ? <wait=40>Je n\'ai rien fait de mal...","story.map6-dungeon7.019":"Faut vraiment être imbue de soi-même pour dire une chose pareille !","story.map6-dungeon7.020":"On ne pourrait pas en rester là ? On a des problèmes bien plus importants, non ?","story.map6-dungeon7.021":"Et puis, il sera plus facile pour nous d\'épauler <rep_handlename>, maintenant.","story.map6-dungeon7.022":"D\'ailleurs, <wait=40>ce n\'est pas notre absence à tous les deux qui changera grand-chose pour ceux qui se battent en bas.","story.map6-dungeon7.023":"Tu as sûrement raison, mais...","story.map6-dungeon7.024":"En tout cas, <wait=40>tu es toujours une déesse aussi incroyable.","story.map6-dungeon7.025":"Tu nous as un peu facilité la tâche, malgré la situation périlleuse dans laquelle on se trouve. ","story.map6-dungeon7.026":"S\'il y avait quelqu\'un capable d\'y arriver en s\'y mettant vraiment, <wait=40>je savais que ce serait toi.","story.map6-dungeon7.027":"Tu te trompes complètement, Karl !<wait=40> Tu es trop naïf !","story.map6-dungeon7.028":"Haha...","story.map6-dungeon7.029":"<size=18>!?<wait=40> Qui est là !?","story.map6-dungeon7.030":"<speed=10>Ah...","story.map6-dungeon7.031":"<speed=10>Il semble que même vous, humains, puissiez sentir ma présence.","story.map6-dungeon7.032":"Zebra !!","story.map6-dungeon7.033":"C\'est Zebra, le dieu fou... <wait=40>Méfiez-vous, il est aussi dangereux qu\'il en a l\'air...","story.map6-dungeon7.034":"Tu vas payer pour ce que tu as fait à Edila !","story.map6-dungeon7.035":"Prépare-toi !","story.map6-dungeon7.036":"Je n\'ai que faire de pitoyables vermisseaux comme vous.","story.map6-dungeon7.037":"Celle que je veux, <wait=40>c\'est Tilith, la disciple de Lucius.","story.map6-dungeon7.038":"<size=18>Te voilà !","story.map6-dungeon7.039":"<size=18>*Bonk*","story.map6-dungeon7.040":"Kyaahh !!","story.map6-dungeon7.041":"Tu sembles épuisée.<wait=40> Rien d\'étonnant, après avoir usé de tant de pouvoir pour les amener ici.","story.map6-dungeon7.042":"Tu t\'es donné bien du mal pour ces pitoyables vermisseaux.","story.map6-dungeon7.043":"Si c\'est une bataille entre dieux que tu cherches, Lucius t\'arrêterait sûrement...","story.map6-dungeon7.044":"...mais si tu comptes nous attaquer maintenant, je ne te ferai pas de cadeau !","story.map6-dungeon7.045":"<size=18>Vous tous, reculez !","story.map6-dungeon7.046":"Quelle est cette puissance...<wait=40> Ugh...<wait=40>Je ne peux plus bouger...","story.map6-dungeon7.047":"Gyah...<wait=40> Comment peux-tu encore avoir une telle puissance après tout ça...<wait=40> Serait-ce...","story.map6-dungeon7.048":"Pff... pff... ","story.map6-dungeon7.049":"Je suis peut-être un peu affaiblie...<wait=40> mais pas question que je perde contre toi...","story.map6-dungeon7.050":"<size=18>Ne crois pas pouvoir te jouer de moi ! <wait=40>Tu n\'es que le petit chien de Lucius !!","story.map6-dungeon7.051":"<size=18>Kyaaahh !!","story.map6-dungeon7.052":"<size=20>Tilith !!","story.map6-dungeon7.053":"Nngh... <wait=40>Elle s\'est mieux défendue que je ne le pensais...","story.map6-dungeon7.054":"Mais peu importe, désormais. <wait=40>J\'ai éliminé ce qui se dressait sur mon chemin. ","story.map6-dungeon7.055":"Il ne reste plus aucun dieu pour vous défendre.","story.map6-dungeon7.056":"Vous ferez un bon entraînement pour mes subordonnés. ","story.map6-dungeon7.057":"Tu crois qu\'on va te laisser filer comme ça ?","story.map6-dungeon7.058":"Vos intentions m\'importent peu.","story.map6-dungeon7.059":"Pitoyables vermisseaux, vous êtes incapables de faire le moindre pas en ma présence.","story.map6-dungeon7.060":"Je n\'utilise ce fort céleste que dans un seul but : libérer Lord Cardes de ses chaînes.","story.map6-dungeon7.061":"Si vous êtes vraiment décidés à m\'affronter, <wait=40>vous me trouverez qui vous attend dans les profondeurs. ","story.map6-dungeon7.062":"Je vais vous inculquer à tous la crainte des dieux !","story.map6-dungeon7.063":"<size=18>Halte !!","story.map6-dungeon7.064":"Bon sang ! <wait=40>Il s\'est enfui !","story.map6-dungeon7.065":"<size=18>Karl !!","story.map6-dungeon7.066":"<size=18>Qu\'est-ce que !?<wait=40> D\'où sortent tous ces monstres !?","story.map6-dungeon7.067":"N-<wait=40>Nngh...","story.map6-dungeon7.068":"Dé-<wait=40>Désolée...<wait=40> <rep_handlename>...","story.map6-dungeon7.069":"Ne parle pas !<wait=40> Tu dois garder tes forces !","story.map6-dungeon7.070":"Karl, <wait=40>tu sais ce qu\'on doit faire !","story.map6-dungeon7.071":"Oui ! <wait=40><rep_handlename> !","story.map6-dungeon7.072":"Toi, poursuis Zebra. <wait=20>Seria et moi, on s\'occupe d\'ici !","story.map6-dungeon7.073":"J\'ignore comment il compte utiliser ce fort...","story.map6-dungeon7.074":"...mais s\'il parvient à libérer Cardes, on est dans un sacré pétrin !","story.map6-dungeon7.075":"Ne reste pas planté là, <wait=40>bouge-toi un peu !","story.map6-dungeon7.076":"Tu crois que des monstres pareils nous posent problème ?","story.map6-dungeon7.077":"Comment oses-tu douter du chef des Pourfendeurs de démons !","story.map6-dungeon7.078":"Si tu as le temps de t\'inquiéter pour rien, <wait=40>alors arrête de traîner et lance-toi à sa poursuite !","story.map6-dungeon7.079":"Et puis, <wait=40>tu sais mieux que personne que cette déesse a encore de la combativité en réserve, non ?","story.map6-dungeon7.080":"C\'est vrai, Seria.","story.map6-dungeon7.081":"Ces monstres ne représentent aucune menace pour nous.","story.map6-dungeon7.082":"Et ne crains rien pour la déesse, elle est désormais sous notre protection.","story.map6-dungeon7.083":"Alors va, <wait=40>et terrasse cet ignoble Zebra !","story.map6-dungeon7.084":"On compte sur toi, <rep_handlename> !","story.map6-dungeon7.085":"Montre-nous quel genre d\'Invocateur tu es vraiment !","story.map6-dungeon7.086":"Seria !!","story.map6-dungeon7.087":"Compris !","story.map6-dungeon7.088":"<speed=20><size=20>C\'est parti !!","story.map6-dungeon_ex_clear.001":"<size=18>*Bzz* </size><wait=20><size=20>*Bz</size><wait=10><size=19>zzzz* </size><wait=40><size=18>*Bzzzzzz*</size>","story.map6-dungeon_ex_clear.002":"Tu as réussi, <rep_handlename> !","story.map6-dungeon_ex_clear.003":"Tu as éliminé la créature avant même l\'arrivée de nos agents logistiques.","story.map6-dungeon_ex_clear.004":"Je savais que tu y arriverais, monsieur !","story.map6-dungeon_ex_clear.005":"Ah, <wait=20>mais apparemment, ils vont quand même se rendre dans ces ruines.","story.map6-dungeon_ex_clear.006":"Il semble que ces ruines abritaient à l\'origine quelque chose d\'immense.","story.map6-dungeon_ex_clear.007":"On dirait une sorte de chantier naval, mais j\'imagine que c\'était la seule option.","story.map6-dungeon_ex_clear.008":"Hmm ? <wait=40>Tu as remarqué quelque chose en entrant, monsieur ?","story.map6-dungeon_ex_clear.009":"Au fait, il existerait des archives indiquant que Valmodora est aussi apparu pendant la bataille contre les dieux.","story.map6-dungeon_ex_clear.010":"Il semble que même à l\'époque, il habitait des ruines quelque part.","story.map6-dungeon_ex_clear.011":"Cependant, il était censé avoir été exterminé par un certain guerrier.","story.map6-dungeon_ex_clear.012":"Je suis sûre que toi aussi, tu entreras dans l\'histoire pour ce que tu viens de faire.","story.map6-dungeon_ex_clear.013":"Mais quand même, <wait=20>essaie de ne pas être aussi imprudent à l\'avenir !","story.map6-dungeon_ex_clear.014":"Mais de toute façon, tu iras quand même, quoi que je dise, pas vrai ?","story.map6-dungeon_ex_clear.015":"Je m\'inquiète vraiment beaucoup pour toi, tu sais !","story.map6-dungeon_ex_clear.016":"......","story.map6-dungeon_ex_clear.017":"Hihi, <wait=20>ça faisait longtemps que je n\'avais pas vu cet air embêté sur ton visage.","story.map6-dungeon_ex_clear.018":"Bref, continue ton enquête dans d\'autres zones, s\'il te plaît !","story.map6-dungeon_ex_open.001":"<size=18>*Bzz* </size><wait=20><size=20>*Bz</size><wait=10><size=19>zzzz* </size><wait=40><size=18>*Bzzzzzz*</size>","story.map6-dungeon_ex_open.002":"Vous m\'entendez, <wait=40>monsieur ?","story.map6-dungeon_ex_open.003":"<size=20><rep_handlename> !</size>","story.map6-dungeon_ex_open.004":"Tu m\'entends ?","story.map6-dungeon_ex_open.005":"Lin Merylham, du Soutien logistique...","story.map6-dungeon_ex_open.006":"...du Bureau d\'enquête de l\'Office d\'exploration de Grand Gaia, à ton service.","story.map6-dungeon_ex_open.007":"Je te contacte aujourd\'hui avec de nouvelles informations.","story.map6-dungeon_ex_open.008":"Le Hall des Invocateurs a fait une découverte effrayante dans les ruines antiques d\'Encervis.","story.map6-dungeon_ex_open.009":"Il semble qu\'une créature incroyablement dangereuse y ait élu domicile.","story.map6-dungeon_ex_open.010":"Pour l\'instant, <wait=20>tout semble calme.","story.map6-dungeon_ex_open.011":"Cependant, elle semble puiser des forces dans les ruines alentour pour étendre son territoire.","story.map6-dungeon_ex_open.012":"Nous allons de nouveau y envoyer nos agents logistiques, alors d\'ici là, tiens-toi à l\'écart !","story.map6-dungeon_ex_open.013":"......","story.map6-dungeon_ex_open.014":"Qu-<wait=20>Quoi, monsieur ? <wait=40>Tu y es déjà ?","story.map6-dungeon_ex_open.015":"Hmph, <wait=40>monsieur, tu es trop imprudent !","story.map6-dungeon_ex_open.016":"Mais de toute façon, tu iras quand même, quoi que je dise, pas vrai ?","story.map6-dungeon_ex_open.017":"Compris !","story.map6-dungeon_ex_open.018":"Je ne vais pas essayer de t\'arrêter !","story.map6-dungeon_ex_open.019":"Le monstre qui t\'attend à l\'intérieur s\'appelle Valmodora.","story.map6-dungeon_ex_open.020":"Il semble que ce soit un monstre plutôt gigantesque, alors sois extrêmement prudent.","story.map6-dungeon_ex_open.021":"Je m\'inquiète toujours tellement pour toi, <wait=20>tu sais...","story.map6-ending.001":"<speed=10>Es-<wait=40>Espèce d\'idiot...","story.map6-ending.002":"<speed=10>Ty-<wait=40>Typique des humains...","story.map6-ending.003":"Gyah !<wait=40> <speed=10>Moi, un disciple...<wait=40> de Lord Cardes...","story.map6-ending.004":"<speed=10>Je-<wait=40>Je ne p-peux pas être..<wait=40> vaincu...<wait=40> si facilement...","story.map6-ending.005":"<speed=10>Nngh...<wait=40> Je n\'ai pas le choix...","story.map6-ending.006":"<speed=10>Je vais faire tomber le fort céleste, <wait=40>et je vous emporte tous avec moi !!","story.map6-ending.007":"<size=18>*Clang*","story.map6-ending.008":"<size=18>Toi-<wait=40>Toiiiiiii !!","story.map6-ending.009":"Même un dieu doit savoir quand s\'arrêter.","story.map6-ending.010":"L\'ignorer ne fait guère de toi qu\'un démon de second ordre, me semble-t-il.","story.map6-ending.011":"Tu devrais prendre le temps d\'y réfléchir. ","story.map6-ending.012":"<size=18>Gwaaaahhh !!","story.map6-ending.013":"Hmm !?","story.map6-ending.014":"Pourquoi cet air surpris ?","story.map6-ending.015":"Peu importe, <wait=40>dépêche-toi d\'appeler la jeune demoiselle.","story.map6-ending.016":"Avec Zebra hors d\'état de nuire, <wait=40>le fort céleste sera sans doute de nouveau scellé.","story.map6-ending.017":"Hmm !? <wait=40>Cette lumière...","story.map6-ending.018":"<speed=10>Se pourrait-il... <wait=40>qu\'elle vienne du Lac Aldela ?","story.map6-ending.019":"<size=18><rep_handlename> !!","story.map6-ending.020":"Aïeuh...<wait=40> Où est-ce qu\'on a atterri, cette fois ?","story.map6-ending.021":"<rep_handlename> !!","story.map6-ending.022":"...<wait=40>...<wait=40>Tu as réussi !","story.map6-ending.023":"Tu es vraiment incroyable, toi !","story.map6-ending.024":"Nngh, <wait=40>j\'ai mal au derrière...","story.map6-ending.025":"Hé, toi !<wait=40> Et si tu soignais un peu plus l\'atterrissage, la prochaine fois !","story.map6-ending.026":"Ho ho ho.","story.map6-ending.027":"Avec un derrière aussi rembourré que le tien, ça ne devrait pas poser de problème, tu ne crois pas, Seria ?","story.map6-ending.028":"Gr-<wait=40>Grahde...<wait=40> Elder Grah !<wait=40> Qu\'est-ce que vous faites ici !?","story.map6-ending.029":"Elder Grah ?<wait=40> C\'est quoi, ce nom ?","story.map6-ending.030":"Attendez une seconde, <wait=40>vous n\'êtes pas Grahdens ?","story.map6-ending.031":"Que fait un Invocateur Ancien comme vous dans un endroit pareil ?","story.map6-ending.032":"Comment oses-tu, <wait=40>petit sot !","story.map6-ending.033":"Et dire que <wait=40>j\'avais enfin réussi à ce que Tilith me voie comme un gentil vieillard...","story.map6-ending.034":"Et voilà que tu arrives et que tu gâches tout !","story.map6-ending.035":"Hein ?<wait=40> Comment ça, « gentil vieillard » ?","story.map6-ending.036":"En tant que l\'un des dirigeants du Hall des Invocateurs,<wait=40> vous ne devriez pas être en train d\'y travailler !?","story.map6-ending.037":"Hmm, <wait=40>je ne comprends pas exactement ce qui se passe, <wait=40>mais on dirait qu\'Elder Grah était quelqu\'un d\'important depuis le début.","story.map6-ending.038":"Ce n\'est pas juste le vieil homme bizarre qu\'on croyait connaître...","story.map6-ending.039":"Hé, <wait=40>maintenant que tu sais qui est Lord Grahdens, tu devrais le traiter avec un peu plus de respect !","story.map6-ending.040":"Mais ça ne me concerne pas, moi...","story.map6-ending.041":"Et puis, je ne sais pas comment vous voyez les choses ici, dans le monde des humains...","story.map6-ending.042":"...mais s\'il fallait choisir, tu ne dirais pas qu\'en tant que déesse, je suis plus importante ?","story.map6-ending.043":"C\'est moi que tu devrais traiter avec plus de respect, Seria !","story.map6-ending.044":"Si c\'est ce que tu penses, alors pourquoi tu n\'essaies pas de te comporter un peu plus comme une déesse ?","story.map6-ending.045":"Où est-ce que tu veux en venir !?","story.map6-ending.046":"Calmez-vous, <wait=40>vous comptez vraiment vous battre malgré la victoire de <rep_handlename> sur Zebra ?","story.map6-ending.047":"Ho ho ho.","story.map6-ending.048":"Seria, <wait=40>c\'est exactement comme le dit Tilith.","story.map6-ending.049":"Comparé aux dieux, <wait=40>mon existence est bien insignifiante. ","story.map6-ending.050":"Tilith, <wait=40>j\'aimerais que vous continuiez à m\'appeler tout simplement Elder Grah.","story.map6-ending.051":"C\'était bien mon intention, de toute façon.","story.map6-ending.052":"Je sais maintenant qui vous êtes vraiment, Elder Grah.<wait=40> Vous n\'êtes pas comme l\'autre olibrius que je connais !","story.map6-ending.053":"De qui tu parles !?","story.map6-ending.054":"Hmm, je me demande...","story.map6-ending.055":"Franchement, <wait=40>vous ne changerez donc jamais, toutes les deux ?","story.map6-ending.056":"Bref, <wait=40>Grahdens...","story.map6-ending.057":"Pour en revenir à ce que je voulais savoir, <wait=40>que faites-vous ici ?","story.map6-ending.058":"Karl...","story.map6-ending.059":"Tu es toi aussi un Invocateur, <wait=40>pourquoi ne pas me témoigner un peu plus de respect ?","story.map6-ending.060":"Allons donc. <wait=40>Je ne vous laisserai pas encore changer de sujet.","story.map6-ending.061":"Je vous connais depuis longtemps, j\'ai l\'habitude de vos manières.","story.map6-ending.062":"Ho ho ho.<wait=40> Toujours aussi brutalement franc, à ce que je vois.","story.map6-ending.063":"Karl, <wait=40>permets-moi de t\'expliquer les détails plus tard.","story.map6-ending.064":"J\'ai d\'abord à parler de quelque chose avec <rep_handlename>.","story.map6-ending.065":"<rep_handlename>, <wait=40>pour avoir vaincu Zebra comme je te l\'avais demandé...","story.map6-ending.066":"Je t\'exprime ma gratitude en tant qu\'Invocateur Ancien du Département de la Défense du Hall des Invocateurs d\'Akras.","story.map6-ending.067":"Héhé, <wait=40>vous vous attendiez à moins de la part d\'un bon ami à moi ?","story.map6-ending.068":"Je savais que tu y arriverais, mon <rep_handlename> !","story.map6-ending.069":"Hé, <wait=20>arrête de dire qu\'il est à toi !","story.map6-ending.070":"B-<wait=40>Bref, puisque <rep_handlename> a accompli la requête de Lord Grahdens...","story.map6-ending.071":"Je suppose que je peux me permettre de te féliciter, en tant que collègue Invocatrice.","story.map6-ending.072":"Que de franchise, dis donc !","story.map6-ending.073":"Qu-<wait=40>Qu\'est-ce que tu racontes !?","story.map6-ending.074":"Ho ho ho.<wait=40> On dirait que tout le monde t\'est bien reconnaissant.","story.map6-ending.075":"Cependant, <wait=40>aussi fort fût-il, <wait=40>n\'oublie pas que Zebra n\'était qu\'un simple disciple de Cardes.","story.map6-ending.076":"La puissance de Zebra n\'est rien comparée à celle du dieu déchu que tu poursuis. ","story.map6-ending.077":"À Palmyna, <wait=40>des batailles d\'une férocité sans égale t\'attendent assurément.","story.map6-ending.078":"Plus que jamais, <wait=40>tu dois avancer avec prudence.","story.map6-ending.079":"Ne vous inquiétez pas pour lui. <wait=40>Il est sous ma protection.","story.map6-ending.080":"Comment ça, « ma protection » ? <wait=40>Tu étais à deux doigts de mourir il y a une seconde, tu ne t\'en souviens pas ?","story.map6-ending.081":"Seria !","story.map6-ending.082":"Qu-<wait=40>Quoi !?","story.map6-ending.083":"Merci...<wait=40> de m\'avoir protégée tout à l\'heure.","story.map6-ending.084":"Q-<wait=20>Qu-<wait=10>Qu\'est-ce qui te p-<wait=10>prend tout à coup ?","story.map6-ending.085":"C-<wait=40>Ce n\'est pas comme si j\'attendais des remerciements ou quoi que ce soit...","story.map6-ending.086":"J-<wait=40>Je voulais juste... <wait=20>*Marmonne* <size=14>*Marmonne* <size=12>*Marmonne*","story.map6-ending.087":"Haha, <wait=40>un peu intimidée, hein ?","story.map6-ending.088":"Ho ho ho.","story.map6-ending.089":"<rep_handlename> !","story.map6-ending.090":"On part enfin pour Palmyna, la terre où Cardes est scellé !","story.map6-ending.091":"Je crois en toi...","story.map6-ending.092":"<rep_handlename>, <wait=40>tu es l\'Invocateur qui va sauver le monde !","story.map6-open.001":"<anchor=center><br><br><br><br><br><br><br><br><br><br><speed=8><size=15>Toi, <rep_handlename>,<wait=39> qui as libéré Amdahl...","story.map6-open.002":"<anchor=center><br><br><br><br><br><br><br><br><br><br><speed=8><size=15>Use de mon pouvoir alors que tu entames ton voyage sur cette nouvelle terre...","story.map6-open.003":"<anchor=center><br><br><br><br><br><br><br><br><br><br><speed=8><size=15>Pour apporter un nouvel espoir à ce monde imprégné de tristesse…","story.map6-open.004":"<anchor=center><br><br><br><br><br><br><br><br><br><br><speed=8><size=15>Tu dois avoir foi en ton pouvoir, <wait=20>et continuer d\'avancer…","story.map6-open.005":"Oh, <wait=40>tu es réveillé !","story.map6-open.006":"Regarde ! <wait=40>On est à Encervis.","story.map6-open.007":"Avec ses eaux profondes et ses hauts volcans, <wait=40>cet endroit est connu pour ses environnements extrêmes.","story.map6-open.008":"Il y a bien longtemps, <wait=40>une bataille entre humains a eu lieu ici...","story.map6-open.009":"...<wait=40>...","story.map6-open.010":"Mais ce n\'est pas très intéressant, alors oublions ça !","story.map6-open.011":"Et puis, <wait=40>tu as tellement d\'autres choses à apprendre !","story.map6-open.012":"Et de toute façon, ça n\'a pas vraiment de rapport avec nous.","story.map6-open.013":"Ici, au milieu de l\'archipel de Palmyna, on est encore assez loin de Palmyna elle-même...","story.map6-open.014":"Mais ne baisse pas ta garde, <wait=20>et reste toujours concentré !","story.map6-open.015":"J\'attends de grandes choses de toi ici aussi !","story.map6-open.016":"Bon, <wait=20>faisons de notre mieux et donnons tout pour vaincre Cardes !!","story.map7-dungeon1.001":"<rep_handlename> !","story.map7-dungeon1.002":"On a un problème !<wait=40> Un gros problème !!","story.map7-dungeon1.003":"Kyaah !","story.map7-dungeon1.004":"<size=18>*Boum*","story.map7-dungeon1.005":"Aïïïïe...","story.map7-dungeon1.006":"Hé !<wait=40> <rep_handlename> ! <wait=40>Ne reste pas planté là !","story.map7-dungeon1.007":"Hein ? <wait=40>Tu croyais que je devais t\'attendre au Château d\'Obselion ?","story.map7-dungeon1.008":"Ce n\'est pas le moment de s\'inquiéter de ces petits détails !","story.map7-dungeon1.009":"On a vraiment un gros problème !","story.map7-dungeon1.010":"Le sceau qui retient Cardes commence à se dissoudre !!","story.map7-dungeon1.011":"Je ne sais pas pourquoi il s\'est soudain mis à se dissoudre...","story.map7-dungeon1.012":"...mais il s\'apprête clairement à s\'échapper !","story.map7-dungeon1.013":"Pourtant, je ne pense pas que quelqu\'un de l\'extérieur y soit pour quelque chose.","story.map7-dungeon1.014":"Pfff !","story.map7-dungeon1.015":"Je pensais qu\'on le battrait sans souci, vu comment tu t\'es occupé de Zebra.","story.map7-dungeon1.016":"Hmph, <wait=40>on dirait que ça va encore être la course...","story.map7-dungeon1.017":"J\'ai encore tant à faire pour Lord Lucius...","story.map7-dungeon1.018":"Et maintenant, je dois en plus gérer ce que Cardes manigance...","story.map7-dungeon1.019":"Pourquoi je n\'ai jamais droit à une pause !","story.map7-dungeon1.020":"Oh, <wait=40>j\'ai failli oublier !","story.map7-dungeon1.021":"Je n\'ai toujours pas trouvé de chemin vers le Monde spirituel !","story.map7-dungeon1.022":"Mais je te promets de trouver d\'ici à ce que tu arrives au Château d\'Obselion, <rep_handlename>.","story.map7-dungeon1.023":"Bonne chance, <wait=40>et cette fois, on se retrouve pour de bon au Château d\'Obselion !","story.map7-dungeon2.001":"Ho ho ho. <wait=40>Mais c\'est <rep_handlename> ?","story.map7-dungeon2.002":"Tu te rends sur la terre où Cardes est scellé, n\'est-ce pas ?","story.map7-dungeon2.003":"Hmm ? <wait=40>Qu\'y a-t-il ?<wait=40> Tu sembles troublé.","story.map7-dungeon2.004":"Si c\'est Tilith que tu cherches, je ne l\'ai pas vue par ici. ","story.map7-dungeon2.005":"Pourquoi cet air soucieux ? <wait=40>Tu n\'as pas à t\'inquiéter pour elle, tu sais ?","story.map7-dungeon2.006":"Elle est bien au-delà des soucis de simples Invocateurs comme nous. ","story.map7-dungeon2.007":"Cela dit, la façon adorable dont elle te regarde me rendrait nerveux moi aussi. ","story.map7-dungeon2.008":"Ho ho ho.","story.map7-dungeon2.009":"Hmph. <wait=40>Il semble que cela faisait longtemps que nous n\'étions pas seuls, tous les deux. ","story.map7-dungeon2.010":"Puisque nous avons un peu de temps, <wait=40>laisse-moi te raconter une petite histoire.","story.map7-dungeon2.011":"L\'histoire d\'une terrible bataille entre les humains et les dieux.","story.map7-dungeon2.012":"Il y a longtemps, <wait=40>le Château d\'Obselion abritait la famille royale de Palmyna. ","story.map7-dungeon2.013":"C\'était à l\'origine un château pittoresque, <wait=40>entouré de verdure. ","story.map7-dungeon2.014":"Mais voici ce qu\'il en est resté après la bataille contre les dieux. ","story.map7-dungeon2.015":"Connais-tu les Quatre Héros de Palmyna ?","story.map7-dungeon2.016":"Une légende raconte que ces quatre guerriers ont combattu Cardes pour sauver cette terre.","story.map7-dungeon2.017":"On dit même qu\'Edea, princesse de Palmyna, était parmi eux.","story.map7-dungeon2.018":"Si la légende dit vrai, ce sont ces Quatre Héros qui ont scellé Cardes. ","story.map7-dungeon2.019":"Cependant, on dit qu\'en échange du pouvoir de sceller Cardes...","story.map7-dungeon2.020":"...les Quatre Héros ont dû sacrifier leur propre vie. ","story.map7-dungeon2.021":"Je me demande à quoi ils pensaient à la fin. ","story.map7-dungeon2.022":"Étaient-ils heureux de croire que sceller Cardes sauverait Palmyna ? ","story.map7-dungeon2.023":"Est-ce ainsi qu\'ils ont pu affronter la mort sans crainte ?","story.map7-dungeon2.024":"Aussi vaillants qu\'ils aient été à risquer leur vie pour protéger ce lieu...","story.map7-dungeon2.025":"...au moment où ils ont commencé à se battre, il était déjà perdu.","story.map7-dungeon2.026":"Une bien triste histoire, en vérité...","story.map7-dungeon2.027":"<rep_handlename>, <wait=40>comprends-tu ce que j\'essaie de te dire ?","story.map7-dungeon2.028":"Ho ho ho. <wait=40>Ne t\'en fais pas.","story.map7-dungeon2.029":"Un jour, <wait=40>tu te retrouveras sûrement dans une situation tout aussi inimaginable. ","story.map7-dungeon2.030":"D\'ici là, <wait=40>observe attentivement ce qui t\'entoure, car tout continue de changer. ","story.map7-dungeon2.031":"Ce que tu découvriras alimentera ta route. ","story.map7-dungeon2.032":"Ho ho ho.<wait=40> Pardon pour ce long sermon. ","story.map7-dungeon2.033":"Quand tu reverras Tilith, transmets-lui ce message, s\'il te plaît.","story.map7-dungeon2.034":"Le sceau de Cardes est presque brisé.","story.map7-dungeon2.035":"Au revoir, et prends soin de toi.","story.map7-dungeon3.001":"<size=18>*Tchac*","story.map7-dungeon3.002":"Ouf. <wait=40>On dirait qu\'on en a presque fini avec les monstres du coin. ","story.map7-dungeon3.003":"Mais je dois l\'admettre, <wait=40>ils sont bien plus forts que prévu.","story.map7-dungeon3.004":"Hmm ?","story.map7-dungeon3.005":"Hé ! <wait=40><rep_handlename> !","story.map7-dungeon3.006":"Bienvenue à Palmyna !","story.map7-dungeon3.007":"On n\'est plus très loin de l\'endroit où Cardes est scellé. <wait=40>Donnons tout pour ce dernier effort !","story.map7-dungeon3.008":"Hé ! <wait=40>Seria !<wait=40> <rep_handlename> est arrivé aussi !","story.map7-dungeon3.009":"Pas besoin de me le dire à chaque fois. <wait=40>Et puis, j\'ignorais <rep_handlename> exprès.","story.map7-dungeon3.010":"Haha. <wait=40>Toujours la même, hein, Seria ?","story.map7-dungeon3.011":"Au fait, <wait=40>où est cette déesse qui te suit partout ?","story.map7-dungeon3.012":"...Hmm, alors elle cherche un chemin vers le Monde spirituel.","story.map7-dungeon3.013":"On dirait qu\'on n\'a pas le choix : il faut y aller si on veut affronter Cardes...","story.map7-dungeon3.014":"Qu\'est-ce qui ne va pas ?<wait=40> Tu es un peu pâle.","story.map7-dungeon3.015":"C-<wait=40>Ce n\'est rien !","story.map7-dungeon3.016":"Je suis juste un peu agacée !","story.map7-dungeon3.017":"Enfin, <wait=40>tu ne vois pas ce qui se passe, Karl !?","story.map7-dungeon3.018":"Notre objectif a toujours été d\'abattre Graham !","story.map7-dungeon3.019":"Pourquoi on devrait perdre notre temps à aider <rep_handlename> !?","story.map7-dungeon3.020":"Allons, <wait=40>vaincre les Quatre Dieux déchus passe sûrement avant Graham. ","story.map7-dungeon3.021":"Je sais, je sais !","story.map7-dungeon3.022":"Mais tu sais ce que je ressens, hein, Karl ?","story.map7-dungeon3.023":"Plus que tout, je veux abattre Graham !","story.map7-dungeon3.024":"Oui, <wait=40>je comprends ce que tu ressens. <wait=50>Pardonne-moi, <wait=40>Seria...","story.map7-dungeon3.025":"Je ne voulais pas te faire de reproche, Karl...","story.map7-dungeon3.026":"Grrr !!<wait=40> Tout ça, c\'est ta faute !","story.map7-dungeon3.027":"Pourquoi tu ne peux pas affronter Cardes tout seul !","story.map7-dungeon3.028":"Un peu absurde,<wait=40> tu ne trouves pas ?","story.map7-dungeon3.029":"J\'ai dit que je savais !","story.map7-dungeon3.030":"Karl, <wait=40>c\'est devenu trop dur de discuter avec toi ces temps-ci !","story.map7-dungeon3.031":"Non, <wait=40>c\'est toi qui dis des choses absurdes ces temps-ci...","story.map7-dungeon3.032":"Je ne vois pas du tout de quoi tu parles !","story.map7-dungeon3.033":"<rep_handlename> ! <wait=40>Dépêche-toi de trouver cette déesse...","story.map7-dungeon3.034":"...et de découvrir comment on est censés aller dans le Monde spirituel !","story.map7-dungeon3.035":"H-<wait=20>Hé !<wait=40> Attends-moi !","story.map7-dungeon3.036":"<rep_handlename> ! On va te dégager la route.","story.map7-dungeon3.037":"Toi, assure-toi juste d\'être prêt à affronter Cardes !","story.map7-dungeon4.001":"...<rep_handlename>.","story.map7-dungeon4.002":"Je suis contente de te voir... <wait=40>On dirait que tu vas bien...","story.map7-dungeon4.003":"Haah...<wait=40> haah...","story.map7-dungeon4.004":"J-<wait=40>Je vais bien...","story.map7-dungeon4.005":"Nngh...<wait=40> On dirait que j\'ai un peu raté mon coup...","story.map7-dungeon4.006":"Pendant que je cherchais comment aller dans le Monde spirituel, <wait=40>un imprévu est survenu...","story.map7-dungeon4.007":"Désolée de t\'avoir inquiété.","story.map7-dungeon4.008":"Ça ira, <wait=20>j\'ai juste besoin d\'une petite pause.","story.map7-dungeon4.009":"Mais surtout, <wait=40>j\'ai quelque chose à te dire...","story.map7-dungeon4.010":"<rep_handlename>...","story.map7-dungeon4.011":"Le sceau de Cardes...<wait=40> il ne faisait pas que se fissurer...","story.map7-dungeon4.012":"Cardes... <wait=40>le détruit... <wait=40>de l\'intérieur...","story.map7-dungeon4.013":"Il est affaibli après être resté scellé si longtemps...","story.map7-dungeon4.014":"Mais ses pouvoirs divins restent immenses...","story.map7-dungeon4.015":"Ils ont déjà commencé à déborder du Monde spirituel, <wait=40>détruisant tout sur leur passage...","story.map7-dungeon4.016":"J\'ai essayé de réparer le sceau, mais j\'ai échoué...","story.map7-dungeon4.017":"Haah...<wait=40> haah...","story.map7-dungeon4.018":"C-<wait=40>Cependant... <wait=40>on a encore une chance.","story.map7-dungeon4.019":"Le chemin vers le Monde spirituel est maintenant ouvert.","story.map7-dungeon4.020":"Va au Champ de bataille de Noera. <wait=40>L\'entrée du Monde spirituel se trouve juste au-delà...","story.map7-dungeon4.021":"Pars devant, <wait=40>et ne t\'inquiète pas pour moi !","story.map7-dungeon4.022":"Demande de l\'aide à Karl, Seria et Elder Grah en chemin. ","story.map7-dungeon4.023":"Je vais me reposer avant de te rejoindre...","story.map7-dungeon4.024":"Ne t\'inquiète pas pour moi...","story.map7-dungeon4.025":"Je suis une déesse belle et invincible !","story.map7-dungeon4.026":"C\'est juste que <wait=40>je suis un peu fatiguée...","story.map7-dungeon4.027":"Mais ne t\'en fais pas... <wait=50>On se retrouve sur le front...","story.map7-dungeon5.001":"Mais c\'est <rep_handlename>.","story.map7-dungeon5.002":"Pourquoi cet air grave ?","story.map7-dungeon5.003":"Qu\'est-ce que tu dis !?<wait=40> Qu\'est-il arrivé à Tilith !?","story.map7-dungeon5.004":"Hmph. <wait=40>La situation semble plus urgente que je ne l\'imaginais. ","story.map7-dungeon5.005":"Désolé, mais j\'ai une affaire à régler par ici, <wait=40>je ne peux donc pas t\'aider. ","story.map7-dungeon5.006":"J\'ai déjà demandé à Karl et Seria de te prêter main-forte. ","story.map7-dungeon5.007":"Unissez vos forces pour vaincre Cardes.","story.map7-dungeon5.008":"......<wait=50><rep_handlename>.","story.map7-dungeon5.009":"J\'ai quelque chose à te dire avant que tu n\'affrontes le Dieu déchu.","story.map7-dungeon5.010":"L\'un des Quatre Héros de Palmyna travaillait ici, au Séminaire d\'Arlind.","story.map7-dungeon5.011":"Il s\'appelait Lorand, et il était professeur. ","story.map7-dungeon5.012":"Bien qu\'il ait déjà quitté la vie de soldat...","story.map7-dungeon5.013":"...Edea, la princesse de Palmyna, <wait=40>l\'a convaincu de combattre les dieux envahisseurs. ","story.map7-dungeon5.014":"La suite, je te l\'ai déjà racontée. ","story.map7-dungeon5.015":"Les Quatre Héros ont sacrifié leur vie pour sceller Cardes. ","story.map7-dungeon5.016":"Cependant, <wait=40>il existe bien d\'autres récits de gens qui se sont battus comme les Quatre Héros. ","story.map7-dungeon5.017":"Il y a longtemps, <wait=40>de nombreux humains ont combattu les dieux ici.","story.map7-dungeon5.018":"La plupart y ont laissé la vie.","story.map7-dungeon5.019":"Selon la légende, <wait=40>Lucius aurait permis à certains survivants de fuir vers Elgaia. ","story.map7-dungeon5.020":"Tous ceux restés à Grand Gaia ont péri. ","story.map7-dungeon5.021":"<rep_handlename>.<wait=50> Pourquoi crois-tu que les dieux ont détruit les humains ?","story.map7-dungeon5.022":"Les théories sont innombrables, <wait=40>mais personne n\'a encore trouvé la réponse.","story.map7-dungeon5.023":"Pourtant, bien longtemps après, <wait=40>Lucius a rouvert le chemin vers Grand Gaia.","story.map7-dungeon5.024":"Il doit lui aussi avoir besoin de la force des humains pour vaincre les Quatre Dieux déchus. ","story.map7-dungeon5.025":"Cela dit, pourquoi les Quatre Dieux déchus se déchaînent-ils au juste ?","story.map7-dungeon5.026":"Et pourquoi le Saint Empereur Karna Masta, seigneur des dieux, n\'a-t-il pas réagi ?","story.map7-dungeon5.027":"Il y a trop de choses que nous, humains, ne comprendrons jamais.","story.map7-dungeon5.028":"Mais Tilith, en tant que disciple de Lucius, devrait sûrement comprendre, tu ne crois pas ?","story.map7-dungeon5.029":"Es-tu sûr qu\'elle ne sait rien ? <wait=40>Peut-être te cache-t-elle simplement certaines choses.","story.map7-dungeon5.030":"Ou peut-être <wait=40>ne réfléchit-elle tout simplement pas. ","story.map7-dungeon5.031":"Ho ho ho.","story.map7-dungeon5.032":"Tilith est une si gentille et jolie fille, j\'espère que ce n\'est que ça. ","story.map7-dungeon5.033":"Quoi qu\'il en soit, <wait=40><rep_handlename>.","story.map7-dungeon5.034":"Pardon d\'avoir divagué ainsi, <wait=40>mais je suis sûr que tu comprends où je veux en venir.","story.map7-dungeon5.035":"Ne te laisse pas emporter par tout ce qui se passe, <wait=40>agis selon tes propres pensées et ta volonté. ","story.map7-dungeon5.036":"Ton rôle dans tout cela dépasse déjà ce qu\'un simple Invocateur devrait pouvoir porter. ","story.map7-dungeon5.037":"Tu devrais te mettre en route.","story.map7-dungeon5.038":"Au-delà du Champ de bataille de Noera, juste devant, se trouve l\'entrée du Monde spirituel.","story.map7-dungeon5.039":"Et n\'oublie pas, <wait=20>Tilith et les dieux ne sont pas les seuls à compter sur toi.","story.map7-dungeon6.001":"Salut, <rep_handlename> !<wait=40> Tu es déjà là.","story.map7-dungeon6.002":"Regarde !<wait=40> L\'entrée du Monde spirituel est juste devant nous.","story.map7-dungeon6.003":"Dis, <wait=40>cette déesse t\'a expliqué comment entrer dans le Monde spirituel, non ?","story.map7-dungeon6.004":"Et où est-elle ? <wait=40>Comment peut-elle aller traîner ailleurs à un moment aussi critique !?","story.map7-dungeon6.005":"Euh......<wait=50> Oh, je vois......","story.map7-dungeon6.006":"M-<wait=40>Mais il n\'y a pas de quoi s\'inquiéter, hein ?<wait=40> C\'est une déesse, après tout, non !?","story.map7-dungeon6.007":"Elle va sûrement réapparaître tôt ou tard avec son petit air suffisant !","story.map7-dungeon6.008":"Alors efface-moi cette mine piteuse et fais ton boulot !","story.map7-dungeon6.009":"Si elle a fait tout ça, c\'est parce qu\'elle croyait que tu pouvais vaincre Cardes !","story.map7-dungeon6.010":"Tu dois tout donner maintenant ! <wait=40>Tu ne peux pas laisser ses efforts partir en fumée !","story.map7-dungeon6.011":"Elle a raison.","story.map7-dungeon6.012":"Je sais que tu t\'inquiètes, <rep_handlename>, <wait=40>mais on doit vaincre Cardes avant tout.","story.map7-dungeon6.013":"Si l\'entrée du Monde spirituel est vraiment ouverte...","story.map7-dungeon6.014":"...alors rien ne nous empêche de t\'aider nous aussi.","story.map7-dungeon6.015":"Pour la déesse, <wait=40>on fera tout notre possible pour t\'aider !","story.map7-dungeon6.016":"J-<wait=40>Je ne fais que suivre les ordres du Hall des Invocateurs !","story.map7-dungeon6.017":"Ce que je fais n\'a rien à voir avec cette idiote de déesse !","story.map7-dungeon6.018":"Enfin, <wait=40>ce serait sympa qu\'elle nous soit redevable, pour une fois. ","story.map7-dungeon6.019":"Je vais peut-être faire un peu plus d\'efforts que d\'habitude, cette fois.","story.map7-dungeon6.020":"Heh, <wait=40>même elle serait rassurée de te voir aussi motivée, Seria.","story.map7-dungeon6.021":"Qu-<wait=40>Qu\'est-ce que tu racontes !?","story.map7-dungeon6.022":"Je dis juste qu\'on peut compter sur toi, Seria. <wait=40>Pas vrai, <rep_handlename> ?","story.map7-dungeon6.023":"Ne l\'encourage pas !","story.map7-dungeon6.024":"Bon, <wait=40>frayons-nous un chemin dans le Monde spirituel !","story.map7-dungeon6.025":"<rep_handlename> !<wait=40> Seria !<wait=40> Allons-y !","story.map7-dungeon7.001":"Alors voici le Monde spirituel Palmyna...<wait=40> Plutôt sinistre, je dois dire.","story.map7-dungeon7.002":"Je suis contente que ce soit bien plus vaste que je ne le pensais.","story.map7-dungeon7.003":"Hein ?<wait=40> Plus c\'est vaste, plus ce sera dur de trouver Cardes, non ?","story.map7-dungeon7.004":"E-<wait=20>Euh, je veux dire...<wait=40> Ce n\'est pas ce que je voulais dire...","story.map7-dungeon7.005":"Je pensais juste que ce serait dur de combattre Cardes dans un espace étroit. ","story.map7-dungeon7.006":"Oui, <wait=40>tu as raison.","story.map7-dungeon7.007":"Avec autant d\'espace, <wait=40>nos options pour affronter Cardes sont illimitées. ","story.map7-dungeon7.008":"Oui, <wait=40>on dirait bien.","story.map7-dungeon7.009":"<size=16>*Grondement*","story.map7-dungeon7.010":"Qu-<wait=20>Qu\'est-ce que c\'était !<wait=20> Pourquoi tout tremble ?","story.map7-dungeon7.011":"Zut ! <wait=40>On dirait que ce n\'est pas aussi paisible qu\'il y paraissait !","story.map7-dungeon7.012":"J\'espérais avoir plus de temps pour chercher Cardes...","story.map7-dungeon7.013":"<rep_handlename> !<wait=40> Seria !","story.map7-dungeon7.014":"Séparons-nous pour chercher Cardes !","story.map7-dungeon7.015":"Tu crois vraiment que c\'est une bonne idée dans un moment pareil !?","story.map7-dungeon7.016":"Le temps presse.","story.map7-dungeon7.017":"Si on ne vainc pas Cardes avant qu\'il se libère...","story.map7-dungeon7.018":"...on risque fort de disparaître avec le Monde spirituel.","story.map7-dungeon7.019":"......<wait=40>Compris.","story.map7-dungeon7.020":"Si vous entendez le fracas des épées, <wait=40>c\'est sûrement là que le combat a commencé. ","story.map7-dungeon7.021":"Gardez l\'oreille tendue et l\'œil ouvert !","story.map7-dungeon7.022":"<rep_handlename> !","story.map7-dungeon7.023":"Tu n\'es encore qu\'un débutant, <wait=40>alors si tu vois Cardes, tu as intérêt à nous attendre sagement !","story.map7-dungeon7.024":"Elle a raison. <wait=40>Quoi qu\'il arrive, aucun de nous ne doit l\'affronter seul !","story.map7-dungeon7.025":"Je veux qu\'on survive tous et qu\'on rentre ensemble à Elgaia !","story.map7-ending.001":"Haah...<wait=40> haah...<wait=40> On est arrivés trop tard !","story.map7-ending.002":"<size=20>*Grondement*","story.map7-ending.003":"<anchor=center><speed=10>Seria...<wait=40> Prends ma main......","story.map7-ending.004":"Bonjour tout le monde ! <wait=40>Désolée pour le retard !!","story.map7-ending.005":"<rep_handlename> ! <wait=40>Je savais que tu y arriverais !","story.map7-ending.006":"T-<wait=20>Toi ! <wait=40>Qu\'est-ce que tu fais ici !?","story.map7-ending.007":"Je croyais que tu étais gravement blessée...","story.map7-ending.008":"J\'avais le pressentiment que <rep_handlename> avait des ennuis, <wait=40>alors j\'ai mis ma convalescence de côté pour venir aider.","story.map7-ending.009":"J\'ai encore un peu mal, quand même.","story.map7-ending.010":"Quelle folie de faire une chose pareille sur un simple pressentiment !","story.map7-ending.011":"Je suis contente d\'être arrivée à temps pour t\'aider aussi, <wait=40>Seria.","story.map7-ending.012":"......","story.map7-ending.013":"M-<wait=40>Merci pour ça...","story.map7-ending.014":"De rien ! <wait=40>Je suis juste heureuse que vous soyez tous sains et saufs !","story.map7-ending.015":"Oui, <wait=40>merci de nous avoir sauvés !","story.map7-ending.016":"Ç\'aurait été bien dommage de périr dans un endroit pareil, <wait=40> après avoir vaincu Cardes. ","story.map7-ending.017":"Merci, <wait=40>déesse.","story.map7-ending.018":"Voilà le Karl que je connais ! <wait=40>N\'hésite pas à me remercier davantage, toi aussi, Seria !","story.map7-ending.019":"N-<wait=40>N\'exagère pas !","story.map7-ending.020":"Enfin, <wait=40>si tu es une déesse, pourquoi tu arrives toujours à la toute dernière minute !","story.map7-ending.021":"Qu-<wait=40>Qu\'est-ce qui te prend !","story.map7-ending.022":"Et puis, pourquoi tu ne nous as pas dit comment sortir du Monde spirituel !?","story.map7-ending.023":"Eu-<wait=40>Euh, <wait=20>j\'ai dû...","story.map7-ending.024":"Restons-en là.","story.map7-ending.025":"Et quoi qu\'il y paraisse, Seria te remercie vraiment de ce que tu as fait pour elle.","story.map7-ending.026":"Oui, <wait=40>je sais.","story.map7-ending.027":"Je le vois bien à sa façon de rougir !","story.map7-ending.028":"Moi aussi, je tiens beaucoup à Seria !","story.map7-ending.029":"Arrête ça tout de suite ! <wait=40>Tu me donnes la nausée !!","story.map7-ending.030":"<size=12>Quelle idiote, franchement...","story.map7-ending.031":"Karl ! <wait=40>Je m\'en vais !","story.map7-ending.032":"On a fait ce que le Hall des Invocateurs nous demandait !","story.map7-ending.033":"Maintenant, c\'est l\'heure de traquer Graham !","story.map7-ending.034":"A-<wait=20>Attends-moi !","story.map7-ending.035":"<rep_handlename> !","story.map7-ending.036":"Je n\'ai jamais été aussi fier de t\'appeler mon ami !","story.map7-ending.037":"Quand les choses se seront calmées, <wait=20>partons à l\'aventure ensemble à Grand Gaia !","story.map7-ending.038":"Ne prends pas la grosse tête juste parce que tu as vaincu Cardes !","story.map7-ending.039":"Ta chance finira bien par tourner, tu sais.","story.map7-ending.040":"La prochaine fois, je te montrerai la vraie puissance de l\'Invocatrice qui commande les Pourfendeurs de démons. ","story.map7-ending.041":"Mais d\'ici là, <wait=20>tâche de rester entier !","story.map7-ending.042":"Ils sont partis.","story.map7-ending.043":"J\'espère qu\'on pourra de nouveau se battre ensemble un jour !","story.map7-ending.044":"<rep_handlename> ! <wait=40>Merci mille fois d\'avoir vaincu Cardes !","story.map7-ending.045":"J\'avoue que je ne pouvais pas trop compter sur toi au début, <wait=40>mais tu as déjà vaincu deux des Quatre Dieux déchus.","story.map7-ending.046":"Vous, les humains, vous êtes vraiment intéressants !","story.map7-ending.047":"Depuis que j\'ai rencontré Karl, Seria,<wait=40> et toi...","story.map7-ending.048":"...je vous aime plus que jamais, vous les humains !","story.map7-ending.049":"J\'ai hâte de vivre d\'autres aventures avec toi, <wait=40>mon <rep_handlename>.","story.map7-ending.050":"......<wait=40>Il semble que le grand Cardes ait été vaincu.","story.map7-ending.051":"Les seuls Dieux déchus restants sont Zevalhua le Suprême <wait=40>et le Dieu-Bête Afla Dilith. ","story.map7-ending.052":"Il est sûrement temps qu\'ils entrent en scène, eux aussi.","story.map7-ending.053":"Nous devons hâter nos préparatifs.","story.map7-ending.054":"<rep_handlename>...","story.map7-ending.055":"J\'ai hâte de voir quelle voie tu choisiras lors de la prochaine bataille...","story.map7-open.001":"<anchor=center><br><br><br><br><br><br><br><br><br><br><speed=8><size=15>Toi, <rep_handlename>,<wait=39> qui as libéré Encervis...","story.map7-open.002":"<anchor=center><br><br><br><br><br><br><br><br><br><br><speed=8><size=15>Use de mon pouvoir en t\'avançant dans Palmyna, <wait=40>terre du Dieu déchu scellé...","story.map7-open.003":"<anchor=center><br><br><br><br><br><br><br><br><br><br><speed=8><size=15>Afin d\'apporter un nouvel espoir à ce monde imprégné de tristesse...","story.map7-open.004":"<anchor=center><br><br><br><br><br><br><br><br><br><br><speed=8><size=15>Tu dois avoir foi en ton pouvoir, <wait=20>et continuer d\'avancer...","story.map7-open.005":"<rep_handlename> !<wait=40> Tu es enfin arrivé à Palmyna !","story.map7-open.006":"Plus très loin jusqu\'au Monde spirituel où Cardes est enfermé !","story.map7-open.007":"Puisque tu as vaincu Zebra, je suis sûre que tu y arriveras sans traîner, <rep_handlename>.","story.map7-open.008":"Mais quand même, <wait=40>ne baisse pas ta garde !","story.map7-open.009":"Il y a longtemps, un royaume appelé Palmyna se dressait ici et a vaillamment combattu les dieux. ","story.map7-open.010":"Les vestiges de cette guerre sont encore visibles aujourd\'hui...","story.map7-open.011":"...ainsi que tous les esprits et monstres qui errent toujours par ici.","story.map7-open.012":"Bon, <wait=40>laisse-moi nous trouver un chemin vers le Monde spirituel. ","story.map7-open.013":"Avance à ton rythme, <rep_handlename>.","story.map7-open.014":"Je t\'attendrai un peu plus loin, au Château d\'Obselion !","story.map8-dungeon1.001":"Bon sang ! <wait=40>C\'est encore tellement loin.","story.map8-dungeon1.002":"Enfin, <wait=20>ça ne sert à rien de se plaindre maintenant.","story.map8-dungeon1.003":"Hm ? <wait=40>Hé, toi !","story.map8-dungeon1.004":"Tss, <wait=20>mais ce ne serait pas notre cher <rep_handlename> ?","story.map8-dungeon1.005":"Qu\'est-ce que tu fais ici ?","story.map8-dungeon1.006":"Ne me dis pas que... !?","story.map8-dungeon1.007":"Tu es venu t\'attribuer le mérite de mon dur labeur, c\'est ça !?","story.map8-dungeon1.008":"Bref, <wait=20>c\'est quoi cette histoire que j\'entends sur Cordelica ?","story.map8-dungeon1.009":"Il paraît que tu as éliminé l\'un des Quatre Dieux déchus tout seul ?","story.map8-dungeon1.010":"Pff, <wait=40>ou peut-être <wait=20>que Karl et Seria ont dû venir à ton secours, hein ?","story.map8-dungeon1.011":"Peu importe, <wait=20>ça ne change rien de toute façon.","story.map8-dungeon1.012":"Tais-toi ! <wait=40>Je ne t\'ai pas demandé d\'explication !","story.map8-dungeon1.013":"Si tu as un minimum de cervelle, tu vas écouter ce que j\'ai à dire !","story.map8-dungeon1.014":"Bre<wait=20>f<wait=20>.","story.map8-dungeon1.015":"T\'as intérêt à ne pas te mettre en travers de mon chemin ! C\'est tout !","story.map8-dungeon1.016":"Je suis en pleine mission de la plus haute importance pour le compte du Hall des Invocateurs.","story.map8-dungeon1.017":"Mais rien qu\'une élite comme moi ne puisse gérer.","story.map8-dungeon1.018":"Si tu vois ce que je veux dire, tu ferais mieux d\'aller voir ailleurs !","story.map8-dungeon1.019":"Et je te le promets, si je te trouve à traîner du côté de Cordelica, je ne ferai qu\'une bouchée de toi.","story.map8-dungeon1.020":"Compris ?","story.map8-dungeon2.001":"Ouf, <wait=40>cet endroit est plus dangereux que je ne le pensais.","story.map8-dungeon2.002":"À ce rythme, j\'ai encore un long chemin avant d\'atteindre la tour.","story.map8-dungeon2.003":"Tiens, <wait=40>mais c\'est <rep_handlename>.","story.map8-dungeon2.004":"Que fais-tu ici ?","story.map8-dungeon2.005":"Hihi, <wait=40>je suppose que je n\'ai pas vraiment besoin de demander.","story.map8-dungeon2.006":"Le Hall des Invocateurs doit être très sérieux pour t\'avoir envoyé si loin.","story.map8-dungeon2.007":"Mais malgré tout, <wait=20>je n\'ai aucune intention de céder.","story.map8-dungeon2.008":"La Garde impériale s\'emparera du pouvoir caché en Lizeria.","story.map8-dungeon2.009":"Hihi, <wait=40>inutile de faire cette tête.","story.map8-dungeon2.010":"J\'ai vu ce que tu vaux vraiment à Cordelica.","story.map8-dungeon2.011":"Pourquoi ne pas laisser tomber cette bande d\'Akras pour nous rejoindre ?","story.map8-dungeon2.012":"Pour bâtir une vraie paix, il faut se libérer de l\'emprise des Anciens !","story.map8-dungeon2.013":"Qu\'est-ce que tu racontes, <wait=40>sale chienne de l\'Empire !","story.map8-dungeon2.014":"Tout ce que tu pourras dire à <rep_handlename> ne servira à rien.","story.map8-dungeon2.015":"Cette voix vulgaire...","story.map8-dungeon2.016":"Ça faisait longtemps...","story.map8-dungeon2.017":"Madame la Garde impériale.","story.map8-dungeon2.018":"Je suis surprise. <wait=40>Comment diable es-tu arrivé jusqu\'ici ?","story.map8-dungeon2.019":"Ce n\'était rien du tout, vraiment.","story.map8-dungeon2.020":"Il se trouve simplement que je suis l\'Invocateur spécialement choisi par le Hall des Invocateurs pour venir mener des recherches ici.","story.map8-dungeon2.021":"Cet Invocateur à l\'air idiot, là, n\'est qu\'un touriste en quête de sensations fortes à bon marché.","story.map8-dungeon2.022":"<rep_handlename> n\'a aucune idée de ce qui se passe ici.","story.map8-dungeon2.023":"Enfin, tu n\'as pas partagé d\'informations importantes avec cet abruti, j\'espère ?","story.map8-dungeon2.024":"Nngh...","story.map8-dungeon2.025":"Quoi qu\'il en soit, <wait=20>les vrais idiots, ce sont ceux du Hall des Invocateurs.","story.map8-dungeon2.026":"Comment ont-ils pu envoyer un Invocateur de second ordre comme toi dans un endroit pareil ?","story.map8-dungeon2.027":"C\'est bien la preuve qu\'ils n\'ont aucune idée de la valeur réelle de cette région.","story.map8-dungeon2.028":"Et si c\'est vraiment le cas, <wait=20>je n\'aurai aucun mal à obtenir le pouvoir caché ici.","story.map8-dungeon2.029":"Hé ! <wait=40>Surveille ton langage !","story.map8-dungeon2.030":"Tu n\'aurais aucune chance contre moi si je donnais tout ce que j\'ai !","story.map8-dungeon2.031":"Hihi, <wait=40>quelle tête tu fais.","story.map8-dungeon2.032":"Mais vraiment, <wait=20>inutile de jouer les durs.","story.map8-dungeon2.033":"De toute façon, je n\'ai pas le temps de jouer avec toi.","story.map8-dungeon2.034":"Tu prends la fuite ?","story.map8-dungeon2.035":"Non, <wait=40>je choisis simplement d\'éviter les affrontements inutiles pour accomplir mon objectif.","story.map8-dungeon2.036":"<rep_handlename>, <wait=40>réfléchis à ce dont nous venons de parler.","story.map8-dungeon2.037":"Je suis sûre que ce serait plus avantageux pour toi que d\'avoir des alliés stupides comme lui.","story.map8-dungeon2.038":"<size=22>Qu\'est-ce que tu racontes !</size>","story.map8-dungeon2.039":"Hé, <wait=40>elle a fini par s\'enfuir.","story.map8-dungeon2.040":"Hé ! <wait=40><rep_handlename> !","story.map8-dungeon2.041":"Pourquoi est-ce que je te trouve toujours dans ce genre d\'endroit ?","story.map8-dungeon2.042":"Tu es en train de me dire que tu n\'as pas l\'intention d\'écouter ce que je dis ?","story.map8-dungeon2.043":"Ou peut-être <wait=20>que tu comptes accepter son offre et trahir le Hall des Invocateurs ?","story.map8-dungeon2.044":"Remarque, ce que tu fais m\'est bien égal.","story.map8-dungeon2.045":"Si tu ignores encore mon avertissement, <wait=20>la prochaine fois que je te vois...","story.map8-dungeon2.046":"...je n\'aurai pas d\'autre choix que de te réduire en poussière.","story.map8-dungeon2.047":"Pff, <wait=40>qu\'est-ce que tu peux être pénible !","story.map8-dungeon2.048":"Mais t\'inquiète, <wait=40>je n\'essaie pas de te menacer ou quoi que ce soit.","story.map8-dungeon2.049":"Je voulais juste que tu saches que je ne laisse personne se mettre en travers de mon chemin !","story.map8-dungeon2.050":"Compris ?","story.map8-dungeon3.001":"Hé, <wait=40><rep_handlename>.","story.map8-dungeon3.002":"Tu as l\'air d\'être de bonne humeur.","story.map8-dungeon3.003":"Attends !","story.map8-dungeon3.004":"Si tu es venu ici en ignorant mon avertissement, c\'est que tu comptes trahir le Hall des Invocateurs, pas vrai ?","story.map8-dungeon3.005":"Quelles conditions cette femme t\'a-t-elle proposées ?","story.map8-dungeon3.006":"Hm ? <wait=40>Tu dis que tu n\'es pas un traître ?","story.map8-dungeon3.007":"<size=22>Ha ha ha !</size>","story.map8-dungeon3.008":"Tu as fait un choix intéressant, pour un idiot pareil.","story.map8-dungeon3.009":"Ce qui ne peut vouloir dire qu\'une chose...","story.map8-dungeon3.010":"Tu es venu dans l\'intention de me causer des ennuis, c\'est ça ?","story.map8-dungeon3.011":"Ha ha ha ! <wait=40>T\'es marrant, toi !","story.map8-dungeon3.012":"<size=22>Ne prends pas trop la grosse tête !</size>","story.map8-dungeon3.013":"Tu veux que je te montre à quel point tu m\'es inférieur ?","story.map8-dungeon3.014":"Quel abruti.","story.map8-dungeon3.015":"Je ne te supporte vraiment pas.","story.map8-dungeon3.016":"Ah, et au fait, il paraît que tu es aussi un ami de cet imbécile de Karl.","story.map8-dungeon3.017":"On dirait que je n\'ai pas le choix : je vais te donner une leçon et te montrer à quel point je suis génial.","story.map8-dungeon3.018":"Ça te va ? <wait=20>Je t\'attendrai juste après ce lac gelé.","story.map8-dungeon3.019":"Je vais te donner la leçon en personne, alors réjouis-toi d\'avance !","story.map8-dungeon4.001":"C-<wait=20>Ce n\'est pas possible ! <wait=40>C\'est impossible.","story.map8-dungeon4.002":"Tu as vaincu Cardes aussi !?","story.map8-dungeon4.003":"N-<wait=20>Non, <wait=40>je ne doute pas de toi...","story.map8-dungeon4.004":"Compris. <wait=40>Je vais m\'en occuper avec le plus grand soin.","story.map8-dungeon4.005":"Oui. <wait=40>Inutile de vous inquiéter pour ça.","story.map8-dungeon4.006":"Je ferai de mon mieux pour ne pas vous décevoir.","story.map8-dungeon4.007":"Ouf... <wait=40>Les choses se précipitent bien plus vite que je ne l\'avais prévu.","story.map8-dungeon4.008":"Hein, <wait=20>ce ne serait pas...","story.map8-dungeon4.009":"Hihi, <wait=40>nous nous retrouvons donc.","story.map8-dungeon4.010":"Dois-je comprendre que tu as vaincu Lugina ?","story.map8-dungeon4.011":"Vaincre un Invocateur aussi faible n\'a sûrement posé aucun problème, à toi qui as déjà vaincu deux des Quatre Dieux déchus ?","story.map8-dungeon4.012":"Hihi, <wait=20>ne me regarde pas comme ça.","story.map8-dungeon4.013":"Je sais à quel point tu es bien plus puissant que lui.","story.map8-dungeon4.014":"Alors, <wait=20>laisse-moi te le demander encore une fois.","story.map8-dungeon4.015":"Ne veux-tu pas quitter le Hall des Invocateurs d\'Akras pour venir travailler avec nous ?","story.map8-dungeon4.016":"La dernière fois, nous n\'avons pas eu le temps de parler, on nous a si grossièrement interrompus.","story.map8-dungeon4.017":"Mais je suis sérieuse.","story.map8-dungeon4.018":"Hihi, <wait=20>bien sûr, une invitation aussi soudaine a de quoi te laisser perplexe.","story.map8-dungeon4.019":"Laisse-moi juste te dire une chose. <wait=40>Le système qui gouverne Elgaia est brisé.","story.map8-dungeon4.020":"Et nous sommes les seuls à pouvoir le réparer.","story.map8-dungeon4.021":"Toi aussi, tu vois bien ce qui se passe, n\'est-ce pas ?","story.map8-dungeon4.022":"Au lieu d\'une république, le monde est dirigé par une organisation d\'Invocateurs.","story.map8-dungeon4.023":"Il y a bien longtemps, <wait=20>quelques-uns ont échappé au tragique affrontement avec les dieux.","story.map8-dungeon4.024":"Ils ont guidé le peuple et fondé l\'Empire de Randall.","story.map8-dungeon4.025":"Puis, <wait=20>longtemps après la fondation de l\'Empire...","story.map8-dungeon4.026":"...plusieurs groupes se sont formés en opposition à la classe privilégiée de l\'Empire de Randall.","story.map8-dungeon4.027":"Ils ont fondé la Fédération d\'Elgaia.","story.map8-dungeon4.028":"Plus récemment, c\'est Elgaia qui a commencé à changer la première.","story.map8-dungeon4.029":"Au cours de ce changement sont apparus les Invocateurs, <wait=20>ainsi que quelqu\'un qui souhaitait tous les rassembler.","story.map8-dungeon4.030":"Ils ont fondé le Hall des Invocateurs d\'Akras.","story.map8-dungeon4.031":"Les Invocateurs d\'antan qui ont mis sur pied le Hall des Invocateurs d\'Akras...","story.map8-dungeon4.032":"...aussi connus sous le nom d\'« Invocateurs originels », pour avoir été les premiers à franchir la porte...","story.map8-dungeon4.033":"...grâce aux formidables pouvoirs d\'invocation qu\'ils avaient acquis...","story.map8-dungeon4.034":"...ont formé l\'une des plus grandes organisations de tout Elgaia.","story.map8-dungeon4.035":"Grâce à l\'immense puissance des Invocateurs, cette organisation a peu à peu pris aussi le contrôle de l\'économie.","story.map8-dungeon4.036":"Avant que quiconque ne s\'en rende compte, la république n\'était plus que l\'ombre d\'elle-même.","story.map8-dungeon4.037":"Aujourd\'hui, l\'Empire de Randall comme la Fédération d\'Elgaia ne sont plus que des coquilles vides.","story.map8-dungeon4.038":"Hihi, <wait=40>ton expression me dit que tu l\'avais déjà compris.","story.map8-dungeon4.039":"Pourtant, <wait=40>cela ne semble pas te déranger.","story.map8-dungeon4.040":"Bien sûr, <wait=20>savoir qui contrôle quoi n\'a pas grand-chose à voir avec les gens ordinaires.","story.map8-dungeon4.041":"Mais il ne faut pas prendre le monde à la légère.","story.map8-dungeon4.042":"Je me demande si tu resterais aux côtés du Hall des Invocateurs si tu connaissais sa face cachée.","story.map8-dungeon4.043":"Si tu promets de te ranger à nos côtés dès maintenant, je te dirai tout.","story.map8-dungeon4.044":"Hihi, <wait=20>mais rien ne presse.","story.map8-dungeon4.045":"Car quoi qu\'il arrive, une fois que j\'aurai mis la main sur le pouvoir caché ici...","story.map8-dungeon4.046":"...tu n\'auras d\'autre choix que de nous suivre sur notre juste voie.","story.map8-dungeon4.047":"......","story.map8-dungeon4.048":"Bien, <wait=40>je dois y aller.","story.map8-dungeon4.049":"J\'ai hâte de reparler avec toi, sans être interrompue par cet idiot vulgaire.","story.map8-dungeon5.001":"<rep_handlename>.","story.map8-dungeon5.002":"Hé, <wait=40>qu\'est-ce qui te prend tout à coup ?","story.map8-dungeon5.003":"Tu crois peut-être que tu étais plus fort que moi lors de notre dernier combat ?","story.map8-dungeon5.004":"On dirait que tu n\'as pas compris à quel point j\'y suis allé doucement avec toi.","story.map8-dungeon5.005":"Il semblerait que tu aies besoin qu\'on te le rappelle.","story.map8-dungeon5.006":"Hein ? <wait=40>Si je connais la face cachée du Hall des Invocateurs ?","story.map8-dungeon5.007":"Espèce d\'idiot, <wait=20>quelle histoire de fou tu as laissé cette femme te mettre dans la tête ?","story.map8-dungeon5.008":"Je t\'avais dit de ne pas écouter cette femme !","story.map8-dungeon5.009":"Et puis, ce que fait le Hall des Invocateurs ne nous regarde pas.","story.map8-dungeon5.010":"Au fond, tout ce qui compte vraiment, c\'est de savoir qui est le plus puissant d\'Elgaia.","story.map8-dungeon5.011":"Est-ce que ce sera la Fédération d\'Elgaia et ses foules enthousiastes ?","story.map8-dungeon5.012":"Ou l\'Empire de Randall et son armée archaïque ?","story.map8-dungeon5.013":"Ou peut-être ni l\'un ni l\'autre.","story.map8-dungeon5.014":"Mais moi, je pense que c\'est le Hall des Invocateurs d\'Akras le plus fort.","story.map8-dungeon5.015":"L\'élite du Hall des Invocateurs est l\'élite d\'Elgaia.","story.map8-dungeon5.016":"C\'est aussi simple que ça.","story.map8-dungeon5.017":"Et c\'est pour ça que je dois donner le meilleur de moi-même pour le Hall des Invocateurs.","story.map8-dungeon5.018":"Mais toi, à venir te mettre en travers de mon chemin alors que je suis déjà en plein boulot, tu commences vraiment à m\'agacer.","story.map8-dungeon5.019":"C\'est pour ça qu\'aujourd\'hui, je ne vais pas te ménager.","story.map8-dungeon5.020":"Je t\'attendrai plus loin.","story.map8-dungeon5.021":"<size=20>Je vais te montrer à quel point on est différents !</size>","story.map8-dungeon5.022":"<size=20>Prépare-toi bien !</size>","story.map8-dungeon6.001":"<rep_handlename>. <wait=40>Tu es donc venu.","story.map8-dungeon6.002":"Regarde. <wait=40>N\'est-ce pas incroyable ?","story.map8-dungeon6.003":"Il y a bien longtemps, c\'était le foyer de la République de La Veda, où le peuple priait le Dieu de la Lumière.","story.map8-dungeon6.004":"Pourtant, <wait=20>ce même peuple a été anéanti par le dieu même qu\'il priait.","story.map8-dungeon6.005":"Quel spectacle effroyable.","story.map8-dungeon6.006":"Il existe divers récits de la bataille contre les dieux.","story.map8-dungeon6.007":"Le premier et le plus important étant la légende des Six Héros.","story.map8-dungeon6.008":"Pourtant, <wait=20>beaucoup de choses restent inconnues.","story.map8-dungeon6.009":"En particulier, <wait=20>on sait peu de choses sur ce qui s\'est passé à Grand Gaia...","story.map8-dungeon6.010":"...après que Lucius a sauvé le peuple.","story.map8-dungeon6.011":"Que faisait donc Lucius...","story.map8-dungeon6.012":"...pendant que les Quatre Dieux déchus commettaient tant de cruautés ?","story.map8-dungeon6.013":"Et pourquoi le grand chef des dieux, Carna Masta, n\'a-t-il toujours rien fait ?","story.map8-dungeon6.014":"Hihi, <wait=20>quand on y pense, on finit vraiment par s\'inquiéter de notre sécurité.","story.map8-dungeon6.015":"Je...","story.map8-dungeon6.016":"Non, <wait=20>nous vivons dans la peur de la situation actuelle.","story.map8-dungeon6.017":"En des temps aussi incertains...","story.map8-dungeon6.018":"...qui sait quand les dieux pourraient de nouveau décider de tout détruire et prendre Elgaia pour cible ?","story.map8-dungeon6.019":"C\'est pourquoi nous devons mettre la main sur le grand pouvoir qui repose ici.","story.map8-dungeon6.020":"Le pouvoir qui reposerait sur la terre où, jadis, le peuple vénérait le Dieu de la Lumière.","story.map8-dungeon6.021":"Hihi, <wait=40>te revoilà avec cet air troublé.","story.map8-dungeon6.022":"Rien ne presse. <wait=40>Prends ton temps pour assimiler tout cela.","story.map8-dungeon6.023":"Mais <wait=20>j\'aimerais aussi que tu penses à l\'avenir.","story.map8-dungeon6.024":"Quelle est la juste voie pour créer un monde où les gens peuvent vivre en paix ?","story.map8-dungeon6.025":"Bien, <wait=20>je dois m\'en aller.","story.map8-dungeon6.026":"Oh, <wait=20>et encore une chose...","story.map8-dungeon6.027":"Il y a peu, j\'ai vu Lugina se diriger vers un pont noir un peu plus loin, l\'air très menaçant.","story.map8-dungeon6.028":"Sois prudent, d\'accord ?","story.map8-dungeon6.029":"Hihihi.","story.map8-dungeon7-2.001":"I-<wait=40>Impossible...","story.map8-dungeon7-2.002":"Comment ai-je pu perdre contre...","story.map8-dungeon7-2.003":"Nngh...","story.map8-dungeon7-2.004":"<size=18>Ce n\'est pas vrai...</size>","story.map8-dungeon7-2.005":"<size=24>Je refuse de l\'accepter !</size>","story.map8-dungeon7-2.006":"Il est hors de question que je perde contre toi !","story.map8-dungeon7-2.007":"Impossible...","story.map8-dungeon7-2.008":"<size=20>Non ! <wait=40>Non ! <wait=40>Non !","story.map8-dungeon7-2.009":"<size=18>Comment ai-je pu perdre...</size>","story.map8-dungeon7-2.010":"Pff, <wait=40>qu\'est-ce que tu regardes ?","story.map8-dungeon7-2.011":"Dégage d\'ici, maintenant !","story.map8-dungeon7-2.012":"<size=20>Maudit sois-tu !!</size>","story.map8-dungeon7-2.013":"Zut...","story.map8-dungeon7.001":"J\'en ai marre d\'attendre, <rep_handlename>.","story.map8-dungeon7.002":"J\'étais sûr que tu passerais par ici.","story.map8-dungeon7.003":"Ce que cette femme et moi cherchons se trouverait dans la tour juste devant.","story.map8-dungeon7.004":"<size=20>Argh !</size>","story.map8-dungeon7.005":"Encore cette tête agaçante !","story.map8-dungeon7.006":"Malgré ton air désintéressé, tu ne vaux pas mieux qu\'elle, avec ta curiosité qui me met des bâtons dans les roues.","story.map8-dungeon7.007":"Aussi ignorant que tu sois, tu comptes vraiment t\'en prendre à mon trophée ?","story.map8-dungeon7.008":"Tu commences vraiment à m\'énerver.","story.map8-dungeon7.009":"Cette mission, c\'est ma chance de montrer ma vraie puissance à ces vieux croûtons.","story.map8-dungeon7.010":"Je ne peux pas laisser un bleu comme toi se mettre en travers de mon chemin !","story.map8-dungeon7.011":"Je ne laisserai cet exploit à personne d\'autre !","story.map8-dungeon7.012":"J\'écraserai tous ceux qui se mettront en travers de mon chemin !","story.map8-dungeon7.013":"Nngh, <wait=20>c\'est quoi ce regard ? C\'est pas le moment d\'avoir peur !","story.map8-dungeon7.014":"Peu importe.","story.map8-dungeon7.015":"C\'est mon dernier avertissement.","story.map8-dungeon7.016":"La prochaine fois que je te croise...","story.map8-dungeon7.017":"<size=22>Ce sera ta fin !</size>","story.map8-dungeon7.018":"<size=22>Compris ?</size>","story.map8-dungeon8.001":"Nngh...","story.map8-dungeon8.002":"C\'est inattendu, <wait=20>je ne pensais pas que ce serait aussi dur.","story.map8-dungeon8.003":"Mais malgré tout, <wait=20>ce ne sont pas ces blessures insignifiantes qui vont me faire abandonner !","story.map8-dungeon8.004":"Je dois absolument trouver la porte pour Eriole.","story.map8-dungeon8.005":"Hé ! <wait=40><rep_handlename> !","story.map8-dungeon8.006":"Je n\'arrive pas à croire que tu m\'aies rattrapée.","story.map8-dungeon8.007":"Si tu es ici, c\'est que tu as réussi à vaincre Lugina, n\'est-ce pas ?","story.map8-dungeon8.008":"Il est peut-être un peu rustre, <wait=20>mais en tant que chef des Pourfendeurs de démons, il est plus que redoutable.","story.map8-dungeon8.009":"Tu dois vraiment être puissant pour avoir réussi à le vaincre.","story.map8-dungeon8.010":"Nngh...","story.map8-dungeon8.011":"Hihi, <wait=20>ces blessures ne sont rien, ne t\'inquiète pas.","story.map8-dungeon8.012":"J\'ai juste eu un léger contretemps.","story.map8-dungeon8.013":"Plus que jamais, mon objectif est d\'obtenir le pouvoir caché qui nous attend ici.","story.map8-dungeon8.014":"Je ne te laisserais même pas te mettre en travers de mon chemin.","story.map8-dungeon8.015":"Haha, <wait=40>quelle expression effrayante.","story.map8-dungeon8.016":"Mais malgré tout, <wait=20>je suis sérieuse.","story.map8-dungeon8.017":"Je crois que le pouvoir qui repose ici peut rendre au monde ce qu\'il devrait être.","story.map8-dungeon8.018":"Sais-tu ce qui nous attend ici ?","story.map8-dungeon8.019":"C\'est une tour qui existerait depuis avant même la fondation de La Veda.","story.map8-dungeon8.020":"La Veda a peut-être même été bâtie pour veiller sur cette tour.","story.map8-dungeon8.021":"Autrement dit, <wait=40>ce qui nous attend ici est d\'une importance capitale.","story.map8-dungeon8.022":"Il y a sans doute aussi d\'innombrables pièges installés pour le protéger.","story.map8-dungeon8.023":"Tu vois ce que je veux dire ?","story.map8-dungeon8.024":"Si oui, <wait=40>tu ferais mieux de ne pas aller plus loin.","story.map8-dungeon8.025":"Tu ne voudrais pas finir par m\'affronter, n\'est-ce pas ?","story.map8-dungeon8.026":"Hé hé hé.","story.map8-dungeon8.027":"Je compte sur toi pour suivre mon conseil et faire demi-tour.","story.map8-dungeon8.028":"Bien, <wait=40>je m\'en vais.","story.map8-dungeon8.029":"Nous reparlerons une fois que j\'aurai accompli mon objectif.","story.map8-dungeon8.030":"Ne crois pas que j\'aie renoncé à te rallier à notre cause.","story.map8-dungeon8.031":"Hé hé hé.","story.map8-dungeon_ex_clear.001":"<size=18>*Bzz* </size><wait=20><size=20>*Bz</size><wait=10><size=19>zzzz* </size><wait=40><size=18>*Bzzzzzz*</size>","story.map8-dungeon_ex_clear.002":"Monsieur ! <wait=40>Tu vas bien ?","story.map8-dungeon_ex_clear.003":"*Soupir* <wait=20>Je suis soulagée.","story.map8-dungeon_ex_clear.004":"Après ton départ, des agents du Hall des Invocateurs ont poursuivi l\'enquête sur le lac souterrain.","story.map8-dungeon_ex_clear.005":"Il semble que le dieu Lagzal y reposait.","story.map8-dungeon_ex_clear.006":"Il est aussi apparu à Grand Gaia lors de la grande bataille entre les dieux et les humains.","story.map8-dungeon_ex_clear.007":"D\'après nos archives, il avait d\'abord été vaincu par un seul héros.","story.map8-dungeon_ex_clear.008":"Mais il semble qu\'il n\'ait pas été complètement détruit et qu\'il se soit plutôt réfugié ici.","story.map8-dungeon_ex_clear.009":"Mon cœur a fait un bond quand nous avons découvert cette information.","story.map8-dungeon_ex_clear.010":"Enfin, il a pris la vie de tant de gens au combat !","story.map8-dungeon_ex_clear.011":"J\'étais tellement inquiète quand j\'ai appris que tu allais l\'affronter...","story.map8-dungeon_ex_clear.012":"......","story.map8-dungeon_ex_clear.013":"C\'est trop tard pour t\'excuser !","story.map8-dungeon_ex_clear.014":"......","story.map8-dungeon_ex_clear.015":"*Soupir* <wait=40>Mais tu es un Invocateur, après tout.","story.map8-dungeon_ex_clear.016":"Désormais, tu vas enquêter dans des endroits de plus en plus dangereux.","story.map8-dungeon_ex_clear.017":"Si je veux vraiment te soutenir, je ne devrais pas essayer de t\'arrêter.","story.map8-dungeon_ex_clear.018":"Compris !","story.map8-dungeon_ex_clear.019":"Je crois en toi, monsieur !","story.map8-dungeon_ex_clear.020":"Et tu pourras toujours compter sur moi, monsieur !","story.map8-dungeon_ex_clear.021":"Hé hé hé.","story.map8-dungeon_ex_clear.022":"Bon, je te recontacterai si de nouvelles informations arrivent !","story.map8-dungeon_ex_clear.023":"D\'ici là, fais bien attention à toi !","story.map8-dungeon_ex_open.001":"<size=18>*Bzz* </size><wait=20><size=20>*Bz</size><wait=10><size=19>zzzz* </size><wait=40><size=18>*Bzzzzzz*</size>","story.map8-dungeon_ex_open.002":"Monsieur, <wait=40>tu m\'entends ?","story.map8-dungeon_ex_open.003":"Super, <wait=20>cette fois, je t\'ai eu du premier coup.","story.map8-dungeon_ex_open.004":"Lin Merylham, du Soutien logistique...","story.map8-dungeon_ex_open.005":"...du Bureau d\'enquête de l\'Office d\'exploration de Grand Gaia, à ton service.","story.map8-dungeon_ex_open.006":"<rep_handlename>, en tant que membre de l\'Armée des Invocateurs du Hall des Invocateurs d\'Akras...","story.map8-dungeon_ex_open.007":"...nous te demandons aujourd\'hui d\'enquêter sur le lac souterrain de Golzo !","story.map8-dungeon_ex_open.008":"Il y a quelques jours, le Hall des Invocateurs a perçu la disparition d\'une grande puissance en Lizeria.","story.map8-dungeon_ex_open.009":"Juste après, nous avons perçu une puissance encore plus grande ici, dans ce lac souterrain.","story.map8-dungeon_ex_open.010":"Nous aimerions que tu enquêtes sur ce qui se passe exactement ici.","story.map8-dungeon_ex_open.011":"Personnellement, j\'ai un très mauvais pressentiment, alors si tu préfères refuser, ce n\'est pas grave...","story.map8-dungeon_ex_open.012":"...mais le ton de ta voix dit le contraire.","story.map8-dungeon_ex_open.013":"Toujours aussi plein d\'ambition !","story.map8-dungeon_ex_open.014":"Compris !","story.map8-dungeon_ex_open.015":"J\'ai beau m\'inquiéter, je vais t\'encourager comme toujours !","story.map8-dungeon_ex_open.016":"Alors s\'il te plaît, <wait=40>reviens-moi en un seul morceau !","story.map8-dungeon_ex_open.017":"C\'est compris ?","story.map8-dungeon_ex_open.018":"Hmpf...","story.map8-ending.001":"Avoir démoli un système de défense pareil...","story.map8-ending.002":"Je suppose que c\'est la puissance qu\'on peut attendre de quelqu\'un qui a vaincu un Dieu déchu.","story.map8-ending.003":"Mais malgré tout, <wait=20>il est hors de question que je renonce à ce qui est scellé derrière la porte devant nous !","story.map8-ending.004":"Regarde-toi, <rep_handlename>.","story.map8-ending.005":"Tu n\'es même pas si gravement blessé, et pourtant tu ne peux toujours pas bouger ?","story.map8-ending.006":"Tss, <wait=40>ça m\'énerve au plus haut point de penser que j\'ai eu autant de mal avec toi.","story.map8-ending.007":"Hein ? <wait=40>Comment ça, me dépêcher d\'avancer ?","story.map8-ending.008":"Heh, <wait=20>on ne t\'a rien dit, hein ?","story.map8-ending.009":"Viens avec moi.","story.map8-ending.010":"Allons voir dans quel pétrin intéressant cette femme s\'est fourrée.","story.map8-ending.011":"A-<wait=20>Attendez. <wait=20>Comment peut-il n\'y avoir rien ?","story.map8-ending.012":"Est-ce que ça veut dire qu\'on nous a trompés ?","story.map8-ending.013":"Comment avons-nous pu être...","story.map8-ending.014":"Qu\'y a-t-il à gagner à nous mener ainsi en bateau ?","story.map8-ending.015":"Hé, <rep_handlename> ! <wait=40>Regarde !","story.map8-ending.016":"C\'est exactement ce que je disais.","story.map8-ending.017":"La petite Garde impériale a l\'air d\'avoir quelques ennuis.","story.map8-ending.018":"Lugina...","story.map8-ending.019":"Hé hé hé. <wait=40>Arrête de faire ces têtes effrayantes.","story.map8-ending.020":"Le pouvoir que tu cherches n\'est nulle part par ici.","story.map8-ending.021":"Il se trouve dans les ruines de la porte.","story.map8-ending.022":"Je le sais parce que les Invocateurs Anciens m\'ont envoyé enquêter dessus.","story.map8-ending.023":"Cela dit, j\'ai bien aimé écouter ton bavardage enflammé.","story.map8-ending.024":"Espèce d\'imbécile vulgaire.","story.map8-ending.025":"<size=20>Bwa ha ha ha !</size>","story.map8-ending.026":"Tu peux me fusiller du regard autant que tu veux, la porte ne s\'ouvrira pas.","story.map8-ending.027":"Nngh...","story.map8-ending.028":"<rep_handlename>.","story.map8-ending.029":"Comment peux-tu supporter un homme aussi vulgaire depuis si longtemps ?","story.map8-ending.030":"Tu vois ce que je veux dire, n\'est-ce pas ?","story.map8-ending.031":"Cet homme est une véritable ordure !","story.map8-ending.032":"J\'attends simplement le jour où tu accepteras mon invitation.","story.map8-ending.033":"Ooh, <wait=20>je suis tellement jaloux ! <wait=40>Moi aussi, je voulais être invité, tu sais !","story.map8-ending.034":"Même si ce serait dommage de perdre mon temps avec ta cause stérile.","story.map8-ending.035":"Nngh.","story.map8-ending.036":"Souviens-toi de ça.","story.map8-ending.037":"Un jour, je te ferai regretter tout ce que tu as fait.","story.map8-ending.038":"Heh, <wait=20>elle est enfin partie.","story.map8-ending.039":"Hé, <rep_handlename>.","story.map8-ending.040":"Pourquoi tu as l\'air si calme tout à coup ?","story.map8-ending.041":"Tu ne crois quand même pas que je t\'ai pardonné, si ?","story.map8-ending.042":"Je vais devenir encore plus puissant qu\'avant.","story.map8-ending.043":"Et une fois que ce sera fait, je vais me servir de toi autant que possible.","story.map8-ending.044":"Ne l\'oublie pas !","story.map8-ending.045":"Heh.","story.map8-ending.046":"Oh, <wait=20>et encore une chose...","story.map8-ending.047":"On dirait que tu n\'avais vraiment aucune idée de ce qu\'on cherchait cette fois.","story.map8-ending.048":"Au début, je pensais que tu essayais juste de me piéger pour prendre l\'avantage sur moi.","story.map8-ending.049":"Mais au final, il semble que tu étais aussi bête que tu en avais l\'air !","story.map8-ending.050":"<size=20>Bwa ha ha ha !</size>","story.map8-ending.051":"Le prochain exploit sera le mien.","story.map8-ending.052":"Et tu as intérêt à être reconnaissant pour tout ce que moi, l\'Invocateur le plus incroyablement puissant au monde, j\'ai fait pour toi !","story.map8-ending.053":"Je vois, <wait=20>la porte a donc disparu.","story.map8-ending.054":"Ce n\'est rien. <wait=20>Inutile de t\'excuser.","story.map8-ending.055":"Tu as fait de ton mieux avec une tâche difficile.","story.map8-ending.056":"Oui, <wait=20>prends soin de toi et reviens sain et sauf.","story.map8-ending.057":"Hé hé hé.","story.map8-ending.058":"Il semble que tout s\'est passé exactement comme vous l\'aviez dit.","story.map8-ending.059":"Il semble que le contrat soit rempli.","story.map8-ending.060":"Il est temps pour nous aussi de nous mettre en route.","story.map8-ending.061":"Oui, <wait=40>mon maître attend lui aussi votre déploiement.","story.map8-ending.062":"Hé hé hé.","story.map8-ending.063":"<size=20>Rendons au monde sa véritable forme !</size>","story.map8-ending.064":"<size=20>Nous le verrons changer et évoluer sous nos yeux !</size>","story.map8-ending.065":"<size=20>Attendez et vous verrez !</size>","story.map8-ending.066":"<size=20>Bientôt, un nouveau héros va naître !</size>","story.map8-open.001":"Randall,<wait=40> capitale de l\'Empire de Randall.","story.map8-open.002":"Les appartements privés des gardes du corps de la famille impériale, <wait=40>la Garde impériale.","story.map8-open.003":"*Toc* <wait=20>*toc*","story.map8-open.004":"Entrez.","story.map8-open.005":"Excusez-moi de vous déranger.","story.map8-open.006":"Oh, <wait=40> quel air réjoui. <wait=20>Je suppose que tu m\'apportes de bonnes nouvelles ?","story.map8-open.007":"Oui, <wait=20>et je m\'excuse d\'avoir mis autant de temps.","story.map8-open.008":"Notre enquête nous porte à croire que la porte que nous cherchons se trouve en Lizeria.","story.map8-open.009":"...Lizeria.","story.map8-open.010":"Si je me souviens bien, La Veda aurait existé là-bas autrefois.","story.map8-open.011":"Je vois. <wait=20>On ne nous a donc pas menti, finalement.","story.map8-open.012":"C\'est exact.","story.map8-open.013":"Je doute que toutes les informations reçues soient exactes, mais je pense que celle-ci l\'est.","story.map8-open.014":"......","story.map8-open.015":"J\'aimerais m\'y rendre pour le vérifier par moi-même.","story.map8-open.016":"Puis-je en avoir la permission ?","story.map8-open.017":"À ma connaissance, l\'Armée des Invocateurs a lancé une nouvelle enquête dans cette région.","story.map8-open.018":"Compris. <wait=40>Je ferai de mon mieux pour terminer au plus vite.","story.map8-open.019":"C\'est une entreprise très dangereuse, tu sais ?","story.map8-open.020":"Je suis prête à me sacrifier pour une paix véritable.","story.map8-open.021":"Je compte sur toi.","story.map8-open.022":"Inutile de dire de telles choses.","story.map8-open.023":"Je veillerai à ce que tout soit réglé !","story.map8-open.024":"Bonne chance.","story.map8-open.025":"Qui est là !?","story.map8-open.026":"On dirait que tu as quelque chose à dire.","story.map8-open.027":"Tu écoutais ? <wait=40>Pourquoi ne te montres-tu pas ?","story.map8-open.028":"......","story.map8-open.029":"Je vois. <wait=40>Tu n\'as même pas besoin de le dire.","story.map8-open.030":"Il n\'y a pas de temps à perdre. <wait=20>Nous devons rendre au monde sa forme véritable.","story.map8-open.031":"Je me demande si cette bande de l\'Armée des Invocateurs finira un jour par comprendre...","story.map8-open.032":"...ce que ce monde était vraiment censé être.","story.map9-dungeon1.001":"Hé, <wait=20><rep_handlename> !","story.map9-dungeon1.002":"Alors toi aussi, tu es venu à Ryvern, <wait=20>porte d\'entrée de la région d\'Agni. ","story.map9-dungeon1.003":"Je suppose que tu pourchasses Zevalhua, <wait=20>le prochain des Dieux déchus. ","story.map9-dungeon1.004":"Bien sûr, on va encore t\'aider cette fois, alors il ne devrait pas y avoir de problème !","story.map9-dungeon1.005":"Karl ! <wait=40>On a nos propres objectifs, tu te souviens !?","story.map9-dungeon1.006":"Je n\'ai aucune envie d\'aider <rep_handlename>, <wait=20>d\'autant que le Hall des Invocateurs ne nous l\'a même pas demandé.","story.map9-dungeon1.007":"Haha, <wait=20>toujours la même, hein, Seria.","story.map9-dungeon1.008":"<rep_handlename> a déjà vaincu deux des Quatre Dieux déchus. ","story.map9-dungeon1.009":"Tu ne crois pas que tu devrais au moins le reconnaître ?","story.map9-dungeon1.010":"Hmph, <wait=20>je reconnais la puissance qu\'il a fallu.","story.map9-dungeon1.011":"Mais regarde-moi cet air suffisant !","story.map9-dungeon1.012":"Je préviens, <wait=20>c\'est tout !","story.map9-dungeon1.013":"<rep_handlename> ! <wait=20>Tu devrais m\'être reconnaissant !","story.map9-dungeon1.014":"Ah ! <wait=20>Te voilà !","story.map9-dungeon1.015":"<rep_handlename> ! <wait=20>Pourquoi tu as mis autant de temps ?","story.map9-dungeon1.016":"Oh, <wait=20>Karl et Seria !","story.map9-dungeon1.017":"Salut, <wait=20>Déesse.","story.map9-dungeon1.018":"Elle est venue, finalement...","story.map9-dungeon1.019":"Hé, vous deux !","story.map9-dungeon1.020":"Vous allez tous les deux aider <rep_handlename> cette fois encore, hein ?","story.map9-dungeon1.021":"Nous, on poursuit Graham !","story.map9-dungeon1.022":"Ne t\'en fais pas pour ça maintenant.","story.map9-dungeon1.023":"De toute façon, il va sûrement s\'échapper, <wait=20>alors pourquoi ne pas aider dès le début, cette fois ?","story.map9-dungeon1.024":"C\'est plutôt méchant de dire ça.","story.map9-dungeon1.025":"Espèce de... !","story.map9-dungeon1.026":"C\'est tellement amusant de partir à l\'aventure comme ça avec vous tous.","story.map9-dungeon1.027":"J\'ai l\'impression que peu importe la difficulté du combat, on finira toujours par s\'en sortir, pas vous ?","story.map9-dungeon1.028":"Haha, <wait=20>si la Déesse le dit, on n\'a pas vraiment le choix.","story.map9-dungeon1.029":"Pas vrai, <wait=20>Seria ?","story.map9-dungeon1.030":"Tu te laisses vraiment faire, Karl...","story.map9-dungeon1.031":"Enfin, <wait=20>je suis sûre que Lord Grahdens nous le demandera de toute façon, alors je suppose qu\'on peut aider. ","story.map9-dungeon1.032":"T\'es adorable, finalement, Seria !","story.map9-dungeon1.033":"Qu-<wait=20>Qu\'est-ce qui te prend !","story.map9-dungeon1.034":"Je n\'aide que parce qu\'on n\'a pas le choix.","story.map9-dungeon1.035":"Ha ha ha. <wait=20>On dirait que c\'est décidé.","story.map9-dungeon1.036":"Cela dit, on est tous dans le même bateau, <rep_handlename> !","story.map9-dungeon1.037":"Donnons tout ce qu\'on a et mettons une raclée à ce Zevalhua !","story.map9-dungeon1.038":"Super ! <wait=40>Faites de votre mieux, tout le monde !","story.map9-dungeon1.039":"*Soupir* <wait=20>Je ne sais toujours pas trop...","story.map9-dungeon1.040":"Hmm. <wait=40>Quel pathétique spectacle...","story.map9-dungeon2.001":"Hé, <rep_handlename>. <wait=40>Tu es un peu en retard. ","story.map9-dungeon2.002":"La Déesse était là il y a une seconde.","story.map9-dungeon2.003":"Ensuite, elle s\'est disputée avec Seria, <wait=20>puis elles sont parties devant toutes les deux. ","story.map9-dungeon2.004":"Ha ha ha. <wait=40>Ces deux-là, <wait=40>elles se sont vraiment rapprochées, hein ?","story.map9-dungeon2.005":"Entraidons-nous pour ne pas nous faire distancer !","story.map9-dungeon2.006":"Vous, les humains, êtes vraiment des êtres pathétiques.","story.map9-dungeon2.007":"Qui est là ?","story.map9-dungeon2.008":"Inutile d\'avoir peur.","story.map9-dungeon2.009":"Mon nom est Mare.","story.map9-dungeon2.010":"Je suis la disciple de Zevalhua le Suprême.","story.map9-dungeon2.011":"Une disciple de Zevalhua ?","story.map9-dungeon2.012":"Alors tu es venue nous tuer ? ","story.map9-dungeon2.013":"Quelle insolence de parler ainsi de Lord Zevalhua...","story.map9-dungeon2.014":"Ce n\'est qu\'un signe de plus de votre ignorance. Quelle tristesse...","story.map9-dungeon2.015":"Toutefois, ne vous méprenez pas.","story.map9-dungeon2.016":"En finir avec vous deux ne vaut pas que j\'y engage mon nom.","story.map9-dungeon2.017":"Mon but n\'est pas toi, Invocateur, <wait=40>mais celui aux cheveux bleus. <wait=40>C\'est toi que je veux.","story.map9-dungeon2.018":"C\'est moi, ta cible ?","story.map9-dungeon2.019":"Qu\'est-ce que tu me veux ?","story.map9-dungeon2.020":"J\'ai pensé jouer le rôle d\'un dieu en te révélant la vérité. ","story.map9-dungeon2.021":"La vérité ?","story.map9-dungeon2.022":"Tu t\'es laissé tromper par ce fou de Grahdens, et maintenant ta vie est sens dessus dessous.","story.map9-dungeon2.023":"Espèce de... <wait=60>Qu\'est-ce que tu manigances, au juste ?","story.map9-dungeon2.024":"Inutile de te méfier. ","story.map9-dungeon2.025":"Ce sont tes aînés qui t\'ont confié à quelqu\'un d\'autre peu après t\'avoir trouvé.","story.map9-dungeon2.026":"Tu as eu une enfance triste, sans jamais connaître la chaleur d\'un parent.","story.map9-dungeon2.027":"C\'est pourquoi à toi, qui as été recueilli par ces vieillards irresponsables...","story.map9-dungeon2.028":"...moi, déesse de la compassion, je vais dire la vérité.","story.map9-dungeon2.029":"Arrête de te moquer de moi !","story.map9-dungeon2.030":"Qu\'est-ce que tu peux bien savoir de l\'Ancien Grahdens !","story.map9-dungeon2.031":"En tant qu\'Invocateur Ancien, il était toujours très occupé...","story.map9-dungeon2.032":"...Mais il a toujours pris soin de moi !","story.map9-dungeon2.033":"Il n\'a rien à voir avec la personne que tu décris, disciple d\'un Dieu déchu !","story.map9-dungeon2.034":"Tu manies les mots aussi habilement que Grahdens. ","story.map9-dungeon2.035":"On dirait qu\'il t\'a bien lavé le cerveau. ","story.map9-dungeon2.036":"Tais-toi ! <wait=40>Je ne te laisserai pas dire un mot de plus contre lui !","story.map9-dungeon2.037":"Tu n\'es qu\'un idiot ignorant et stupide.","story.map9-dungeon2.038":"Je vais te montrer la voie.","story.map9-dungeon2.039":"Je t\'attendrai dans les Ruines d\'Azura, juste devant. ","story.map9-dungeon2.040":"Viens seul si tu veux connaître la vérité.","story.map9-dungeon2.041":"<rep_handlename>, <wait=40>je dois tout à l\'Ancien Grahdens.","story.map9-dungeon2.042":"Il est peut-être un peu bizarre, mais c\'est quelqu\'un de confiance et il compte énormément pour moi !","story.map9-dungeon2.043":"Je ne peux pas pardonner ce qu\'elle a dit sur lui. ","story.map9-dungeon2.044":"Désolé, mais tu vas devoir continuer sans moi.","story.map9-dungeon2.045":"Je vais aux Ruines d\'Azura pour l\'affronter.","story.map9-dungeon2.046":"Je te laisse Zevalhua !","story.map9-dungeon2.047":"Je t\'en supplie, <rep_handlename>, <wait=20>compte sur toi !","story.map9-dungeon3.001":"<rep_handlename> !","story.map9-dungeon3.002":"Tu as vu Karl ?","story.map9-dungeon3.003":"Il m\'a dit de partir devant quand on était à Khelne, <wait=20>alors je l\'ai fait, mais...","story.map9-dungeon3.004":"Il avait l\'air calme, <wait=20>mais je crois qu\'il était vraiment bouleversé. ","story.map9-dungeon3.005":"Je ne l\'avais jamais vu aussi bouleversé.","story.map9-dungeon3.006":"Hein ? <wait=40>Une disciple de Zevalhua est apparue en parlant de lui et de Lord Grahdens ?","story.map9-dungeon3.007":"Je vois.","story.map9-dungeon3.008":"Lord Grahdens est quelqu\'un de très important pour Karl.","story.map9-dungeon3.009":"Vous êtes amis depuis l\'enfance, non ? <wait=40>Tu connais toute l\'histoire, pas vrai ?","story.map9-dungeon3.010":"Quand même, <wait=40>Karl n\'aime vraiment pas parler de lui, hein...","story.map9-dungeon3.011":"S\'il nous disait simplement ce qui se passe, <wait=20>on pourrait peut-être l\'aider.","story.map9-dungeon3.012":"Bref, <wait=20>dépêchons-nous d\'aller aux Ruines d\'Azura !","story.map9-dungeon3.013":"Je suis sûre que Karl va bien, mais je ne peux pas m\'empêcher de m\'inquiéter.","story.map9-dungeon3.014":"Tu es bien prévenante <wait=40>pour le vermisseau que tu es.","story.map9-dungeon3.015":"Il est déjà des nôtres.","story.map9-dungeon3.016":"Il ne reviendra plus vers vous. ","story.map9-dungeon3.017":"Alors c\'est toi, Mare !","story.map9-dungeon3.018":"Humains stupides. <wait=40>Avez-vous peur de voir la vérité ?","story.map9-dungeon3.019":"Si c\'est le cas, vous devriez venir aussi.","story.map9-dungeon3.020":"Vous devriez le voir, maintenant qu\'il a accepté la vérité.","story.map9-dungeon3.021":"Ça suffit !","story.map9-dungeon3.022":"Tilith !","story.map9-dungeon3.023":"Héhé, <wait=20>c\'est la première fois que tu m\'appelles par mon nom.","story.map9-dungeon3.024":"I-<wait=20>Idiote ! <wait=40>Ce n\'est pas le moment !","story.map9-dungeon3.025":"Tu as raison. <wait=20>Il faut faire quelque chose contre Mare.","story.map9-dungeon3.026":"Qu\'est-ce qu\'une divinité de bas étage comme toi me veut ?","story.map9-dungeon3.027":"C\'est méchant !","story.map9-dungeon3.028":"Je suis la merveilleuse disciple de Lord Lucius, tu sais !","story.map9-dungeon3.029":"Encore une chose, Seria. <wait=20>Ne te laisse pas berner.","story.map9-dungeon3.030":"Mare est douée pour troubler le cœur des autres. ","story.map9-dungeon3.031":"Il y a très peu de vérité dans ce qu\'elle dit.","story.map9-dungeon3.032":"Es-tu capable de distinguer le vrai du faux ?","story.map9-dungeon3.033":"Toi <wait=20>qui suis aveuglément chaque parole de Lucius, <wait=20>prêtant tes pouvoirs aux humains et ainsi de suite.","story.map9-dungeon3.034":"Tu insinues que Lord Lucius a tort ?","story.map9-dungeon3.035":"Peu importe. <wait=40>On n\'y peut rien avec des divinités aussi stupides. ","story.map9-dungeon3.036":"C\'est de toi que je parle, tu sais.","story.map9-dungeon3.037":"Si tu veux connaître la vérité, il te suffit de croire ce que je dis.","story.map9-dungeon3.038":"Et ainsi, tu pourras revoir cet homme. ","story.map9-dungeon3.039":"Attends une seconde !","story.map9-dungeon3.040":"Pff ! <wait=40>Elle est aussi désagréable qu\'on me l\'avait dit !","story.map9-dungeon3.041":"Seria ! <wait=20>Je suis sûre que Karl va bien !","story.map9-dungeon3.042":"Alors ne fais rien d\'irréfléchi !","story.map9-dungeon3.043":"Je sais. <wait=40>Ça va, maintenant.","story.map9-dungeon3.044":"Mais je m\'inquiète quand même pour Karl.","story.map9-dungeon3.045":"Je sais que c\'est peut-être un piège...","story.map9-dungeon3.046":"...mais Karl est sûrement en route là-bas en ce moment.","story.map9-dungeon3.047":"<rep_handlename>, je veux que tu fasses le plus de grabuge possible par ici.","story.map9-dungeon3.048":"J\'ai besoin d\'une diversion pour rejoindre Karl au plus vite. ","story.map9-dungeon3.049":"Ouais, <wait=20>t\'as vraiment l\'air d\'aller bien !","story.map9-dungeon3.050":"Même ta façon de faire semblant de malmener <rep_handlename> te va bien !","story.map9-dungeon3.051":"Je ne fais semblant de rien du tout !","story.map9-dungeon3.052":"*Soupir* <wait=40>Bref, assez parlé de ça.","story.map9-dungeon3.053":"Tilith, <wait=20>protège <rep_handlename> pour moi.","story.map9-dungeon3.054":"Qui sait ce que cette disciple, Mare, pourrait tenter.","story.map9-dungeon3.055":"Je l\'imagine mal laisser tranquille quelqu\'un qui a déjà vaincu deux des Quatre Dieux déchus.","story.map9-dungeon3.056":"Compris. <wait=40>Mais <wait=20>ne fais rien d\'imprudent, s\'il te plaît.","story.map9-dungeon3.057":"Ne t\'en fais pas pour moi.","story.map9-dungeon3.058":"Je ne suis pas faible au point qu\'une déesse idiote comme toi doive s\'inquiéter pour moi.","story.map9-dungeon3.059":"Toujours aussi peu modeste, à ce que je vois, Seria !","story.map9-dungeon3.060":"Héhé, <wait=40>bref, j\'y vais.","story.map9-dungeon3.061":"<rep_handlename>, <wait=40>prends bien soin de toi aussi, d\'accord ?","story.map9-dungeon4.001":"<rep_handlename>...","story.map9-dungeon4.002":"Je suis désolée...","story.map9-dungeon4.003":"Mare...<wait=20> Elle nous a piégés...","story.map9-dungeon4.004":"Seria ! <wait=40>Ça va ?","story.map9-dungeon4.005":"Je vais...<wait=40>bien...","story.map9-dungeon4.006":"Mais...<wait=20>Karl est...","story.map9-dungeon4.007":"Ne force pas !","story.map9-dungeon4.008":"Mare...<wait=20>et Karl étaient...<wait=20>à égalité...","story.map9-dungeon4.009":"J\'ai voulu aider...","story.map9-dungeon4.010":"Mais <wait=40>on dirait que c\'était...<wait=20>exactement ce qu\'elle voulait...","story.map9-dungeon4.011":"Au moment où je me suis concentrée sur elle...","story.map9-dungeon4.012":"Elle a appelé ses sbires qui se cachaient. <wait=20>Ils m\'ont tous attaquée en même temps...","story.map9-dungeon4.013":"Et alors que j\'essayais d\'esquiver leurs attaques...<wait=20>Mare m\'a attaquée par derrière...","story.map9-dungeon4.014":"Karl...<wait=20>m\'a protégée <wait=20>de son attaque...","story.map9-dungeon4.015":"Puis, <wait=20>alors que j\'essayais de protéger Karl après sa chute, <wait=20>voilà ce qui est arrivé...","story.map9-dungeon4.016":"Seria...","story.map9-dungeon4.017":"Elle m\'a dit...","story.map9-dungeon4.018":"« Je te laisse en vie comme message pour <rep_handlename>...","story.map9-dungeon4.019":"...C\'est la seule raison pour laquelle je t\'épargne. »","story.map9-dungeon4.020":"J\'ai été si stupide !","story.map9-dungeon4.021":"Non seulement je suis tombée dans son piège, mais maintenant ça. <wait=20>Comment vivre avec une telle honte ? ","story.map9-dungeon4.022":"Moi, je suis quand même contente d\'entendre ça.","story.map9-dungeon4.023":"Contente de quoi !","story.map9-dungeon4.024":"Tu es vivante, non ? <wait=20>Je suis juste contente que tu sois encore là.","story.map9-dungeon4.025":"Tilith...","story.map9-dungeon4.026":"Et si Karl a été capturé, <wait=20>ça veut dire qu\'il est encore en vie, lui aussi !","story.map9-dungeon4.027":"Mon <rep_handlename> pourra sûrement le sauver !","story.map9-dungeon4.028":"Je n\'aime pas ta façon de dire « mon » <rep_handlename>, <wait=20>ni ta confiance aveugle...","story.map9-dungeon4.029":"Mais...<wait=20>tu as raison...","story.map9-dungeon4.030":"On dirait que Karl est retenu dans un endroit appelé la Tour blanche. ","story.map9-dungeon4.031":"Mare a dit qu\'elle t\'y attendrait.","story.map9-dungeon4.032":"C\'est sans aucun doute un piège.","story.map9-dungeon4.033":"Mais malgré tout, je t\'en supplie, essaie.","story.map9-dungeon4.034":"<size=20><rep_handlename>, <wait=40>sauve Karl !</size>","story.map9-dungeon4.035":"Hmph, <wait=20>c\'est quoi, ce hochement de tête l\'air de rien ?","story.map9-dungeon4.036":"Tu serais allé le sauver même si je n\'avais rien dit, pas vrai ?","story.map9-dungeon4.037":"Nngh...","story.map9-dungeon4.038":"Seria ! <wait=20>Ne force pas !","story.map9-dungeon4.039":"<rep_handlename> ! <wait=40>Laisse-moi m\'occuper de Seria !","story.map9-dungeon4.040":"Je vais la ramener saine et sauve à Elgaia. ","story.map9-dungeon4.041":"Alors s\'il te plaît, <rep_handlename>, <wait=20>va sauver Karl.","story.map9-dungeon4.042":"Seria et moi, <wait=20>on croit en toi, <rep_handlename>.","story.map9-dungeon4.043":"Moi, je ne crois pas forcément en toi...","story.map9-dungeon4.044":"Seria, <wait=20>ça va.","story.map9-dungeon4.045":"Mon <rep_handlename> est le plus fort de tous !","story.map9-dungeon4.046":"Qui tu appelles « mon » ?","story.map9-dungeon4.047":"Bah, <wait=40>peu importe...","story.map9-dungeon4.048":"<rep_handlename>...","story.map9-dungeon4.049":"S\'il te plaît...<wait=40>ramène-moi Karl...","story.map9-dungeon5.001":"<rep_handlename>. <wait=40>Je t\'attendais.","story.map9-dungeon5.002":"Je pensais bien que tu passerais par ici en route vers la Tour blanche.","story.map9-dungeon5.003":"La Tour blanche se trouve de l\'autre côté des Monts Ryvern, <wait=20>juste à la sortie de la grotte. ","story.map9-dungeon5.004":"Je doute que ce soit facile à traverser, même avec tes talents.","story.map9-dungeon5.005":"Cependant, <wait=20>n\'aie crainte. ","story.map9-dungeon5.006":"Je sauverai le jeune Karl.","story.map9-dungeon5.007":"C\'est mon fils bien-aimé, après tout. ","story.map9-dungeon5.008":"Ho ho ho. <wait=40>Pourquoi cet air dubitatif ?","story.map9-dungeon5.009":"Je ne sais pas ce que cette disciple, Mare, a raconté.","story.map9-dungeon5.010":"Mais c\'est moi qui ai recueilli ce bébé abandonné et l\'ai élevé comme mon propre fils.","story.map9-dungeon5.011":"Cela dit, <wait=20>c\'est vrai que j\'ai fini par le confier à une connaissance de confiance. ","story.map9-dungeon5.012":"La vie d\'un Invocateur Ancien est tout simplement trop mouvementée.","story.map9-dungeon5.013":"Mais tu connais la suite de l\'histoire, n\'est-ce pas ?","story.map9-dungeon5.014":"Je te remercie d\'avoir toujours joué avec Karl quand vous étiez enfants. ","story.map9-dungeon5.015":"Ho ho ho.","story.map9-dungeon5.016":"Pourtant, si occupé que je sois...","story.map9-dungeon5.017":"...je ne l\'aurais jamais simplement laissé à quelqu\'un d\'autre.","story.map9-dungeon5.018":"Je m\'éclipsais de temps en temps, sans que personne ne le remarque, pour aller le voir. ","story.map9-dungeon5.019":"J\'aurais eu bien des ennuis si quelqu\'un avait su que moi, un Invocateur Ancien, j\'avais un enfant.","story.map9-dungeon5.020":"Pourtant, <wait=20>malgré toutes ces cachotteries, il m\'a quand même accepté.","story.map9-dungeon5.021":"Ho ho ho. <wait=40>Que de souvenirs.","story.map9-dungeon5.022":"Bien, <wait=20>je suppose que je devrais me mettre en route.","story.map9-dungeon5.023":"Retrouver un enfant perdu est la responsabilité de ses parents.","story.map9-dungeon5.024":"Et puis, <wait=20>je dois punir celle qui a osé tromper mon cher fils.","story.map9-dungeon5.025":"Ho ho ho. <wait=20>N\'aie crainte.","story.map9-dungeon5.026":"J\'ai peut-être vieilli, <wait=20>mais je suis sans doute encore bien plus fort que n\'importe lequel d\'entre vous.","story.map9-dungeon5.027":"De plus, <wait=20>même s\'il devait m\'arriver quelque chose...","story.map9-dungeon5.028":"...j\'ai demandé aux autres Invocateurs Anciens de veiller sur vous tous. ","story.map9-dungeon5.029":"Ho ho ho. <wait=40>Je suis peut-être trop prudent ?","story.map9-dungeon5.030":"N\'aie crainte, et va affronter Zevalhua.","story.map9-dungeon5.031":"Je suis sûr que Karl ne veut pas te retarder non plus.","story.map9-dungeon5.032":"Mais malgré tout, tu comptes quand même aller à la Tour blanche, n\'est-ce pas ?","story.map9-dungeon5.033":"Karl a vraiment de bons amis. ","story.map9-dungeon5.034":"Bien, <wait=20>je vais sauver Karl, puis je t\'attendrai à la Tour blanche. ","story.map9-dungeon5.035":"Ho ho ho.","story.map9-dungeon6.001":"On dirait qu\'il n\'en reste plus qu\'un. ","story.map9-dungeon6.002":"Vous, les humains, êtes vraiment des êtres stupides, semble-t-il. ","story.map9-dungeon6.003":"Je vais te détruire, comme j\'ai détruit le reste de ces guerriers stupides.","story.map9-dungeon6.004":"<size=20>Je ne te laisserai pas faire !</size>","story.map9-dungeon6.005":"Je protégerai <rep_handlename> !","story.map9-dungeon6.006":"C\'est toi...","story.map9-dungeon6.007":"Tu es revenue bien plus tôt que je ne le pensais.","story.map9-dungeon6.008":"Je te traiterais bien d\'idiote, <wait=20>mais que pouvais-je attendre d\'autre d\'une disciple de Lucius ?","story.map9-dungeon6.009":"Enfin...","story.map9-dungeon6.010":"Invocateur, <wait=40>je t\'attendrai à la Tour blanche.","story.map9-dungeon6.011":"Ton ami sera aussi avec moi.","story.map9-dungeon6.012":"<rep_handlename>, ça va ?","story.map9-dungeon6.013":"Si tu t\'inquiètes pour Seria, ce n\'est pas la peine.","story.map9-dungeon6.014":"Je l\'ai ramenée saine et sauve à Elgaia, et elle se repose tranquillement au Hall des Invocateurs. ","story.map9-dungeon6.015":"Alors, <wait=20>allons sauver Karl ensemble !","story.map9-dungeon6.016":"Toi et moi, on peut y arriver, <wait=20>peu importe le nombre de pièges que Mare tend !","story.map9-dungeon6.017":"Aucun ennemi ne peut nous battre tant qu\'on est ensemble !","story.map9-dungeon6.018":"Karl ! Tiens bon encore un peu !","story.map9-dungeon7.001":"Malgré toute cette lumière, cet endroit me donne la chair de poule.","story.map9-dungeon7.002":"Ce serait encore un des pièges de Mare ?","story.map9-dungeon7.003":"Je n\'ai pas besoin de gaspiller mes précieux pièges pour vous.","story.map9-dungeon7.004":"C\'est la voix de Mare !","story.map9-dungeon7.005":"Je vous ai préparé un adversaire.","story.map9-dungeon7.006":"Granvalm, gardien de cette tour. <wait=40>Détruis ces intrus !","story.map9-dungeon7.007":"<size=20>Kyaaaah ! <wait=40>Regarde ce dragon !</size>","story.map9-dungeon7.008":"Il devrait être parfait pour une paire d\'idiots comme vous.","story.map9-dungeon7.009":"Attends !","story.map9-dungeon7.010":"Là, je suis vraiment en colère ! <wait=40><rep_handlename>, recule !","story.map9-dungeon7.011":"Ha ha ha...","story.map9-dungeon7.012":"Ils se sont enfuis...","story.map9-dungeon7.013":"Pourtant, <wait=20>ce dragon avait l\'air de repartir protéger quelque chose...","story.map9-dungeon7.014":"Peut-être qu\'il voulait s\'assurer que Karl ne s\'échappe pas.","story.map9-dungeon7.015":"<rep_handlename> !","story.map9-dungeon7.016":"C\'est sûrement ça !","story.map9-dungeon7.017":"Poursuis ce dragon, ça ira pour moi !","story.map9-dungeon7.018":"J\'ai juste besoin de me reposer ici une seconde !","story.map9-dungeon7.019":"On doit se montrer dignes de la confiance que Seria nous accorde.","story.map9-dungeon7.020":"Ce ne sera pas un problème pour mon <rep_handlename> !","story.map9-dungeon7.021":"Tiens ta promesse envers Seria et sauve Karl !","story.map9-ending.001":"Invocateur. <wait=40>On dirait que tu tiens encore debout.","story.map9-ending.002":"Détends-toi. <wait=40>Je veillerai à ce que ta fin soit rapide et sans douleur.","story.map9-ending.003":"Après toi, il ne restera plus personne pour menacer Lord Zevalhua. ","story.map9-ending.004":"Pourquoi cet air surpris ?","story.map9-ending.005":"C\'est toi que je visais depuis le tout début.","story.map9-ending.006":"Toi, l\'Invocateur choisi par Lucius.","story.map9-ending.007":"Maintenant que j\'ai éliminé tous ceux qui te protégeaient...","story.map9-ending.008":"...il ne reste plus personne pour te sauver.","story.map9-ending.009":"Même le vieil homme a été vaincu en se battant pour sauver quelqu\'un qui n\'était même pas là.","story.map9-ending.010":"En plus, <wait=20>le pouvoir de cette déesse idiote qui avait foi en toi s\'est épuisé lui aussi.","story.map9-ending.011":"Peu importe combien de disciples Lucius envoie.","story.map9-ending.012":"Faibles comme ils sont, ils doivent bien comprendre que le dragon blanc les réduira simplement à l\'immobilité.","story.map9-ending.013":"Il est devenu stupide à force de passer autant de temps avec vous, les humains.","story.map9-ending.014":"Vous, vermisseaux humains, êtes vraiment pitoyables.","story.map9-ending.015":"Vous vous emballez facilement, puis vous agissez seuls.","story.map9-ending.016":"Même en sachant que c\'est un piège, vous dites que c\'est pour sauver vos amis, et vous entraînez les autres dans vos ennuis. ","story.map9-ending.017":"Agir seul quand on porte de si lourdes responsabilités ne mène qu\'à l\'échec. ","story.map9-ending.018":"Et <wait=20>ceux qui ont de grands buts mais s\'attardent sur les petits finissent par tout perdre.","story.map9-ending.019":"Quelle façon stupide de vivre.","story.map9-ending.020":"Tu ne fais sûrement pas exception.","story.map9-ending.021":"Invocateur...","story.map9-ending.022":"Hmph, <wait=40>je m\'ennuie.","story.map9-ending.023":"J\'ai parlé en pensant que tu opposerais un peu de résistance, mais on dirait que tu es déjà à bout.","story.map9-ending.024":"Très bien. <wait=40>Je n\'ai plus qu\'à en finir avec toi ici !","story.map9-ending.025":"<size=20>Arrête-toi tout de suite !</size>","story.map9-ending.026":"......","story.map9-ending.027":"......","story.map9-ending.028":"On dirait qu\'il te reste encore des alliés.","story.map9-ending.029":"Mais peu importe.","story.map9-ending.030":"L\'homme que tu cherches est retenu dans la capitale d\'Agni. ","story.map9-ending.031":"Tu ferais mieux de te lancer à sa poursuite si tu veux le sauver.","story.map9-ending.032":"Et tu n\'as pas le temps d\'attendre que tes amis se rétablissent.","story.map9-ending.033":"Sinon, tu arriveras trop tard pour le sauver.","story.map9-ending.034":"......","story.map9-ending.035":"Hé, <rep_handlename>, <wait=20>ne reste pas planté là !","story.map9-ending.036":"On parlera plus tard. <wait=40>Pour l\'instant, mettons-nous en route vers la capitale d\'Agni.","story.map9-ending.037":"J\'ai quelque chose à te dire une fois là-bas.","story.map9-ending.038":"Tu devrais m\'être reconnaissant !","story.map9-ending.039":"<size=20>Ah ha ha ha !</size>","story.map9-open.001":"<anchor=center><br><br><br><br><br><br><br><br><br><br><speed=8><size=15>Je suis Lucius...<br><wait=40>Dieu de cette Porte...","story.map9-open.002":"<anchor=center><br><br><br><br><br><br><br><br><br><br><speed=8><size=15>La crise provoquée par les Quatre Dieux déchus,<wait=40> perdure encore...","story.map9-open.003":"<anchor=center><br><br><br><br><br><br><br><br><br><br><speed=8><size=15>Use de mon pouvoir <wait=40>et aventure-toi sur de nouvelles terres...","story.map9-open.004":"<anchor=center><br><br><br><br><br><br><br><br><br><br><speed=8><size=15>Afin d\'apporter un nouvel espoir à ce monde sans ordre...","story.map9-open.005":"<anchor=center><br><br><br><br><br><br><br><br><br><br><speed=8><size=15>Tu dois avoir foi en ton pouvoir, <wait=20>et continuer d\'avancer...","story.map9-open.006":"<rep_handlename> ! <wait=40>Désolée de t\'avoir fait attendre !","story.map9-open.007":"Mais comme c\'est toujours moi qui t\'attends, <rep_handlename>...","story.map9-open.008":"...je me suis dit que cette fois, ce serait ton tour !","story.map9-open.009":"Quoi ? <wait=20>Tu dis que tu n\'as pas attendu si longtemps ?","story.map9-open.010":"C\'est pas juste !","story.map9-open.011":"Je pensais que tu suerais au moins un peu à m\'attendre !","story.map9-open.012":"Mais peu importe ! <wait=40>L\'important, c\'est de vaincre vite le prochain Dieu déchu !","story.map9-open.013":"Il ne reste plus que la moitié des Quatre Dieux déchus !","story.map9-open.014":"Et ton prochain adversaire est...","story.map9-open.015":"...le grand empereur Zevalhua, qui contrôle la région d\'Agni. ","story.map9-open.016":"On dit qu\'il est en mauvais termes avec Afla Dilith, un autre des Dieux déchus...","story.map9-open.017":"...mais il a sûrement déjà remarqué notre arrivée ici.","story.map9-open.018":"Il va sûrement essayer de nous tendre des pièges !","story.map9-open.019":"Mais ce n\'est pas comme si tu allais tomber dedans, hein, <rep_handlename> ?","story.map9-open.020":"Bon, <wait=20>je file vers Milvana, où Zevalhua nous attend !","story.map9-open.021":"Randall,<wait=40> capitale de l\'Empire de Randall.","story.map9-open.022":"Château de Randall, dans les quartiers privés des gardes du corps de la famille royale, <wait=40>la Garde impériale.","story.map9-open.023":"*Toc* <wait=20>*toc*","story.map9-open.024":"Excusez-moi.","story.map9-open.025":"......","story.map9-open.026":"Les préparatifs pour partir vers la région d\'Agni sont terminés. ","story.map9-open.027":"Vraiment.","story.map9-open.028":"Dans ce cas, mettons-nous nous aussi en route. ","story.map9-open.029":"Vers Grand Gaia, la terre contrôlée par les dieux. ","storylog.category.10000.description":"En voyageant à travers Grand Gaia avec ses amis et une puissante déesse, un Invocateur affronte des démons dans de féroces batailles.","storylog.category.10000.name":"Mémoires de Grand Gaia","storylog.category.10100.description":"Guidé par Tilith, au service du dieu Lucius, l\'Invocateur entame une grande aventure. Il faut vaincre les Quatre Dieux déchus, à commencer par Maxwell.","storylog.category.10100.name":"Mistral","storylog.category.10101.description":"Une île jadis habitée par des géants semble être la prochaine étape de l\'Invocateur. Mais Paris, de la Garde impériale, se dirige elle aussi vers Cordelica...","storylog.category.10101.name":"Cordelica","storylog.category.10102.description":"L\'Invocateur arrive sur la terre que Cardes le Malveillant veut détruire. Une nouvelle bataille commence là où se dressaient jadis les 4 Héros légendaires de Palmyna.","storylog.category.10102.name":"Palmyna","storylog.category.10103.description":"Paris arrive sur l\'île de l\'ancienne République de La Veda pour chercher une porte dont on parle, mais le Hall des Invocateurs a déjà commencé à enquêter.","storylog.category.10103.name":"Lizeria","storylog.category.10104.description":"Zevalhua le Suprême doit être abattu avant qu\'il ne détruise tout. On dit qu\'il est en conflit avec Afla Dilith, l\'un des Quatre Dieux déchus.","storylog.category.10104.name":"Région d\'Agni","storylog.category.11001.description":"Tandis que Karl traque le démon Graham, l\'Invocateur part défier Abaddon, le disciple de Maxwell. Mais Abaddon peut-il vraiment être vaincu ?","storylog.category.11001.name":"Morgan","storylog.category.11002.description":"La terre gouvernée par Maxwell la Créatrice est la nouvelle destination. Le but : rejoindre avec Tilith le Palais de St. Lamia, forteresse de Maxwell.","storylog.category.11002.name":"St. Lamia","storylog.category.11010.description":"L\'Invocateur pose le pied là où prospérait jadis le grand Empire d\'Amdahl. Tilith espère que ce voyage s\'achèvera par la défaite de Cardes le Malveillant.","storylog.category.11010.name":"Amdahl","storylog.category.11011.description":"Selon Tilith, cette terre a autrefois connu une guerre civile entre humains. De violents combats éclatent en pleine nature sauvage.","storylog.category.11011.name":"Encervis","storylog.category.11040.description":"Zevalhua le Suprême est la nouvelle cible. Tilith craint qu\'un complot ne se trame.","storylog.category.11040.name":"Ryvern","storylog.category.11041.description":"L\'Invocateur arrive sur la terre où se dressait jadis un empire. Grahdens t\'a confié, à toi et à Lugina, le sauvetage de Karl, mais...","storylog.category.11041.name":"Agni","storylog.category.11042.description":"Enfin arrivé au bastion de Zevalhua, il est temps que cet ancien champ de bataille accueille un nouveau combat pour sauver Grahdens, capturé.","storylog.category.11042.name":"Mirvana","storylog.category.20000.description":"On demande à l\'Invocateur d\'explorer une terre mystérieuse récemment découverte. Mais les ennemis qui l\'y attendent sont bien plus forts que prévu...","storylog.category.20000.name":"Une nouvelle région","storylog.scenario.10001.description":"Dans la Grotte des flammes, Tilith explique la situation de Grand Gaia. L\'Invocateur doit entreprendre un long voyage pour vaincre les Quatre Dieux déchus...","storylog.scenario.10001.title":"Le début du voyage","storylog.scenario.10002.description":"Dans la Plaine enneigée d\'Egor, Tilith souligne l\'importance des éléments des unités. La Foudre bat l\'Eau, etc. Bon à savoir pour les prochains combats.","storylog.scenario.10002.title":"Affinités des unités","storylog.scenario.10003.description":"L\'Invocateur atteint la Forêt des bêtes, où des ennemis chassent les animaux sauvages pour se nourrir. L\'usage des sphères y est aussi expliqué en détail.","storylog.scenario.10003.title":"L\'équipement compte","storylog.scenario.10004.description":"L\'humidité du Marais de Magutagal met Tilith de mauvaise humeur, mais elle explique tout de même les étincelles créées par des attaques synchronisées.","storylog.scenario.10004.title":"Technique de combat","storylog.scenario.10005.description":"Tilith est impressionnée que l\'Invocateur ait atteint les Vestiges de Mirza sain et sauf. En récompense, elle explique les avantages des Compétences de Leader.","storylog.scenario.10005.title":"Leadership","storylog.scenario.10006.description":"On dit qu\'un mystérieux épéiste rôde dans le Nid du monstre. Tilith jure qu\'elle n\'a pas peur, mais elle a l\'air vraiment effrayée...","storylog.scenario.10006.title":"Je n\'ai pas peur !","storylog.scenario.10007.description":"À la Tour de Mistral, la libération de toute la région n\'est plus qu\'à un pas. Mais Maxwell la Créatrice a conçu un adversaire terrifiant...","storylog.scenario.10007.title":"Mistral libéré","storylog.scenario.10008.description":"L\'Invocateur vainc le Juggernaut et reçoit les éloges de Tilith. Lucius va maintenant ouvrir la voie vers la terre inconnue de Morgan.","storylog.scenario.10008.title":"Vers de nouvelles terres","storylog.scenario.10009.description":"À la recherche de Tilith, notre Invocateur entre dans le Désert de Kagan. Une rencontre fortuite avec Karl révèle qu\'il traque le démon Graham.","storylog.scenario.10009.title":"Retrouvailles avec Karl","storylog.scenario.10010.description":"À la Plage de la brise, Tilith entend parler d\'une épéiste belle mais froide. Elle est pourtant convaincue d\'être bien plus jolie que cette beauté.","storylog.scenario.10010.title":"La belle épéiste","storylog.scenario.10011.description":"Karl se blesse en poursuivant Graham. La Forêt nocturne serait le territoire d\'un des sbires de Graham, qui attaque de nombreux Invocateurs.","storylog.scenario.10011.title":"Le sbire de Graham","storylog.scenario.10012.description":"Karl parvient à chasser Graham de la Forêt nocturne. Acculé, il est temps de tout régler dans la Désolation d\'Asekutt.","storylog.scenario.10012.title":"La traque de Karl","storylog.scenario.10013.description":"Seria, membre des Pourfendeurs de démons, se montre au Sanctuaire de Lystia. Selon elle, Graham est l\'un des sbires favoris d\'Abaddon.","storylog.scenario.10013.title":"Abaddon & Graham","storylog.scenario.10014.description":"Seria se montre hostile envers l\'Invocateur. Karl veut continuer à trois jusqu\'à la Cathédrale détruite, mais Seria ne lui facilite pas la tâche...","storylog.scenario.10014.title":"Refus","storylog.scenario.10015.description":"Arrivés enfin au repaire d\'Abaddon, la Tour de Morgan, Karl et Seria repoussent les ennemis pour aider l\'Invocateur à avancer.","storylog.scenario.10015.title":"Pour mes camarades","storylog.scenario.10016.description":"Abaddon est vaincu. Après avoir retrouvé Karl puis s\'être de nouveau séparés, Tilith et l\'Invocateur partent pour St. Lamia à la recherche de Maxwell.","storylog.scenario.10016.title":"Vers la base ennemie","storylog.scenario.10017.description":"Au Volcan Eldent, Tilith prévient que négliger ses devoirs est inacceptable. Elle affirme n\'avoir jamais tiré au flanc dans son travail, mais...","storylog.scenario.10017.title":"Pas de paresse !","storylog.scenario.10018.description":"Tilith tente de raconter l\'histoire du Mt sacré Craylia, mais elle ne semble pas en forme. Elle aurait attrapé un rhume...","storylog.scenario.10018.title":"Mauvais présage","storylog.scenario.10019.description":"Dans la Forêt de sang, Tilith fait de son mieux pour cacher que son état empire. Mais il est clair que ça l\'épuise...","storylog.scenario.10019.title":"Bluff","storylog.scenario.10020.description":"Au Mt Wistorea, Tilith avoue enfin qu\'elle est mal en point. La malédiction de Maxwell l\'affecte d\'autant plus qu\'elle approche du Palais de St. Lamia.","storylog.scenario.10020.title":"La malédiction","storylog.scenario.10021.description":"Au Sanctuaire isolé, Tilith s\'effondre enfin. La confiant à Seria, l\'Invocateur part seul pour le Palais de St. Lamia afin de briser la malédiction.","storylog.scenario.10021.title":"Une promesse","storylog.scenario.10022.description":"Secouru par Karl, l\'Invocateur poursuit Maxwell dans le Palais de St. Lamia. Tilith pourra-t-elle vraiment être sauvée de cette terrible malédiction ?!","storylog.scenario.10022.title":"Ce qu\'il faut protéger","storylog.scenario.10023.description":"La malédiction brisée, Tilith redevient elle-même, mais finit on ne sait comment dans une dispute théâtrale avec Seria...","storylog.scenario.10023.title":"La chute de la Créatrice","storylog.scenario.10100.description":"Apprenant que le Hall des Invocateurs d\'Akras a ouvert la région sud de Mistral, Eriole envoie Paris à Cordelica...","storylog.scenario.10100.title":"Le complot commence","storylog.scenario.10101.description":"Rencontre avec le Pourfendeur de démons Lugina dans les Grottes de Greskya. N\'ayant aucun respect pour l\'Armée régulière, il exige que l\'Invocateur parte.","storylog.scenario.10101.title":"Lugina le Pourfendeur","storylog.scenario.10102.description":"Aux Chutes d\'Ignia, Lugina explique comment l\'Empire de Randall et le Hall des Invocateurs d\'Akras influencent la vie à Elgaia.","storylog.scenario.10102.title":"Les affaires d\'Elgaia","storylog.scenario.10103.description":"Dans la Forêt de Lomass, Lugina explique le fonctionnement de l\'Armée des Invocateurs. En tant qu\'élite, il exige que l\'Invocateur respecte son autorité.","storylog.scenario.10103.title":"L\'Armée des Invocateurs","storylog.scenario.10104.description":"Paris se montre à la Forteresse de Valtan. Elle demande la coopération de l\'Invocateur pour l\'exploration de Cordelica, mais...","storylog.scenario.10104.title":"La requête de Paris","storylog.scenario.10105.description":"En route vers la Tour de lumière, Paris dit que l\'Invocateur est un ami de Karl, mais Lugina n\'y croit pas. Il ne semble pas apprécier Karl.","storylog.scenario.10105.title":"Quel snob !","storylog.scenario.10106.description":"Dans la Mine de Cordelica, Paris explique qu\'une race de géants habitait l\'île il y a longtemps. Il semblerait que le dieu des géants se soit aussi réveillé.","storylog.scenario.10106.title":"Un dieu géant","storylog.scenario.10107.description":"Tandis que Lugina part vaincre le dieu géant Grantos dans les Ruines du géant, Paris demande à l\'Invocateur de montrer ce qu\'est la vraie puissance.","storylog.scenario.10107.title":"Lugina l\'enthousiaste","storylog.scenario.10108.description":"Apprenant que l\'Invocateur a vaincu Grantos, Eriole rit en proclamant que le monde va dans la bonne direction...","storylog.scenario.10108.title":"Les motifs d\'Eriole","storylog.scenario.10200.description":"Lucius guide l\'Invocateur vers l\'archipel de Palmyna, tandis qu\'un homme à Randall apprend que la barrière couvrant ces îles a disparu.","storylog.scenario.10200.title":"Le Chevalier superviseur","storylog.scenario.10201.description":"La prochaine cible est Cardes le Malveillant, un autre des Quatre Dieux déchus. Au Village de Julep, tu apprends que la moitié de son pouvoir est encore scellée.","storylog.scenario.10201.title":"Cardes le Malveillant","storylog.scenario.10202.description":"Tilith prétend ne pas avoir peur à bord du Vaisseau fantôme Legnia. Elle donne tout de même des informations sur Palmyna, où Cardes est scellé...","storylog.scenario.10202.title":"La route de Palmyna","storylog.scenario.10203.description":"L\'Invocateur est soudain attaqué par un homme étrange dans les Plaines d\'Elios. Mais la présence de cet homme mystérieux disparaît aussi vite qu\'elle est apparue.","storylog.scenario.10203.title":"Un homme mystérieux","storylog.scenario.10204.description":"Une rencontre avec Seria et Karl dans les Mines de Saji révèle qu\'ils traquent toujours Graham. Karl met l\'Invocateur en garde contre un certain Zebra.","storylog.scenario.10204.title":"Il s\'appelle Zebra","storylog.scenario.10205.description":"Tilith et son Invocateur tombent sur « Elder Grah » au Temple de Lamellia. Le vieil homme dit enquêter sur le folklore lié aux Quatre Dieux déchus.","storylog.scenario.10205.title":"Un vieillard mystérieux","storylog.scenario.10206.description":"Karl et Seria acculent Graham dans la Ville fantôme Edila, mais une force inconnue et puissante les repousse, permettant à Graham de s\'enfuir.","storylog.scenario.10206.title":"Force inconnue","storylog.scenario.10207.description":"Apparaissant au Château d\'Amdahl, Elder Grah parle de l\'esprit vengeur du dernier empereur d\'Amdahl, qui hanterait encore le château.","storylog.scenario.10207.title":"Le dernier empereur d\'Amdahl","storylog.scenario.10208.description":"Elder Grah est impressionné que l\'Invocateur ait vaincu l\'esprit maléfique. Seria accourt, et elle semble connaître le vieil homme...","storylog.scenario.10208.title":"Seria & Elder Grah","storylog.scenario.10209.description":"Guidé par Lucius, l\'Invocateur atteint Encervis. Selon Tilith, une guerre civile entre humains a ravagé cette terre il y a longtemps.","storylog.scenario.10209.title":"Ruines du passé","storylog.scenario.10210.description":"Au Cratère d\'Elsta, Tilith raconte à l\'Invocateur à quel point elle a travaillé dur jusqu\'ici. Mais ses affirmations semblent douteuses...","storylog.scenario.10210.title":"Tilith la travailleuse","storylog.scenario.10211.description":"Zebra attaque soudain au Lac Aldela, mais l\'aide d\'Elder Grah évite le pire. Ce puissant ennemi semble vivre dans un fort flottant.","storylog.scenario.10211.title":"Le fort céleste restauré","storylog.scenario.10212.description":"Elder Grah raconte l\'histoire d\'Amdahl en errant dans le Château d\'Avenia. Il demande à l\'Invocateur de détruire le fort céleste, mais Tilith s\'en moque...","storylog.scenario.10212.title":"L\'histoire d\'Amdahl","storylog.scenario.10213.description":"Dans le Ravin de Gadillian, Zebra et la Silhouette sombre discutent de la manière de régler le cas de l\'Invocateur. Quel lien peut bien les unir... ?","storylog.scenario.10213.title":"Zebra & une silhouette sombre","storylog.scenario.10214.description":"Seria et Karl cherchent l\'Invocateur au Mausolée d\'Alman. Tous deux veulent unir leurs forces pour faire tomber le fort céleste.","storylog.scenario.10214.title":"Un soutien rassurant","storylog.scenario.10215.description":"Sur la Terre des morts, Tilith révèle que le nom officiel du fort céleste est Solaris. Elle compte user de ses pouvoirs pour aider à l\'infiltrer.","storylog.scenario.10215.title":"Infiltrer le fort","storylog.scenario.10216.description":"Grâce aux pouvoirs de Tilith, l\'infiltration du Fort céleste Solaris est un succès. Zebra y voit l\'occasion d\'attaquer la déesse épuisée.","storylog.scenario.10216.title":"Zebra contre Tilith","storylog.scenario.10217.description":"Zebra est enfin vaincu. Mais il détruit Solaris pour entraîner l\'Invocateur dans sa chute. Qui pourra empêcher ce drame... ?","storylog.scenario.10217.title":"Zebra & Grahdens","storylog.scenario.10218.description":"L\'Invocateur atteint Palmyna, guidé par Lucius. Les traces d\'un royaume qui s\'est battu contre les dieux y sont encore bien visibles.","storylog.scenario.10218.title":"Le champ de bataille","storylog.scenario.10219.description":"D\'abord au Château d\'Obselion, Tilith se précipite aux Ruines de Dejour pour prévenir que le sceau de Cardes commence à s\'affaiblir.","storylog.scenario.10219.title":"Le sceau se défait","storylog.scenario.10220.description":"Grahdens reste seul avec l\'Invocateur au Château d\'Obselion. Il raconte l\'histoire des 4 Héros de Palmyna qui ont scellé Cardes le Malveillant.","storylog.scenario.10220.title":"Les 4 Héros de Palmyna","storylog.scenario.10221.description":"Sur le Chemin d\'émeraude, Seria et Karl apprennent qu\'ils doivent se rendre dans le monde des esprits pour vaincre Cardes. Mais Seria agit bizarrement...","storylog.scenario.10221.title":"L\'étrange Seria","storylog.scenario.10222.description":"En traversant les Ruines de Grandelt, Tilith révèle que le corps de Cardes se désagrège peu à peu et que ses pouvoirs divins se déchaînent.","storylog.scenario.10222.title":"Le déchaînement des dieux","storylog.scenario.10223.description":"Au Séminaire d\'Arlind, Grahdens exprime ses doutes sur les agissements passés et récents des dieux. Ses pensées semblent influencer l\'Invocateur.","storylog.scenario.10223.title":"Les doutes de Grahdens","storylog.scenario.10224.description":"Karl et Seria accompagnent l\'Invocateur jusqu\'aux portes des enfers, sur le Champ de bataille de Noera. Tous deux s\'inquiètent pour Tilith.","storylog.scenario.10224.title":"L\'entrée des enfers","storylog.scenario.10225.description":"L\'Invocateur et les autres se séparent pour trouver Cardes dans le Monde spirituel Palmyna. Pourra-t-il être vaincu avant de tout détruire ?","storylog.scenario.10225.title":"Le combat contre Cardes","storylog.scenario.10226.description":"Alors que tous tentent de fuir les enfers qui s\'effondrent, Seria est blessée. Dans cette situation désespérée, Tilith apparaît pour sauver la situation.","storylog.scenario.10226.title":"La déesse renaît","storylog.scenario.10300.description":"Après avoir entendu le rapport de Paris, Eriole l\'envoie en Lizeria. Que peut-il bien chercher ?","storylog.scenario.10300.title":"La recherche","storylog.scenario.10301.description":"Lugina se montre dans les Plaines d\'Erinecht et prétend avoir une mission bien plus importante que celle de l\'Invocateur. Son attitude fougueuse n\'a pas changé.","storylog.scenario.10301.title":"La mission de Lugina","storylog.scenario.10302.description":"Arrivé aux Monts Golzo, on apprend que Paris recherche un pouvoir endormi en Lizeria. Et il semble que Lugina poursuive le même but.","storylog.scenario.10302.title":"Une ambition pour deux","storylog.scenario.10303.description":"Au Lac gelé de Lodan, Lugina croit à tort que Paris a retourné l\'Invocateur. Tout s\'éclaircit, mais Lugina tient à l\'entraîner...","storylog.scenario.10303.title":"L\'entraînement de Lugina","storylog.scenario.10304.description":"Dans les Marécages infranchissables, Paris parle de la structure sociale d\'Elgaia. On sent qu\'elle se méfie du pouvoir du Hall des Invocateurs.","storylog.scenario.10304.title":"La face cachée du Hall","storylog.scenario.10305.description":"Dans la Forêt foudroyante de Zaljiba, Paris évoque la face cachée du Hall des Invocateurs. Lugina est ensuite interrogé à ce sujet et répond à sa façon.","storylog.scenario.10305.title":"La motivation de Lugina","storylog.scenario.10306.description":"Dans la Cité perdue de La Veda, Paris confie ses doutes sur les dieux et parle de l\'instabilité du monde. Elle veut prendre les choses en main.","storylog.scenario.10306.title":"La motivation de Paris","storylog.scenario.10307.description":"Sur le Pont noir, Lugina déclare qu\'il écrasera quiconque se mettra en travers de son chemin, et fait une dernière confidence à l\'Invocateur avant d\'avancer.","storylog.scenario.10307.title":"Dernier avertissement","storylog.scenario.10308.description":"Bien que Lugina perde contre l\'Invocateur, il affirme qu\'il n\'a pas pu échouer et continue de nier sa propre défaite.","storylog.scenario.10308.title":"La défaite de Lugina","storylog.scenario.10309.description":"À la Tour de la destruction, Paris, blessée, refuse toujours de renoncer au pouvoir endormi de la région. Elle ne pardonnera pas l\'intrusion de l\'Invocateur.","storylog.scenario.10309.title":"La résolution de Paris","storylog.scenario.10310.description":"Un système de défense capable de détruire des Invocateurs. Pourtant, ce que Paris cherchait, qui aurait dû être tout proche, est introuvable...","storylog.scenario.10310.title":"Puissance destructrice","storylog.scenario.10400.description":"Tilith et l\'Invocateur partent vaincre Zevalhua le Suprême. À leur insu, Eriole et Paris se dirigent eux aussi vers Agni...","storylog.scenario.10400.title":"Double voyage","storylog.scenario.10401.description":"Dans le Creux de Glomore, Karl et Seria déclarent vouloir aider à vaincre Zevalhua, tandis qu\'une femme mystérieuse les observe de loin avec mépris.","storylog.scenario.10401.title":"Camarades","storylog.scenario.10402.description":"Arrivée à la Zone enneigée de Khelne, la disciple Mare apparaît soudain et demande à Karl de la rejoindre seul aux Ruines d\'Azura pour lui révéler un secret.","storylog.scenario.10402.title":"Le passé de Karl","storylog.scenario.10403.description":"Seria s\'inquiète pour Karl en errant dans la Forêt de Stokhelna, quand Mare réapparaît pour dire que Karl est tombé droit dans son piège...","storylog.scenario.10403.title":"La disciple Mare","storylog.scenario.10404.description":"Seria tombe dans le piège de Mare aux Ruines d\'Azura et est blessée. Tilith confie le sauvetage de Karl à l\'Invocateur pendant qu\'elle soigne Seria.","storylog.scenario.10404.title":"Seria piégée","storylog.scenario.10405.description":"Grahdens attend l\'Invocateur dans les Monts Ryvern et partage ses souvenirs de Karl. Il compte se faire capturer par Mare pour libérer Karl.","storylog.scenario.10405.title":"Grahdens et Karl","storylog.scenario.10406.description":"Mare se montre devant l\'Invocateur, seul dans la Grotte des abysses. Alors qu\'elle s\'apprête à attaquer, Tilith revient et l\'en empêche.","storylog.scenario.10406.title":"Tilith en douce","storylog.scenario.10407.description":"Mare lâche Granvalm sur l\'Invocateur dans la Tour blanche, puis s\'enfuit. Mais Tilith ne compte pas la laisser filer si facilement.","storylog.scenario.10407.title":"Granvalm le Blanc","storylog.scenario.10408.description":"Mare réapparaît après la défaite de Granvalm, et en pleine situation désespérée, un allié inattendu sauve la peau de tout le monde...","storylog.scenario.10408.title":"Renfort inattendu","storylog.scenario.10409.description":"Lugina sauve l\'Invocateur à Ryvern pour honorer la demande de Grahdens. Il insiste aussi sur le fait qu\'on lui a demandé d\'aider à sauver Karl.","storylog.scenario.10409.title":"Sois reconnaissant","storylog.scenario.10410.description":"Dans l\'Empire d\'Agni, Lugina est tout excité par la mission de sauvetage. Selon lui, c\'est l\'occasion parfaite de remplir sa mission et de se moquer de Karl.","storylog.scenario.10410.title":"Lugina fait de son mieux","storylog.scenario.10411.description":"Lassé d\'attendre que Mare se montre, Lugina laisse l\'Invocateur sur la Côte d\'Agniria et part chercher Karl de son côté...","storylog.scenario.10411.title":"Nouveau départ","storylog.scenario.10412.description":"Mare se montre enfin sur le Plateau de Granasta. Mais elle ne veut pas se battre. Elle exige plutôt que l\'Invocateur la suive pour sauver Karl.","storylog.scenario.10412.title":"Mare la manipulatrice","storylog.scenario.10413.description":"Mare se remémore une personne qui a combattu dans la guerre contre les dieux, tandis que l\'Invocateur angoissé la poursuit jusqu\'au Sommet tonnant de Navara.","storylog.scenario.10413.title":"Les souvenirs de Mare","storylog.scenario.10414.description":"L\'Invocateur s\'avance dans le Tombeau du roi sans perdre l\'espoir de sauver Karl. Mare ne comprend pas une telle obstination, et finit par frapper.","storylog.scenario.10414.title":"Forces opposées","storylog.scenario.10415.description":"Alors que Mare s\'apprête à porter le coup de grâce dans la Crique de Lognea, Seria, censée être gravement blessée, surgit pour sauver l\'Invocateur.","storylog.scenario.10415.title":"Contre-attaque","storylog.scenario.10416.description":"Une horde d\'ennemis surgit au Sanctuaire océanique d\'Albina, mettant Seria et l\'Invocateur en difficulté. Mais Lugina arrive juste à temps avec Karl libéré.","storylog.scenario.10416.title":"Le sauvetage","storylog.scenario.10417.description":"Mare est enfin vaincue par l\'Invocateur, mais aussitôt, Paris apparaît pour annoncer que Grahdens a été fait prisonnier.","storylog.scenario.10417.title":"Grahdens capturé","storylog.scenario.10418.description":"L\'Invocateur pose enfin le pied à Mirvana. Tilith explique que ce fut le théâtre de la bataille la plus sanglante de la grande guerre contre les dieux.","storylog.scenario.10418.title":"Ancien champ de bataille","storylog.scenario.10419.description":"Grahdens a été capturé par Zevalhua le Suprême. Pour le sauver, l\'Invocateur et les autres se séparent en groupes dans la Grotte des ténèbres.","storylog.scenario.10419.title":"Les recherches commencent","storylog.scenario.10420.description":"Dans la Plaine enneigée d\'Arvest, Paris se demande avec méfiance pourquoi les dieux ont fait Grahdens prisonnier au lieu de le tuer sur-le-champ...","storylog.scenario.10420.title":"Agissements suspects","storylog.scenario.10421.description":"En cherchant Grahdens dans l\'Océan d\'arbres de Marleg, Paris invite à nouveau l\'Invocateur à rejoindre sa cause. Mais Tilith finit par l\'interrompre.","storylog.scenario.10421.title":"À qui l\'Invocateur ?","storylog.scenario.10422.description":"Lugina réprimande Paris dans le Marais de la pluie éternelle. Mais avant que les choses ne s\'enveniment, Seria s\'en mêle et se dispute avec Lugina.","storylog.scenario.10422.title":"Lugina et Seria","storylog.scenario.10423.description":"L\'emplacement de Grahdens est confirmé une fois arrivés au Cap Narasta, et Paris se demande pourquoi Lucius ne vainc pas lui-même les Quatre Dieux déchus.","storylog.scenario.10423.title":"Les doutes de Paris","storylog.scenario.10424.description":"Karl remercie Tilith quand elle révèle de nouvelles informations sur Grahdens dans les Ruines de Mirvana. Lugina et Seria, eux, continuent leur dispute habituelle.","storylog.scenario.10424.title":"Ils ne changent pas","storylog.scenario.10425.description":"Tout le groupe a enfin atteint la Tour des dieux. Parviendront-ils à vaincre Zevalhua le Suprême pour sauver Grahdens ?","storylog.scenario.10425.title":"Zevalhua le Suprême","storylog.scenario.10426.description":"Grahdens se montre et révèle le secret de la naissance de Karl. Au même moment, Eriole fait soudain son apparition et vient s\'entretenir avec l\'Ancien.","storylog.scenario.10426.title":"Le secret de sa naissance","storylog.scenario.20000.description":"Lin, du Bureau de l\'Office d\'exploration, demande à l\'Invocateur d\'enquêter sur les Monts d\'Egor. Un démon de glace y sommeillerait.","storylog.scenario.20000.title":"Le démon de la montagne","storylog.scenario.20001.description":"Lin évoque le passé de Skramya. La légende dit qu\'un héros a scellé le démon après qu\'il a tenté de détruire la nation qui voulait le manipuler.","storylog.scenario.20001.title":"Le passé du démon","storylog.scenario.20002.description":"Lin demande à l\'Invocateur d\'explorer la Caverne d\'Ignia. Il semble qu\'un démon s\'y soit réveillé après les séismes de Cordelica...","storylog.scenario.20002.title":"Gluant et visqueux","storylog.scenario.20003.description":"L\'Invocateur vainc le démon gigantesque et incontrôlable. Lin le couvre d\'éloges, mais son attitude change soudain du tout au tout...","storylog.scenario.20003.title":"Ce que Lin déteste","storylog.scenario.20004.description":"Lin transmet à l\'Invocateur des informations selon lesquelles le Nid de Valmodora abrite un démon. Elle attend de l\'Invocateur qu\'il recueille plus de détails.","storylog.scenario.20004.title":"Un démon gigantesque","storylog.scenario.20005.description":"L\'Invocateur vainc Valmodora en explorant les lieux. Il semble que les ruines abritaient bel et bien quelque chose de gigantesque.","storylog.scenario.20005.title":"Ruines mystérieuses","storylog.scenario.20006.description":"L\'Invocateur sent une puissance phénoménale émaner du fond du Lac souterrain de Golzo. Lin a un mauvais pressentiment, mais demande une exploration.","storylog.scenario.20006.title":"Le mauvais pressentiment de Lin","storylog.scenario.20007.description":"Lagzal, qui sommeillait sous terre, était un dieu qui cherchait à détruire les humains. Il semble que Lin se soit beaucoup inquiétée pour l\'Invocateur pendant l\'expédition.","storylog.scenario.20007.title":"Lagzal, le Dieu déchu","storylog.scenario.20008.description":"En traversant le Donjon d\'Agni, Lin demande à l\'Invocateur de soumettre un certain « être maléfique » enfermé à l\'intérieur.","storylog.scenario.20008.title":"Caché dans le donjon","storylog.scenario.20009.description":"Selon Lin, ce qui était enfermé là était le fantôme d\'un tyran redouté, scellé par ses propres vassaux.","storylog.scenario.20009.title":"La fin d\'un tyran"}')}]);